// === js/utils/error-handler.js ===
'use strict';
/* ============================================================
   error-handler.js — Глобальная обработка ошибок.
   Логирует в консоль, предотвращает крэш UI.
   Загружается ПЕРВЫМ (до всех остальных скриптов).
   ============================================================ */

window.onerror = function(message, source, lineno, colno, error) {
  console.error('[D20 Error]', message, '\n  at', source + ':' + lineno + ':' + colno);
  if (error && error.stack) console.error(error.stack);
  // Не блокируем дальнейшее выполнение
  return false;
};

window.onunhandledrejection = function(event) {
  console.error('[D20 Unhandled Promise]', event.reason);
  // Предотвращаем крэш — промис отклонён но не убивает игру
};

// === js/utils/safe-storage.js ===
'use strict';
/* ============================================================
   safe-storage.js — Безопасная обёртка над localStorage.
   В Private Browsing (Safari, некоторые WebView) localStorage
   может бросать исключения. Fallback: in-memory хранилище.
   ============================================================ */

const SafeStorage = (function() {
  let _available = true;
  const _fallback = {};

  // Проверяем доступность при загрузке
  try {
    const testKey = '__d20_storage_test__';
    localStorage.setItem(testKey, '1');
    localStorage.removeItem(testKey);
  } catch (e) {
    _available = false;
    console.warn('[SafeStorage] localStorage unavailable, using in-memory fallback.');
  }

  return {
    getItem(key) {
      try {
        if (_available) return localStorage.getItem(key);
      } catch (e) { /* fallback */ }
      return _fallback[key] !== undefined ? _fallback[key] : null;
    },

    setItem(key, value) {
      try {
        if (_available) { localStorage.setItem(key, value); return; }
      } catch (e) { /* fallback */ }
      _fallback[key] = String(value);
    },

    removeItem(key) {
      try {
        if (_available) { localStorage.removeItem(key); return; }
      } catch (e) { /* fallback */ }
      delete _fallback[key];
    },

    /** Является ли хранилище реальным localStorage (не fallback) */
    get isReal() { return _available; }
  };
})();

window.SafeStorage = SafeStorage;

// === js/i18n/engine.js ===
'use strict';
/* ============================================================
   i18n.js — Система локализации (RU/EN).
   Функция t(key) возвращает строку на текущем языке.
   Язык сохраняется в localStorage ('d20_lang').
   ============================================================ */

const LOCALE = { ru: {}, en: {} };

// --- Определение языка ---
let _currentLang = 'ru';
(function() {
  const saved = SafeStorage.getItem('d20_lang');
  if (saved && (saved === 'ru' || saved === 'en')) {
    _currentLang = saved;
  } else {
    const nav = (navigator.language || navigator.userLanguage || 'ru').toLowerCase();
    _currentLang = nav.startsWith('en') ? 'en' : 'ru';
    SafeStorage.setItem('d20_lang', _currentLang);
  }
})();

/** Получить строку на текущем языке */
function t(key, ...args) {
  const str = (LOCALE[_currentLang] && LOCALE[_currentLang][key]) ||
              (LOCALE.ru && LOCALE.ru[key]) || key;
  if (args.length === 0) return str;
  // Поддержка подстановки {0}, {1}...
  return str.replace(/\{(\d+)\}/g, (m, i) => args[i] !== undefined ? args[i] : m);
}

/** Сменить язык */
function setLang(lang) {
  if (lang !== 'ru' && lang !== 'en') return;
  _currentLang = lang;
  SafeStorage.setItem('d20_lang', lang);
  // Обновить HTML-элементы с data-i18n
  document.querySelectorAll('[data-i18n]').forEach(el => {
    el.textContent = t(el.getAttribute('data-i18n'));
  });
  // Перестроить динамические оверлеи лагеря при смене языка
  if (window.UI && UI._campOverlay) {
    UI._campOverlay.remove();
    UI._campOverlay = null;
  }
}

/** Получить текущий язык */
function getLang() { return _currentLang; }

window.t = t;
window.setLang = setLang;
window.getLang = getLang;
window.LOCALE = LOCALE;

