const GameAudio = {
  ctx: null,
  masterGain: null,
  sfxGain: null,
  musicGain: null,
  compressor: null,    // DynamicsCompressorNode на мастере
  reverbNode: null,    // ConvolverNode (общий реверб)
  reverbGain: null,    // Gain для реверба

  // Settings
  sfxVolume: 0.7,
  musicVolume: 0.25,
  muted: false,
  initialized: false,

  // Music state
  _musicDrone: null,
  _musicDroneGain: null,
  _musicDroneFilter: null,
  _musicNoteTimer: null,
  _musicBiome: null,
  _musicPlaying: false,
  _musicHarmonics: [],  // дополнительные осцилляторы для органного звука

  // Limiter: max concurrent oscillators
  _activeOscCount: 0,
  _maxOsc: 20,

  // Шаги героя (throttle)
  _lastStepTime: 0,
  _stepInterval: 0.3,

  /* ============================================================
     Initialization
     ============================================================ */

  init() {
    this._loadSettings();
    // Bug fix: используем единую функцию и удаляем слушатели после создания контекста
    this._activateHandler = () => {
      if (!this.ctx) {
        this._createContext();
      } else if (this.ctx.state === 'suspended') {
        this.ctx.resume().catch(() => {});
      }
      // После успешного создания контекста убираем слушатели
      if (this.ctx && this.ctx.state === 'running') {
        this._removeActivateListeners();
      }
    };
    document.addEventListener('click', this._activateHandler);
    document.addEventListener('touchstart', this._activateHandler);
    document.addEventListener('pointerdown', this._activateHandler);

    document.addEventListener('visibilitychange', () => {
      if (!this.ctx) return;
      try {
        if (document.hidden) {
          if (this.ctx.state === 'running') this.ctx.suspend().catch(() => {});
        } else {
          if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
        }
      } catch (e) { /* безопасно игнорируем */ }
    });
  },

  /** Bug fix: удалить слушатели активации после создания AudioContext */
  _removeActivateListeners() {
    if (this._activateHandler) {
      document.removeEventListener('click', this._activateHandler);
      document.removeEventListener('touchstart', this._activateHandler);
      document.removeEventListener('pointerdown', this._activateHandler);
      this._activateHandler = null;
    }
  },

  _createContext() {
    try {
      this.ctx = new (window.AudioContext || window.webkitAudioContext)();

      // Bug fix: на мобильных контекст может создаться в suspended,
      // явно вызываем resume()
      if (this.ctx.state === 'suspended') {
        this.ctx.resume().catch(() => {});
      }

      // Компрессор на мастере (предотвращает клиппинг)
      this.compressor = this.ctx.createDynamicsCompressor();
      this.compressor.threshold.value = -12;
      this.compressor.knee.value = 10;
      this.compressor.ratio.value = 4;
      this.compressor.attack.value = 0.005;
      this.compressor.release.value = 0.1;
      this.compressor.connect(this.ctx.destination);

      // Master gain
      this.masterGain = this.ctx.createGain();
      this.masterGain.gain.value = this.muted ? 0 : 1;
      this.masterGain.connect(this.compressor);

      // SFX bus
      this.sfxGain = this.ctx.createGain();
      this.sfxGain.gain.value = this.sfxVolume;
      this.sfxGain.connect(this.masterGain);

      // Music bus
      this.musicGain = this.ctx.createGain();
      this.musicGain.gain.value = this.musicVolume;
      this.musicGain.connect(this.masterGain);

      // Общий реверб (ConvolverNode с синтетическим импульсом)
      this._createReverb();

      this.initialized = true;
    } catch (e) {
      console.warn('[GameAudio] Failed to create AudioContext:', e.message);
      this.initialized = false;
    }
  },

  /** Создать ConvolverNode с синтетическим импульсным откликом */
  _createReverb() {
    const ctx = this.ctx;
    const sampleRate = ctx.sampleRate;
    const length = Math.floor(sampleRate * 1.5); // 1.5 сек реверб
    const impulse = ctx.createBuffer(2, length, sampleRate);
    for (let ch = 0; ch < 2; ch++) {
      const data = impulse.getChannelData(ch);
      for (let i = 0; i < length; i++) {
        // Экспоненциально затухающий шум
        data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / length, 2.5);
      }
    }
    this.reverbNode = ctx.createConvolver();
    this.reverbNode.buffer = impulse;
    this.reverbGain = ctx.createGain();
    this.reverbGain.gain.value = 0.3;
    this.reverbNode.connect(this.reverbGain);
    this.reverbGain.connect(this.masterGain);
  },

  /* ============================================================
     Settings persistence
     ============================================================ */

  _loadSettings() {
    try {
      const raw = SafeStorage.getItem(AUDIO_SETTINGS_KEY);
      if (raw) {
        const s = JSON.parse(raw);
        if (typeof s.sfxVolume === 'number') this.sfxVolume = s.sfxVolume;
        if (typeof s.musicVolume === 'number') this.musicVolume = s.musicVolume;
        if (typeof s.muted === 'boolean') this.muted = s.muted;
      }
    } catch (e) { /* ignore */ }
  },

  _saveSettings() {
    try {
      SafeStorage.setItem(AUDIO_SETTINGS_KEY, JSON.stringify({
        sfxVolume: this.sfxVolume,
        musicVolume: this.musicVolume,
        muted: this.muted,
      }));
    } catch (e) { /* ignore */ }
  },

  setSfxVolume(v) {
    this.sfxVolume = Math.max(0, Math.min(1, v));
    if (this.sfxGain) this.sfxGain.gain.value = this.sfxVolume;
    this._saveSettings();
  },
  setMusicVolume(v) {
    this.musicVolume = Math.max(0, Math.min(1, v));
    if (this.musicGain) this.musicGain.gain.value = this.musicVolume;
    this._saveSettings();
  },
  setMuted(v) {
    this.muted = !!v;
    if (this.masterGain) this.masterGain.gain.value = this.muted ? 0 : 1;
    this._saveSettings();
  },
  toggleMute() { this.setMuted(!this.muted); },

  /* ============================================================
     Helpers: oscillator tracking, noise buffers, ADSR
     ============================================================ */

  _canPlay() {
    if (!this.initialized || !this.ctx) return false;
    // Bug fix: если контекст suspended (мобильные), пытаемся возобновить
    if (this.ctx.state === 'suspended') {
      this.ctx.resume().catch(() => {});
      return false; // в этом кадре пропускаем, в следующем сыграет
    }
    return this.ctx.state === 'running' && this._activeOscCount < this._maxOsc;
  },

  _trackOsc(osc) {
    this._activeOscCount++;
    osc.onended = () => { this._activeOscCount = Math.max(0, this._activeOscCount - 1); };
  },

  /** Белый шум заданной длительности */
  _noiseBuffer(duration) {
    const ctx = this.ctx;
    const len = Math.floor(ctx.sampleRate * duration);
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
    return buf;
  },

  /** Коричневый шум (интеграция белого) */
  _brownNoiseBuffer(duration) {
    const ctx = this.ctx;
    const len = Math.floor(ctx.sampleRate * duration);
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const d = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const w = Math.random() * 2 - 1;
      last = (last + 0.02 * w) / 1.02;
      d[i] = last * 3.5;
    }
    return buf;
  },

  /** ADSR-огибающая на GainNode. Возвращает общую длительность. */
  _applyADSR(gainNode, t, a, d, s, r, peak) {
    peak = peak || 1.0;
    const g = gainNode.gain;
    g.setValueAtTime(0.001, t);
    g.linearRampToValueAtTime(peak, t + a);
    g.linearRampToValueAtTime(peak * s, t + a + d);
    // sustain удерживается; release запланируем позже
    return { sustainEnd: t + a + d };
  },

  /** Запланировать release на GainNode */
  _scheduleRelease(gainNode, startTime, releaseTime, sustainLevel) {
    const g = gainNode.gain;
    g.setValueAtTime(sustainLevel, startTime);
    g.exponentialRampToValueAtTime(0.001, startTime + releaseTime);
  },

  /** Создать waveshaper для лёгкого distortion */
  _createDistortion(amount) {
    const ctx = this.ctx;
    const ws = ctx.createWaveShaper();
    const k = amount || 50;
    const n = 44100;
    const curve = new Float32Array(n);
    for (let i = 0; i < n; i++) {
      const x = (i * 2) / n - 1;
      curve[i] = ((3 + k) * x * 20 * (Math.PI / 180)) / (Math.PI + k * Math.abs(x));
    }
    ws.curve = curve;
    ws.oversample = '2x';
    return ws;
  },

  /* ============================================================
     Sound Effects (SFX) — Dispatcher
     ============================================================ */

  playSfx(type, opts) {
    if (!this._canPlay()) return;
    switch (type) {
      case 'sword':       this._sfxSword(); break;
      case 'bow':         this._sfxBow(); break;
      case 'magic':       this._sfxMagic(); break;
      case 'heavy':       this._sfxHeavy(); break;
      case 'explosion':   this._sfxExplosion(); break;
      case 'ice':         this._sfxIce(); break;
      case 'lightning':   this._sfxLightning(); break;
      case 'poison':      this._sfxPoison(); break;
      case 'xp':          this._sfxXp(); break;
      case 'xp_red':      this._sfxXpRed(); break;
      case 'xp_blue':     this._sfxXpBlue(); break;
      case 'xp_yellow':   this._sfxXpYellow(); break;
      case 'gold':        this._sfxGold(); break;
      case 'levelup':     this._sfxLevelUp(); break;
      case 'death':       this._sfxDeath(); break;
      case 'chest':       this._sfxChest(); break;
      case 'd20':         this._sfxD20(); break;
      case 'boss_appear': this._sfxBossAppear(); break;
      case 'boss_roar':   this._sfxBossRoar(); break;
      case 'boss_death':  this._sfxBossDeath(); break;
      case 'enemy_hit':   this._sfxEnemyHit(opts); break;
      case 'enemy_death': this._sfxEnemyDeath(); break;
      case 'step':        this._sfxStep(); break;
      case 'apple_crunch': this._sfxAppleCrunch(); break;
      case 'urn_break':    this._sfxUrnBreak(); break;
    }
  },

  /* ============================================================
     WEAPON SOUNDS
     ============================================================ */

  /** Меч: металлический лязг (шум + bandpass 3кГц + низкий гул) */
  _sfxSword() {
    const ctx = this.ctx, t = ctx.currentTime;
    // Шум-компонент (металлический)
    const nBuf = this._noiseBuffer(0.08);
    const nSrc = ctx.createBufferSource();
    nSrc.buffer = nBuf;
    const bp = ctx.createBiquadFilter();
    bp.type = 'bandpass'; bp.frequency.value = 3000; bp.Q.value = 3;
    const nGain = ctx.createGain();
    nGain.gain.setValueAtTime(0.5, t);
    nGain.gain.exponentialRampToValueAtTime(0.001, t + 0.08);
    nSrc.connect(bp); bp.connect(nGain);
    nGain.connect(this.sfxGain);
    nSrc.start(t); nSrc.stop(t + 0.09);
    this._trackOsc(nSrc);
    // Низкий гул (triangle 150 Гц)
    const osc = ctx.createOscillator();
    osc.type = 'triangle'; osc.frequency.value = 150;
    const oGain = ctx.createGain();
    oGain.gain.setValueAtTime(0.3, t);
    oGain.gain.exponentialRampToValueAtTime(0.001, t + 0.06);
    osc.connect(oGain); oGain.connect(this.sfxGain);
    osc.start(t); osc.stop(t + 0.07);
    this._trackOsc(osc);
  },

  /** Лук: тетива (triangle sweep 800→400 + щипок) */
  _sfxBow() {
    const ctx = this.ctx, t = ctx.currentTime;
    const osc = ctx.createOscillator();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(800, t);
    osc.frequency.exponentialRampToValueAtTime(400, t + 0.08);
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.001, t);
    gain.gain.linearRampToValueAtTime(0.35, t + 0.002);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.08);
    osc.connect(gain); gain.connect(this.sfxGain);
    // Тихий шум щипка
    const nBuf = this._noiseBuffer(0.03);
    const nSrc = ctx.createBufferSource(); nSrc.buffer = nBuf;
    const nGain = ctx.createGain();
    nGain.gain.setValueAtTime(0.15, t);
    nGain.gain.exponentialRampToValueAtTime(0.001, t + 0.03);
    const hp = ctx.createBiquadFilter();
    hp.type = 'highpass'; hp.frequency.value = 4000;
    nSrc.connect(hp); hp.connect(nGain); nGain.connect(this.sfxGain);
    nSrc.start(t); nSrc.stop(t + 0.04);
    osc.start(t); osc.stop(t + 0.09);
    this._trackOsc(osc); this._trackOsc(nSrc);
  },

  /** Магия: синус 600 Гц с вибрато + шипение + реверберация */
  _sfxMagic() {
    const ctx = this.ctx, t = ctx.currentTime;
    const dur = 0.15;
    const osc = ctx.createOscillator();
    osc.type = 'sine'; osc.frequency.value = 600;
    // Вибрато (LFO 30 Гц)
    const lfo = ctx.createOscillator();
    lfo.frequency.value = 30;
    const lfoG = ctx.createGain(); lfoG.gain.value = 50;
    lfo.connect(lfoG); lfoG.connect(osc.frequency);
    // Огибающая
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.001, t);
    gain.gain.linearRampToValueAtTime(0.35, t + 0.02);
    gain.gain.setValueAtTime(0.3, t + dur * 0.5);
    gain.gain.exponentialRampToValueAtTime(0.001, t + dur);
    osc.connect(gain);
    gain.connect(this.sfxGain);
    // Отправить в реверб
    if (this.reverbNode) gain.connect(this.reverbNode);
    // Шипение
    const nBuf = this._noiseBuffer(dur);
    const nSrc = ctx.createBufferSource(); nSrc.buffer = nBuf;
    const nBp = ctx.createBiquadFilter();
    nBp.type = 'highpass'; nBp.frequency.value = 6000;
    const nG = ctx.createGain();
    nG.gain.setValueAtTime(0.08, t);
    nG.gain.exponentialRampToValueAtTime(0.001, t + dur);
    nSrc.connect(nBp); nBp.connect(nG); nG.connect(this.sfxGain);
    osc.start(t); lfo.start(t); nSrc.start(t);
    osc.stop(t + dur + 0.01); lfo.stop(t + dur + 0.01); nSrc.stop(t + dur + 0.01);
    this._trackOsc(osc); this._trackOsc(lfo); this._trackOsc(nSrc);
  },

  /** Молот: тяжёлый удар (triangle 80 Гц + шум, компрессия) */
  _sfxHeavy() {
    const ctx = this.ctx, t = ctx.currentTime;
    const dur = 0.2;
    // Низкий удар
    const osc = ctx.createOscillator();
    osc.type = 'triangle'; osc.frequency.value = 80;
    const oG = ctx.createGain();
    oG.gain.setValueAtTime(0.001, t);
    oG.gain.linearRampToValueAtTime(0.6, t + 0.005);
    oG.gain.exponentialRampToValueAtTime(0.001, t + dur);
    osc.connect(oG); oG.connect(this.sfxGain);
    // Шум удара
    const nBuf = this._noiseBuffer(0.1);
    const nSrc = ctx.createBufferSource(); nSrc.buffer = nBuf;
    const lp = ctx.createBiquadFilter();
    lp.type = 'lowpass'; lp.frequency.value = 1500;
    const nG = ctx.createGain();
    nG.gain.setValueAtTime(0.4, t);
    nG.gain.exponentialRampToValueAtTime(0.001, t + 0.1);
    nSrc.connect(lp); lp.connect(nG); nG.connect(this.sfxGain);
    osc.start(t); nSrc.start(t);
    osc.stop(t + dur + 0.01); nSrc.stop(t + 0.11);
    this._trackOsc(osc); this._trackOsc(nSrc);
  },

  /** Взрыв/огонь: коричневый шум 300мс + triangle 60 Гц + реверб */
  _sfxExplosion() {
    const ctx = this.ctx, t = ctx.currentTime;
    const dur = 0.3;
    // Коричневый шум
    const nBuf = this._brownNoiseBuffer(dur);
    const nSrc = ctx.createBufferSource(); nSrc.buffer = nBuf;
    const nG = ctx.createGain();
    nG.gain.setValueAtTime(0.001, t);
    nG.gain.linearRampToValueAtTime(0.7, t + 0.005);
    nG.gain.exponentialRampToValueAtTime(0.001, t + dur);
    nSrc.connect(nG); nG.connect(this.sfxGain);
    if (this.reverbNode) nG.connect(this.reverbNode);
    // Низкий тон
    const osc = ctx.createOscillator();
    osc.type = 'triangle'; osc.frequency.value = 60;
    const oG = ctx.createGain();
    oG.gain.setValueAtTime(0.001, t);
    oG.gain.linearRampToValueAtTime(0.5, t + 0.005);
    oG.gain.exponentialRampToValueAtTime(0.001, t + dur);
    osc.connect(oG); oG.connect(this.sfxGain);
    nSrc.start(t); osc.start(t);
    nSrc.stop(t + dur + 0.01); osc.stop(t + dur + 0.01);
    this._trackOsc(nSrc); this._trackOsc(osc);
  },

  /** Лёд: triangle 2000→1000 Гц + хрустальный шум (bandpass 5кГц) */
  _sfxIce() {
    const ctx = this.ctx, t = ctx.currentTime;
    const dur = 0.1;
    const osc = ctx.createOscillator();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(2000, t);
    osc.frequency.exponentialRampToValueAtTime(1000, t + dur);
    const oG = ctx.createGain();
    oG.gain.setValueAtTime(0.001, t);
    oG.gain.linearRampToValueAtTime(0.35, t + 0.005);
    oG.gain.exponentialRampToValueAtTime(0.001, t + dur);
    osc.connect(oG); oG.connect(this.sfxGain);
    // Хрустальный шум
    const nBuf = this._noiseBuffer(0.08);
    const nSrc = ctx.createBufferSource(); nSrc.buffer = nBuf;
    const bp = ctx.createBiquadFilter();
    bp.type = 'bandpass'; bp.frequency.value = 5000; bp.Q.value = 4;
    const nG = ctx.createGain();
    nG.gain.setValueAtTime(0.2, t);
    nG.gain.exponentialRampToValueAtTime(0.001, t + 0.08);
    nSrc.connect(bp); bp.connect(nG); nG.connect(this.sfxGain);
    osc.start(t); nSrc.start(t);
    osc.stop(t + dur + 0.01); nSrc.stop(t + 0.09);
    this._trackOsc(osc); this._trackOsc(nSrc);
  },

  /** Молния: пила 200 Гц + шум bandpass 1кГц + хорус */
  _sfxLightning() {
    const ctx = this.ctx, t = ctx.currentTime;
    const dur = 0.15;
    // Основной тон
    const osc1 = ctx.createOscillator();
    osc1.type = 'sawtooth'; osc1.frequency.value = 200;
    // Хорус: слегка расстроенная копия
    const osc2 = ctx.createOscillator();
    osc2.type = 'sawtooth'; osc2.frequency.value = 203;
    const oG = ctx.createGain();
    oG.gain.setValueAtTime(0.001, t);
    oG.gain.linearRampToValueAtTime(0.3, t + 0.001);
    oG.gain.exponentialRampToValueAtTime(0.001, t + dur);
    osc1.connect(oG); osc2.connect(oG); oG.connect(this.sfxGain);
    // Шум-компонент
    const nBuf = this._noiseBuffer(dur);
    const nSrc = ctx.createBufferSource(); nSrc.buffer = nBuf;
    const bp = ctx.createBiquadFilter();
    bp.type = 'bandpass'; bp.frequency.value = 1000; bp.Q.value = 2;
    const nG = ctx.createGain();
    nG.gain.setValueAtTime(0.25, t);
    nG.gain.exponentialRampToValueAtTime(0.001, t + dur);
    nSrc.connect(bp); bp.connect(nG); nG.connect(this.sfxGain);
    osc1.start(t); osc2.start(t); nSrc.start(t);
    osc1.stop(t + dur + 0.01); osc2.stop(t + dur + 0.01); nSrc.stop(t + dur + 0.01);
    this._trackOsc(osc1); this._trackOsc(osc2); this._trackOsc(nSrc);
  },

  /** Яд: пузырящийся шум с LFO + triangle 300 Гц */
  _sfxPoison() {
    const ctx = this.ctx, t = ctx.currentTime;
    const dur = 0.5;
    // Triangle основа
    const osc = ctx.createOscillator();
    osc.type = 'triangle'; osc.frequency.value = 300;
    const oG = ctx.createGain();
    oG.gain.setValueAtTime(0.001, t);
    oG.gain.linearRampToValueAtTime(0.2, t + 0.03);
    oG.gain.exponentialRampToValueAtTime(0.001, t + dur);
    osc.connect(oG); oG.connect(this.sfxGain);
    // Пузыри: шум модулированный LFO
    const nBuf = this._noiseBuffer(dur);
    const nSrc = ctx.createBufferSource(); nSrc.buffer = nBuf;
    const bp = ctx.createBiquadFilter();
    bp.type = 'bandpass'; bp.frequency.value = 800; bp.Q.value = 3;
    // LFO на громкость шума (эффект пузырей)
    const nG = ctx.createGain(); nG.gain.value = 0;
    const lfo = ctx.createOscillator();
    lfo.frequency.value = 8;
    const lfoG = ctx.createGain(); lfoG.gain.value = 0.15;
    lfo.connect(lfoG); lfoG.connect(nG.gain);
    nSrc.connect(bp); bp.connect(nG); nG.connect(this.sfxGain);
    osc.start(t); nSrc.start(t); lfo.start(t);
    osc.stop(t + dur + 0.01); nSrc.stop(t + dur + 0.01); lfo.stop(t + dur + 0.01);
    this._trackOsc(osc); this._trackOsc(nSrc); this._trackOsc(lfo);
  },

  /* ============================================================
     PICKUP SOUNDS
     ============================================================ */

  /** Опыт (зелёный): две triangle ноты 1200→1800 Гц */
  _sfxXp() {
    const ctx = this.ctx, t = ctx.currentTime;
    const osc = ctx.createOscillator();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(1200, t);
    osc.frequency.exponentialRampToValueAtTime(1800, t + 0.06);
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.001, t);
    gain.gain.linearRampToValueAtTime(0.2, t + 0.005);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.06);
    osc.connect(gain); gain.connect(this.sfxGain);
    osc.start(t); osc.stop(t + 0.07);
    this._trackOsc(osc);
  },

  /** Опыт красный (×10): 1500→2200 Гц + лёгкий хорус */
  _sfxXpRed() {
    const ctx = this.ctx, t = ctx.currentTime;
    const dur = 0.08;
    const osc1 = ctx.createOscillator();
    osc1.type = 'triangle';
    osc1.frequency.setValueAtTime(1500, t);
    osc1.frequency.exponentialRampToValueAtTime(2200, t + dur);
    const osc2 = ctx.createOscillator();
    osc2.type = 'triangle';
    osc2.frequency.setValueAtTime(1503, t);
    osc2.frequency.exponentialRampToValueAtTime(2205, t + dur);
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.001, t);
    gain.gain.linearRampToValueAtTime(0.22, t + 0.005);
    gain.gain.exponentialRampToValueAtTime(0.001, t + dur);
    osc1.connect(gain); osc2.connect(gain); gain.connect(this.sfxGain);
    osc1.start(t); osc2.start(t);
    osc1.stop(t + dur + 0.01); osc2.stop(t + dur + 0.01);
    this._trackOsc(osc1); this._trackOsc(osc2);
  },

  /** Опыт синий (×100): арпеджио C5-E5-G5 за 150мс */
  _sfxXpBlue() {
    const ctx = this.ctx, t = ctx.currentTime;
    const notes = [523, 659, 784];
    const noteDur = 0.05;
    notes.forEach((freq, i) => {
      const osc = ctx.createOscillator();
      osc.type = 'triangle'; osc.frequency.value = freq;
      const g = ctx.createGain();
      const s = t + i * noteDur;
      g.gain.setValueAtTime(0.001, s);
      g.gain.linearRampToValueAtTime(0.25, s + 0.005);
      g.gain.exponentialRampToValueAtTime(0.001, s + noteDur);
      osc.connect(g); g.connect(this.sfxGain);
      osc.start(s); osc.stop(s + noteDur + 0.01);
      this._trackOsc(osc);
    });
  },

  /** Опыт жёлтый (×1000): торжественное арпеджио 5 нот + реверб */
  _sfxXpYellow() {
    const ctx = this.ctx, t = ctx.currentTime;
    const notes = [523, 659, 784, 1047, 1319]; // C5-E5-G5-C6-E6
    const noteDur = 0.05;
    notes.forEach((freq, i) => {
      const osc = ctx.createOscillator();
      osc.type = 'triangle'; osc.frequency.value = freq;
      const g = ctx.createGain();
      const s = t + i * noteDur;
      g.gain.setValueAtTime(0.001, s);
      g.gain.linearRampToValueAtTime(0.28, s + 0.005);
      g.gain.setValueAtTime(0.25, s + noteDur * 0.7);
      g.gain.exponentialRampToValueAtTime(0.001, s + noteDur * 1.5);
      osc.connect(g); g.connect(this.sfxGain);
      if (this.reverbNode) g.connect(this.reverbNode);
      osc.start(s); osc.stop(s + noteDur * 1.5 + 0.01);
      this._trackOsc(osc);
    });
  },

  /** Золото: монетка triangle 2500→3000 + шум звона */
  _sfxGold() {
    const ctx = this.ctx, t = ctx.currentTime;
    const dur = 0.04;
    const osc = ctx.createOscillator();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(2500, t);
    osc.frequency.exponentialRampToValueAtTime(3000, t + dur);
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.001, t);
    gain.gain.linearRampToValueAtTime(0.3, t + 0.002);
    gain.gain.exponentialRampToValueAtTime(0.001, t + dur);
    osc.connect(gain); gain.connect(this.sfxGain);
    // Звон (шум bandpass)
    const nBuf = this._noiseBuffer(0.03);
    const nSrc = ctx.createBufferSource(); nSrc.buffer = nBuf;
    const bp = ctx.createBiquadFilter();
    bp.type = 'bandpass'; bp.frequency.value = 6000; bp.Q.value = 5;
    const nG = ctx.createGain();
    nG.gain.setValueAtTime(0.12, t);
    nG.gain.exponentialRampToValueAtTime(0.001, t + 0.03);
    nSrc.connect(bp); bp.connect(nG); nG.connect(this.sfxGain);
    osc.start(t); nSrc.start(t);
    osc.stop(t + dur + 0.01); nSrc.stop(t + 0.04);
    this._trackOsc(osc); this._trackOsc(nSrc);
  },

  /* ============================================================
     EVENT SOUNDS
     ============================================================ */

  /** Повышение уровня: «Та-даа!» C5-E5-G5 triangle + хорус + реверб */
  _sfxLevelUp() {
    const ctx = this.ctx, t = ctx.currentTime;
    const notes = [523, 659, 784];
    const noteDur = 0.1;
    notes.forEach((freq, i) => {
      // Основной
      const osc1 = ctx.createOscillator();
      osc1.type = 'triangle'; osc1.frequency.value = freq;
      // Хорус
      const osc2 = ctx.createOscillator();
      osc2.type = 'triangle'; osc2.frequency.value = freq * 1.005;
      const g = ctx.createGain();
      const s = t + i * noteDur;
      g.gain.setValueAtTime(0.001, s);
      g.gain.linearRampToValueAtTime(0.3, s + 0.01);
      g.gain.setValueAtTime(0.28, s + noteDur * 0.7);
      g.gain.exponentialRampToValueAtTime(0.001, s + noteDur * 1.2);
      osc1.connect(g); osc2.connect(g);
      g.connect(this.sfxGain);
      if (this.reverbNode) g.connect(this.reverbNode);
      osc1.start(s); osc2.start(s);
      osc1.stop(s + noteDur * 1.2 + 0.01);
      osc2.stop(s + noteDur * 1.2 + 0.01);
      this._trackOsc(osc1); this._trackOsc(osc2);
    });
  },

  /** Смерть героя: triangle 400→80 Гц за 600мс + хорус + реверб */
  _sfxDeath() {
    const ctx = this.ctx, t = ctx.currentTime;
    const dur = 0.6;
    const osc1 = ctx.createOscillator();
    osc1.type = 'triangle';
    osc1.frequency.setValueAtTime(400, t);
    osc1.frequency.exponentialRampToValueAtTime(80, t + dur);
    const osc2 = ctx.createOscillator();
    osc2.type = 'triangle';
    osc2.frequency.setValueAtTime(403, t);
    osc2.frequency.exponentialRampToValueAtTime(81, t + dur);
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.001, t);
    gain.gain.linearRampToValueAtTime(0.5, t + 0.02);
    gain.gain.exponentialRampToValueAtTime(0.001, t + dur);
    osc1.connect(gain); osc2.connect(gain);
    gain.connect(this.sfxGain);
    if (this.reverbNode) gain.connect(this.reverbNode);
    osc1.start(t); osc2.start(t);
    osc1.stop(t + dur + 0.01); osc2.stop(t + dur + 0.01);
    this._trackOsc(osc1); this._trackOsc(osc2);
  },

  /** Открытие сундука: скрип (bandpass 4кГц) + звон монет */
  _sfxChest() {
    const ctx = this.ctx, t = ctx.currentTime;
    // Скрип
    const nBuf = this._noiseBuffer(0.1);
    const nSrc = ctx.createBufferSource(); nSrc.buffer = nBuf;
    const bp = ctx.createBiquadFilter();
    bp.type = 'bandpass'; bp.frequency.value = 4000; bp.Q.value = 6;
    const nG = ctx.createGain();
    nG.gain.setValueAtTime(0.001, t);
    nG.gain.linearRampToValueAtTime(0.3, t + 0.01);
    nG.gain.exponentialRampToValueAtTime(0.001, t + 0.1);
    nSrc.connect(bp); bp.connect(nG); nG.connect(this.sfxGain);
    nSrc.start(t); nSrc.stop(t + 0.11);
    this._trackOsc(nSrc);
    // Звон монет (после скрипа)
    const jingleStart = t + 0.08;
    const jingleNotes = [2200, 2800, 3200];
    jingleNotes.forEach((freq, i) => {
      const osc = ctx.createOscillator();
      osc.type = 'triangle'; osc.frequency.value = freq;
      const g = ctx.createGain();
      const s = jingleStart + i * 0.03;
      g.gain.setValueAtTime(0.001, s);
      g.gain.linearRampToValueAtTime(0.2, s + 0.003);
      g.gain.exponentialRampToValueAtTime(0.001, s + 0.06);
      osc.connect(g); g.connect(this.sfxGain);
      osc.start(s); osc.stop(s + 0.07);
      this._trackOsc(osc);
    });
  },

  /** Бросок d20: три щелчка + финальный громче + реверб */
  _sfxD20() {
    const ctx = this.ctx, t = ctx.currentTime;
    const clickDur = 0.02;
    const gap = 0.03;
    for (let i = 0; i < 3; i++) {
      const start = t + i * (clickDur + gap);
      const buf = this._noiseBuffer(clickDur);
      const src = ctx.createBufferSource(); src.buffer = buf;
      const bp = ctx.createBiquadFilter();
      bp.type = 'bandpass'; bp.frequency.value = 3000; bp.Q.value = 2;
      const g = ctx.createGain();
      const vol = (i === 2) ? 0.5 : 0.3;
      g.gain.setValueAtTime(vol, start);
      g.gain.exponentialRampToValueAtTime(0.001, start + clickDur);
      src.connect(bp); bp.connect(g); g.connect(this.sfxGain);
      if (i === 2 && this.reverbNode) g.connect(this.reverbNode);
      src.start(start); src.stop(start + clickDur + 0.01);
      this._trackOsc(src);
    }
  },

  /* ============================================================
     BOSS SOUNDS
     ============================================================ */

  /** Появление босса: низкий гул triangle 40 Гц с вибрато, 2 сек + реверб */
  _sfxBossAppear() {
    const ctx = this.ctx, t = ctx.currentTime;
    const dur = 2.0;
    const osc = ctx.createOscillator();
    osc.type = 'triangle'; osc.frequency.value = 40;
    // Вибрато
    const lfo = ctx.createOscillator(); lfo.frequency.value = 4;
    const lfoG = ctx.createGain(); lfoG.gain.value = 5;
    lfo.connect(lfoG); lfoG.connect(osc.frequency);
    // Огибающая: медленный attack
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.001, t);
    gain.gain.linearRampToValueAtTime(0.4, t + 0.5);
    gain.gain.setValueAtTime(0.35, t + dur - 0.3);
    gain.gain.exponentialRampToValueAtTime(0.001, t + dur);
    osc.connect(gain); gain.connect(this.sfxGain);
    if (this.reverbNode) gain.connect(this.reverbNode);
    // Шум (атмосфера)
    const nBuf = this._brownNoiseBuffer(dur);
    const nSrc = ctx.createBufferSource(); nSrc.buffer = nBuf;
    const nG = ctx.createGain();
    nG.gain.setValueAtTime(0.001, t);
    nG.gain.linearRampToValueAtTime(0.15, t + 0.5);
    nG.gain.exponentialRampToValueAtTime(0.001, t + dur);
    const lp = ctx.createBiquadFilter();
    lp.type = 'lowpass'; lp.frequency.value = 300;
    nSrc.connect(lp); lp.connect(nG); nG.connect(this.sfxGain);
    osc.start(t); lfo.start(t); nSrc.start(t);
    osc.stop(t + dur + 0.01); lfo.stop(t + dur + 0.01); nSrc.stop(t + dur + 0.01);
    this._trackOsc(osc); this._trackOsc(lfo); this._trackOsc(nSrc);
  },

  /** Рёв босса: пила 100 Гц + шум + distortion, 800мс */
  _sfxBossRoar() {
    const ctx = this.ctx, t = ctx.currentTime;
    const dur = 0.8;
    const osc = ctx.createOscillator();
    osc.type = 'sawtooth'; osc.frequency.value = 100;
    // LFO модуляция частоты
    const lfo = ctx.createOscillator(); lfo.frequency.value = 6;
    const lfoG = ctx.createGain(); lfoG.gain.value = 20;
    lfo.connect(lfoG); lfoG.connect(osc.frequency);
    const dist = this._createDistortion(30);
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.001, t);
    gain.gain.linearRampToValueAtTime(0.45, t + 0.1);
    gain.gain.setValueAtTime(0.4, t + dur * 0.5);
    gain.gain.exponentialRampToValueAtTime(0.001, t + dur);
    osc.connect(dist); dist.connect(gain); gain.connect(this.sfxGain);
    // Шум
    const nBuf = this._noiseBuffer(dur);
    const nSrc = ctx.createBufferSource(); nSrc.buffer = nBuf;
    const lp = ctx.createBiquadFilter();
    lp.type = 'lowpass'; lp.frequency.value = 500;
    const nG = ctx.createGain();
    nG.gain.setValueAtTime(0.001, t);
    nG.gain.linearRampToValueAtTime(0.2, t + 0.1);
    nG.gain.exponentialRampToValueAtTime(0.001, t + dur);
    nSrc.connect(lp); lp.connect(nG); nG.connect(this.sfxGain);
    osc.start(t); lfo.start(t); nSrc.start(t);
    osc.stop(t + dur + 0.01); lfo.stop(t + dur + 0.01); nSrc.stop(t + dur + 0.01);
    this._trackOsc(osc); this._trackOsc(lfo); this._trackOsc(nSrc);
  },

  /** Смерть босса: громкий взрыв + глубокий реверб, 1 сек */
  _sfxBossDeath() {
    const ctx = this.ctx, t = ctx.currentTime;
    const dur = 1.0;
    // Мощный коричневый шум
    const nBuf = this._brownNoiseBuffer(0.5);
    const nSrc = ctx.createBufferSource(); nSrc.buffer = nBuf;
    const nG = ctx.createGain();
    nG.gain.setValueAtTime(0.001, t);
    nG.gain.linearRampToValueAtTime(0.7, t + 0.01);
    nG.gain.exponentialRampToValueAtTime(0.001, t + 0.5);
    nSrc.connect(nG); nG.connect(this.sfxGain);
    if (this.reverbNode) nG.connect(this.reverbNode);
    // Низкий triangle гул
    const osc = ctx.createOscillator();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(50, t);
    osc.frequency.exponentialRampToValueAtTime(25, t + dur);
    const oG = ctx.createGain();
    oG.gain.setValueAtTime(0.001, t);
    oG.gain.linearRampToValueAtTime(0.6, t + 0.02);
    oG.gain.exponentialRampToValueAtTime(0.001, t + dur);
    osc.connect(oG); oG.connect(this.sfxGain);
    if (this.reverbNode) oG.connect(this.reverbNode);
    nSrc.start(t); osc.start(t);
    nSrc.stop(t + 0.51); osc.stop(t + dur + 0.01);
    this._trackOsc(nSrc); this._trackOsc(osc);
  },

  /* ============================================================
     ENEMY SOUNDS
     ============================================================ */

  /** Боль врага: короткий писк/шум (частота зависит от типа) */
  _sfxEnemyHit(opts) {
    const ctx = this.ctx, t = ctx.currentTime;
    const dur = 0.05;
    const freq = (opts && opts.freq) || 800;
    const osc = ctx.createOscillator();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(freq, t);
    osc.frequency.exponentialRampToValueAtTime(freq * 0.6, t + dur);
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.001, t);
    gain.gain.linearRampToValueAtTime(0.15, t + 0.002);
    gain.gain.exponentialRampToValueAtTime(0.001, t + dur);
    osc.connect(gain); gain.connect(this.sfxGain);
    osc.start(t); osc.stop(t + dur + 0.01);
    this._trackOsc(osc);
  },

  /** Смерть врага: тихий «dusting» (шум bandpass + triangle 400→200) */
  _sfxEnemyDeath() {
    const ctx = this.ctx, t = ctx.currentTime;
    const dur = 0.1;
    // Шум dusting
    const nBuf = this._noiseBuffer(dur);
    const nSrc = ctx.createBufferSource(); nSrc.buffer = nBuf;
    const bp = ctx.createBiquadFilter();
    bp.type = 'bandpass'; bp.frequency.value = 2000; bp.Q.value = 2;
    const nG = ctx.createGain();
    nG.gain.setValueAtTime(0.1, t);
    nG.gain.exponentialRampToValueAtTime(0.001, t + dur);
    nSrc.connect(bp); bp.connect(nG); nG.connect(this.sfxGain);
    // Тон
    const osc = ctx.createOscillator();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(400, t);
    osc.frequency.exponentialRampToValueAtTime(200, t + dur);
    const oG = ctx.createGain();
    oG.gain.setValueAtTime(0.08, t);
    oG.gain.exponentialRampToValueAtTime(0.001, t + dur);
    osc.connect(oG); oG.connect(this.sfxGain);
    nSrc.start(t); osc.start(t);
    nSrc.stop(t + dur + 0.01); osc.stop(t + dur + 0.01);
    this._trackOsc(nSrc); this._trackOsc(osc);
  },

  /** Шаги героя: тихий шум bandpass 200 Гц, throttled */
  _sfxStep() {
    const ctx = this.ctx, t = ctx.currentTime;
    // Throttle
    if (t - this._lastStepTime < this._stepInterval) return;
    this._lastStepTime = t;
    const dur = 0.05;
    const nBuf = this._noiseBuffer(dur);
    const nSrc = ctx.createBufferSource(); nSrc.buffer = nBuf;
    const bp = ctx.createBiquadFilter();
    bp.type = 'bandpass'; bp.frequency.value = 200; bp.Q.value = 1;
    const nG = ctx.createGain();
    nG.gain.setValueAtTime(0.06, t);
    nG.gain.exponentialRampToValueAtTime(0.001, t + dur);
    nSrc.connect(bp); bp.connect(nG); nG.connect(this.sfxGain);
    nSrc.start(t); nSrc.stop(t + dur + 0.01);
    this._trackOsc(nSrc);
  },

  /* ============================================================
     Background Music (Ambient) — Полная переработка
     ============================================================ */

  playMusic(biomeId) {
    if (!this.initialized || !this.ctx) return;
    // Bug fix: пытаемся возобновить контекст если suspended
    if (this.ctx.state === 'suspended') {
      this.ctx.resume().catch(() => {});
    }
    if (this._musicBiome === biomeId && this._musicPlaying) return;
    this.stopMusic();

    const cfg = BIOME_MUSIC[biomeId];
    if (!cfg) return;

    this._musicBiome = biomeId;
    this._musicPlaying = true;

    const ctx = this.ctx;
    const t = ctx.currentTime;

    // --- Дрон: triangle/sine с low-pass фильтром + лёгкий хорус ---
    const drone = ctx.createOscillator();
    drone.type = cfg.wave || 'triangle';
    drone.frequency.value = cfg.drone;

    const droneGain = ctx.createGain();
    droneGain.gain.setValueAtTime(0, t);
    droneGain.gain.linearRampToValueAtTime(0.12, t + 2.0);

    // Low-pass на дроне для тёплого звука
    const droneFilter = ctx.createBiquadFilter();
    droneFilter.type = 'lowpass';
    droneFilter.frequency.value = cfg.filterFreq || 800;
    droneFilter.Q.value = 0.7;

    drone.connect(droneFilter);
    droneFilter.connect(droneGain);
    droneGain.connect(this.musicGain);

    // Хорус для дрона (слегка расстроенная копия)
    if (cfg.chorus) {
      const drone2 = ctx.createOscillator();
      drone2.type = cfg.wave || 'triangle';
      drone2.frequency.value = cfg.drone * 1.003;
      const d2Gain = ctx.createGain();
      d2Gain.gain.setValueAtTime(0, t);
      d2Gain.gain.linearRampToValueAtTime(0.08, t + 2.0);
      drone2.connect(droneFilter);
      drone2.start(t);
      this._musicHarmonics.push(drone2);
    }

    // Гармоники для органного звука (замок)
    if (cfg.harmonics) {
      [2, 3, 4].forEach((h) => {
        const ho = ctx.createOscillator();
        ho.type = 'sine';
        ho.frequency.value = cfg.drone * h;
        const hg = ctx.createGain();
        hg.gain.setValueAtTime(0, t);
        hg.gain.linearRampToValueAtTime(0.04 / h, t + 2.5);
        ho.connect(hg); hg.connect(droneGain);
        ho.start(t);
        this._musicHarmonics.push(ho);
      });
    }

    drone.start(t);
    this._musicDrone = drone;
    this._musicDroneGain = droneGain;
    this._musicDroneFilter = droneFilter;

    // Мелодические ноты (пентатоника)
    this._scheduleNote(cfg);
  },

  _scheduleNote(cfg) {
    if (!this._musicPlaying || !this.ctx) return;

    const [minI, maxI] = cfg.noteInterval;
    const delay = minI + Math.random() * (maxI - minI);

    this._musicNoteTimer = setTimeout(() => {
      if (!this._musicPlaying || !this.ctx) return;
      // Bug fix: если контекст suspended, перепланируем без воспроизведения
      if (this.ctx.state !== 'running') {
        this._scheduleNote(cfg);
        return;
      }

      try {
        const ctx = this.ctx;
        const t = ctx.currentTime;
        const freq = cfg.notes[Math.floor(Math.random() * cfg.notes.length)];
        const attack = cfg.noteAttack || 0.1;
        const decay = cfg.noteDecay || 0.3;
        const duration = attack + decay + 0.4 + Math.random() * 0.3;

        const osc = ctx.createOscillator();
        osc.type = cfg.noteWave || 'sine';
        osc.frequency.value = freq;

        // LFO на ноту (для лесных/эльфийских биомов)
        if (cfg.lfo) {
          const lfo = ctx.createOscillator();
          lfo.frequency.value = cfg.lfoRate || 3;
          const lG = ctx.createGain();
          lG.gain.value = cfg.lfoDepth || 5;
          lfo.connect(lG); lG.connect(osc.frequency);
          lfo.start(t); lfo.stop(t + duration + 0.1);
        }

        const noteGain = ctx.createGain();
        // ADSR
        noteGain.gain.setValueAtTime(0.001, t);
        noteGain.gain.linearRampToValueAtTime(0.1, t + attack);
        noteGain.gain.setValueAtTime(0.08, t + attack + decay * 0.5);
        noteGain.gain.exponentialRampToValueAtTime(0.001, t + duration);

        // Distortion для огненных/горных биомов
        if (cfg.distortion) {
          const dist = this._createDistortion(15);
          osc.connect(dist); dist.connect(noteGain);
        } else {
          osc.connect(noteGain);
        }

        noteGain.connect(this.musicGain);

        // Реверберация
        if (cfg.reverb && this.reverbNode) {
          const revSend = ctx.createGain();
          revSend.gain.value = 0.15;
          noteGain.connect(revSend);
          revSend.connect(this.reverbNode);
        }

        osc.start(t);
        osc.stop(t + duration + 0.1);
        osc.onended = () => { /* cleanup */ };
      } catch (e) {
        // Bug fix: не даём ошибкам в воспроизведении ноты сломать цикл
      }

      this._scheduleNote(cfg);
    }, delay * 1000);
  },

  stopMusic() {
    this._musicPlaying = false;
    this._musicBiome = null;

    if (this._musicNoteTimer) {
      clearTimeout(this._musicNoteTimer);
      this._musicNoteTimer = null;
    }

    // Останавливаем дрон с безопасным fade-out
    if (this._musicDrone) {
      try {
        const ctx = this.ctx;
        if (ctx && this._musicDroneGain && ctx.state === 'running') {
          const t = ctx.currentTime;
          this._musicDroneGain.gain.setValueAtTime(
            this._musicDroneGain.gain.value, t
          );
          this._musicDroneGain.gain.exponentialRampToValueAtTime(0.001, t + 0.5);
          this._musicDrone.stop(t + 0.6);
        } else {
          this._musicDrone.stop();
        }
      } catch (e) { /* already stopped or InvalidStateError */ }
      this._musicDrone = null;
      this._musicDroneGain = null;
      this._musicDroneFilter = null;
    }

    // Останавливаем дополнительные осцилляторы (хорус, гармоники)
    for (const h of this._musicHarmonics) {
      try { h.stop(); } catch (e) { /* ignore */ }
    }
    this._musicHarmonics = [];
  },

  pauseMusic() {
    if (this.ctx && this.ctx.state === 'running') {
      this.ctx.suspend().catch(() => {});
    }
  },

  resumeMusic() {
    if (this.ctx && this.ctx.state === 'suspended') {
      this.ctx.resume().catch(() => {});
    }
  },

  /* ============================================================
     Шаг 1: Звуки урн и яблок
     ============================================================ */

  /** Яблоко: сочный хруст (шум + low sine + bandpass) */
  _sfxAppleCrunch() {
    const ctx = this.ctx, t = ctx.currentTime;
    // Хруст (шум через bandpass)
    const nBuf = this._noiseBuffer(0.12);
    const nSrc = ctx.createBufferSource(); nSrc.buffer = nBuf;
    const bp = ctx.createBiquadFilter();
    bp.type = 'bandpass'; bp.frequency.value = 2000; bp.Q.value = 2;
    const nGain = ctx.createGain();
    nGain.gain.setValueAtTime(0.4, t);
    nGain.gain.exponentialRampToValueAtTime(0.001, t + 0.12);
    nSrc.connect(bp); bp.connect(nGain); nGain.connect(this.sfxGain);
    nSrc.start(t); nSrc.stop(t + 0.13);
    this._trackOsc(nSrc);
    // Сочный тон (sine 300 Hz, короткий)
    const osc = ctx.createOscillator();
    osc.type = 'sine'; osc.frequency.value = 300;
    osc.frequency.exponentialRampToValueAtTime(200, t + 0.08);
    const oGain = ctx.createGain();
    oGain.gain.setValueAtTime(0.25, t);
    oGain.gain.exponentialRampToValueAtTime(0.001, t + 0.08);
    osc.connect(oGain); oGain.connect(this.sfxGain);
    osc.start(t); osc.stop(t + 0.09);
    this._trackOsc(osc);
  },

  /** Урна: глухой удар + осколки (шум + low thud) */
  _sfxUrnBreak() {
    const ctx = this.ctx, t = ctx.currentTime;
    // Глухой удар (sine 100 Hz)
    const osc = ctx.createOscillator();
    osc.type = 'sine'; osc.frequency.value = 100;
    osc.frequency.exponentialRampToValueAtTime(50, t + 0.1);
    const oGain = ctx.createGain();
    oGain.gain.setValueAtTime(0.4, t);
    oGain.gain.exponentialRampToValueAtTime(0.001, t + 0.1);
    osc.connect(oGain); oGain.connect(this.sfxGain);
    osc.start(t); osc.stop(t + 0.11);
    this._trackOsc(osc);
    // Осколки (шум через highpass)
    const nBuf = this._noiseBuffer(0.1);
    const nSrc = ctx.createBufferSource(); nSrc.buffer = nBuf;
    const hp = ctx.createBiquadFilter();
    hp.type = 'highpass'; hp.frequency.value = 3000;
    const nGain = ctx.createGain();
    nGain.gain.setValueAtTime(0.3, t + 0.02);
    nGain.gain.exponentialRampToValueAtTime(0.001, t + 0.1);
    nSrc.connect(hp); hp.connect(nGain); nGain.connect(this.sfxGain);
    nSrc.start(t); nSrc.stop(t + 0.11);
    this._trackOsc(nSrc);
  },
};

window.GameAudio = GameAudio;

// === js/map/dungeon-generator.js ===
'use strict';
/* ============================================================
   map.js — карта, тайлы, камера, наземные эффекты + Шаг 5/13:
   процедурная генерация подземелья (комнаты, коридоры, ловушки,
   декор, миникарта). Шаг 13: биомы, портал, новые ловушки.
   ============================================================ */

/* ============================================================
   Простой детерминированный PRNG (Mulberry32). Используется при
   ненулевом seed; иначе берём Math.random().
   ============================================================ */
function _mulberry32(seed) {
  let s = seed >>> 0;
  return function() {
    s = (s + 0x6D2B79F5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const GameMap = {
  /** Совместимость со Шагом 4: пул наземных эффектов. */
  groundEffects: null,

  /** Глобальный rand-генератор для текущего забега. */
  rng: Math.random,

  /** Структура подземелья (заполняется generateDungeon). */
  dungeon: null,

  /** Тики времени (для анимаций ловушек/факелов). */
  time: 0,

  /** Кэш фоновых тайлов комнат — offscreen canvas (для производительности). */
  _floorCache: null,

  /** Шаг 13: текущий биом (объект из BIOMES). */
  currentBiome: null,

  /** Шаг 13: номер текущей карты (1-based). */
  currentMapNumber: 1,

  /** Шаг 13: портал (объект или null). */
  portal: null,

  /** Шаг 13: ширина/высота текущей карты (могут отличаться от CONFIG.MAP). */
  mapW: 2000,
  mapH: 2000,

  /* ============================================================
     Прекомпьют: создаёт пул эффектов. Подземелье генерируется
     отдельно (generateDungeon), уже после старта забега.
     ============================================================ */
  precompute() {
    if (!this.groundEffects) {
      this.groundEffects = new ObjectPool(createGroundEffect, CONFIG.POOLS.GROUND_EFFECTS);
    }
  },

  /** Очистить все наземные эффекты (новый забег). */
  clearGroundEffects() {
    if (this.groundEffects) this.groundEffects.clearAll();
  },

  /**
   * Заспавнить наземный эффект.
   *   kind ∈ 'slime' | 'rot' | 'fire'
   *   opts: { radius, life, slow=0..1, dps=0, color }
   */
  spawnGroundEffect(kind, x, y, opts) {
    if (!this.groundEffects) return null;
    const ge = this.groundEffects.spawn();
    if (!ge) return null;
    opts = opts || {};
    ge.kind = kind || 'slime';
    ge.x = x; ge.y = y;
    ge.radius = opts.radius || 22;
    ge.life = ge.maxLife = opts.life || 2;
    ge.slow = opts.slow || 0;
    ge.dps = opts.dps || 0;
    ge.color = opts.color || GROUND_DEFAULT_COLOR[ge.kind] || 'rgba(255,255,255,0.4)';
    return ge;
  },

  /** Найти суммарный slow-фактор (0..1) и dps по позиции игрока. */
  queryGroundAt(x, y) {
    if (!this.groundEffects) return { slow: 0, dps: 0 };
    let maxSlow = 0;
    let totalDps = 0;
    const items = this.groundEffects.items;
    for (let i = 0; i < items.length; i++) {
      const g = items[i];
      if (!g.active) continue;
      const dx = x - g.x, dy = y - g.y;
      if (dx * dx + dy * dy <= g.radius * g.radius) {
        if (g.slow > maxSlow) maxSlow = g.slow;
        totalDps += g.dps;
      }
    }
    return { slow: maxSlow, dps: totalDps };
  },

  /** Обновить наземные эффекты — таймеры жизни. */
  updateGroundEffects(dt) {
    if (!this.groundEffects) return;
    const items = this.groundEffects.items;
    for (let i = 0; i < items.length; i++) {
      const g = items[i];
      if (!g.active) continue;
      g.life -= dt;
      if (g.life <= 0) g.active = false;
    }
  },

  /** Отрисовать наземные эффекты. ctx уже сдвинут на -cam. */
  renderGroundEffects(ctx, cam, viewW, viewH) {
    if (!this.groundEffects) return;
    const minX = cam.x, minY = cam.y;
    const maxX = cam.x + viewW, maxY = cam.y + viewH;
    const items = this.groundEffects.items;
    for (let i = 0; i < items.length; i++) {
      const g = items[i];
      if (!g.active) continue;
      if (g.x + g.radius < minX || g.x - g.radius > maxX ||
          g.y + g.radius < minY || g.y - g.radius > maxY) continue;
      const t = Math.max(0, g.life / g.maxLife);
      const pulse = (g.kind === 'fire') ? (1 + Math.sin(g.life * 8) * 0.05) : 1;
      const alpha = 0.25 + 0.55 * t;
      ctx.globalAlpha = alpha;
      ctx.fillStyle = g.color;
      ctx.beginPath();
      ctx.arc(g.x, g.y, g.radius * pulse, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = alpha * 0.85;
      ctx.strokeStyle = GROUND_OUTLINE_COLOR[g.kind] || 'rgba(255,255,255,0.5)';
      ctx.lineWidth = 1.5;
      ctx.stroke();
      ctx.globalAlpha = 1;
    }
  },

  /** Камера, центрированная по игроку, с учётом границ карты. */
  getCamera(player, viewW, viewH) {
    let cx = player.x - viewW / 2;
    let cy = player.y - viewH / 2;
    cx = Utils.clamp(cx, 0, Math.max(0, this.mapW - viewW));
    cy = Utils.clamp(cy, 0, Math.max(0, this.mapH - viewH));
    return { x: cx, y: cy };
  },

  /* ============================================================
     ГЕНЕРАЦИЯ ПОДЗЕМЕЛЬЯ
     ============================================================ */

  /**
   * Сгенерировать новое подземелье. Вызывать при старте забега.
   * Шаг 13: принимает biomeId и mapNumber для бесконечного режима.
   * @param {string|number} [seedOrBiomeId] — сид (число) или biomeId (строка).
   * @param {number} [mapNumber] — номер карты (1-based), определяет сложность/размер.
   */
  generateDungeon(seedOrBiomeId, mapNumber) {
    const cfg = CONFIG.DUNGEON;
    let useSeed = cfg.SEED;
    let biome = null;

    // Шаг 13: определяем биом и номер карты
    if (typeof seedOrBiomeId === 'string') {
      // biomeId passed
      biome = BIOMES.find(b => b.id === seedOrBiomeId) || BIOMES[0];
    } else if (typeof seedOrBiomeId === 'number') {
      useSeed = seedOrBiomeId;
    }
    if (!biome) biome = BIOMES[0]; // по умолчанию — склеп
    if (!mapNumber) mapNumber = 1;

    this.currentBiome = biome;
    this.currentMapNumber = mapNumber;
    this.portal = null;

    // Шаг 13: определяем размер карты
    const mapSize = INFINITE_MODE.getMapSize(mapNumber);
    this.mapW = mapSize.w;
    this.mapH = mapSize.h;
    CONFIG.MAP.W = this.mapW;
    CONFIG.MAP.H = this.mapH;

    this.rng = (useSeed > 0) ? _mulberry32(useSeed) : Math.random;
    this.time = 0;

    // Шаг 13: кол-во комнат и ловушек по номеру карты
    const roomCounts = INFINITE_MODE.getRoomCount(mapNumber);
    const trapMul = INFINITE_MODE.getTrapMultiplier(mapNumber);

    const dungeon = {
      rooms: [],         // { x, y, w, h, isStart, isPuzzle, isSecret, hasMosaic }
      corridors: [],     // { x, y, w, h }
      pillars: [],       // { x, y, w, h }
      sarcophagi: [],    // { x, y, w, h }
      walls: [],         // { x, y, w, h } — собранные стены (для рендера)
      traps: [],         // Trap
      levers: [],        // { x, y, state (0/1), correct (0/1) }
      secretDoor: null,  // { x, y, w, h, open, openProgress }
      decor: {
        torches: [],     // { x, y, phase }
        runes: [],       // { x, y, color, phase }
        webs: [],        // { x, y, kind } — kind: 'tl'|'tr'|'bl'|'br'
      },
      // Сетка проходимости: 0 — стена, 1 — пол.
      grid: null,
      gridW: 0, gridH: 0,
      cellSize: cfg.GRID_CELL,
      // Стартовая комната — для размещения игрока
      startRoom: null,
      // Координата сундука внутри секретной комнаты
      secretChestPos: null,
      // Шаг 13: ссылка на биом
      biome: biome,
      mapNumber: mapNumber,
    };

    // 1) Комнаты (Шаг 13: количество из roomCounts)
    this._generateRooms(dungeon, cfg, roomCounts);

    // 2) Коридоры
    this._generateCorridors(dungeon, cfg);

    // 3) Сетка проходимости (пол / стена) на основе комнат и коридоров
    this._buildGrid(dungeon);

    // 4) Колонны
    this._placePillars(dungeon, cfg);

    // 5) Саркофаги
    this._placeSarcophagi(dungeon, cfg);

    // 6) Загадка (рычаги + секретная комната)
    this._placePuzzle(dungeon, cfg);

    // 7) Ловушки (Шаг 13: биом-зависимые)
    this._placeTraps(dungeon, cfg, biome, trapMul);

    // 8) Декор
    this._placeDecor(dungeon, cfg);

    // 9) Соберём прямоугольники стен для отрисовки (не для коллизий —
    //    коллизии живут в grid).
    this._buildWallRects(dungeon);

    // 10) Кеш пола (Шаг 13: биом-зависимые цвета)
    this._buildFloorCache(dungeon, biome);

    // Шаг 17: размещаем новые загадки и ловушки
    const isCampaign = !!(window.Campaign && Campaign.active);
    if (GameMap._placeStep17Objects) {
      GameMap._placeStep17Objects(dungeon, mapNumber, isCampaign);
    }

    this.dungeon = dungeon;
    return dungeon;
  },

  _rand(min, max) { return min + this.rng() * (max - min); },
  _randInt(min, max) { return Math.floor(this._rand(min, max + 1)); },
  _randPick(arr) { return arr[Math.floor(this.rng() * arr.length)]; },

  _generateRooms(dungeon, cfg, roomCounts) {
    const count = this._randInt(roomCounts ? roomCounts.min : cfg.ROOMS_MIN,
                                roomCounts ? roomCounts.max : cfg.ROOMS_MAX);
    const margin = 80;
    const W = this.mapW, H = this.mapH;
    let attempts = 0, maxAttempts = 600;
    while (dungeon.rooms.length < count && attempts < maxAttempts) {
      attempts += 1;
      const w = this._randInt(cfg.ROOM_W_MIN, cfg.ROOM_W_MAX);
      const h = this._randInt(cfg.ROOM_H_MIN, cfg.ROOM_H_MAX);
      const x = this._randInt(margin, W - w - margin);
      const y = this._randInt(margin, H - h - margin);
      // Проверка пересечения с другими (с padding)
      let ok = true;
      for (const r of dungeon.rooms) {
        if (this._rectsOverlap(
          x - cfg.ROOM_PADDING, y - cfg.ROOM_PADDING,
          w + cfg.ROOM_PADDING * 2, h + cfg.ROOM_PADDING * 2,
          r.x, r.y, r.w, r.h
        )) { ok = false; break; }
      }
      if (ok) {
        dungeon.rooms.push({
          x, y, w, h,
          cx: x + w / 2, cy: y + h / 2,
          isStart: false, isPuzzle: false, isSecret: false,
          hasMosaic: (w * h) >= 75000, // большие комнаты с мозаикой
        });
      }
    }
    // Гарантированный минимум — хотя бы 3 комнаты, иначе делаем "запасную".
    while (dungeon.rooms.length < 3) {
      const w = cfg.ROOM_W_MIN, h = cfg.ROOM_H_MIN;
      const x = margin + dungeon.rooms.length * (w + cfg.ROOM_PADDING + 20);
      const y = margin + 50;
      dungeon.rooms.push({
        x, y, w, h, cx: x + w / 2, cy: y + h / 2,
        isStart: false, isPuzzle: false, isSecret: false, hasMosaic: false,
      });
    }
    // Сортировка по координате (для предсказуемости коридоров)
    dungeon.rooms.sort((a, b) => (a.cx + a.cy) - (b.cx + b.cy));
    // Стартовая комната — первая
    dungeon.rooms[0].isStart = true;
    dungeon.startRoom = dungeon.rooms[0];
  },

  _rectsOverlap(ax, ay, aw, ah, bx, by, bw, bh) {
    return !(ax + aw <= bx || bx + bw <= ax || ay + ah <= by || by + bh <= ay);
  },

  _generateCorridors(dungeon, cfg) {
    // Соединяем по очереди: каждую комнату с предыдущей. + кольцевая связь
    // между концами цепочки для большей связности.
    const rooms = dungeon.rooms;
    for (let i = 1; i < rooms.length; i++) {
      this._connectRooms(dungeon, rooms[i - 1], rooms[i], cfg);
    }
    // Дополнительная связь: чтобы "вернуться" из дальних комнат
    if (rooms.length > 3) {
      this._connectRooms(dungeon, rooms[0], rooms[Math.floor(rooms.length / 2)], cfg);
    }
  },

  _connectRooms(dungeon, a, b, cfg) {
    const w = this._randInt(cfg.CORRIDOR_W_MIN, cfg.CORRIDOR_W_MAX);
    const halfW = Math.floor(w / 2);
    const ax = Math.floor(a.cx), ay = Math.floor(a.cy);
    const bx = Math.floor(b.cx), by = Math.floor(b.cy);

    // L-образная: горизонталь, потом вертикаль (или наоборот, выбор случайно)
    const horizontalFirst = this.rng() < 0.5;
    if (horizontalFirst) {
      this._addCorridorRect(dungeon, Math.min(ax, bx) - halfW, ay - halfW,
                            Math.abs(bx - ax) + w, w);
      this._addCorridorRect(dungeon, bx - halfW, Math.min(ay, by) - halfW,
                            w, Math.abs(by - ay) + w);
    } else {
      this._addCorridorRect(dungeon, ax - halfW, Math.min(ay, by) - halfW,
                            w, Math.abs(by - ay) + w);
      this._addCorridorRect(dungeon, Math.min(ax, bx) - halfW, by - halfW,
                            Math.abs(bx - ax) + w, w);
    }
  },

  _addCorridorRect(dungeon, x, y, w, h) {
    // Зажимаем в карту
    x = Math.max(40, x); y = Math.max(40, y);
    if (x + w > this.mapW - 40) w = this.mapW - 40 - x;
    if (y + h > this.mapH - 40) h = this.mapH - 40 - y;
    if (w <= 0 || h <= 0) return;
    dungeon.corridors.push({ x, y, w, h });
  },

  _buildGrid(dungeon) {
    const cs = dungeon.cellSize;
    const gw = Math.ceil(this.mapW / cs);
    const gh = Math.ceil(this.mapH / cs);
    const grid = new Uint8Array(gw * gh); // 0 — стена
    dungeon.grid = grid;
    dungeon.gridW = gw;
    dungeon.gridH = gh;

    // Заливаем комнаты как пол
    for (const r of dungeon.rooms) this._fillRectFloor(dungeon, r.x, r.y, r.w, r.h);
    // Коридоры — пол
    for (const c of dungeon.corridors) this._fillRectFloor(dungeon, c.x, c.y, c.w, c.h);
  },

  _fillRectFloor(dungeon, x, y, w, h) {
    const cs = dungeon.cellSize;
    const i0 = Math.max(0, Math.floor(x / cs));
    const j0 = Math.max(0, Math.floor(y / cs));
    const i1 = Math.min(dungeon.gridW - 1, Math.ceil((x + w) / cs) - 1);
    const j1 = Math.min(dungeon.gridH - 1, Math.ceil((y + h) / cs) - 1);
    for (let j = j0; j <= j1; j++) {
      for (let i = i0; i <= i1; i++) {
        dungeon.grid[j * dungeon.gridW + i] = 1;
      }
    }
  },

  /** Поставить стену (или препятствие) в одной ячейке. */
  _setCellWall(dungeon, gx, gy) {
    if (gx < 0 || gy < 0 || gx >= dungeon.gridW || gy >= dungeon.gridH) return;
    dungeon.grid[gy * dungeon.gridW + gx] = 0;
  },

  /** Закрасить прямоугольник стенами на сетке. */
  _fillRectWall(dungeon, x, y, w, h) {
    const cs = dungeon.cellSize;
    const i0 = Math.max(0, Math.floor(x / cs));
    const j0 = Math.max(0, Math.floor(y / cs));
    const i1 = Math.min(dungeon.gridW - 1, Math.ceil((x + w) / cs) - 1);
    const j1 = Math.min(dungeon.gridH - 1, Math.ceil((y + h) / cs) - 1);
    for (let j = j0; j <= j1; j++) {
      for (let i = i0; i <= i1; i++) {
        dungeon.grid[j * dungeon.gridW + i] = 0;
      }
    }
  },

  _placePillars(dungeon, cfg) {
    for (const r of dungeon.rooms) {
      if (r.isSecret) continue;
      const count = this._randInt(cfg.PILLARS_PER_ROOM_MIN, cfg.PILLARS_PER_ROOM_MAX);
      const ps = cfg.PILLAR_SIZE;
      let attempts = 0;
      let placed = 0;
      while (placed < count && attempts < 60) {
        attempts++;
        const x = r.x + this._randInt(40, r.w - 40 - ps);
        const y = r.y + this._randInt(40, r.h - 40 - ps);
        // Не вплотную к другим колоннам/саркофагам
        if (this._tooCloseToSolids(dungeon, x, y, ps, ps, 28)) continue;
        // Не на проходе коридора (центр клетки внутри коридора)
        const cx = x + ps / 2, cy = y + ps / 2;
        if (this._pointInCorridor(dungeon, cx, cy)) continue;
        const pillar = { x, y, w: ps, h: ps };
        dungeon.pillars.push(pillar);
        // Половинная коллизия для колонн: только центральная 50% площадь
        const inset = Math.floor(ps * 0.25);
        this._fillRectWall(dungeon, x + inset, y + inset, ps - inset * 2, ps - inset * 2);
        placed++;
      }
    }
  },

  _placeSarcophagi(dungeon, cfg) {
    const candidates = dungeon.rooms.filter(r => !r.isStart && !r.isSecret);
    const want = Math.min(cfg.SARCOPHAGI, candidates.length);
    for (let k = 0; k < want; k++) {
      const r = candidates[Math.floor(this.rng() * candidates.length)];
      let placed = false, attempts = 0;
      const w = 48, h = 32;
      while (!placed && attempts < 30) {
        attempts++;
        const x = r.x + this._randInt(40, r.w - 40 - w);
        const y = r.y + this._randInt(40, r.h - 40 - h);
        if (this._tooCloseToSolids(dungeon, x, y, w, h, 30)) continue;
        dungeon.sarcophagi.push({ x, y, w, h });
        this._fillRectWall(dungeon, x, y, w, h);
        placed = true;
      }
    }
  },

  _tooCloseToSolids(dungeon, x, y, w, h, gap) {
    const ax = x - gap, ay = y - gap, aw = w + gap * 2, ah = h + gap * 2;
    for (const p of dungeon.pillars) {
      if (this._rectsOverlap(ax, ay, aw, ah, p.x, p.y, p.w, p.h)) return true;
    }
    for (const s of dungeon.sarcophagi) {
      if (this._rectsOverlap(ax, ay, aw, ah, s.x, s.y, s.w, s.h)) return true;
    }
    return false;
  },

  _pointInRoom(dungeon, x, y) {
    for (const r of dungeon.rooms) {
      if (x >= r.x && x <= r.x + r.w && y >= r.y && y <= r.y + r.h) return r;
    }
    return null;
  },

  _pointInCorridor(dungeon, x, y) {
    for (const c of dungeon.corridors) {
      if (x >= c.x && x <= c.x + c.w && y >= c.y && y <= c.y + c.h) return c;
    }
    return null;
  },

  /** Загадка: выбрать комнату средней по размеру (не стартовую), поставить
   *  3 рычага вдоль одной из стен и секретную комнату-нишу за решёткой. */
  _placePuzzle(dungeon, cfg) {
    const candidates = dungeon.rooms
      .filter(r => !r.isStart)
      .sort((a, b) => (a.w * a.h) - (b.w * b.h));
    if (candidates.length === 0) return;
    // Возьмём комнату из средней трети
    const idx = Math.floor(candidates.length / 2);
    const room = candidates[idx];
    room.isPuzzle = true;

    // Размещаем 3 рычага вдоль нижней стены комнаты
    const lev = CONFIG.LEVER;
    const count = lev.COUNT;
    const padX = 50;
    const slotW = (room.w - padX * 2) / count;
    const correct = [];
    for (let i = 0; i < count; i++) {
      const cx = room.x + padX + slotW * i + slotW / 2 - lev.W / 2;
      const cy = room.y + room.h - 36;
      const corr = this.rng() < 0.5 ? 1 : 0;
      correct.push(corr);
      dungeon.levers.push({
        x: cx, y: cy, w: lev.W, h: lev.H,
        state: 0, correct: corr, index: i + 1,
      });
    }
    // Гарантируем, что не все одинаковые (хоть один отличается)
    if (correct.every(v => v === correct[0])) {
      correct[0] = correct[0] === 0 ? 1 : 0;
      dungeon.levers[0].correct = correct[0];
    }
    room.puzzleCorrect = correct.slice();

    // Секретная комната — небольшая ниша, прилегающая к одной из стен
    // комнаты-загадки. Соединяется коротким коридором (за дверью).
    this._placeSecretRoom(dungeon, room, cfg);
  },

  _placeSecretRoom(dungeon, room, cfg) {
    const sw = 180, sh = 140;
    // Пробуем разные стороны
    const sides = ['top', 'right', 'bottom', 'left'];
    // Случайный порядок
    for (let i = sides.length - 1; i > 0; i--) {
      const j = Math.floor(this.rng() * (i + 1));
      [sides[i], sides[j]] = [sides[j], sides[i]];
    }
    for (const side of sides) {
      let sx, sy, doorRect;
      const gap = 20;
      if (side === 'top') {
        sx = Math.floor(room.cx - sw / 2);
        sy = room.y - gap - sh;
        if (sy < 60) continue;
        doorRect = { x: Math.floor(room.cx - 30), y: room.y - gap - 4, w: 60, h: gap + 8 };
      } else if (side === 'bottom') {
        sx = Math.floor(room.cx - sw / 2);
        sy = room.y + room.h + gap;
        if (sy + sh > this.mapH - 60) continue;
        doorRect = { x: Math.floor(room.cx - 30), y: room.y + room.h - 4, w: 60, h: gap + 8 };
      } else if (side === 'left') {
        sx = room.x - gap - sw;
        sy = Math.floor(room.cy - sh / 2);
        if (sx < 60) continue;
        doorRect = { x: room.x - gap - 4, y: Math.floor(room.cy - 30), w: gap + 8, h: 60 };
      } else { // right
        sx = room.x + room.w + gap;
        sy = Math.floor(room.cy - sh / 2);
        if (sx + sw > this.mapW - 60) continue;
        doorRect = { x: room.x + room.w - 4, y: Math.floor(room.cy - 30), w: gap + 8, h: 60 };
      }
      // Проверка пересечений с уже существующими комнатами
      let ok = true;
      for (const r of dungeon.rooms) {
        if (this._rectsOverlap(sx - 20, sy - 20, sw + 40, sh + 40, r.x, r.y, r.w, r.h)) {
          ok = false; break;
        }
      }
      if (!ok) continue;

      // Регистрируем секретную комнату
      const secret = {
        x: sx, y: sy, w: sw, h: sh,
        cx: sx + sw / 2, cy: sy + sh / 2,
        isStart: false, isPuzzle: false, isSecret: true, hasMosaic: false,
      };
      dungeon.rooms.push(secret);
      this._fillRectFloor(dungeon, sx, sy, sw, sh);

      // Дверь — пол с флагом "стена пока закрыта"
      this._fillRectFloor(dungeon, doorRect.x, doorRect.y, doorRect.w, doorRect.h);
      dungeon.secretDoor = {
        x: doorRect.x, y: doorRect.y, w: doorRect.w, h: doorRect.h,
        open: false, openProgress: 0,
      };
      // Пока дверь закрыта — на сетке это стена.
      this._fillRectWall(dungeon, doorRect.x, doorRect.y, doorRect.w, doorRect.h);

      // Точка для сундука — центр секретной комнаты
      dungeon.secretChestPos = { x: secret.cx, y: secret.cy };
      return;
    }
    // Если не получилось — нет секретной комнаты (сундук не появится).
  },

  _placeTraps(dungeon, cfg, biome, trapMul) {
    const traps = dungeon.traps;
    const trapTypes = biome ? biome.trapTypes : ['spike', 'fire'];
    const mul = trapMul || 1.0;

    // Шаг 13: размещаем ловушки по типам биома
    for (const trapType of trapTypes) {
      let count = 0;
      switch (trapType) {
        case 'spike':
          count = Math.round(cfg.SPIKE_TRAPS * mul);
          this._placeSpikeTrapsBatch(dungeon, count);
          break;
        case 'fire':
          count = Math.round(cfg.FIRE_TRAPS * mul);
          this._placeFireTrapsBatch(dungeon, count);
          break;
        case 'ice_spike':
          count = Math.round(4 * mul);
          this._placeIceSpikeTrapsBatch(dungeon, count);
          break;
        case 'slippery_floor':
          count = Math.round(3 * mul);
          this._placeSlipperyFloorBatch(dungeon, count);
          break;
        case 'fire_geyser':
          count = Math.round(4 * mul);
          this._placeFireGeyserBatch(dungeon, count);
          break;
        case 'rockfall':
          count = Math.round(3 * mul);
          this._placeRockfallBatch(dungeon, count);
          break;
        case 'poison_plant':
          count = Math.round(4 * mul);
          this._placePoisonPlantBatch(dungeon, count);
          break;
        case 'root_grab':
          count = Math.round(3 * mul);
          this._placeRootGrabBatch(dungeon, count);
          break;
        case 'magic_rune':
          count = Math.round(4 * mul);
          this._placeMagicRuneBatch(dungeon, count);
          break;
        case 'portrait_trap':
          count = Math.round(3 * mul);
          this._placePortraitTrapBatch(dungeon, count);
          break;
      }
    }
  },

  // Оригинальные ловушки — вынесены в batch-методы
  _placeSpikeTrapsBatch(dungeon, count) {
    let placed = 0, attempts = 0;
    while (placed < count && attempts < 200) {
      attempts++;
      const corridorOrRoom = this.rng() < 0.7
        ? this._randPick(dungeon.corridors)
        : this._randPick(dungeon.rooms.filter(r => !r.isStart && !r.isSecret));
      if (!corridorOrRoom) continue;
      const tw = CONFIG.TRAP.SPIKE.W, th = CONFIG.TRAP.SPIKE.H;
      const x = corridorOrRoom.x + this._randInt(20, Math.max(20, corridorOrRoom.w - 20 - tw));
      const y = corridorOrRoom.y + this._randInt(20, Math.max(20, corridorOrRoom.h - 20 - th));
      if (this._tooCloseToSolids(dungeon, x, y, tw, th, 16)) continue;
      if (this._tooCloseToLevers(dungeon, x, y, tw, th, 30)) continue;
      dungeon.traps.push(this._makeSpikeTrap(x, y));
      placed++;
    }
  },

  _placeFireTrapsBatch(dungeon, count) {
    let placed = 0, attempts = 0;
    while (placed < count && attempts < 200) {
      attempts++;
      const room = this._randPick(dungeon.rooms.filter(r => !r.isStart && !r.isSecret && !r.isPuzzle));
      if (!room) continue;
      const tw = CONFIG.TRAP.FIRE.W, th = CONFIG.TRAP.FIRE.H;
      const side = ['top', 'bottom', 'left', 'right'][this._randInt(0, 3)];
      let x, y, dx, dy;
      const inset = 14;
      if (side === 'top') {
        x = room.x + this._randInt(40, room.w - 40 - tw);
        y = room.y + inset;
        dx = 0; dy = 1;
      } else if (side === 'bottom') {
        x = room.x + this._randInt(40, room.w - 40 - tw);
        y = room.y + room.h - inset - th;
        dx = 0; dy = -1;
      } else if (side === 'left') {
        x = room.x + inset;
        y = room.y + this._randInt(40, room.h - 40 - th);
        dx = 1; dy = 0;
      } else {
        x = room.x + room.w - inset - tw;
        y = room.y + this._randInt(40, room.h - 40 - th);
        dx = -1; dy = 0;
      }
      if (this._tooCloseToSolids(dungeon, x, y, tw, th, 24)) continue;
      dungeon.traps.push(this._makeFireTrap(x, y, dx, dy));
      placed++;
    }
  },

  // === Шаг 13: Новые ловушки по биомам ===

  _placeIceSpikeTrapsBatch(dungeon, count) {
    let placed = 0, attempts = 0;
    const tc = BIOME_TRAP_CONFIG.ice_spike;
    while (placed < count && attempts < 200) {
      attempts++;
      const corridorOrRoom = this.rng() < 0.7
        ? this._randPick(dungeon.corridors)
        : this._randPick(dungeon.rooms.filter(r => !r.isStart && !r.isSecret));
      if (!corridorOrRoom) continue;
      const x = corridorOrRoom.x + this._randInt(20, Math.max(20, corridorOrRoom.w - 20 - tc.W));
      const y = corridorOrRoom.y + this._randInt(20, Math.max(20, corridorOrRoom.h - 20 - tc.H));
      if (this._tooCloseToSolids(dungeon, x, y, tc.W, tc.H, 16)) continue;
      if (this._tooCloseToLevers(dungeon, x, y, tc.W, tc.H, 30)) continue;
      dungeon.traps.push({
        kind: 'ice_spike', x, y, w: tc.W, h: tc.H,
        cx: x + tc.W / 2, cy: y + tc.H / 2,
        phase: 'hidden', timer: this.rng() * tc.HIDDEN_TIME,
        damage: tc.DAMAGE, slowPct: tc.SLOW_PCT, slowDuration: tc.SLOW_DURATION,
        _struck: false,
      });
      placed++;
    }
  },

  _placeSlipperyFloorBatch(dungeon, count) {
    let placed = 0, attempts = 0;
    const tc = BIOME_TRAP_CONFIG.slippery_floor;
    while (placed < count && attempts < 150) {
      attempts++;
      const room = this._randPick(dungeon.rooms.filter(r => !r.isStart && !r.isSecret));
      if (!room || room.w < tc.W + 60 || room.h < tc.H + 60) continue;
      const x = room.x + this._randInt(30, room.w - 30 - tc.W);
      const y = room.y + this._randInt(30, room.h - 30 - tc.H);
      if (this._tooCloseToSolids(dungeon, x, y, tc.W, tc.H, 20)) continue;
      dungeon.traps.push({
        kind: 'slippery_floor', x, y, w: tc.W, h: tc.H,
        cx: x + tc.W / 2, cy: y + tc.H / 2,
        slideDuration: tc.SLIDE_DURATION, wallDamage: tc.WALL_DAMAGE,
      });
      placed++;
    }
  },

  _placeFireGeyserBatch(dungeon, count) {
    let placed = 0, attempts = 0;
    const tc = BIOME_TRAP_CONFIG.fire_geyser;
    while (placed < count && attempts < 200) {
      attempts++;
      const room = this._randPick(dungeon.rooms.filter(r => !r.isStart && !r.isSecret));
      if (!room) continue;
      const x = room.x + this._randInt(40, Math.max(40, room.w - 40 - tc.W));
      const y = room.y + this._randInt(40, Math.max(40, room.h - 40 - tc.H));
      if (this._tooCloseToSolids(dungeon, x, y, tc.W, tc.H, 20)) continue;
      dungeon.traps.push({
        kind: 'fire_geyser', x, y, w: tc.W, h: tc.H,
        cx: x + tc.W / 2, cy: y + tc.H / 2,
        phase: 'idle', timer: this.rng() * tc.COOLDOWN,
        damage: tc.DAMAGE, radius: tc.RADIUS,
        cooldown: tc.COOLDOWN, warnTime: tc.WARN_TIME, activeTime: tc.ACTIVE_TIME,
        _struck: false,
      });
      placed++;
    }
  },

  _placeRockfallBatch(dungeon, count) {
    let placed = 0, attempts = 0;
    const tc = BIOME_TRAP_CONFIG.rockfall;
    while (placed < count && attempts < 200) {
      attempts++;
      const room = this._randPick(dungeon.rooms.filter(r => !r.isStart && !r.isSecret));
      if (!room) continue;
      const x = room.x + this._randInt(40, Math.max(40, room.w - 40 - tc.W));
      const y = room.y + this._randInt(40, Math.max(40, room.h - 40 - tc.H));
      dungeon.traps.push({
        kind: 'rockfall', x, y, w: tc.W, h: tc.H,
        cx: x + tc.W / 2, cy: y + tc.H / 2,
        phase: 'idle', timer: this.rng() * tc.COOLDOWN,
        damage: tc.DAMAGE, aoeRadius: tc.AOE_RADIUS,
        cooldown: tc.COOLDOWN, warnTime: tc.WARN_TIME,
        _struck: false, _targetX: 0, _targetY: 0,
      });
      placed++;
    }
  },

  _placePoisonPlantBatch(dungeon, count) {
    let placed = 0, attempts = 0;
    const tc = BIOME_TRAP_CONFIG.poison_plant;
    while (placed < count && attempts < 200) {
      attempts++;
      const room = this._randPick(dungeon.rooms.filter(r => !r.isStart && !r.isSecret));
      if (!room) continue;
      const x = room.x + this._randInt(30, Math.max(30, room.w - 30 - tc.W));
      const y = room.y + this._randInt(30, Math.max(30, room.h - 30 - tc.H));
      if (this._tooCloseToSolids(dungeon, x, y, tc.W, tc.H, 20)) continue;
      dungeon.traps.push({
        kind: 'poison_plant', x, y, w: tc.W, h: tc.H,
        cx: x + tc.W / 2, cy: y + tc.H / 2,
        triggerRadius: tc.TRIGGER_RADIUS, cooldown: tc.COOLDOWN,
        projSpeed: tc.PROJECTILE_SPEED, projDamage: tc.PROJECTILE_DAMAGE,
        poisonDps: tc.POISON_DPS, poisonDuration: tc.POISON_DURATION,
        timer: 0,
      });
      placed++;
    }
  },

  _placeRootGrabBatch(dungeon, count) {
    let placed = 0, attempts = 0;
    const tc = BIOME_TRAP_CONFIG.root_grab;
    while (placed < count && attempts < 150) {
      attempts++;
      const room = this._randPick(dungeon.rooms.filter(r => !r.isStart && !r.isSecret));
      if (!room || room.w < tc.W + 60 || room.h < tc.H + 60) continue;
      const x = room.x + this._randInt(30, room.w - 30 - tc.W);
      const y = room.y + this._randInt(30, room.h - 30 - tc.H);
      if (this._tooCloseToSolids(dungeon, x, y, tc.W, tc.H, 20)) continue;
      dungeon.traps.push({
        kind: 'root_grab', x, y, w: tc.W, h: tc.H,
        cx: x + tc.W / 2, cy: y + tc.H / 2,
        slowPct: tc.SLOW_PCT, dps: tc.DPS,
      });
      placed++;
    }
  },

  _placeMagicRuneBatch(dungeon, count) {
    let placed = 0, attempts = 0;
    const tc = BIOME_TRAP_CONFIG.magic_rune;
    while (placed < count && attempts < 200) {
      attempts++;
      const corridorOrRoom = this.rng() < 0.5
        ? this._randPick(dungeon.corridors)
        : this._randPick(dungeon.rooms.filter(r => !r.isStart && !r.isSecret));
      if (!corridorOrRoom) continue;
      const x = corridorOrRoom.x + this._randInt(20, Math.max(20, corridorOrRoom.w - 20 - tc.W));
      const y = corridorOrRoom.y + this._randInt(20, Math.max(20, corridorOrRoom.h - 20 - tc.H));
      if (this._tooCloseToSolids(dungeon, x, y, tc.W, tc.H, 16)) continue;
      dungeon.traps.push({
        kind: 'magic_rune', x, y, w: tc.W, h: tc.H,
        cx: x + tc.W / 2, cy: y + tc.H / 2,
        damage: tc.DAMAGE, cooldown: tc.COOLDOWN,
        timer: 0, _triggered: false,
      });
      placed++;
    }
  },

  _placePortraitTrapBatch(dungeon, count) {
    let placed = 0, attempts = 0;
    const tc = BIOME_TRAP_CONFIG.portrait_trap;
    while (placed < count && attempts < 200) {
      attempts++;
      const room = this._randPick(dungeon.rooms.filter(r => !r.isStart && !r.isSecret && !r.isPuzzle));
      if (!room) continue;
      // Размещаем у стены
      const side = this._randInt(0, 3);
      let x, y;
      if (side === 0) { x = room.x + this._randInt(30, room.w - 30 - tc.W); y = room.y + 4; }
      else if (side === 1) { x = room.x + this._randInt(30, room.w - 30 - tc.W); y = room.y + room.h - tc.H - 4; }
      else if (side === 2) { x = room.x + 4; y = room.y + this._randInt(30, room.h - 30 - tc.H); }
      else { x = room.x + room.w - tc.W - 4; y = room.y + this._randInt(30, room.h - 30 - tc.H); }
      dungeon.traps.push({
        kind: 'portrait_trap', x, y, w: tc.W, h: tc.H,
        cx: x + tc.W / 2, cy: y + tc.H / 2,
        triggerRadius: tc.TRIGGER_RADIUS, cooldown: tc.COOLDOWN,
        projSpeed: tc.PROJECTILE_SPEED, projDamage: tc.PROJECTILE_DAMAGE,
        timer: 0,
      });
      placed++;
    }
  },

  _tooCloseToLevers(dungeon, x, y, w, h, gap) {
    const ax = x - gap, ay = y - gap, aw = w + gap * 2, ah = h + gap * 2;
    for (const lv of dungeon.levers) {
      if (this._rectsOverlap(ax, ay, aw, ah, lv.x, lv.y, lv.w, lv.h)) return true;
    }
    return false;
  },

  _makeSpikeTrap(x, y) {
    const c = CONFIG.TRAP.SPIKE;
    return {
      kind: 'spike',
      x, y, w: c.W, h: c.H,
      cx: x + c.W / 2, cy: y + c.H / 2,
      // Цикл: hidden -> warning -> active -> hidden ...
      phase: 'hidden',
      timer: this.rng() * c.HIDDEN_TIME, // случайный сдвиг — не синхронны
      damage: c.DAMAGE,
    };
  },

  _makeFireTrap(x, y, dx, dy) {
    const c = CONFIG.TRAP.FIRE;
    return {
      kind: 'fire',
      x, y, w: c.W, h: c.H,
      cx: x + c.W / 2, cy: y + c.H / 2,
      dx, dy,                 // направление струи (один из 4)
      phase: 'idle',
      timer: this.rng() * c.INTERVAL,
      activeTime: 0.4,        // длительность струи (видимая)
      damage: c.DAMAGE,
      dotDps: c.DOT_DPS,
      dotTime: c.DOT_TIME,
      range: c.RANGE,
      width: c.WIDTH,
    };
  },

  _placeDecor(dungeon, cfg) {
    // Факелы полностью убраны (по запросу)

    // Руны и паутина — остаются
    for (const r of dungeon.rooms) {
      // Руны (только в обычных комнатах)
      if (!r.isSecret) {
        const runesCount = this._randInt(3, cfg.RUNES_PER_ROOM + 1);
        for (let k = 0; k < runesCount; k++) {
          const rx = r.x + this._randInt(30, r.w - 30);
          const ry = r.y + this._randInt(30, r.h - 30);
          dungeon.decor.runes.push({
            x: rx, y: ry,
            color: this._randPick(['#a259ff', '#7e57c2', '#c47bff']),
            phase: this.rng() * 6,
          });
        }
      }
      // Паутина в углах
      if (!r.isSecret) {
        const corners = [
          { x: r.x + 4, y: r.y + 4, kind: 'tl' },
          { x: r.x + r.w - 4, y: r.y + 4, kind: 'tr' },
          { x: r.x + 4, y: r.y + r.h - 4, kind: 'bl' },
          { x: r.x + r.w - 4, y: r.y + r.h - 4, kind: 'br' },
        ];
        for (const c of corners) {
          if (this.rng() < 0.6) dungeon.decor.webs.push(c);
        }
      }
    }
    // Подсказки-руны рядом с рычагами для комнаты-загадки
    const puzzle = dungeon.rooms.find(r => r.isPuzzle);
    if (puzzle && dungeon.levers.length > 0) {
      // Рисуем над рычагами римские цифры — это будет отдельный декор
      dungeon.puzzleHints = dungeon.levers.map((lv, i) => ({
        x: lv.x + lv.w / 2,
        y: lv.y - 14,
        text: ['I', 'II', 'III'][i] || String(i + 1),
        color: '#c47bff',
      }));
    }
    // Корридорные факелы полностью убраны

    // === Богатый декор по биомам (D&D стиль) ===
    if (!dungeon.decor.biomeDecor) dungeon.decor.biomeDecor = [];
    const biomeId = dungeon.biome ? dungeon.biome.id : 'crypt';
    this._placeBiomeDecor(dungeon, biomeId);
  },

  /** Размещение декоративных объектов в зависимости от биома. */
  _placeBiomeDecor(dungeon, biomeId) {
    const decor = dungeon.decor.biomeDecor;
    const rooms = dungeon.rooms.filter(r => !r.isSecret);

    for (const room of rooms) {
      if (room.isStart && this.rng() > 0.5) continue; // меньше декора в стартовой
      const area = room.w * room.h;
      const decorCount = Math.max(2, Math.floor(area / 8000));

      for (let d = 0; d < decorCount; d++) {
        const decorItem = this._generateBiomeDecorItem(biomeId, room);
        if (decorItem) {
          // Проверяем что не перекрывает рычаги/ловушки
          if (!this._tooCloseToLevers(dungeon, decorItem.x - 8, decorItem.y - 8, 16, 16, 20)) {
            decor.push(decorItem);
          }
        }
      }
    }

    // Декор в коридорах (менее густо)
    for (const corr of dungeon.corridors) {
      if (this.rng() < 0.6) {
        const decorItem = this._generateBiomeDecorItem(biomeId, corr);
        if (decorItem) decor.push(decorItem);
      }
    }
  },

  /** Генерация одного декоративного объекта по биому и области. */
  _generateBiomeDecorItem(biomeId, area) {
    const x = area.x + this._randInt(20, Math.max(20, area.w - 40));
    const y = area.y + this._randInt(20, Math.max(20, area.h - 40));
    const rng = this.rng;

    switch (biomeId) {
      case 'crypt': {
        const types = ['bones', 'skull', 'broken_column', 'cobweb_floor', 'cracked_tile', 'chain_skull'];
        const type = this._randPick(types);
        return { x, y, type, biome: biomeId, size: type === 'broken_column' ? 16 : 8, hasCollision: type === 'broken_column' };
      }
      case 'ice_caves': {
        const types = ['ice_crystal', 'stalactite', 'frozen_corpse', 'snow_pile', 'ice_crack'];
        const type = this._randPick(types);
        return { x, y, type, biome: biomeId, size: type === 'ice_crystal' ? 12 : 8, hasCollision: false };
      }
      case 'fire_mines': {
        const types = ['lava_pool', 'ore_chunk', 'mine_cart', 'chain', 'bellows', 'ember'];
        const type = this._randPick(types);
        return { x, y, type, biome: biomeId, size: type === 'mine_cart' ? 16 : 8, hasCollision: type === 'mine_cart', glow: type === 'lava_pool' || type === 'ember' };
      }
      case 'forest_ruins': {
        const types = ['glowing_mushroom', 'vine', 'broken_statue', 'mossy_rock', 'fallen_tree', 'flower_bush'];
        const type = this._randPick(types);
        return { x, y, type, biome: biomeId, size: type === 'fallen_tree' ? 24 : 8, hasCollision: type === 'fallen_tree' || type === 'mossy_rock' };
      }
      case 'castle': {
        const types = ['tapestry', 'armor_stand', 'candelabra', 'bookshelf', 'throne', 'cage', 'banner'];
        const type = this._randPick(types);
        return { x, y, type, biome: biomeId, size: type === 'throne' ? 16 : (type === 'bookshelf' ? 16 : 8), hasCollision: type === 'throne' || type === 'bookshelf' };
      }
      case 'sky_citadel': {
        const types = ['golden_urn', 'marble_statue', 'floating_crystal', 'cloud_fountain', 'light_pillar', 'angel_wing'];
        const type = this._randPick(types);
        return { x, y, type, biome: biomeId, size: type === 'marble_statue' ? 16 : 8, hasCollision: type === 'golden_urn', glow: type === 'floating_crystal' || type === 'light_pillar', floats: true };
      }
      case 'elven_forest': {
        const types = ['rune_stone', 'elven_lantern', 'bloom_bush', 'magic_mushroom', 'nature_altar', 'fairy_circle'];
        const type = this._randPick(types);
        return { x, y, type, biome: biomeId, size: type === 'nature_altar' ? 16 : 8, hasCollision: type === 'nature_altar', glow: type === 'elven_lantern' || type === 'magic_mushroom' };
      }
      case 'mountain_keep': {
        const types = ['barrel', 'ore_crate', 'pickaxe', 'chain_lantern', 'forge_anvil', 'stone_bridge', 'rock_pile'];
        const type = this._randPick(types);
        return { x, y, type, biome: biomeId, size: type === 'forge_anvil' ? 16 : (type === 'barrel' ? 12 : 8), hasCollision: type === 'barrel' || type === 'ore_crate' || type === 'forge_anvil' };
      }
      default:
        return { x, y, type: 'generic_rock', biome: biomeId, size: 8, hasCollision: false };
    }
  },

  /** Сборка прямоугольников стен — для рендера. */
  _buildWallRects(dungeon) {
    // Рамки вокруг комнат и коридоров. Для скорости — просто чёрные
    // прямоугольники, накладываемые на пол. На самом деле проще
    // отрисовать "тёмный фон" + сверху "светлый пол" комнат/коридоров.
    // Так и сделаем в render(). А walls/walls — оставим пустым, пользуемся
    // grid.
  },

  _buildFloorCache(dungeon, biome) {
    // Кешируем целое подземелье в один offscreen canvas размером с карту.
    const off = document.createElement('canvas');
    off.width = this.mapW;
    off.height = this.mapH;
    const ctx = off.getContext('2d');

    // Шаг 13: цвета из биома
    const wallColor = biome ? biome.wallColor : '#1a1a1a';
    const corridorColor = biome ? biome.corridorColor : '#2a2a2a';
    const floorColor = biome ? biome.floorColor : '#3a3a3a';
    const floorGridColor = biome ? biome.floorGridColor : '#444444';
    const secretFloorColor = biome ? biome.secretFloorColor : '#3a3245';
    const secretGridColor = biome ? biome.secretGridColor : '#4a3f60';
    const mosaicColor = biome ? biome.mosaicColor : 'rgba(120, 90, 60, 0.35)';
    const biomeId = biome ? biome.id : 'crypt';

    // 1) Заполняем стены (тёмный фон) с текстурой
    // Для Небесного города: стены полупрозрачные, чтобы небо просвечивало в проёмах
    if (biomeId === 'sky_citadel') {
      // Не заливаем фон целиком — оставляем прозрачным для неба
      // Стены будут нарисованы текстурой в _renderWallTexture
      ctx.fillStyle = 'rgba(232, 232, 232, 0.85)';
      ctx.fillRect(0, 0, this.mapW, this.mapH);
    } else {
      ctx.fillStyle = wallColor;
      ctx.fillRect(0, 0, this.mapW, this.mapH);
    }

    // Текстура стен (кирпичная кладка/обводка по биому)
    this._renderWallTexture(ctx, dungeon, biomeId);

    // 2) Коридоры (тёмный пол)
    ctx.fillStyle = corridorColor;
    for (const c of dungeon.corridors) {
      ctx.fillRect(c.x, c.y, c.w, c.h);
      // Текстура пола коридора
      this._renderCorridorFloorTexture(ctx, c, biomeId);
    }

    // 2b) Площадка под секретной дверью
    if (dungeon.secretDoor) {
      const d = dungeon.secretDoor;
      ctx.fillStyle = secretFloorColor;
      ctx.fillRect(d.x, d.y, d.w, d.h);
    }

    // 3) Комнаты (более светлый пол + сетка плитки + текстуры)
    for (const r of dungeon.rooms) {
      // фон
      ctx.fillStyle = r.isSecret ? secretFloorColor : floorColor;
      ctx.fillRect(r.x, r.y, r.w, r.h);

      // Биом-специфичная текстура пола
      this._renderRoomFloorTexture(ctx, r, biomeId);

      // сетка плитки 40x40
      ctx.strokeStyle = r.isSecret ? secretGridColor : floorGridColor;
      ctx.lineWidth = 1;
      for (let xx = r.x; xx <= r.x + r.w; xx += 40) {
        ctx.beginPath();
        ctx.moveTo(xx + 0.5, r.y);
        ctx.lineTo(xx + 0.5, r.y + r.h);
        ctx.stroke();
      }
      for (let yy = r.y; yy <= r.y + r.h; yy += 40) {
        ctx.beginPath();
        ctx.moveTo(r.x, yy + 0.5);
        ctx.lineTo(r.x + r.w, yy + 0.5);
        ctx.stroke();
      }
      // Мозаика в больших комнатах — концентрические круги по центру
      if (r.hasMosaic && !r.isSecret) {
        ctx.strokeStyle = mosaicColor;
        ctx.lineWidth = 2;
        for (let k = 1; k <= 3; k++) {
          ctx.beginPath();
          ctx.arc(r.x + r.w / 2, r.y + r.h / 2, 22 * k, 0, Math.PI * 2);
          ctx.stroke();
        }
        // Диагонали
        ctx.strokeStyle = mosaicColor.replace('0.35', '0.25').replace('0.3', '0.2');
        ctx.beginPath();
        ctx.moveTo(r.x + r.w / 2 - 60, r.y + r.h / 2 - 60);
        ctx.lineTo(r.x + r.w / 2 + 60, r.y + r.h / 2 + 60);
        ctx.moveTo(r.x + r.w / 2 - 60, r.y + r.h / 2 + 60);
        ctx.lineTo(r.x + r.w / 2 + 60, r.y + r.h / 2 - 60);
        ctx.stroke();
      }
      // Тёмная окантовка комнаты
      ctx.strokeStyle = '#0e0e0e';
      ctx.lineWidth = 2;
      ctx.strokeRect(r.x + 0.5, r.y + 0.5, r.w - 1, r.h - 1);
    }

    // === Дверные проёмы/арки на стыках комнат и коридоров ===
    this._renderDoorways(ctx, dungeon, biomeId);

    // === Узкая плиточная текстура коридоров (отличие от комнат) ===
    this._renderCorridorNarrowTiles(ctx, dungeon, biomeId);

    this._floorCache = off;

    // Небесный город: сгенерировать кеш фона неба
    if (biomeId === 'sky_citadel') {
      this._buildSkyBackground();
    } else {
      this._skyBgCache = null;
      this._skyClouds = null;
    }
  },

  /** Рисует дверные проёмы на стыках коридоров и комнат. */
  _renderDoorways(ctx, dungeon, biomeId) {
    const rooms = dungeon.rooms;
    const corridors = dungeon.corridors;

    for (const room of rooms) {
      if (room.isSecret) continue;
      for (const corr of corridors) {
        // Проверяем пересечение коридора со стеной комнаты
        const doorways = this._findDoorway(room, corr);
        for (const dw of doorways) {
          // Тёмная арка
          ctx.fillStyle = biomeId === 'sky_citadel' ? '#a0b0c0' :
                         biomeId === 'elven_forest' ? '#3a5a2a' :
                         '#1a1a1a';
          ctx.fillRect(dw.x, dw.y, dw.w, dw.h);
          // Арка (полукруг сверху)
          ctx.fillStyle = biomeId === 'sky_citadel' ? '#c9a84c' :
                         biomeId === 'castle' ? '#5a4a3a' :
                         biomeId === 'elven_forest' ? '#2a4a1a' :
                         '#2a2a2a';
          if (dw.w > dw.h) {
            // Горизонтальный проход — арка слева и справа
            ctx.beginPath();
            ctx.arc(dw.x, dw.y + dw.h / 2, 4, 0, Math.PI * 2);
            ctx.arc(dw.x + dw.w, dw.y + dw.h / 2, 4, 0, Math.PI * 2);
            ctx.fill();
          } else {
            // Вертикальный проход — арка сверху
            ctx.beginPath();
            ctx.arc(dw.x + dw.w / 2, dw.y, dw.w / 2, 0, Math.PI);
            ctx.fill();
          }
          // Боковые колонны/столбы у проёма
          ctx.fillStyle = biomeId === 'sky_citadel' ? '#f0f0f0' :
                         biomeId === 'elven_forest' ? '#5a3a1a' :
                         '#4a4a4a';
          if (dw.w > dw.h) {
            ctx.fillRect(dw.x - 3, dw.y - 2, 3, dw.h + 4);
            ctx.fillRect(dw.x + dw.w, dw.y - 2, 3, dw.h + 4);
          } else {
            ctx.fillRect(dw.x - 2, dw.y - 3, dw.w + 4, 3);
            ctx.fillRect(dw.x - 2, dw.y + dw.h, dw.w + 4, 3);
          }
        }
      }
    }
  },

  /** Находит точки пересечения коридора со стенами комнаты (для дверных проёмов). */
  _findDoorway(room, corr) {
    const doorways = [];
    const overlap = 6; // ширина дверного проёма визуальная
    // Верхняя стена
    if (corr.y < room.y && corr.y + corr.h >= room.y) {
      const overlapX = Math.max(corr.x, room.x);
      const overlapW = Math.min(corr.x + corr.w, room.x + room.w) - overlapX;
      if (overlapW > 20) {
        doorways.push({ x: overlapX + 4, y: room.y - overlap / 2, w: overlapW - 8, h: overlap });
      }
    }
    // Нижняя стена
    if (corr.y + corr.h > room.y + room.h && corr.y <= room.y + room.h) {
      const overlapX = Math.max(corr.x, room.x);
      const overlapW = Math.min(corr.x + corr.w, room.x + room.w) - overlapX;
      if (overlapW > 20) {
        doorways.push({ x: overlapX + 4, y: room.y + room.h - overlap / 2, w: overlapW - 8, h: overlap });
      }
    }
    // Левая стена
    if (corr.x < room.x && corr.x + corr.w >= room.x) {
      const overlapY = Math.max(corr.y, room.y);
      const overlapH = Math.min(corr.y + corr.h, room.y + room.h) - overlapY;
      if (overlapH > 20) {
        doorways.push({ x: room.x - overlap / 2, y: overlapY + 4, w: overlap, h: overlapH - 8 });
      }
    }
    // Правая стена
    if (corr.x + corr.w > room.x + room.w && corr.x <= room.x + room.w) {
      const overlapY = Math.max(corr.y, room.y);
      const overlapH = Math.min(corr.y + corr.h, room.y + room.h) - overlapY;
      if (overlapH > 20) {
        doorways.push({ x: room.x + room.w - overlap / 2, y: overlapY + 4, w: overlap, h: overlapH - 8 });
      }
    }
    return doorways;
  },

  /** Рисует узкую плиточную разметку в коридорах (отличающуюся от комнат). */
  _renderCorridorNarrowTiles(ctx, dungeon, biomeId) {
    ctx.globalAlpha = 0.10;
    ctx.strokeStyle = biomeId === 'sky_citadel' ? '#a0b8c8' :
                     biomeId === 'elven_forest' ? '#4a6a3a' :
                     biomeId === 'mountain_keep' ? '#5a5040' :
                     '#3a3a3a';
    ctx.lineWidth = 0.5;
    const narrowTile = 20; // узкие плитки 20px (vs 40px в комнатах)
    for (const c of dungeon.corridors) {
      // Узкая сетка
      for (let xx = c.x; xx <= c.x + c.w; xx += narrowTile) {
        ctx.beginPath();
        ctx.moveTo(xx + 0.5, c.y);
        ctx.lineTo(xx + 0.5, c.y + c.h);
        ctx.stroke();
      }
      for (let yy = c.y; yy <= c.y + c.h; yy += narrowTile) {
        ctx.beginPath();
        ctx.moveTo(c.x, yy + 0.5);
        ctx.lineTo(c.x + c.w, yy + 0.5);
        ctx.stroke();
      }
    }
    ctx.globalAlpha = 1.0;
  },

  /** Текстура стен по биому — богатые узоры для непроходимых блоков (D&D стиль).
   *  Рисуется поверх wallColor фона, только в ячейках стен. */
  _renderWallTexture(ctx, dungeon, biomeId) {
    const cellSize = dungeon.cellSize;
    const gridW = dungeon.gridW, gridH = dungeon.gridH;
    const rng = this.rng || Math.random;

    // Используем кешированную тайловую текстуру 32x32 если доступна
    const tile = this._getWallTile(biomeId);
    if (tile) {
      // Покрываем все стены тайлом (pattern fill)
      const pattern = ctx.createPattern(tile, 'repeat');
      ctx.fillStyle = pattern;
      for (let j = 0; j < gridH; j++) {
        for (let i = 0; i < gridW; i++) {
          if (dungeon.grid[j * gridW + i] !== 0) continue;
          ctx.fillRect(i * cellSize, j * cellSize, cellSize, cellSize);
        }
      }
      return;
    }
    // Фоллбэк если тайл не создан
    ctx.globalAlpha = 0.15;
    ctx.globalAlpha = 1.0;
  },

  /** Кеш тайловых текстур стен (по биомам). */
  _wallTileCache: {},

  /** Получить или сгенерировать тайл текстуры стены 32×32 для биома. */
  _getWallTile(biomeId) {
    if (this._wallTileCache[biomeId]) return this._wallTileCache[biomeId];
    const tile = this._generateWallTile(biomeId);
    if (tile) this._wallTileCache[biomeId] = tile;
    return tile;
  },

  /** Генерация пиксельной тайловой текстуры 32×32 для стен по биому.
   *  Шаг 1: используем фиксированный детерминированный rng для ровных текстур. */
  _generateWallTile(biomeId) {
    const size = 32;
    const off = document.createElement('canvas');
    off.width = size;
    off.height = size;
    const ctx = off.getContext('2d');
    ctx.imageSmoothingEnabled = false;

    // Шаг 1: фиксированный сид для каждого биома (чтобы текстуры были ровными и повторяемыми)
    const biomeSeeds = { crypt: 42, ice_caves: 73, fire_mines: 101, forest_ruins: 137, castle: 191, sky_citadel: 233, elven_forest: 277, mountain_keep: 311 };
    const seed = biomeSeeds[biomeId] || 42;
    const rng = _mulberry32(seed);

    switch (biomeId) {
      case 'crypt': {
        // Каменная кладка из серых кирпичей с тёмными швами и трещинами
        ctx.fillStyle = '#2a2a2a';
        ctx.fillRect(0, 0, size, size);
        // Кирпичи (8x4 каждый, со смещением)
        const brickH = 8, brickW = 16;
        ctx.strokeStyle = '#0e0e0e';
        ctx.lineWidth = 1;
        for (let row = 0; row < size / brickH; row++) {
          const offset = (row % 2) * (brickW / 2);
          for (let col = -1; col < size / brickW + 1; col++) {
            const bx = col * brickW + offset;
            const by = row * brickH;
            // Разные оттенки серого для вариации
            const shade = 30 + Math.floor(rng() * 20);
            ctx.fillStyle = `rgb(${shade}, ${shade}, ${shade + 5})`;
            ctx.fillRect(bx + 1, by + 1, brickW - 2, brickH - 2);
            ctx.strokeRect(bx + 0.5, by + 0.5, brickW, brickH);
          }
        }
        // Трещины (2-3 штуки)
        ctx.strokeStyle = '#0a0a0a';
        ctx.lineWidth = 1;
        for (let i = 0; i < 2; i++) {
          ctx.beginPath();
          const sx = Math.floor(rng() * size);
          const sy = Math.floor(rng() * size);
          ctx.moveTo(sx, sy);
          ctx.lineTo(sx + (rng() * 8 - 4), sy + rng() * 10);
          ctx.lineTo(sx + (rng() * 6 - 3), sy + rng() * 14);
          ctx.stroke();
        }
        break;
      }
      case 'ice_caves': {
        // Лёд с голубоватыми прожилками и вкраплениями
        ctx.fillStyle = '#1a2a3a';
        ctx.fillRect(0, 0, size, size);
        // Геометрические трещины льда
        ctx.strokeStyle = '#4080a0';
        ctx.lineWidth = 1;
        // Вертикальные и диагональные прожилки
        for (let i = 0; i < 5; i++) {
          ctx.beginPath();
          const sx = Math.floor(rng() * size);
          const sy = Math.floor(rng() * size);
          ctx.moveTo(sx, sy);
          const angle = rng() * Math.PI;
          const len = 8 + rng() * 16;
          ctx.lineTo(sx + Math.cos(angle) * len, sy + Math.sin(angle) * len);
          ctx.stroke();
        }
        // Вкрапления (блёстки)
        ctx.fillStyle = '#80c0e0';
        for (let i = 0; i < 6; i++) {
          ctx.fillRect(Math.floor(rng() * size), Math.floor(rng() * size), 1, 1);
        }
        // Тёмные зоны глубины
        ctx.fillStyle = 'rgba(0, 20, 40, 0.3)';
        ctx.beginPath();
        ctx.arc(8 + rng() * 16, 8 + rng() * 16, 4 + rng() * 4, 0, Math.PI * 2);
        ctx.fill();
        break;
      }
      case 'fire_mines': {
        // Обсидиан с красными рудными жилами, потрескавшаяся лава
        ctx.fillStyle = '#1a1018';
        ctx.fillRect(0, 0, size, size);
        // Тёмный обсидиан — вкрапления
        for (let i = 0; i < 8; i++) {
          const shade = 20 + Math.floor(rng() * 15);
          ctx.fillStyle = `rgb(${shade + 5}, ${shade - 5}, ${shade + 10})`;
          ctx.fillRect(Math.floor(rng() * size), Math.floor(rng() * size), 3 + Math.floor(rng() * 5), 3 + Math.floor(rng() * 5));
        }
        // Красные рудные жилы
        ctx.strokeStyle = '#8a2010';
        ctx.lineWidth = 1.5;
        for (let i = 0; i < 3; i++) {
          ctx.beginPath();
          const sx = rng() * size, sy = rng() * size;
          ctx.moveTo(sx, sy);
          ctx.quadraticCurveTo(sx + rng() * 10, sy + rng() * 10, sx + rng() * 20, sy + rng() * 20);
          ctx.stroke();
        }
        // Яркие точки лавы
        ctx.fillStyle = '#ff4400';
        ctx.globalAlpha = 0.6;
        for (let i = 0; i < 3; i++) {
          ctx.fillRect(Math.floor(rng() * size), Math.floor(rng() * size), 2, 2);
        }
        ctx.globalAlpha = 1;
        break;
      }
      case 'forest_ruins': {
        // Замшелый камень (серо-зелёный), обвитый пиксельными лианами
        ctx.fillStyle = '#2a3028';
        ctx.fillRect(0, 0, size, size);
        // Каменная основа с вариациями
        for (let i = 0; i < 6; i++) {
          const shade = 35 + Math.floor(rng() * 20);
          ctx.fillStyle = `rgb(${shade - 5}, ${shade + 10}, ${shade - 5})`;
          ctx.fillRect(Math.floor(rng() * size), Math.floor(rng() * size), 5 + Math.floor(rng() * 8), 5 + Math.floor(rng() * 8));
        }
        // Мох (зелёные пятна)
        ctx.fillStyle = '#3a6a2a';
        ctx.globalAlpha = 0.5;
        for (let i = 0; i < 4; i++) {
          ctx.beginPath();
          ctx.arc(rng() * size, rng() * size, 2 + rng() * 4, 0, Math.PI * 2);
          ctx.fill();
        }
        ctx.globalAlpha = 1;
        // Лианы (вертикальные волнистые линии)
        ctx.strokeStyle = '#2a5a1a';
        ctx.lineWidth = 1.5;
        for (let i = 0; i < 2; i++) {
          ctx.beginPath();
          const sx = rng() * size;
          ctx.moveTo(sx, 0);
          ctx.quadraticCurveTo(sx + rng() * 6 - 3, size * 0.5, sx + rng() * 4 - 2, size);
          ctx.stroke();
          // Листочки
          ctx.fillStyle = '#4a8a2a';
          ctx.fillRect(sx + (rng() * 4 - 2), size * 0.3 + rng() * 10, 3, 2);
          ctx.fillRect(sx + (rng() * 4 - 2), size * 0.6 + rng() * 10, 3, 2);
        }
        break;
      }
      case 'castle': {
        // Тёмная каменная кладка с золотыми гербами/рунами
        ctx.fillStyle = '#1a1a20';
        ctx.fillRect(0, 0, size, size);
        // Кладка — большие блоки
        const blockH = 16, blockW = 16;
        ctx.strokeStyle = '#0a0a0a';
        ctx.lineWidth = 1;
        for (let row = 0; row < size / blockH; row++) {
          const offset = (row % 2) * (blockW / 2);
          for (let col = -1; col < size / blockW + 1; col++) {
            const bx = col * blockW + offset;
            const by = row * blockH;
            const shade = 22 + Math.floor(rng() * 12);
            ctx.fillStyle = `rgb(${shade}, ${shade}, ${shade + 8})`;
            ctx.fillRect(bx + 1, by + 1, blockW - 2, blockH - 2);
            ctx.strokeRect(bx + 0.5, by + 0.5, blockW, blockH);
          }
        }
        // Золотой герб/руна в центре (появляется раз в 2 тайла)
        if (rng() < 0.5) {
          ctx.fillStyle = '#c9a84c';
          ctx.globalAlpha = 0.7;
          // Ромб-герб
          ctx.beginPath();
          ctx.moveTo(16, 6);
          ctx.lineTo(22, 16);
          ctx.lineTo(16, 26);
          ctx.lineTo(10, 16);
          ctx.closePath();
          ctx.fill();
          ctx.strokeStyle = '#8a6a2c';
          ctx.lineWidth = 1;
          ctx.stroke();
          ctx.globalAlpha = 1;
        }
        break;
      }
      case 'sky_citadel': {
        // Белый мрамор с золотыми прожилками, греческий меандр
        ctx.fillStyle = '#e8e8e8';
        ctx.fillRect(0, 0, size, size);
        // Мраморные вариации (светлые/тёмные пятна)
        for (let i = 0; i < 5; i++) {
          const shade = 210 + Math.floor(rng() * 40);
          ctx.fillStyle = `rgb(${shade}, ${shade}, ${shade + 5})`;
          ctx.fillRect(Math.floor(rng() * size), Math.floor(rng() * size), 6 + Math.floor(rng() * 10), 6 + Math.floor(rng() * 10));
        }
        // Золотые прожилки
        ctx.strokeStyle = '#c9a84c';
        ctx.lineWidth = 0.8;
        ctx.globalAlpha = 0.6;
        for (let i = 0; i < 3; i++) {
          ctx.beginPath();
          const sx = rng() * size, sy = rng() * size;
          ctx.moveTo(sx, sy);
          ctx.lineTo(sx + rng() * 15 - 7, sy + rng() * 15 - 7);
          ctx.stroke();
        }
        ctx.globalAlpha = 1;
        // Греческий меандр (ключевой узор) — по верхнему и нижнему краю
        ctx.strokeStyle = '#c9a84c';
        ctx.lineWidth = 1;
        ctx.globalAlpha = 0.5;
        // Упрощённый меандр: ступенчатый рисунок
        const step = 4;
        ctx.beginPath();
        ctx.moveTo(0, 2);
        for (let x = 0; x < size; x += step * 2) {
          ctx.lineTo(x + step, 2);
          ctx.lineTo(x + step, 2 + step);
          ctx.lineTo(x + step * 2, 2 + step);
          ctx.lineTo(x + step * 2, 2);
        }
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(0, size - 2);
        for (let x = 0; x < size; x += step * 2) {
          ctx.lineTo(x + step, size - 2);
          ctx.lineTo(x + step, size - 2 - step);
          ctx.lineTo(x + step * 2, size - 2 - step);
          ctx.lineTo(x + step * 2, size - 2);
        }
        ctx.stroke();
        ctx.globalAlpha = 1;
        break;
      }
      case 'elven_forest': {
        // Кора дерева (коричневая с вертикальными полосами), светящиеся руны
        ctx.fillStyle = '#3a2a18';
        ctx.fillRect(0, 0, size, size);
        // Вертикальные полосы коры
        ctx.strokeStyle = '#2a1a08';
        ctx.lineWidth = 2;
        for (let i = 0; i < 5; i++) {
          const x = 3 + Math.floor(rng() * (size - 6));
          ctx.beginPath();
          ctx.moveTo(x, 0);
          ctx.quadraticCurveTo(x + rng() * 4 - 2, size * 0.5, x + rng() * 3 - 1, size);
          ctx.stroke();
        }
        // Более светлые участки коры
        ctx.fillStyle = '#4a3a20';
        for (let i = 0; i < 4; i++) {
          ctx.fillRect(Math.floor(rng() * size), Math.floor(rng() * size), 2 + Math.floor(rng() * 4), 4 + Math.floor(rng() * 8));
        }
        // Светящаяся руна (зелёная)
        if (rng() < 0.4) {
          ctx.fillStyle = '#60ff80';
          ctx.globalAlpha = 0.6;
          const rx = 8 + Math.floor(rng() * 16);
          const ry = 8 + Math.floor(rng() * 16);
          // Простая руна — крест + точки
          ctx.fillRect(rx - 1, ry - 4, 2, 8);
          ctx.fillRect(rx - 3, ry - 1, 6, 2);
          ctx.fillRect(rx - 2, ry - 3, 1, 1);
          ctx.fillRect(rx + 2, ry + 2, 1, 1);
          ctx.globalAlpha = 1;
        }
        break;
      }
      case 'mountain_keep': {
        // Серый гранит с тёмными вкраплениями, деревянные балки
        ctx.fillStyle = '#3a3a38';
        ctx.fillRect(0, 0, size, size);
        // Гранит — неровные пятна разных оттенков
        for (let i = 0; i < 10; i++) {
          const shade = 45 + Math.floor(rng() * 25);
          ctx.fillStyle = `rgb(${shade}, ${shade - 2}, ${shade - 5})`;
          ctx.fillRect(Math.floor(rng() * size), Math.floor(rng() * size), 3 + Math.floor(rng() * 6), 3 + Math.floor(rng() * 6));
        }
        // Тёмные вкрапления (слюда/минералы)
        ctx.fillStyle = '#1a1a18';
        for (let i = 0; i < 5; i++) {
          ctx.fillRect(Math.floor(rng() * size), Math.floor(rng() * size), 1 + Math.floor(rng() * 2), 1 + Math.floor(rng() * 2));
        }
        // Деревянная балка (горизонтальная, ~20% шанс)
        if (rng() < 0.3) {
          ctx.fillStyle = '#5a4020';
          ctx.fillRect(0, 12, size, 6);
          ctx.strokeStyle = '#3a2a10';
          ctx.lineWidth = 0.5;
          ctx.strokeRect(0, 12, size, 6);
          // Зернистость дерева
          ctx.strokeStyle = '#4a3018';
          ctx.lineWidth = 0.5;
          for (let x = 2; x < size; x += 5 + Math.floor(rng() * 4)) {
            ctx.beginPath();
            ctx.moveTo(x, 13);
            ctx.lineTo(x + rng() * 3, 17);
            ctx.stroke();
          }
        }
        break;
      }
      default: {
        // Базовая тёмная текстура
        ctx.fillStyle = '#1a1a1a';
        ctx.fillRect(0, 0, size, size);
        ctx.strokeStyle = '#2a2a2a';
        ctx.lineWidth = 1;
        ctx.strokeRect(4, 4, size - 8, size - 8);
        break;
      }
    }

    return off;
  },

  /** Текстура пола коридора по биому. */
  _renderCorridorFloorTexture(ctx, corridor, biomeId) {
    ctx.globalAlpha = 0.08;
    const rng = this.rng || Math.random;
    switch (biomeId) {
      case 'crypt': {
        // Трещины
        ctx.strokeStyle = '#1a1a1a';
        ctx.lineWidth = 0.8;
        for (let i = 0; i < 3; i++) {
          const x1 = corridor.x + rng() * corridor.w;
          const y1 = corridor.y + rng() * corridor.h;
          ctx.beginPath();
          ctx.moveTo(x1, y1);
          ctx.lineTo(x1 + rng() * 30 - 15, y1 + rng() * 30 - 15);
          ctx.stroke();
        }
        break;
      }
      case 'ice_caves': {
        // Ледяные прожилки
        ctx.strokeStyle = '#6090b0';
        ctx.lineWidth = 0.6;
        for (let i = 0; i < 2; i++) {
          const x1 = corridor.x + rng() * corridor.w;
          const y1 = corridor.y + rng() * corridor.h;
          ctx.beginPath();
          ctx.moveTo(x1, y1);
          ctx.lineTo(x1 + rng() * 40 - 20, y1 + rng() * 40 - 20);
          ctx.stroke();
        }
        break;
      }
      case 'fire_mines': {
        // Потрескавшаяся лава
        ctx.strokeStyle = '#8a3a0a';
        ctx.lineWidth = 1;
        for (let i = 0; i < 2; i++) {
          const x1 = corridor.x + rng() * corridor.w;
          const y1 = corridor.y + rng() * corridor.h;
          ctx.beginPath();
          ctx.moveTo(x1, y1);
          ctx.lineTo(x1 + rng() * 20, y1 + rng() * 20);
          ctx.lineTo(x1 + rng() * 20, y1 + rng() * 20);
          ctx.stroke();
        }
        break;
      }
      case 'sky_citadel': {
        // Золотые линии на мраморе
        ctx.strokeStyle = '#c9a84c';
        ctx.lineWidth = 0.5;
        for (let i = 0; i < 2; i++) {
          const x1 = corridor.x + rng() * corridor.w;
          const y1 = corridor.y + rng() * corridor.h;
          ctx.beginPath();
          ctx.moveTo(x1, y1);
          ctx.lineTo(x1 + rng() * 30, y1 + rng() * 10 - 5);
          ctx.stroke();
        }
        break;
      }
      case 'elven_forest': {
        // Мох и мелкие камушки
        ctx.fillStyle = '#3a6a2a';
        for (let i = 0; i < 3; i++) {
          ctx.beginPath();
          ctx.arc(corridor.x + rng() * corridor.w, corridor.y + rng() * corridor.h, 2 + rng() * 3, 0, Math.PI * 2);
          ctx.fill();
        }
        break;
      }
      case 'mountain_keep': {
        // Грубый камень — мелкие точки
        ctx.fillStyle = '#4a4a3a';
        for (let i = 0; i < 4; i++) {
          ctx.beginPath();
          ctx.arc(corridor.x + rng() * corridor.w, corridor.y + rng() * corridor.h, 1 + rng() * 2, 0, Math.PI * 2);
          ctx.fill();
        }
        break;
      }
    }
    ctx.globalAlpha = 1.0;
  },

  /** Текстура пола комнаты по биому. */
  _renderRoomFloorTexture(ctx, room, biomeId) {
    const rng = this.rng || Math.random;
    ctx.globalAlpha = 0.12;

    switch (biomeId) {
      case 'crypt': {
        // Трещины на плитке
        ctx.strokeStyle = '#2a2a2a';
        ctx.lineWidth = 0.7;
        const crackCount = Math.floor(room.w * room.h / 5000);
        for (let i = 0; i < crackCount; i++) {
          const cx = room.x + rng() * room.w;
          const cy = room.y + rng() * room.h;
          ctx.beginPath();
          ctx.moveTo(cx, cy);
          let px = cx, py = cy;
          for (let s = 0; s < 3; s++) {
            px += rng() * 16 - 8;
            py += rng() * 16 - 8;
            ctx.lineTo(px, py);
          }
          ctx.stroke();
        }
        break;
      }
      case 'ice_caves': {
        // Голубоватые прожилки льда
        ctx.strokeStyle = '#5080a0';
        ctx.lineWidth = 0.8;
        const iceCount = Math.floor(room.w * room.h / 4000);
        for (let i = 0; i < iceCount; i++) {
          const cx = room.x + rng() * room.w;
          const cy = room.y + rng() * room.h;
          ctx.beginPath();
          ctx.moveTo(cx, cy);
          ctx.lineTo(cx + rng() * 30 - 15, cy + rng() * 30 - 15);
          ctx.stroke();
        }
        // Блёстки на полу
        ctx.fillStyle = '#aaddff';
        for (let i = 0; i < 5; i++) {
          ctx.beginPath();
          ctx.arc(room.x + rng() * room.w, room.y + rng() * room.h, 1.5, 0, Math.PI * 2);
          ctx.fill();
        }
        break;
      }
      case 'fire_mines': {
        // Потрескавшийся камень с оранжевыми жилами
        ctx.strokeStyle = '#6a2a0a';
        ctx.lineWidth = 1;
        const fireCount = Math.floor(room.w * room.h / 6000);
        for (let i = 0; i < fireCount; i++) {
          const cx = room.x + rng() * room.w;
          const cy = room.y + rng() * room.h;
          ctx.beginPath();
          ctx.moveTo(cx, cy);
          ctx.lineTo(cx + rng() * 24 - 12, cy + rng() * 24 - 12);
          ctx.lineTo(cx + rng() * 24 - 12, cy + rng() * 24 - 12);
          ctx.stroke();
        }
        // Светящиеся точки (лава)
        ctx.fillStyle = '#ff6633';
        ctx.globalAlpha = 0.08;
        for (let i = 0; i < 4; i++) {
          ctx.beginPath();
          ctx.arc(room.x + rng() * room.w, room.y + rng() * room.h, 2 + rng() * 3, 0, Math.PI * 2);
          ctx.fill();
        }
        break;
      }
      case 'forest_ruins': {
        // Замшелые пятна и корни
        ctx.fillStyle = '#3a5a3a';
        ctx.globalAlpha = 0.10;
        const mossCount = Math.floor(room.w * room.h / 4000);
        for (let i = 0; i < mossCount; i++) {
          ctx.beginPath();
          ctx.arc(room.x + rng() * room.w, room.y + rng() * room.h, 4 + rng() * 8, 0, Math.PI * 2);
          ctx.fill();
        }
        // Корни (тёмные изогнутые линии)
        ctx.strokeStyle = '#2a3a1a';
        ctx.lineWidth = 1.2;
        ctx.globalAlpha = 0.12;
        for (let i = 0; i < 3; i++) {
          const sx = room.x + rng() * room.w;
          const sy = room.y + rng() * room.h;
          ctx.beginPath();
          ctx.moveTo(sx, sy);
          ctx.quadraticCurveTo(sx + rng() * 40, sy + rng() * 40, sx + rng() * 60 - 30, sy + rng() * 60 - 30);
          ctx.stroke();
        }
        break;
      }
      case 'castle': {
        // Паркет/мозаика — ромбовидная сетка
        ctx.strokeStyle = '#4a3a2a';
        ctx.lineWidth = 0.6;
        const tileSize = 30;
        for (let xx = room.x; xx < room.x + room.w; xx += tileSize) {
          for (let yy = room.y; yy < room.y + room.h; yy += tileSize) {
            ctx.beginPath();
            ctx.moveTo(xx + tileSize / 2, yy);
            ctx.lineTo(xx + tileSize, yy + tileSize / 2);
            ctx.lineTo(xx + tileSize / 2, yy + tileSize);
            ctx.lineTo(xx, yy + tileSize / 2);
            ctx.closePath();
            ctx.stroke();
          }
        }
        break;
      }
      case 'sky_citadel': {
        // Мраморные узоры — диагональные прожилки
        ctx.strokeStyle = '#b0c0d0';
        ctx.lineWidth = 0.6;
        const marbleCount = Math.floor(room.w * room.h / 3000);
        for (let i = 0; i < marbleCount; i++) {
          const cx = room.x + rng() * room.w;
          const cy = room.y + rng() * room.h;
          ctx.beginPath();
          ctx.moveTo(cx, cy);
          ctx.lineTo(cx + rng() * 20 - 10, cy + rng() * 20 - 10);
          ctx.stroke();
        }
        // Золотые акценты на плитке
        ctx.strokeStyle = '#c9a84c';
        ctx.globalAlpha = 0.08;
        ctx.lineWidth = 0.8;
        const tileS = 40;
        for (let xx = room.x + tileS; xx < room.x + room.w - tileS; xx += tileS * 2) {
          for (let yy = room.y + tileS; yy < room.y + room.h - tileS; yy += tileS * 2) {
            if (rng() < 0.3) {
              ctx.beginPath();
              ctx.arc(xx, yy, 3, 0, Math.PI * 2);
              ctx.stroke();
            }
          }
        }
        break;
      }
      case 'elven_forest': {
        // Мох, цветы и трава
        ctx.fillStyle = '#5a9a4a';
        ctx.globalAlpha = 0.10;
        const grassCount = Math.floor(room.w * room.h / 3000);
        for (let i = 0; i < grassCount; i++) {
          const gx = room.x + rng() * room.w;
          const gy = room.y + rng() * room.h;
          ctx.beginPath();
          ctx.arc(gx, gy, 2 + rng() * 4, 0, Math.PI * 2);
          ctx.fill();
        }
        // Цветочки (маленькие яркие точки)
        ctx.globalAlpha = 0.15;
        const flowers = ['#ff69b4', '#ffa500', '#add8e6', '#dda0dd', '#ffff00'];
        for (let i = 0; i < 6; i++) {
          ctx.fillStyle = flowers[Math.floor(rng() * flowers.length)];
          ctx.beginPath();
          ctx.arc(room.x + rng() * room.w, room.y + rng() * room.h, 1.5, 0, Math.PI * 2);
          ctx.fill();
        }
        // Тропинки из светлого камня
        ctx.strokeStyle = '#a0a080';
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.06;
        ctx.beginPath();
        ctx.moveTo(room.x + room.w * 0.2, room.y + room.h * 0.5);
        ctx.quadraticCurveTo(room.x + room.w * 0.5, room.y + room.h * (0.3 + rng() * 0.4), room.x + room.w * 0.8, room.y + room.h * 0.5);
        ctx.stroke();
        break;
      }
      case 'mountain_keep': {
        // Грубый каменный пол со сколами
        ctx.strokeStyle = '#5a5040';
        ctx.lineWidth = 0.8;
        const chipCount = Math.floor(room.w * room.h / 4000);
        for (let i = 0; i < chipCount; i++) {
          const cx = room.x + rng() * room.w;
          const cy = room.y + rng() * room.h;
          ctx.beginPath();
          ctx.moveTo(cx, cy);
          ctx.lineTo(cx + rng() * 12 - 6, cy + rng() * 12 - 6);
          ctx.stroke();
        }
        // Вырубленные ступени (горизонтальные линии через неравные промежутки)
        ctx.strokeStyle = '#4a4030';
        ctx.lineWidth = 0.5;
        ctx.globalAlpha = 0.08;
        for (let yy = room.y + 20; yy < room.y + room.h - 20; yy += 25 + rng() * 15) {
          ctx.beginPath();
          ctx.moveTo(room.x + 10, yy);
          ctx.lineTo(room.x + room.w - 10, yy);
          ctx.stroke();
        }
        break;
      }
    }
    ctx.globalAlpha = 1.0;
  },

  /* ============================================================
     Walkability / collisions — «половинная» проходимость (v2).

     Система коллизий с уменьшенными хитбоксами:
     - Визуальный размер блока остаётся прежним (32×32).
     - Хитбокс коллизии уменьшен: стены ~70%, колонны ~50%.
     - Игрок может «заходить» визуально за край блока.
     - Для врагов — чуть более строгая коллизия (60–70%).
     ============================================================ */

  /**
   * Может ли точка (x, y) находиться на проходимом полу?
   * Базовая проверка по сетке.
   */
  isWalkable(x, y) {
    if (!this.dungeon) return true;
    if (x < 0 || y < 0 || x >= this.mapW || y >= this.mapH) return false;
    const cs = this.dungeon.cellSize;
    const i = Math.floor(x / cs), j = Math.floor(y / cs);
    if (i < 0 || j < 0 || i >= this.dungeon.gridW || j >= this.dungeon.gridH) return false;
    return this.dungeon.grid[j * this.dungeon.gridW + i] === 1;
  },

  /**
   * Проверка с учётом «половинного» хитбокса.
   * Стены на сетке имеют уменьшенную зону коллизии: центральные 50–70%
   * ячейки считаются непроходимыми, остаток — «мягкий край».
   * @param {number} x — мировая координата
   * @param {number} y — мировая координата
   * @param {number} shrinkFactor — 0..1, сколько «сжимать» хитбокс стены
   *   (0.5 = 50% хитбокс в центре ячейки; 0.3 = 30% отступ с каждой стороны)
   */
  isWalkableSoft(x, y, shrinkFactor) {
    if (!this.dungeon) return true;
    if (x < 0 || y < 0 || x >= this.mapW || y >= this.mapH) return false;
    const cs = this.dungeon.cellSize;
    const i = Math.floor(x / cs), j = Math.floor(y / cs);
    if (i < 0 || j < 0 || i >= this.dungeon.gridW || j >= this.dungeon.gridH) return false;
    // Если ячейка проходима — ok
    if (this.dungeon.grid[j * this.dungeon.gridW + i] === 1) return true;
    // Ячейка — стена. Проверяем, попадает ли точка в уменьшенный хитбокс.
    // shrinkFactor определяет отступ от краёв ячейки (в долях от размера).
    const sf = shrinkFactor || 0.25; // по умолчанию 25% отступ = 50% хитбокс
    const cellX = i * cs;
    const cellY = j * cs;
    const insetX = cs * sf;
    const insetY = cs * sf;
    // Уменьшенный хитбокс стены — центральная часть ячейки
    if (x >= cellX + insetX && x <= cellX + cs - insetX &&
        y >= cellY + insetY && y <= cellY + cs - insetY) {
      return false; // внутри жёсткого ядра стены
    }
    // На «мягком» краю — проходимо (игрок может заходить за визуальный край)
    return true;
  },

  /** Проверка, что прямоугольник (cx-rad..cx+rad) полностью на полу.
   *  Используется для движения сущностей. rad — половина ширины квадрата.
   *  shrinkFactor игнорируется — всегда строгая проверка (без захода в стену). */
  rectIsWalkable(cx, cy, rad, shrinkFactor) {
    if (!this.dungeon) return true;
    // Строгая проверка по 4 углам + центр — сущности НЕ могут заходить в стену.
    // Это гарантирует корректное скольжение вдоль стен (раздельные оси в moveWithCollision).
    return this.isWalkable(cx - rad, cy - rad) &&
           this.isWalkable(cx + rad, cy - rad) &&
           this.isWalkable(cx - rad, cy + rad) &&
           this.isWalkable(cx + rad, cy + rad) &&
           this.isWalkable(cx, cy);
  },

  /**
   * Двинуть сущность по (dx, dy) с раздельной проверкой осей + скольжение вдоль стен.
   * Каждая ось обрабатывается независимо: если одна заблокирована, другая всё равно работает.
   * Это даёт плавное скольжение вдоль любой стены (горизонтальной/вертикальной/диагональной).
   * shrinkFactor игнорируется — строгая коллизия (без захода в стену).
   * Возвращает { x, y, blockedX, blockedY }.
   */
  moveWithCollision(x, y, dx, dy, rad, shrinkFactor) {
    if (!this.dungeon) return { x: x + dx, y: y + dy, blockedX: false, blockedY: false };
    let nx = x, ny = y;
    let blockedX = false, blockedY = false;

    // --- Ось X: пробуем полный шаг, иначе бинарный поиск (8 итераций) ---
    if (dx !== 0) {
      const tryX = x + dx;
      if (this.rectIsWalkable(tryX, y, rad)) {
        nx = tryX;
      } else {
        blockedX = true;
        // Бинарный поиск: находим максимально возможное продвижение по X
        let lo = 0, hi = Math.abs(dx);
        const sign = dx > 0 ? 1 : -1;
        for (let step = 0; step < 8; step++) {
          const mid = (lo + hi) * 0.5;
          if (this.rectIsWalkable(x + sign * mid, y, rad)) {
            lo = mid;
          } else {
            hi = mid;
          }
        }
        // Применяем любое ненулевое продвижение (порог ~0.01px)
        if (lo > 0.01) {
          nx = x + sign * lo;
        }
      }
    }

    // --- Ось Y: пробуем полный шаг (от новой X), иначе бинарный поиск ---
    if (dy !== 0) {
      const tryY = y + dy;
      if (this.rectIsWalkable(nx, tryY, rad)) {
        ny = tryY;
      } else {
        blockedY = true;
        let lo = 0, hi = Math.abs(dy);
        const sign = dy > 0 ? 1 : -1;
        for (let step = 0; step < 8; step++) {
          const mid = (lo + hi) * 0.5;
          if (this.rectIsWalkable(nx, y + sign * mid, rad)) {
            lo = mid;
          } else {
            hi = mid;
          }
        }
        if (lo > 0.01) {
          ny = y + sign * lo;
        }
      }
    }

    // --- Если обе оси заблокированы, пробуем каждую отдельно от исходной позиции ---
    if (blockedX && blockedY) {
      // Пробуем только X от исходной Y
      if (dx !== 0 && this.rectIsWalkable(x + dx, y, rad)) {
        nx = x + dx;
        blockedX = false;
      }
      // Пробуем только Y от исходной X
      if (dy !== 0 && this.rectIsWalkable(x, y + dy, rad)) {
        ny = y + dy;
        blockedY = false;
      }
    }

    return { x: nx, y: ny, blockedX, blockedY };
  },

  /** Случайная проходимая точка внутри комнаты (или null). */
  randomPointInRoom(room, rad) {
    rad = rad || 16;
    if (!room) return null;
    for (let i = 0; i < 30; i++) {
      const x = room.x + 20 + this.rng() * (room.w - 40);
      const y = room.y + 20 + this.rng() * (room.h - 40);
      if (this.rectIsWalkable(x, y, rad)) return { x, y };
    }
    return { x: room.x + room.w / 2, y: room.y + room.h / 2 };
  },

  /** Случайная точка в любой не-секретной комнате — для волн врагов. */
  randomEnemySpawnPoint(player, minDist, maxDist) {
    if (!this.dungeon) return null;
    const rooms = this.dungeon.rooms.filter(r => !r.isSecret);
    if (rooms.length === 0) return null;
    for (let i = 0; i < 40; i++) {
      const r = rooms[Math.floor(this.rng() * rooms.length)];
      const x = r.x + 20 + this.rng() * (r.w - 40);
      const y = r.y + 20 + this.rng() * (r.h - 40);
      const d = Math.hypot(x - player.x, y - player.y);
      if (d >= minDist && d <= maxDist && this.rectIsWalkable(x, y, 16)) {
        return { x, y };
      }
    }
    // fallback — любая проходимая точка в случайной комнате
    const r = rooms[Math.floor(this.rng() * rooms.length)];
    return this.randomPointInRoom(r, 16);
  },

  /* ============================================================
     attractToWalkable — притяжение объектов к проходимой зоне.
     Сундуки, кристаллы опыта, враги не должны застревать в стенах.
     ============================================================ */

  /**
   * Найти ближайшую проходимую точку к (x, y).
   * Проверяет 8 направлений с шагом step, в радиусе до maxDist.
   * Возвращает { x, y } или null если не нашлось.
   */
  findNearestWalkable(x, y, step, maxDist) {
    if (!this.dungeon) return { x, y };
    if (this.isWalkable(x, y)) return { x, y };
    step = step || 10;
    maxDist = maxDist || 200;
    const dirs = [
      { dx: 0, dy: -1 }, { dx: 0, dy: 1 }, { dx: -1, dy: 0 }, { dx: 1, dy: 0 },
      { dx: -1, dy: -1 }, { dx: 1, dy: -1 }, { dx: -1, dy: 1 }, { dx: 1, dy: 1 },
    ];
    let bestDist = Infinity;
    let best = null;
    for (let dist = step; dist <= maxDist; dist += step) {
      for (const d of dirs) {
        const tx = x + d.dx * dist;
        const ty = y + d.dy * dist;
        if (tx < 0 || ty < 0 || tx >= this.mapW || ty >= this.mapH) continue;
        if (this.isWalkable(tx, ty)) {
          const dd = dist;
          if (dd < bestDist) {
            bestDist = dd;
            best = { x: tx, y: ty };
          }
        }
      }
      if (best) return best; // нашли на этом расстоянии — ближе не будет
    }
    return best;
  },

  /**
   * Шаг 1: Улучшенное притяжение объектов из непроходимых мест.
   * Скорость 120 px/sec (быстрее, чем раньше).
   * Если не нашли проходимую точку в 100px — телепорт к центру ближайшей комнаты.
   * @param {object} obj — объект с полями .x, .y
   * @param {number} speed — скорость притяжения px/sec (по умолчанию 120)
   * @param {number} dt — дельта времени
   * @returns {boolean} true если объект был в непроходимой зоне и сдвинут
   */
  attractToWalkable(obj, speed, dt) {
    if (!this.dungeon || !obj) return false;
    if (this.isWalkable(obj.x, obj.y)) return false;

    // Объект в стене — ищем ближайшую проходимую точку (8 направлений, шаг 8px)
    const target = this.findNearestWalkable(obj.x, obj.y, 8, 100);
    if (!target) {
      // Крайний случай: телепорт к центру ближайшей комнаты
      const room = this._findNearestRoom(obj.x, obj.y);
      if (room) { obj.x = room.cx; obj.y = room.cy; }
      return true;
    }

    speed = speed || 120;
    const dx = target.x - obj.x;
    const dy = target.y - obj.y;
    const dist = Math.hypot(dx, dy);
    if (dist < 2) {
      obj.x = target.x;
      obj.y = target.y;
      return true;
    }
    const move = Math.min(speed * dt, dist);
    obj.x += (dx / dist) * move;
    obj.y += (dy / dist) * move;
    return true;
  },

  /** Шаг 1: найти ближайшую комнату к точке (x, y). */
  _findNearestRoom(x, y) {
    if (!this.dungeon || !this.dungeon.rooms) return null;
    let best = null, bestDist = Infinity;
    for (const r of this.dungeon.rooms) {
      if (r.isSecret) continue;
      const d = Math.hypot(r.cx - x, r.cy - y);
      if (d < bestDist) { bestDist = d; best = r; }
    }
    return best;
  },

  /**
   * Вытащить игрока из стены — если игрок каким-то образом оказался внутри стены,
   * телепортируем его к ближайшей проходимой точке.
   */
  attractPlayerFromWalls(player, dt) {
    if (!this.dungeon || !player) return;
    if (this.isWalkable(player.x, player.y)) return;
    // Игрок в стене — вытаскиваем
    const target = this.findNearestWalkable(player.x, player.y, 8, 200);
    if (target) {
      player.x = target.x;
      player.y = target.y;
    }
  },

  /**
   * Шаг 1: Обработка всех «застрявших» объектов.
   * Вызывается из Game.update() раз в 0.5 сек (для врагов/лута).
   * @param {object} game — объект Game с пулами
   * @param {number} dt — дельта времени
   */
  attractAllStuck(game, dt) {
    if (!this.dungeon || !game) return;

    // XP кристаллы
    if (game.xpDrops) {
      game.xpDrops.forEachActive((xp) => {
        this.attractToWalkable(xp, 120, dt);
      });
    }

    // Золото
    if (game.goldDrops) {
      game.goldDrops.forEachActive((g) => {
        this.attractToWalkable(g, 120, dt);
      });
    }

    // Сундук
    if (game.chest && game.chest.active !== false) {
      this.attractToWalkable(game.chest, 80, dt);
    }

    // Враги — быстрое притяжение (120 px/sec), телепорт после 1.5 сек
    if (game.enemies) {
      game.enemies.forEachActive((e) => {
        if (!this.isWalkable(e.x, e.y)) {
          if (!e._stuckTimer) e._stuckTimer = 0;
          e._stuckTimer += dt;
          if (e._stuckTimer >= 1.5) {
            // Телепорт к ближайшей проходимой точке или комнате
            const target = this.findNearestWalkable(e.x, e.y, 8, 100);
            if (target) { e.x = target.x; e.y = target.y; }
            else {
              const room = this._findNearestRoom(e.x, e.y);
              if (room) { e.x = room.cx; e.y = room.cy; }
            }
            e._stuckTimer = 0;
          } else {
            this.attractToWalkable(e, 120, dt);
          }
        } else {
          e._stuckTimer = 0;
        }
      });
    }

    // Боссы — вытаскиваем так же
    if (window.Bosses && Bosses.current) {
      const boss = Bosses.current;
      if (!this.isWalkable(boss.x, boss.y)) {
        this.attractToWalkable(boss, 150, dt);
      }
    }
    if (window.Bosses && Bosses.guardian) {
      const g = Bosses.guardian;
      if (!this.isWalkable(g.x, g.y)) {
        this.attractToWalkable(g, 150, dt);
      }
    }
  },

  /* ============================================================
     Loop tick — обновление ловушек и анимаций
     ============================================================ */

  update(dt) {
    this.time += dt;
    if (!this.dungeon) return;
    const player = (window.Game && Game.player) ? Game.player : null;

    // Ловушки
    const traps = this.dungeon.traps;
    for (let i = 0; i < traps.length; i++) {
      const t = traps[i];
      if (t.kind === 'spike') this._updateSpikeTrap(t, dt, player);
      else if (t.kind === 'fire') this._updateFireTrap(t, dt, player);
      else if (t.kind === 'ice_spike') this._updateIceSpikeTrap(t, dt, player);
      else if (t.kind === 'slippery_floor') this._updateSlipperyFloor(t, dt, player);
      else if (t.kind === 'fire_geyser') this._updateFireGeyser(t, dt, player);
      else if (t.kind === 'rockfall') this._updateRockfall(t, dt, player);
      else if (t.kind === 'poison_plant') this._updatePoisonPlant(t, dt, player);
      else if (t.kind === 'root_grab') this._updateRootGrab(t, dt, player);
      else if (t.kind === 'magic_rune') this._updateMagicRune(t, dt, player);
      else if (t.kind === 'portrait_trap') this._updatePortraitTrap(t, dt, player);
    }

    // Кулдауны рычагов
    if (this.dungeon.levers) {
      for (const lv of this.dungeon.levers) {
        if (lv._cooldown > 0) lv._cooldown = Math.max(0, lv._cooldown - dt);
      }
    }

    // Дверь (анимация открытия)
    const door = this.dungeon.secretDoor;
    if (door && door.open && door.openProgress < 1) {
      door.openProgress = Math.min(1, door.openProgress + dt * 1.5);
      if (!door._gridCleared) {
        this._fillRectFloor(this.dungeon, door.x, door.y, door.w, door.h);
        door._gridCleared = true;
      }
    }

    // Шаг 17: обновить загадки и ловушки
    if (GameMap.updateStep17) GameMap.updateStep17(dt, player);
  },

  _updateSpikeTrap(t, dt, player) {
    const c = CONFIG.TRAP.SPIKE;
    t.timer += dt;
    // Жизненный цикл: hidden -> warning -> active -> hidden
    if (t.phase === 'hidden') {
      if (t.timer >= c.HIDDEN_TIME) {
        t.phase = 'warning'; t.timer = 0;
      }
    } else if (t.phase === 'warning') {
      if (t.timer >= c.WARN_TIME) {
        t.phase = 'active'; t.timer = 0;
      }
    } else if (t.phase === 'active') {
      // Урон если игрок в зоне (только в момент перехода и непрерывно с
      // hitInterval-подобной задержкой — для простоты, один раз за фазу)
      if (player && !t._struck) {
        const dx = player.x - t.cx, dy = player.y - t.cy;
        if (Math.abs(dx) <= t.w / 2 + player.size / 2 &&
            Math.abs(dy) <= t.h / 2 + player.size / 2) {
          if (window.Player && Player.takeDamage) Player.takeDamage(player, c.DAMAGE, null);
          else player.hp -= c.DAMAGE;
          t._struck = true;
          if (window.Particles) {
            Particles.burst(player.x, player.y, 5, {
              color: '#c0392b', speedMin: 60, speedMax: 140,
              lifeMin: 0.3, lifeMax: 0.5, sizeMin: 2, sizeMax: 3,
            });
          }
        }
      }
      if (t.timer >= c.ACTIVE_TIME) {
        t.phase = 'hidden'; t.timer = 0; t._struck = false;
      }
    }
  },

  _updateFireTrap(t, dt, player) {
    const c = CONFIG.TRAP.FIRE;
    t.timer += dt;
    if (t.phase === 'idle') {
      if (t.timer >= c.INTERVAL - c.WARN_TIME) {
        t.phase = 'warning'; t.timer = 0;
      }
    } else if (t.phase === 'warning') {
      if (t.timer >= c.WARN_TIME) {
        t.phase = 'active'; t.timer = 0;
        t._struck = false;
        // Создаём горящий ground effect в зоне струи (поджигание)
        if (window.GameMap) {
          // Несколько кружков вдоль направления
          const steps = Math.floor(t.range / 30);
          for (let s = 1; s <= steps; s++) {
            const px = t.cx + t.dx * 30 * s;
            const py = t.cy + t.dy * 30 * s;
            this.spawnGroundEffect('fire', px, py, {
              radius: 22, life: c.DOT_TIME, dps: c.DOT_DPS,
              color: 'rgba(255, 120, 30, 0.55)',
            });
          }
        }
      }
    } else if (t.phase === 'active') {
      // Прямой контакт со струёй — мгновенный урон один раз
      if (player && !t._struck) {
        if (this._pointInFireBeam(player.x, player.y, t)) {
          if (window.Player && Player.takeDamage) Player.takeDamage(player, c.DAMAGE, null);
          else player.hp -= c.DAMAGE;
          t._struck = true;
        }
      }
      if (t.timer >= t.activeTime) {
        t.phase = 'idle'; t.timer = 0;
      }
    }
  },

  _pointInFireBeam(px, py, t) {
    // Снимаем координату вдоль направления и поперёк
    const lx = px - t.cx;
    const ly = py - t.cy;
    const along = lx * t.dx + ly * t.dy;
    const across = lx * (-t.dy) + ly * t.dx;
    return along >= 0 && along <= t.range &&
           Math.abs(across) <= t.width / 2;
  },

  /* ============================================================
     Levers / puzzle
     ============================================================ */

  /**
   * Проверить, не активирует ли игрок рычаг (по касанию).
   * Если да — переключаем состояние и проверяем комбинацию.
   * Возвращает событие: 'toggle' | 'solved' | 'reset' | null.
   */
  tryToggleLever(player) {
    if (!this.dungeon || !player) return null;
    const lev = CONFIG.LEVER;
    let event = null;
    for (const lv of this.dungeon.levers) {
      const cx = lv.x + lv.w / 2, cy = lv.y + lv.h / 2;
      const dx = cx - player.x, dy = cy - player.y;
      const r = lev.INTERACT_RADIUS + player.size / 2;
      if (dx * dx + dy * dy <= r * r) {
        if (!lv._cooldown) lv._cooldown = 0;
        if (lv._cooldown > 0) continue;
        lv.state = lv.state === 0 ? 1 : 0;
        lv._cooldown = 1.0;
        event = 'toggle';
        if (window.Particles) {
          Particles.spark(cx, cy - 4, 0, -40, 0.4, '#ffd84a', 3);
        }
      }
    }
    if (event === 'toggle') {
      const ok = this._checkPuzzleSolved();
      if (ok) {
        this._openSecretDoor();
        event = 'solved';
      } else if (this._allLeversFlipped()) {
        this._scheduleResetIfWrong();
      }
    }
    return event;
  },

  _checkPuzzleSolved() {
    if (!this.dungeon || !this.dungeon.levers) return false;
    for (const lv of this.dungeon.levers) {
      if (lv.state !== lv.correct) return false;
    }
    return true;
  },

  _allLeversFlipped() {
    if (!this.dungeon || !this.dungeon.levers) return false;
    for (const lv of this.dungeon.levers) {
      if (lv.state === 0) return false;
    }
    return true;
  },

  _scheduleResetIfWrong() {
    if (!this.dungeon || this.dungeon._resetTimer) return;
    const targetDungeon = this.dungeon;  // фиксируем ссылку для замыкания
    this.dungeon._resetTimer = setTimeout(() => {
      // Если за это время подземелье было перегенерировано — игнорируем
      if (this.dungeon !== targetDungeon) return;
      this.dungeon._resetTimer = null;
      if (!this._checkPuzzleSolved()) {
        for (const lv of this.dungeon.levers) lv.state = 0;
        if (window.Particles) {
          for (const lv of this.dungeon.levers) {
            Particles.burst(lv.x + lv.w / 2, lv.y + lv.h / 2, 4, {
              color: '#c0392b', speedMin: 30, speedMax: 90,
              lifeMin: 0.3, lifeMax: 0.5,
            });
          }
        }
      }
    }, CONFIG.LEVER.RESET_DELAY * 1000);
  },

  _openSecretDoor() {
    const door = this.dungeon.secretDoor;
    if (!door || door.open) return;
    door.open = true;
    door.openProgress = 0;
    if (window.Particles) {
      Particles.ring(door.x + door.w / 2, door.y + door.h / 2, 80, 0.5,
        'rgba(255, 215, 80, 0.85)', 4);
      Particles.text(door.x + door.w / 2, door.y - 16,
        'SECRET ROOM OPENED', 1.6, '#ffd84a', 14);
    }
    // Спавним сундук в секретной комнате (через main.js)
    if (window.Game && Game.spawnSecretChest) Game.spawnSecretChest();
  },

  /* ============================================================
     RENDER
     ============================================================ */

  /** Отрисовать пол + декор. ctx уже сдвинут на -cam. */
  render(ctx, cam, viewW, viewH) {
    // === Небесный город: фоновый слой неба (рисуется ПЕРВЫМ) ===
    if (this.currentBiome && this.currentBiome.id === 'sky_citadel') {
      this._renderSkyBackground(ctx, cam, viewW, viewH);
    } else {
      // Фон карты — почти чёрный (стены)
      ctx.fillStyle = '#0e0e0e';
      ctx.fillRect(0, 0, this.mapW, this.mapH);
    }

    // Кешированный пол
    if (this._floorCache) {
      const sx = cam.x, sy = cam.y;
      const sw = Math.min(viewW, this.mapW - sx);
      const sh = Math.min(viewH, this.mapH - sy);
      if (sw > 0 && sh > 0) {
        ctx.drawImage(this._floorCache, sx, sy, sw, sh, sx, sy, sw, sh);
      }
    }

    if (!this.dungeon) {
      // Совместимость: если подземелье не сгенерено
      ctx.fillStyle = '#2a2a2a';
      ctx.fillRect(0, 0, this.mapW, this.mapH);
      return;
    }

    // Декор: руны на полу
    this._renderRunes(ctx, cam, viewW, viewH);

    // Декор: мозаичные элементы рисуются в _floorCache, тут пропускаем

    // Двери секретной комнаты (если есть)
    this._renderSecretDoor(ctx);

    // Колонны и саркофаги
    this._renderPillars(ctx, cam, viewW, viewH);
    this._renderSarcophagi(ctx, cam, viewW, viewH);

    // Богатый биом-декор (D&D стиль)
    this._renderBiomeDecor(ctx, cam, viewW, viewH);

    // Декор: паутина
    this._renderWebs(ctx, cam, viewW, viewH);

    // Рычаги
    this._renderLevers(ctx);

    // Ловушки (под факелами, чтобы факелы перекрывали)
    this._renderTraps(ctx, cam, viewW, viewH);

    // Шаг 17: новые загадки и ловушки
    if (GameMap.renderStep17) GameMap.renderStep17(ctx, cam, viewW, viewH);

    // Декор: факелы полностью удалены

    // Подсказки рунами над рычагами
    if (this.dungeon.puzzleHints) {
      ctx.font = 'bold 14px ui-monospace, monospace';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      for (const h of this.dungeon.puzzleHints) {
        ctx.fillStyle = h.color;
        ctx.fillText(h.text, h.x, h.y);
      }
    }

    // Шаг 13: портал
    this.renderPortal(ctx, cam, viewW, viewH);
  },

  /* ============================================================
     Небесный город: фоновый слой неба с облаками и солнцем.
     Создаёт ощущение, что город парит в небесах.
     ============================================================ */

  /** Кеш фона неба (offscreen canvas). Генерируется один раз. */
  _skyBgCache: null,
  _skyClouds: null, // массив облаков с позициями для анимации

  /** Сгенерировать кеш фона неба (вызывается при генерации карты sky_citadel). */
  _buildSkyBackground() {
    const w = this.mapW;
    const h = this.mapH;
    const off = document.createElement('canvas');
    off.width = w;
    off.height = h;
    const ctx = off.getContext('2d');

    // 1) Градиент неба: светло-голубой сверху → ещё светлее снизу
    const grad = ctx.createLinearGradient(0, 0, 0, h);
    grad.addColorStop(0, '#87CEEB');
    grad.addColorStop(0.4, '#a8ddf0');
    grad.addColorStop(1, '#c8e8f8');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);

    // 2) Солнце в верхнем правом углу (статичное)
    const sunX = w * 0.82;
    const sunY = h * 0.12;
    const sunRadius = 40;
    // Мягкое свечение (3 слоя)
    ctx.globalAlpha = 0.15;
    ctx.fillStyle = '#fffde0';
    ctx.beginPath();
    ctx.arc(sunX, sunY, sunRadius * 3, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 0.3;
    ctx.fillStyle = '#fff8b0';
    ctx.beginPath();
    ctx.arc(sunX, sunY, sunRadius * 1.8, 0, Math.PI * 2);
    ctx.fill();
    // Ядро солнца (яркое, пиксельное)
    ctx.globalAlpha = 1;
    ctx.fillStyle = '#fffde0';
    ctx.beginPath();
    ctx.arc(sunX, sunY, sunRadius, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(sunX, sunY, sunRadius * 0.6, 0, Math.PI * 2);
    ctx.fill();

    // 3) Статичные облака (крупные, полупрозрачные, пиксельные формы)
    const rng = this.rng || Math.random;
    const clouds = [];
    const cloudCount = 12 + Math.floor(rng() * 6);
    for (let i = 0; i < cloudCount; i++) {
      const cx = rng() * w;
      const cy = rng() * h;
      const cw = 80 + rng() * 200;
      const ch = 30 + rng() * 60;
      const alpha = 0.2 + rng() * 0.3;
      clouds.push({ x: cx, y: cy, w: cw, h: ch, alpha, speed: 0.3 + rng() * 0.4 });

      // Рисуем облако из пиксельных «бамп» (несколько кругов)
      ctx.globalAlpha = alpha;
      ctx.fillStyle = '#ffffff';
      const bumps = 4 + Math.floor(rng() * 4);
      for (let b = 0; b < bumps; b++) {
        const bx = cx + (b / bumps) * cw - cw * 0.3;
        const by = cy + (rng() - 0.5) * ch * 0.5;
        const br = ch * 0.3 + rng() * ch * 0.4;
        ctx.beginPath();
        ctx.arc(bx, by, br, 0, Math.PI * 2);
        ctx.fill();
      }
    }
    ctx.globalAlpha = 1;

    this._skyBgCache = off;
    this._skyClouds = clouds;
  },

  /** Рендер фона неба (вызывается каждый кадр для sky_citadel). */
  _renderSkyBackground(ctx, cam, viewW, viewH) {
    // Рисуем кешированный фон (статичное небо + солнце)
    if (this._skyBgCache) {
      const sx = cam.x, sy = cam.y;
      const sw = Math.min(viewW, this.mapW - sx);
      const sh = Math.min(viewH, this.mapH - sy);
      if (sw > 0 && sh > 0) {
        ctx.drawImage(this._skyBgCache, sx, sy, sw, sh, sx, sy, sw, sh);
      }
    } else {
      // Фоллбэк: градиент прямо на canvas
      ctx.fillStyle = '#87CEEB';
      ctx.fillRect(0, 0, this.mapW, this.mapH);
    }

    // Анимация облаков: лёгкое покачивание (сдвиг по X на 0.5px/сек)
    if (this._skyClouds) {
      const t = this.time;
      ctx.fillStyle = '#ffffff';
      for (const cloud of this._skyClouds) {
        // Облако дрейфует по X с покачиванием по Y
        const offsetX = Math.sin(t * cloud.speed * 0.3 + cloud.x * 0.01) * 8;
        const offsetY = Math.cos(t * cloud.speed * 0.2 + cloud.y * 0.02) * 3;
        const cx = cloud.x + offsetX;
        const cy = cloud.y + offsetY;

        // Проверка видимости
        if (cx + cloud.w < cam.x - 50 || cx - cloud.w > cam.x + viewW + 50 ||
            cy + cloud.h < cam.y - 50 || cy - cloud.h > cam.y + viewH + 50) continue;

        ctx.globalAlpha = cloud.alpha * 0.6;
        const bumps = 4;
        for (let b = 0; b < bumps; b++) {
          const bx = cx + (b / bumps) * cloud.w - cloud.w * 0.3;
          const by = cy + Math.sin(b * 1.5) * cloud.h * 0.2;
          const br = cloud.h * 0.3 + (b % 2) * cloud.h * 0.2;
          ctx.beginPath();
          ctx.arc(bx, by, br, 0, Math.PI * 2);
          ctx.fill();
        }
      }
      ctx.globalAlpha = 1;
    }

    // Полупрозрачный затемняющий слой, чтобы стены читались поверх
    // (стены уже в _floorCache поверх фона)
  },

  _isOnScreen(x, y, w, h, cam, vw, vh) {
    return !(x + w < cam.x || x > cam.x + vw || y + h < cam.y || y > cam.y + vh);
  },

  _renderPillars(ctx, cam, vw, vh) {
    const biome = this.currentBiome;
    const biomeId = biome ? biome.id : 'crypt';
    const baseColor = biome ? biome.pillarColor : '#4a4a4a';
    const capColor = biome ? biome.pillarCapColor : '#5a5a5a';

    // Получаем тайл текстуры для колонн (тот же что и для стен)
    const tile = this._getWallTile(biomeId);

    for (const p of this.dungeon.pillars) {
      if (!this._isOnScreen(p.x, p.y, p.w, p.h, cam, vw, vh)) continue;

      // Тело колонны с текстурой
      if (tile) {
        ctx.drawImage(tile, 0, 0, 32, 32, p.x, p.y, p.w, p.h);
      } else {
        ctx.fillStyle = baseColor;
        ctx.fillRect(p.x, p.y, p.w, p.h);
      }

      // Обводка
      ctx.strokeStyle = '#0e0e0e';
      ctx.lineWidth = 2;
      ctx.strokeRect(p.x + 0.5, p.y + 0.5, p.w - 1, p.h - 1);

      // Светлая верхушка (имитация капители)
      ctx.fillStyle = capColor;
      ctx.fillRect(p.x - 2, p.y, p.w + 4, 4);
      // Нижняя база
      ctx.fillRect(p.x - 1, p.y + p.h - 3, p.w + 2, 3);
    }
  },

  _renderSarcophagi(ctx, cam, vw, vh) {
    const biome = this.currentBiome;
    const biomeId = biome ? biome.id : 'crypt';
    const tile = this._getWallTile(biomeId);

    for (const s of this.dungeon.sarcophagi) {
      if (!this._isOnScreen(s.x, s.y, s.w, s.h, cam, vw, vh)) continue;

      // Тело саркофага с текстурой биома
      if (tile) {
        // Повторяем тайл по ширине саркофага
        const pattern = ctx.createPattern(tile, 'repeat');
        ctx.fillStyle = pattern;
        ctx.fillRect(s.x, s.y, s.w, s.h);
      } else {
        ctx.fillStyle = '#5a4a3a';
        ctx.fillRect(s.x, s.y, s.w, s.h);
      }

      // Обводка
      ctx.strokeStyle = '#0e0e0e';
      ctx.lineWidth = 2;
      ctx.strokeRect(s.x + 0.5, s.y + 0.5, s.w - 1, s.h - 1);

      // Крест / символ по биому
      ctx.fillStyle = biomeId === 'sky_citadel' ? '#c9a84c' :
                     biomeId === 'castle' ? '#8a6a2c' :
                     biomeId === 'elven_forest' ? '#60ff80' :
                     '#3a2a1a';
      ctx.globalAlpha = 0.7;
      ctx.fillRect(s.x + s.w / 2 - 2, s.y + 4, 4, s.h - 8);
      ctx.fillRect(s.x + s.w / 2 - 8, s.y + s.h / 2 - 2, 16, 4);
      ctx.globalAlpha = 1;
    }
  },

  _renderRunes(/* ctx, cam, vw, vh */) {
    // Декоративные мерцающие руны отключены — визуальный мусор (Шаг 7).
  },

  _renderWebs(ctx, cam, vw, vh) {
    ctx.strokeStyle = 'rgba(220, 220, 220, 0.25)';
    ctx.lineWidth = 1;
    for (const w of this.dungeon.decor.webs) {
      if (w.x < cam.x - 20 || w.x > cam.x + vw + 20 ||
          w.y < cam.y - 20 || w.y > cam.y + vh + 20) continue;
      const k = w.kind;
      const sx = (k === 'tr' || k === 'br') ? -1 : 1;
      const sy = (k === 'bl' || k === 'br') ? -1 : 1;
      ctx.beginPath();
      // Несколько коротких линий из угла
      for (let i = 0; i < 4; i++) {
        const len = 14 + i * 3;
        const ang = (Math.PI / 2) * (i / 3);
        ctx.moveTo(w.x, w.y);
        ctx.lineTo(w.x + sx * Math.cos(ang) * len, w.y + sy * Math.sin(ang) * len);
      }
      ctx.stroke();
    }
  },

  /** Отрисовать богатый декор по биомам — только видимая область. */
  _renderBiomeDecor(ctx, cam, vw, vh) {
    if (!this.dungeon || !this.dungeon.decor.biomeDecor) return;
    const decor = this.dungeon.decor.biomeDecor;
    const t = this.time;
    const biome = this.currentBiome;
    const isFloating = biome && biome.floatingAnimation;

    for (let i = 0; i < decor.length; i++) {
      const d = decor[i];
      if (d.x < cam.x - 20 || d.x > cam.x + vw + 20 ||
          d.y < cam.y - 20 || d.y > cam.y + vh + 20) continue;

      // Смещение парения для Небесного города
      let yOff = 0;
      if (isFloating && d.floats) {
        yOff = Math.sin(t * (biome.floatSpeed || 1.5) + d.x * 0.1) * (biome.floatAmplitude || 2);
      }

      const dx = d.x, dy = d.y + yOff;
      const s = d.size || 8;

      // Свечение (для светящихся объектов)
      if (d.glow) {
        ctx.globalAlpha = 0.15 + Math.sin(t * 2 + d.x) * 0.05;
        ctx.fillStyle = d.biome === 'fire_mines' ? '#ff6600' :
                       d.biome === 'sky_citadel' ? '#ffe080' :
                       d.biome === 'elven_forest' ? '#60ffa0' : '#ffffff';
        ctx.beginPath();
        ctx.arc(dx, dy, s + 4, 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha = 1;
      }

      // Спрайт декора — используем DECOR_SPRITES если доступен
      const DS = window.DECOR_SPRITES;
      if (DS && DS[d.type]) {
        ctx.drawImage(DS[d.type], dx - s / 2, dy - s / 2, s, s);
      } else {
        // Фоллбэк: простая геометрия
        this._renderDecorFallback(ctx, d, dx, dy, s);
      }
    }
  },

  /** Фоллбэк-отрисовка декора простыми фигурами. */
  _renderDecorFallback(ctx, d, x, y, s) {
    const hs = s / 2;
    switch (d.type) {
      case 'bones': case 'skull': case 'chain_skull':
        ctx.fillStyle = '#c0b090'; ctx.fillRect(x - hs, y - hs, s, s * 0.6);
        ctx.fillStyle = '#a09070'; ctx.fillRect(x - 2, y - hs, 4, s);
        break;
      case 'broken_column':
        ctx.fillStyle = '#6a6a6a'; ctx.fillRect(x - hs, y - hs, s, s);
        ctx.fillStyle = '#4a4a4a'; ctx.fillRect(x - hs + 2, y - hs + 2, s - 4, 3);
        break;
      case 'ice_crystal':
        ctx.fillStyle = '#80c0e0'; ctx.beginPath();
        ctx.moveTo(x, y - hs); ctx.lineTo(x + hs, y + hs); ctx.lineTo(x - hs, y + hs); ctx.closePath(); ctx.fill();
        break;
      case 'stalactite': case 'snow_pile':
        ctx.fillStyle = d.type === 'stalactite' ? '#7a8a9a' : '#e0e8f0';
        ctx.beginPath(); ctx.arc(x, y, hs, 0, Math.PI * 2); ctx.fill();
        break;
      case 'lava_pool': case 'ember':
        ctx.fillStyle = '#ff4400'; ctx.globalAlpha = 0.6;
        ctx.beginPath(); ctx.arc(x, y, hs, 0, Math.PI * 2); ctx.fill();
        ctx.globalAlpha = 1;
        break;
      case 'ore_chunk': case 'rock_pile':
        ctx.fillStyle = '#8a7a5a'; ctx.fillRect(x - hs, y - hs * 0.6, s, s * 0.6);
        break;
      case 'mine_cart':
        ctx.fillStyle = '#5a4a3a'; ctx.fillRect(x - hs, y - hs * 0.5, s, s * 0.7);
        ctx.fillStyle = '#3a3a3a'; ctx.beginPath(); ctx.arc(x - 3, y + hs * 0.6, 3, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(x + 3, y + hs * 0.6, 3, 0, Math.PI * 2); ctx.fill();
        break;
      case 'glowing_mushroom': case 'magic_mushroom':
        ctx.fillStyle = '#40e0d0'; ctx.beginPath(); ctx.arc(x, y - 2, hs * 0.8, Math.PI, 0); ctx.fill();
        ctx.fillStyle = '#6a5a4a'; ctx.fillRect(x - 1, y - 1, 2, hs);
        break;
      case 'mossy_rock': case 'rune_stone':
        ctx.fillStyle = '#5a6a4a'; ctx.fillRect(x - hs, y - hs * 0.7, s, s * 0.7);
        if (d.type === 'rune_stone') { ctx.fillStyle = '#80c0ff'; ctx.fillRect(x - 2, y - 3, 4, 2); }
        break;
      case 'tapestry': case 'banner':
        ctx.fillStyle = '#8b0000'; ctx.fillRect(x - 3, y - hs, 6, s);
        ctx.fillStyle = '#ffd700'; ctx.fillRect(x - 2, y - hs + 2, 4, 2);
        break;
      case 'armor_stand':
        ctx.fillStyle = '#808080'; ctx.fillRect(x - 3, y - hs, 6, s);
        ctx.fillStyle = '#a0a0a0'; ctx.fillRect(x - 4, y - hs + 2, 8, 3);
        break;
      case 'candelabra': case 'elven_lantern': case 'chain_lantern':
        ctx.fillStyle = '#c9a84c'; ctx.fillRect(x - 1, y - hs, 2, s * 0.8);
        ctx.fillStyle = '#ffcc00'; ctx.beginPath(); ctx.arc(x, y - hs, 3, 0, Math.PI * 2); ctx.fill();
        break;
      case 'golden_urn':
        ctx.fillStyle = '#c9a84c'; ctx.beginPath(); ctx.arc(x, y, hs * 0.8, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#a08030'; ctx.fillRect(x - hs * 0.5, y - hs, s * 0.5, 3);
        break;
      case 'marble_statue': case 'angel_wing':
        ctx.fillStyle = '#f0f0f0'; ctx.fillRect(x - hs * 0.5, y - hs, s * 0.5, s);
        ctx.fillStyle = '#d0d0d0'; ctx.beginPath(); ctx.arc(x, y - hs, hs * 0.4, 0, Math.PI * 2); ctx.fill();
        break;
      case 'floating_crystal': case 'light_pillar':
        ctx.fillStyle = '#ffe080'; ctx.beginPath();
        ctx.moveTo(x, y - hs); ctx.lineTo(x + hs * 0.6, y); ctx.lineTo(x, y + hs); ctx.lineTo(x - hs * 0.6, y); ctx.closePath(); ctx.fill();
        break;
      case 'bloom_bush': case 'flower_bush':
        ctx.fillStyle = '#3a8a3a'; ctx.beginPath(); ctx.arc(x, y, hs, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#ff69b4'; ctx.beginPath(); ctx.arc(x + 2, y - 2, 2, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#ffff00'; ctx.beginPath(); ctx.arc(x - 2, y + 1, 1.5, 0, Math.PI * 2); ctx.fill();
        break;
      case 'nature_altar':
        ctx.fillStyle = '#6a8a5a'; ctx.fillRect(x - hs, y - hs * 0.5, s, s * 0.7);
        ctx.fillStyle = '#80c0ff'; ctx.beginPath(); ctx.arc(x, y - hs * 0.3, 3, 0, Math.PI * 2); ctx.fill();
        break;
      case 'barrel': case 'ore_crate':
        ctx.fillStyle = d.type === 'barrel' ? '#8b6914' : '#6a5a3a';
        ctx.fillRect(x - hs, y - hs, s, s);
        ctx.strokeStyle = '#4a3a1a'; ctx.lineWidth = 1; ctx.strokeRect(x - hs, y - hs, s, s);
        break;
      case 'pickaxe':
        ctx.strokeStyle = '#8a8a8a'; ctx.lineWidth = 1.5;
        ctx.beginPath(); ctx.moveTo(x - hs, y + hs); ctx.lineTo(x + hs, y - hs); ctx.stroke();
        ctx.fillStyle = '#5a5a5a'; ctx.fillRect(x + hs - 3, y - hs, 4, 4);
        break;
      case 'forge_anvil':
        ctx.fillStyle = '#4a4a4a'; ctx.fillRect(x - hs, y - hs * 0.3, s, s * 0.5);
        ctx.fillStyle = '#3a3a3a'; ctx.fillRect(x - 2, y + hs * 0.2, 4, hs * 0.5);
        break;
      default:
        ctx.fillStyle = '#6a6a6a'; ctx.fillRect(x - hs * 0.5, y - hs * 0.5, s * 0.5, s * 0.5);
        break;
    }
  },

  _renderTorches(ctx, cam, vw, vh) {
    // Факелы полностью удалены — метод оставлен для совместимости
    return;
  },

  _renderTraps(ctx, cam, vw, vh) {
    const t = this.time;
    for (const tr of this.dungeon.traps) {
      if (!this._isOnScreen(tr.x - 10, tr.y - 10, tr.w + 20, tr.h + 20, cam, vw, vh)) continue;

      // Шаг 13: новые ловушки отрисовываются через _renderBiomeTrap
      if (tr.kind !== 'spike' && tr.kind !== 'fire') {
        this._renderBiomeTrap(ctx, tr);
        continue;
      }

      if (tr.kind === 'spike') {
        // База: тёмная плита
        ctx.fillStyle = '#222';
        ctx.fillRect(tr.x, tr.y, tr.w, tr.h);
        ctx.strokeStyle = '#0a0a0a';
        ctx.lineWidth = 1;
        ctx.strokeRect(tr.x + 0.5, tr.y + 0.5, tr.w - 1, tr.h - 1);

        let height = 0;
        let color = '#8a8a8a';
        if (tr.phase === 'hidden') {
          height = 0;
        } else if (tr.phase === 'warning') {
          height = 4;
          // Мерцание
          const pulse = (Math.sin(t * 30) + 1) / 2;
          color = 'rgba(255, 200, 60, ' + (0.5 + 0.4 * pulse) + ')';
        } else if (tr.phase === 'active') {
          height = 14;
          color = '#c8c8c8';
        }
        if (height > 0) {
          ctx.fillStyle = color;
          // 3 треугольника
          for (let s = 0; s < 3; s++) {
            const sx = tr.x + 6 + s * (tr.w - 12) / 2;
            ctx.beginPath();
            ctx.moveTo(sx, tr.y + tr.h - 4);
            ctx.lineTo(sx + 7, tr.y + tr.h - 4 - height);
            ctx.lineTo(sx + 14, tr.y + tr.h - 4);
            ctx.closePath();
            ctx.fill();
          }
        }
      } else if (tr.kind === 'fire') {
        // Решётка-источник (на стене)
        ctx.fillStyle = '#3a2a18';
        ctx.fillRect(tr.x, tr.y, tr.w, tr.h);
        ctx.strokeStyle = '#0a0a0a';
        ctx.lineWidth = 1;
        ctx.strokeRect(tr.x + 0.5, tr.y + 0.5, tr.w - 1, tr.h - 1);
        // Прутья
        ctx.fillStyle = '#1a1a1a';
        for (let s = 0; s < 4; s++) {
          ctx.fillRect(tr.x + 4 + s * 7, tr.y + 4, 2, tr.h - 8);
        }
        // Эффекты по фазе
        if (tr.phase === 'warning') {
          const pulse = (Math.sin(t * 25) + 1) / 2;
          // Искры на источнике
          ctx.fillStyle = 'rgba(255, 200, 60, ' + (0.4 + 0.4 * pulse) + ')';
          for (let s = 0; s < 4; s++) {
            const sx = tr.cx + Math.cos(s) * 4;
            const sy = tr.cy + Math.sin(s) * 4;
            ctx.beginPath();
            ctx.arc(sx, sy, 2, 0, Math.PI * 2);
            ctx.fill();
          }
        } else if (tr.phase === 'active') {
          // Струя огня
          const beamLen = tr.range;
          const beamW = tr.width;
          ctx.save();
          ctx.translate(tr.cx, tr.cy);
          const ang = Math.atan2(tr.dy, tr.dx);
          ctx.rotate(ang);
          // Внешний слой (оранжевый)
          ctx.fillStyle = 'rgba(255, 100, 30, 0.7)';
          ctx.fillRect(0, -beamW / 2, beamLen, beamW);
          // Внутренний (жёлтый)
          ctx.fillStyle = 'rgba(255, 220, 100, 0.65)';
          ctx.fillRect(0, -beamW / 4, beamLen, beamW / 2);
          // Сердцевина
          ctx.fillStyle = 'rgba(255, 255, 200, 0.9)';
          ctx.fillRect(0, -beamW / 8, beamLen, beamW / 4);
          ctx.restore();
        }
      }
    }
  },

  _renderLevers(ctx) {
    if (!this.dungeon || !this.dungeon.levers) return;
    for (const lv of this.dungeon.levers) {
      // Постамент
      ctx.fillStyle = '#3a3a3a';
      ctx.fillRect(lv.x - 2, lv.y + lv.h - 6, lv.w + 4, 6);
      // Корпус
      ctx.fillStyle = lv.state === 1 ? '#ffd84a' : '#888';
      ctx.fillRect(lv.x, lv.y, lv.w, lv.h);
      ctx.strokeStyle = '#1a1a1a';
      ctx.lineWidth = 1;
      ctx.strokeRect(lv.x + 0.5, lv.y + 0.5, lv.w - 1, lv.h - 1);
      // Рычажок
      ctx.strokeStyle = lv.state === 1 ? '#fff5b8' : '#cccccc';
      ctx.lineWidth = 3;
      ctx.beginPath();
      const cx = lv.x + lv.w / 2;
      const cy = lv.y + lv.h / 2;
      if (lv.state === 1) {
        ctx.moveTo(cx, cy);
        ctx.lineTo(cx + 6, cy - 8);
      } else {
        ctx.moveTo(cx, cy);
        ctx.lineTo(cx - 6, cy - 8);
      }
      ctx.stroke();
    }
  },

  _renderSecretDoor(ctx) {
    const door = this.dungeon.secretDoor;
    if (!door) return;
    if (door.open && door.openProgress >= 1) return; // полностью открыта — не рисуем
    const openH = door.h * (1 - door.openProgress);
    const openW = door.w * (1 - door.openProgress);
    let dx = door.x, dy = door.y, dw = door.w, dh = door.h;
    // Решётка "поднимается" — уменьшаем по соответствующей оси
    if (door.w >= door.h) {
      dh = openH;
    } else {
      dw = openW;
    }
    // Корпус
    ctx.fillStyle = '#2a1a0a';
    ctx.fillRect(dx, dy, dw, dh);
    // Прутья
    ctx.strokeStyle = '#5a4a3a';
    ctx.lineWidth = 2;
    if (door.w >= door.h) {
      for (let i = 4; i < dw; i += 8) {
        ctx.beginPath();
        ctx.moveTo(dx + i, dy);
        ctx.lineTo(dx + i, dy + dh);
        ctx.stroke();
      }
    } else {
      for (let i = 4; i < dh; i += 8) {
        ctx.beginPath();
        ctx.moveTo(dx, dy + i);
        ctx.lineTo(dx + dw, dy + i);
        ctx.stroke();
      }
    }
  },

  /* ============================================================
     Миникарта полностью удалена.
     ============================================================ */

  /* ============================================================
     Шаг 13: ПОРТАЛ
     ============================================================ */

  /** Заспавнить портал в случайной не-стартовой комнате. */
  spawnPortal() {
    if (!this.dungeon) return;
    const rooms = this.dungeon.rooms.filter(r => !r.isStart && !r.isSecret && !r.isPuzzle);
    if (rooms.length === 0) return;
    // Выбираем комнату случайно
    const room = rooms[Math.floor(Math.random() * rooms.length)];
    const pt = this.randomPointInRoom(room, PORTAL_CONFIG.RADIUS);
    if (!pt) return;
    this.portal = {
      x: pt.x,
      y: pt.y,
      radius: PORTAL_CONFIG.RADIUS,
      visualRadius: PORTAL_CONFIG.VISUAL_RADIUS,
      pulse: 0,
      active: true,
    };
    // Визуальный эффект появления
    if (window.Particles) {
      Particles.ring(pt.x, pt.y, 60, 0.5, 'rgba(155, 89, 182, 0.9)', 4);
      Particles.burst(pt.x, pt.y, 12, {
        color: '#f1c40f', speedMin: 50, speedMax: 150,
        lifeMin: 0.5, lifeMax: 1.0, sizeMin: 3, sizeMax: 5,
      });
    }
  },

  /** Проверить, входит ли игрок в портал. */
  isPlayerInPortal(player) {
    if (!this.portal || !this.portal.active || !player) return false;
    const dx = player.x - this.portal.x;
    const dy = player.y - this.portal.y;
    return (dx * dx + dy * dy) <= this.portal.radius * this.portal.radius;
  },

  /** Отрисовать портал (вызывается из render). */
  renderPortal(ctx, cam, viewW, viewH) {
    if (!this.portal || !this.portal.active) return;
    const p = this.portal;
    if (p.x + 60 < cam.x || p.x - 60 > cam.x + viewW ||
        p.y + 60 < cam.y || p.y - 60 > cam.y + viewH) return;

    const t = this.time;
    const pulseScale = 1 + Math.sin(t * PORTAL_CONFIG.PULSE_SPEED) * 0.1;
    const r = p.visualRadius * pulseScale;

    // Внешнее свечение
    ctx.save();
    ctx.shadowColor = PORTAL_CONFIG.COLOR_OUTER;
    ctx.shadowBlur = 20;
    ctx.beginPath();
    ctx.arc(p.x, p.y, r, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(155, 89, 182, 0.3)';
    ctx.fill();
    ctx.shadowBlur = 0;

    // Вихрь (несколько вращающихся дуг)
    ctx.strokeStyle = PORTAL_CONFIG.COLOR_OUTER;
    ctx.lineWidth = 3;
    for (let i = 0; i < 4; i++) {
      const startAngle = t * 2 + (Math.PI / 2) * i;
      ctx.beginPath();
      ctx.arc(p.x, p.y, r * 0.7, startAngle, startAngle + Math.PI * 0.4);
      ctx.stroke();
    }

    // Внутренний золотой круг
    ctx.beginPath();
    ctx.arc(p.x, p.y, r * 0.4, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(241, 196, 15, 0.6)';
    ctx.fill();
    ctx.strokeStyle = PORTAL_CONFIG.COLOR_INNER;
    ctx.lineWidth = 2;
    ctx.stroke();

    // Символ портала
    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 16px ui-monospace, monospace';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('⟐', p.x, p.y);
    ctx.restore();
  },

  /* ============================================================
     Шаг 13: Обновление новых ловушек
     ============================================================ */

  _updateIceSpikeTrap(t, dt, player) {
    const c = BIOME_TRAP_CONFIG.ice_spike;
    t.timer += dt;
    if (t.phase === 'hidden') {
      if (t.timer >= c.HIDDEN_TIME) { t.phase = 'warning'; t.timer = 0; }
    } else if (t.phase === 'warning') {
      if (t.timer >= c.WARN_TIME) { t.phase = 'active'; t.timer = 0; t._struck = false; }
    } else if (t.phase === 'active') {
      if (player && !t._struck) {
        const dx = player.x - t.cx, dy = player.y - t.cy;
        if (Math.abs(dx) <= t.w / 2 + player.size / 2 &&
            Math.abs(dy) <= t.h / 2 + player.size / 2) {
          if (window.Player && Player.takeDamage) Player.takeDamage(player, t.damage, null);
          else player.hp -= t.damage;
          // Замедление
          player._iceSlow = t.slowPct;
          player._iceSlowTimer = t.slowDuration;
          t._struck = true;
          if (window.Particles) {
            Particles.burst(player.x, player.y, 5, {
              color: '#88ccff', speedMin: 60, speedMax: 140,
              lifeMin: 0.3, lifeMax: 0.5, sizeMin: 2, sizeMax: 3,
            });
          }
        }
      }
      if (t.timer >= c.ACTIVE_TIME) { t.phase = 'hidden'; t.timer = 0; t._struck = false; }
    }
  },

  _updateSlipperyFloor(t, dt, player) {
    if (!player) return;
    const dx = player.x - t.cx, dy = player.y - t.cy;
    if (Math.abs(dx) <= t.w / 2 + player.size / 2 &&
        Math.abs(dy) <= t.h / 2 + player.size / 2) {
      // Игрок на скользком полу: помечаем состояние скольжения
      if (!player._sliding) {
        player._sliding = true;
        player._slideTimer = t.slideDuration;
        // Направление скольжения — текущее направление движения
        const move = (window.Input && Input.getMove) ? Input.getMove() : { x: 0, y: 0 };
        player._slideDirX = move.x;
        player._slideDirY = move.y;
      }
    }
  },

  _updateFireGeyser(t, dt, player) {
    t.timer += dt;
    if (t.phase === 'idle') {
      if (t.timer >= t.cooldown - t.warnTime) { t.phase = 'warning'; t.timer = 0; }
    } else if (t.phase === 'warning') {
      if (t.timer >= t.warnTime) { t.phase = 'active'; t.timer = 0; t._struck = false; }
    } else if (t.phase === 'active') {
      if (player && !t._struck) {
        const dx = player.x - t.cx, dy = player.y - t.cy;
        if (dx * dx + dy * dy <= t.radius * t.radius) {
          if (window.Player && Player.takeDamage) Player.takeDamage(player, t.damage, null);
          else player.hp -= t.damage;
          t._struck = true;
          if (window.Particles) {
            Particles.burst(t.cx, t.cy, 8, {
              color: '#ff6600', speedMin: 80, speedMax: 200,
              lifeMin: 0.3, lifeMax: 0.6, sizeMin: 3, sizeMax: 5,
            });
          }
        }
      }
      if (t.timer >= t.activeTime) { t.phase = 'idle'; t.timer = 0; }
    }
  },

  _updateRockfall(t, dt, player) {
    t.timer += dt;
    if (t.phase === 'idle') {
      if (t.timer >= t.cooldown) {
        t.phase = 'warning'; t.timer = 0;
        // Целевая позиция — рядом с игроком (если есть)
        if (player) {
          t._targetX = player.x + Utils.rand(-30, 30);
          t._targetY = player.y + Utils.rand(-30, 30);
        } else {
          t._targetX = t.cx; t._targetY = t.cy;
        }
      }
    } else if (t.phase === 'warning') {
      if (t.timer >= t.warnTime) {
        t.phase = 'active'; t.timer = 0; t._struck = false;
        // Урон при приземлении
        if (player) {
          const dx = player.x - t._targetX, dy = player.y - t._targetY;
          if (dx * dx + dy * dy <= t.aoeRadius * t.aoeRadius) {
            if (window.Player && Player.takeDamage) Player.takeDamage(player, t.damage, null);
            else player.hp -= t.damage;
          }
        }
        if (window.Particles) {
          Particles.burst(t._targetX, t._targetY, 6, {
            color: '#8b6914', speedMin: 40, speedMax: 100,
            lifeMin: 0.2, lifeMax: 0.4, sizeMin: 3, sizeMax: 5,
          });
        }
      }
    } else if (t.phase === 'active') {
      if (t.timer >= 0.5) { t.phase = 'idle'; t.timer = 0; }
    }
  },

  _updatePoisonPlant(t, dt, player) {
    if (t.timer > 0) { t.timer -= dt; return; }
    if (!player) return;
    const dx = player.x - t.cx, dy = player.y - t.cy;
    const dist2 = dx * dx + dy * dy;
    if (dist2 <= t.triggerRadius * t.triggerRadius) {
      // Стреляем ядовитым снарядом
      t.timer = t.cooldown;
      if (window.Game && Game.projectiles) {
        const p = Game.projectiles.spawn();
        if (p) {
          const dist = Math.sqrt(dist2) || 1;
          p.kind = 'poison_plant_bolt';
          p.owner = 'enemy';
          p.x = t.cx; p.y = t.cy;
          p.vx = (dx / dist) * t.projSpeed;
          p.vy = (dy / dist) * t.projSpeed;
          p.life = 2.0;
          p.damage = t.projDamage;
          p.radius = 5;
          p.angle = Math.atan2(dy, dx);
          p.explodeRadius = 0;
          p.source = 'poison_plant';
          p.poisonDps = t.poisonDps;
          p.poisonDuration = t.poisonDuration;
        }
      }
    }
  },

  _updateRootGrab(t, dt, player) {
    if (!player) return;
    const dx = player.x - t.cx, dy = player.y - t.cy;
    if (Math.abs(dx) <= t.w / 2 + player.size / 2 &&
        Math.abs(dy) <= t.h / 2 + player.size / 2) {
      // Замедление + урон по времени
      player._rootSlow = t.slowPct;
      player._rootSlowTimer = 0.2; // обновляется каждый кадр пока внутри
      player.hp -= t.dps * dt;
    }
  },

  _updateMagicRune(t, dt, player) {
    if (t.timer > 0) { t.timer -= dt; return; }
    if (!player) return;
    const dx = player.x - t.cx, dy = player.y - t.cy;
    if (Math.abs(dx) <= t.w / 2 + player.size / 2 &&
        Math.abs(dy) <= t.h / 2 + player.size / 2) {
      // Мгновенный урон
      const tc = BIOME_TRAP_CONFIG.magic_rune;
      if (window.Player && Player.takeDamage) Player.takeDamage(player, t.damage, null);
      else player.hp -= t.damage;
      t.timer = t.cooldown;
      // Случайный эффект
      const effect = Math.floor(Math.random() * 3);
      if (effect === 0) {
        // Отбрасывание игрока удалено — свободное скольжение по стенам
      } else if (effect === 1) {
        // Замедление
        player._runeSlow = tc.SLOW_PCT;
        player._runeSlowTimer = tc.SLOW_DURATION;
      } else {
        // Молния — AoE урон
        player.hp -= tc.LIGHTNING_DAMAGE;
        if (window.Particles) {
          Particles.ring(t.cx, t.cy, tc.LIGHTNING_RADIUS, 0.3, 'rgba(100, 200, 255, 0.8)', 3);
        }
      }
      if (window.Particles) {
        Particles.burst(t.cx, t.cy, 6, {
          color: '#a259ff', speedMin: 60, speedMax: 140,
          lifeMin: 0.2, lifeMax: 0.4, sizeMin: 2, sizeMax: 4,
        });
      }
    }
  },

  _updatePortraitTrap(t, dt, player) {
    if (t.timer > 0) { t.timer -= dt; return; }
    if (!player) return;
    const dx = player.x - t.cx, dy = player.y - t.cy;
    const dist2 = dx * dx + dy * dy;
    if (dist2 <= t.triggerRadius * t.triggerRadius) {
      t.timer = t.cooldown;
      // Выстрел магической стрелой
      if (window.Game && Game.projectiles) {
        const p = Game.projectiles.spawn();
        if (p) {
          const dist = Math.sqrt(dist2) || 1;
          p.kind = 'portrait_bolt';
          p.owner = 'enemy';
          p.x = t.cx; p.y = t.cy;
          p.vx = (dx / dist) * t.projSpeed;
          p.vy = (dy / dist) * t.projSpeed;
          p.life = 2.0;
          p.damage = t.projDamage;
          p.radius = 5;
          p.angle = Math.atan2(dy, dx);
          p.explodeRadius = 0;
          p.source = 'portrait_trap';
        }
      }
    }
  },

  /* ============================================================
     Шаг 13: Рендер новых ловушек (вызывается из _renderTraps)
     ============================================================ */

  _renderBiomeTrap(ctx, tr) {
    const t = this.time;
    switch (tr.kind) {
      case 'ice_spike': {
        ctx.fillStyle = '#1a3a5a';
        ctx.fillRect(tr.x, tr.y, tr.w, tr.h);
        ctx.strokeStyle = '#0a2040';
        ctx.lineWidth = 1;
        ctx.strokeRect(tr.x + 0.5, tr.y + 0.5, tr.w - 1, tr.h - 1);
        if (tr.phase === 'warning') {
          const pulse = (Math.sin(t * 30) + 1) / 2;
          ctx.fillStyle = `rgba(100, 200, 255, ${0.4 + 0.4 * pulse})`;
          ctx.fillRect(tr.x + 4, tr.y + 4, tr.w - 8, tr.h - 8);
        } else if (tr.phase === 'active') {
          ctx.fillStyle = '#88ccff';
          for (let s = 0; s < 3; s++) {
            const sx = tr.x + 6 + s * (tr.w - 12) / 2;
            ctx.beginPath();
            ctx.moveTo(sx, tr.y + tr.h - 4);
            ctx.lineTo(sx + 7, tr.y + 4);
            ctx.lineTo(sx + 14, tr.y + tr.h - 4);
            ctx.closePath();
            ctx.fill();
          }
        }
        break;
      }
      case 'slippery_floor': {
        ctx.fillStyle = 'rgba(100, 180, 240, 0.2)';
        ctx.fillRect(tr.x, tr.y, tr.w, tr.h);
        ctx.strokeStyle = 'rgba(100, 180, 240, 0.4)';
        ctx.lineWidth = 1;
        ctx.strokeRect(tr.x, tr.y, tr.w, tr.h);
        // Мелкие линии скольжения
        ctx.strokeStyle = 'rgba(200, 230, 255, 0.3)';
        for (let i = 0; i < 4; i++) {
          const ly = tr.y + 10 + i * 14;
          ctx.beginPath();
          ctx.moveTo(tr.x + 5, ly);
          ctx.lineTo(tr.x + tr.w - 5, ly);
          ctx.stroke();
        }
        break;
      }
      case 'fire_geyser': {
        ctx.fillStyle = '#3a1a0a';
        ctx.beginPath();
        ctx.arc(tr.cx, tr.cy, tr.w / 2, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#1a0a0a';
        ctx.lineWidth = 1;
        ctx.stroke();
        if (tr.phase === 'warning') {
          const pulse = (Math.sin(t * 25) + 1) / 2;
          ctx.fillStyle = `rgba(255, 100, 30, ${0.3 + 0.4 * pulse})`;
          ctx.beginPath();
          ctx.arc(tr.cx, tr.cy, tr.w / 3, 0, Math.PI * 2);
          ctx.fill();
        } else if (tr.phase === 'active') {
          ctx.fillStyle = 'rgba(255, 140, 30, 0.8)';
          ctx.beginPath();
          ctx.arc(tr.cx, tr.cy, tr.radius * 0.6, 0, Math.PI * 2);
          ctx.fill();
          ctx.fillStyle = 'rgba(255, 220, 80, 0.6)';
          ctx.beginPath();
          ctx.arc(tr.cx, tr.cy, tr.radius * 0.3, 0, Math.PI * 2);
          ctx.fill();
        }
        break;
      }
      case 'rockfall': {
        if (tr.phase === 'warning') {
          // Тень предупреждения
          const pulse = (Math.sin(t * 20) + 1) / 2;
          ctx.fillStyle = `rgba(60, 40, 20, ${0.3 + 0.3 * pulse})`;
          ctx.beginPath();
          ctx.arc(tr._targetX, tr._targetY, tr.aoeRadius, 0, Math.PI * 2);
          ctx.fill();
        } else if (tr.phase === 'active') {
          ctx.fillStyle = '#6b4a2a';
          ctx.beginPath();
          ctx.arc(tr._targetX, tr._targetY, 12, 0, Math.PI * 2);
          ctx.fill();
          ctx.strokeStyle = '#3a2a1a';
          ctx.lineWidth = 2;
          ctx.stroke();
        }
        break;
      }
      case 'poison_plant': {
        ctx.fillStyle = '#2a6a2a';
        ctx.beginPath();
        ctx.arc(tr.cx, tr.cy, tr.w / 2, 0, Math.PI * 2);
        ctx.fill();
        // Лепестки
        ctx.fillStyle = '#4aaa4a';
        for (let i = 0; i < 5; i++) {
          const ang = (Math.PI * 2 / 5) * i + t * 0.5;
          const lx = tr.cx + Math.cos(ang) * (tr.w / 3);
          const ly = tr.cy + Math.sin(ang) * (tr.h / 3);
          ctx.beginPath();
          ctx.arc(lx, ly, 4, 0, Math.PI * 2);
          ctx.fill();
        }
        break;
      }
      case 'root_grab': {
        ctx.fillStyle = 'rgba(80, 60, 30, 0.3)';
        ctx.fillRect(tr.x, tr.y, tr.w, tr.h);
        // Корни
        ctx.strokeStyle = '#5a4020';
        ctx.lineWidth = 2;
        for (let i = 0; i < 5; i++) {
          const sx = tr.x + this.rng() * tr.w;
          const sy = tr.y + this.rng() * tr.h;
          ctx.beginPath();
          ctx.moveTo(sx, sy);
          ctx.quadraticCurveTo(sx + 10, sy + 5, sx + 15, sy - 3);
          ctx.stroke();
        }
        break;
      }
      case 'magic_rune': {
        const alpha = tr.timer > 0 ? 0.2 : (0.4 + Math.sin(t * 3) * 0.2);
        ctx.fillStyle = `rgba(162, 89, 255, ${alpha})`;
        ctx.beginPath();
        ctx.arc(tr.cx, tr.cy, tr.w / 2, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = `rgba(200, 130, 255, ${alpha + 0.2})`;
        ctx.lineWidth = 1.5;
        // Pentagram-like lines
        ctx.beginPath();
        for (let i = 0; i < 5; i++) {
          const ang = (Math.PI * 2 / 5) * i - Math.PI / 2;
          const px = tr.cx + Math.cos(ang) * (tr.w / 2 - 4);
          const py = tr.cy + Math.sin(ang) * (tr.h / 2 - 4);
          if (i === 0) ctx.moveTo(px, py);
          else ctx.lineTo(px, py);
        }
        ctx.closePath();
        ctx.stroke();
        break;
      }
      case 'portrait_trap': {
        ctx.fillStyle = '#4a3020';
        ctx.fillRect(tr.x, tr.y, tr.w, tr.h);
        ctx.strokeStyle = '#8a6a4a';
        ctx.lineWidth = 2;
        ctx.strokeRect(tr.x + 1, tr.y + 1, tr.w - 2, tr.h - 2);
        // Глаза
        ctx.fillStyle = tr.timer > 0 ? '#333' : '#ff3333';
        ctx.beginPath();
        ctx.arc(tr.cx - 4, tr.cy - 4, 2, 0, Math.PI * 2);
        ctx.arc(tr.cx + 4, tr.cy - 4, 2, 0, Math.PI * 2);
        ctx.fill();
        break;
      }
    }
  },
};

/* ============================================================
   Шаг 16: Campaign special objects — алтари, клетка, ключ, огненное сердце.
   ============================================================ */
GameMap.campaignObjects = [];

/** Разместить специальные объекты кампании на текущей карте. */
GameMap.placeCampaignObjects = function(mapCfg) {
  this.campaignObjects = [];
  if (!this.dungeon || !mapCfg) return;

  const rooms = this.dungeon.rooms.filter(r => !r.isStart && !r.isSecret);

  if (mapCfg.specialObjects.includes('altars')) {
    // Карта 1: 2 рунных алтаря в разных комнатах
    const altarRooms = rooms.slice(0, Math.min(2, rooms.length));
    for (let i = 0; i < 2 && i < altarRooms.length; i++) {
      const room = altarRooms[i];
      this.campaignObjects.push({
        type: 'altar',
        x: room.cx,
        y: room.cy,
        size: 28,
        activated: false,
        pulse: Math.random() * Math.PI * 2,
        levers: [
          { x: room.cx - 40, y: room.cy + 40, state: 0, correct: Math.random() < 0.5 ? 1 : 0 },
          { x: room.cx + 40, y: room.cy + 40, state: 0, correct: 0 },
        ],
        interactRadius: 36,
      });
      // Гарантируем разную комбинацию
      const alt = this.campaignObjects[this.campaignObjects.length - 1];
      if (alt.levers[0].correct === alt.levers[1].correct) {
        alt.levers[1].correct = alt.levers[0].correct === 0 ? 1 : 0;
      }
    }
  }

  if (mapCfg.specialObjects.includes('cage')) {
    // Карта 4: клетка с магом
    const cageRoom = rooms.length > 1 ? rooms[Math.floor(rooms.length / 2)] : rooms[0];
    if (cageRoom) {
      this.campaignObjects.push({
        type: 'cage',
        x: cageRoom.cx,
        y: cageRoom.cy,
        size: 36,
        opened: false,
        interactRadius: 40,
      });
    }
  }

  if (mapCfg.specialObjects.includes('key_enemy')) {
    // Хранитель ключа появляется через 2-3 минуты (обрабатывается в campaign update)
    this.campaignObjects.push({
      type: 'key_marker',
      spawned: false,
      spawnTime: 120 + Math.random() * 60, // 2-3 минуты
    });
  }
};

/** Обновить кампейн-объекты. */
GameMap.updateCampaignObjects = function(dt, player) {
  if (!player || !window.Campaign || !Campaign.active) return;

  for (const obj of this.campaignObjects) {
    if (obj.type === 'altar' && !obj.activated) {
      obj.pulse += dt * 3;
      // Проверка взаимодействия с рычагами алтаря
      for (const lev of obj.levers) {
        if (lev._cooldown > 0) { lev._cooldown -= dt; continue; }
        const dx = player.x - lev.x, dy = player.y - lev.y;
        if (dx * dx + dy * dy < 30 * 30) {
          // Авто-взаимодействие при приближении
          if (!lev._triggered) {
            lev._triggered = true;
            lev.state = lev.state === 0 ? 1 : 0;
            lev._cooldown = 1.5;
            if (window.Particles) {
              Particles.burst(lev.x, lev.y, 4, {
                color: '#ffd700', speedMin: 40, speedMax: 100,
                lifeMin: 0.2, lifeMax: 0.4, sizeMin: 2, sizeMax: 3,
              });
            }
          }
        } else {
          lev._triggered = false;
        }
      }
      // Проверяем, все ли рычаги в правильном положении
      const allCorrect = obj.levers.every(l => l.state === l.correct);
      if (allCorrect) {
        obj.activated = true;
        Campaign.onAltarActivated();
        if (window.Particles) {
          Particles.burst(obj.x, obj.y, 12, {
            color: '#9b59b6', speedMin: 60, speedMax: 180,
            lifeMin: 0.5, lifeMax: 1.0, sizeMin: 3, sizeMax: 6,
          });
          Particles.text(obj.x, obj.y - 30, 'ALTAR ACTIVATED!', 1.5, '#9b59b6', 14);
        }
      }
    }

    if (obj.type === 'cage' && !obj.opened) {
      // Проверка: подошёл с ключом?
      if (Campaign.hasKey) {
        const dx = player.x - obj.x, dy = player.y - obj.y;
        if (dx * dx + dy * dy < obj.interactRadius * obj.interactRadius) {
          obj.opened = true;
          Campaign.onCageOpened();
          if (window.Particles) {
            Particles.burst(obj.x, obj.y, 10, {
              color: '#2ecc71', speedMin: 60, speedMax: 150,
              lifeMin: 0.4, lifeMax: 0.8, sizeMin: 3, sizeMax: 5,
            });
          }
        }
      }
    }

    if (obj.type === 'key_marker' && !obj.spawned) {
      // Ключ появляется через определённое время (враг спавнится)
      obj.spawnTime -= dt;
      if (obj.spawnTime <= 0) {
        obj.spawned = true;
        // Спавним "элитного" врага с ключом
        if (window.Game && window.Enemies && Game.enemies) {
          const pt = this.randomEnemySpawnPoint(player, 300, 500);
          if (pt) {
            Enemies.spawnByType(Game.enemies, 'captain', pt.x, pt.y);
            // Помечаем последнего заспавненного как носителя ключа
            const items = Game.enemies.items;
            for (let i = items.length - 1; i >= 0; i--) {
              if (items[i].active && items[i].type === 'captain') {
                items[i]._hasKey = true;
                items[i]._keyIcon = true;
                break;
              }
            }
          }
          if (window.Particles && player) {
            Particles.text(player.x, player.y - 40, 'KEY GUARDIAN APPEARED!', 2.0, '#ffd700', 14);
          }
        }
      }
    }
  }

  // Проверка подбора огненного сердца и ключа (из Campaign.specialObjects)
  if (Campaign.specialObjects) {
    for (const obj of Campaign.specialObjects) {
      if (obj.type === 'fire_heart' && !obj.pickedUp) {
        obj.pulse += dt * 4;
        const dx = player.x - obj.x, dy = player.y - obj.y;
        if (dx * dx + dy * dy < 40 * 40) {
          obj.pickedUp = true;
          Campaign.onFireHeartPickedUp();
        }
      }
    }
  }
};

/** Рендер кампейн-объектов. ctx уже в мировых координатах. */
GameMap.renderCampaignObjects = function(ctx, cam, viewW, viewH) {
  const t = this.time;

  for (const obj of this.campaignObjects) {
    // Проверка видимости
    const sx = obj.x - cam.x, sy = obj.y - cam.y;
    if (obj.x && (sx < -80 || sx > viewW + 80 || sy < -80 || sy > viewH + 80)) continue;

    if (obj.type === 'altar') {
      // Рунный алтарь
      const pulse = 1 + Math.sin(obj.pulse) * 0.1;
      const s = obj.size * pulse;
      if (obj.activated) {
        ctx.fillStyle = '#9b59b6';
        ctx.shadowColor = '#9b59b6';
        ctx.shadowBlur = 15;
      } else {
        ctx.fillStyle = '#4a4a6a';
        ctx.shadowColor = '#6a4aaa';
        ctx.shadowBlur = 8;
      }
      // Алтарь — ромб
      ctx.beginPath();
      ctx.moveTo(obj.x, obj.y - s / 2);
      ctx.lineTo(obj.x + s / 2, obj.y);
      ctx.lineTo(obj.x, obj.y + s / 2);
      ctx.lineTo(obj.x - s / 2, obj.y);
      ctx.closePath();
      ctx.fill();
      ctx.shadowBlur = 0;
      // Буква
      ctx.fillStyle = obj.activated ? '#ffd700' : '#aaaacc';
      ctx.font = 'bold 14px ui-monospace, monospace';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(obj.activated ? '✓' : '⬡', obj.x, obj.y);

      // Рычаги
      for (const lev of obj.levers) {
        const lw = 16, lh = 16;
        ctx.fillStyle = lev.state === 1 ? '#2ecc71' : '#e74c3c';
        ctx.fillRect(lev.x - lw / 2, lev.y - lh / 2, lw, lh);
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 1;
        ctx.strokeRect(lev.x - lw / 2, lev.y - lh / 2, lw, lh);
        // Рукоять
        ctx.fillStyle = '#888';
        const handleY = lev.state === 1 ? lev.y - lh / 2 - 6 : lev.y + lh / 2;
        ctx.fillRect(lev.x - 2, handleY, 4, 6);
      }
    }

    if (obj.type === 'cage') {
      const s = obj.size;
      if (obj.opened) {
        // Открытая клетка
        ctx.strokeStyle = '#555';
        ctx.lineWidth = 2;
        ctx.strokeRect(obj.x - s / 2, obj.y - s / 2, s, s);
        // Маг вышел
        ctx.fillStyle = '#9b59b6';
        ctx.font = 'bold 18px ui-monospace, monospace';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('M', obj.x, obj.y);
      } else {
        // Закрытая клетка — решётка
        ctx.fillStyle = '#2a2a2a';
        ctx.fillRect(obj.x - s / 2, obj.y - s / 2, s, s);
        ctx.strokeStyle = '#888888';
        ctx.lineWidth = 2;
        ctx.strokeRect(obj.x - s / 2, obj.y - s / 2, s, s);
        // Решётки
        for (let i = 1; i < 4; i++) {
          const bx = obj.x - s / 2 + (s / 4) * i;
          ctx.beginPath();
          ctx.moveTo(bx, obj.y - s / 2);
          ctx.lineTo(bx, obj.y + s / 2);
          ctx.stroke();
        }
        // NPC внутри
        ctx.fillStyle = '#9b59b6';
        ctx.font = 'bold 16px ui-monospace, monospace';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('M', obj.x, obj.y);
        // Замок
        if (!Campaign.hasKey) {
          ctx.fillStyle = '#ffd700';
          ctx.font = '10px ui-monospace, monospace';
          ctx.fillText('🔒', obj.x, obj.y + s / 2 + 8);
        } else {
          ctx.fillStyle = '#2ecc71';
          ctx.font = '10px ui-monospace, monospace';
          ctx.fillText('🔑', obj.x, obj.y + s / 2 + 8);
        }
      }
    }
  }

  // Рендер огненного сердца и других campaign special objects
  if (window.Campaign && Campaign.specialObjects) {
    for (const obj of Campaign.specialObjects) {
      if (obj.type === 'fire_heart' && !obj.pickedUp) {
        const sx2 = obj.x - cam.x, sy2 = obj.y - cam.y;
        if (sx2 < -50 || sx2 > viewW + 50 || sy2 < -50 || sy2 > viewH + 50) continue;
        const pulse = 1 + Math.sin((obj.pulse || 0)) * 0.15;
        const s = obj.size * pulse;
        ctx.shadowColor = '#ff6600';
        ctx.shadowBlur = 12;
        ctx.fillStyle = '#ff8800';
        ctx.beginPath();
        ctx.moveTo(obj.x, obj.y - s);
        ctx.lineTo(obj.x + s * 0.7, obj.y);
        ctx.lineTo(obj.x, obj.y + s * 0.5);
        ctx.lineTo(obj.x - s * 0.7, obj.y);
        ctx.closePath();
        ctx.fill();
        ctx.shadowBlur = 0;
        ctx.fillStyle = '#ffd700';
        ctx.font = 'bold 12px ui-monospace, monospace';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('♦', obj.x, obj.y);
      }
    }
  }
};

// === js/map/traps.js ===
/* ============================================================
   GroundEffect — пул-объект для луж/следов (Шаг 4).
   ============================================================ */
function createGroundEffect() {
  return {
    active: false,
    kind: 'slime',
    x: 0, y: 0,
    radius: 22,
    life: 0, maxLife: 0,
    slow: 0,
    dps: 0,
    color: 'rgba(255,160,60,0.45)',
  };
}

const GROUND_DEFAULT_COLOR = {
  slime: 'rgba(255, 160, 60, 0.45)',
  rot:   'rgba(120, 200, 100, 0.45)',
  fire:  'rgba(255, 120, 30, 0.55)',
};
const GROUND_OUTLINE_COLOR = {
  slime: 'rgba(255, 200, 130, 0.7)',
  rot:   'rgba(180, 240, 160, 0.7)',
  fire:  'rgba(255, 220, 130, 0.9)',
};

window.createGroundEffect = createGroundEffect;

/* ============================================================
   ШАГ 17: Интеграция новых загадок и ловушек в генерацию и цикл.
   ============================================================ */

/**
 * Разместить новые загадки и ловушки (Шаг 17) после генерации подземелья.
 * Вызывается в конце generateDungeon().
 */
GameMap._placeStep17Objects = function(dungeon, mapNumber, isCampaign) {
  if (!window.STEP17_CONFIG) return;

  // Инициализируем массивы
  dungeon.runePuzzles = [];
  dungeon.floorPuzzles = [];
  dungeon.boulders = [];
  dungeon.vanishingPlatforms = [];
  dungeon.magicFloorRunes = [];

  const cfg = STEP17_CONFIG;
  let genCfg;

  if (isCampaign && cfg.GENERATION.CAMPAIGN[mapNumber]) {
    genCfg = cfg.GENERATION.CAMPAIGN[mapNumber];
    if (genCfg.puzzles) {
      for (const pType of genCfg.puzzles) {
        if (pType === 'rune_puzzle') GameMap._placeRunePuzzle(dungeon, mapNumber);
        else if (pType === 'floor_puzzle') GameMap._placeFloorPuzzle(dungeon, mapNumber);
      }
    }
    GameMap._placeBoulders(dungeon, genCfg.boulders || 0);
    GameMap._placeVanishingPlatforms(dungeon, genCfg.platforms || 0);
    GameMap._placeMagicFloorRunes(dungeon, genCfg.magicRunes || 0);
  } else {
    genCfg = cfg.GENERATION.INFINITE;
    const puzzleCount = Utils.randInt(genCfg.PUZZLES_MIN, genCfg.PUZZLES_MAX);
    for (let i = 0; i < puzzleCount; i++) {
      const roll = Math.random();
      if (roll < 0.4) GameMap._placeRunePuzzle(dungeon, mapNumber);
      else if (roll < 0.8) GameMap._placeFloorPuzzle(dungeon, mapNumber);
    }
    GameMap._placeBoulders(dungeon, Utils.randInt(genCfg.BOULDERS_MIN, genCfg.BOULDERS_MAX));
    GameMap._placeVanishingPlatforms(dungeon, Utils.randInt(genCfg.PLATFORMS_MIN, genCfg.PLATFORMS_MAX));
    GameMap._placeMagicFloorRunes(dungeon, Utils.randInt(genCfg.MAGIC_RUNES_MIN, genCfg.MAGIC_RUNES_MAX));
  }
};

GameMap._placeRunePuzzle = function(dungeon, mapNumber) {
  if (!window.RunePuzzle) return;
  const candidates = dungeon.rooms.filter(r => !r.isStart && !r.isSecret && !r.isPuzzle && r.w >= 200 && r.h >= 150);
  if (candidates.length === 0) return;
  const room = candidates[Math.floor(Math.random() * candidates.length)];
  room.isPuzzle = true;
  const runeCount = (STEP17_CONFIG.RUNE_PUZZLE.RUNES_BY_MAP[mapNumber]) || 4;
  const puzzle = RunePuzzle.create(room, runeCount);
  dungeon.runePuzzles.push(puzzle);
};

GameMap._placeFloorPuzzle = function(dungeon, mapNumber) {
  if (!window.FloorPuzzle) return;
  const candidates = dungeon.rooms.filter(r => !r.isStart && !r.isSecret && !r.isPuzzle && r.w >= 200 && r.h >= 150);
  if (candidates.length === 0) return;
  const room = candidates[Math.floor(Math.random() * candidates.length)];
  room.isPuzzle = true;
  const plateCfg = (STEP17_CONFIG.FLOOR_PUZZLE.PLATES_BY_MAP[mapNumber]) || { plates: 5, seq: 3 };
  const puzzle = FloorPuzzle.create(room, plateCfg.plates, plateCfg.seq);
  dungeon.floorPuzzles.push(puzzle);
};

GameMap._placeBoulders = function(dungeon, count) {
  if (!window.Boulder || count <= 0) return;
  const cfg = STEP17_CONFIG.BOULDER;
  const suitableCorridors = dungeon.corridors.filter(c => Math.max(c.w, c.h) >= cfg.MIN_CORRIDOR_LEN);
  if (suitableCorridors.length === 0) return;
  const maxBoulders = Math.min(count, cfg.MAX_PER_MAP, suitableCorridors.length);
  const shuffled = suitableCorridors.slice();
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  for (let i = 0; i < maxBoulders; i++) {
    dungeon.boulders.push(Boulder.create(shuffled[i]));
  }
};

GameMap._placeVanishingPlatforms = function(dungeon, count) {
  if (!window.VanishingPlatform || count <= 0) return;
  const cfg = STEP17_CONFIG.VANISHING_PLATFORM;
  const maxPlat = Math.min(count, cfg.MAX_PER_MAP);
  const candidates = dungeon.rooms.filter(r => !r.isStart && !r.isSecret && r.w >= 200 && r.h >= 150);
  if (candidates.length === 0) return;
  let placed = 0;
  for (let attempt = 0; attempt < 50 && placed < maxPlat; attempt++) {
    const room = candidates[Math.floor(Math.random() * candidates.length)];
    const x = room.x + 60 + Math.random() * (room.w - 120 - cfg.SIZE);
    const y = room.y + 60 + Math.random() * (room.h - 120 - cfg.SIZE);
    let ok = true;
    for (const p of dungeon.pillars) {
      if (GameMap._rectsOverlap(x, y, cfg.SIZE, cfg.SIZE, p.x - 10, p.y - 10, p.w + 20, p.h + 20)) {
        ok = false; break;
      }
    }
    if (!ok) continue;
    dungeon.vanishingPlatforms.push(VanishingPlatform.create(x, y));
    placed++;
  }
};

GameMap._placeMagicFloorRunes = function(dungeon, count) {
  if (!window.MagicFloorRune || count <= 0) return;
  const candidates = dungeon.rooms.filter(r => !r.isStart && !r.isSecret);
  if (candidates.length === 0) return;
  let placed = 0;
  for (let attempt = 0; attempt < 100 && placed < count; attempt++) {
    const room = candidates[Math.floor(Math.random() * candidates.length)];
    const x = room.x + 40 + Math.random() * (room.w - 80);
    const y = room.y + 40 + Math.random() * (room.h - 80);
    let ok = true;
    for (const rune of dungeon.magicFloorRunes) {
      const dx = x - rune.x, dy = y - rune.y;
      if (dx * dx + dy * dy < 60 * 60) { ok = false; break; }
    }
    if (!ok) continue;
    dungeon.magicFloorRunes.push(MagicFloorRune.create(x, y));
    placed++;
  }
};

/** Обновить объекты Шага 17 (вызывается из GameMap.update). */
GameMap.updateStep17 = function(dt, player) {
  if (!this.dungeon || !player) return;

  if (this.dungeon.runePuzzles) {
    for (const puzzle of this.dungeon.runePuzzles) {
      const ev = RunePuzzle.update(puzzle, player, dt);
      if (ev) GameMap._handlePuzzleEvent(ev, player);
    }
  }
  if (this.dungeon.floorPuzzles) {
    for (const puzzle of this.dungeon.floorPuzzles) {
      const ev = FloorPuzzle.update(puzzle, player, dt);
      if (ev) GameMap._handlePuzzleEvent(ev, player);
    }
  }
  if (this.dungeon.boulders) {
    const enemies = (window.Game && Game.enemies) ? Game.enemies : null;
    for (const boulder of this.dungeon.boulders) {
      const ev = Boulder.update(boulder, player, enemies, dt);
      if (ev && ev.type === 'hit_player') {
        player.hp -= ev.damage;
        // Отбрасывание игрока удалено — свободное скольжение по стенам
        player.x = Utils.clamp(player.x, 20, GameMap.mapW - 20);
        player.y = Utils.clamp(player.y, 20, GameMap.mapH - 20);
        if (window.Particles) {
          Particles.burst(player.x, player.y, 6, {
            color: '#aaaaaa', speedMin: 60, speedMax: 140,
            lifeMin: 0.2, lifeMax: 0.4, sizeMin: 3, sizeMax: 5,
          });
        }
      }
    }
  }
  if (this.dungeon.vanishingPlatforms) {
    const enemies = (window.Game && Game.enemies) ? Game.enemies : null;
    for (const plat of this.dungeon.vanishingPlatforms) {
      const ev = VanishingPlatform.update(plat, player, enemies, dt);
      if (ev && ev.type === 'player_fell') {
        player.hp -= ev.damage;
        const safePos = GameMap._findSafePosition(player.x, player.y, plat);
        if (safePos) { player.x = safePos.x; player.y = safePos.y; }
        player._stunTimer = ev.stunDuration;
        if (window.Particles) {
          Particles.burst(player.x, player.y, 4, {
            color: '#333333', speedMin: 40, speedMax: 100,
            lifeMin: 0.3, lifeMax: 0.5, sizeMin: 2, sizeMax: 4,
          });
        }
      }
    }
  }
  if (this.dungeon.magicFloorRunes) {
    for (const rune of this.dungeon.magicFloorRunes) {
      const ev = MagicFloorRune.update(rune, player, dt);
      if (ev) GameMap._handleMagicRuneEvent(ev, player);
    }
  }
};

GameMap._handlePuzzleEvent = function(event, player) {
  if (event.type === 'solved') {
    if (window.Game && !event.puzzle.rewardSpawned) {
      event.puzzle.rewardSpawned = true;
      const room = event.puzzle.room;
      const c = Chest.create();
      c.x = room.cx; c.y = room.cy + 30;
      c.guaranteedRare = true;
      if (window.Particles) Particles.chestGlow(c.x, c.y);
      Game.secretChest = c;
      if (window.Particles) {
        Particles.burst(c.x, c.y, 10, { color: '#ffd700', speedMin: 60, speedMax: 160, lifeMin: 0.4, lifeMax: 0.8, sizeMin: 3, sizeMax: 6 });
        Particles.text(player.x, player.y - 40, 'PUZZLE SOLVED!', 1.5, '#ffd700', 14);
      }
    }
  } else if (event.type === 'error') {
    player.hp -= event.damage || 5;
    if (window.Particles) {
      Particles.burst(player.x, player.y, 4, { color: '#ff3333', speedMin: 40, speedMax: 100, lifeMin: 0.2, lifeMax: 0.4, sizeMin: 2, sizeMax: 4 });
      Particles.text(player.x, player.y - 30, 'ERROR!', 1.0, '#ff3333', 12);
    }
    if (window.Enemies && window.Game && Game.enemies) {
      const count = event.damage >= 10 ? 2 : 1;
      for (let i = 0; i < count; i++) {
        const ang = Math.random() * Math.PI * 2;
        const dist = 80 + Math.random() * 40;
        Enemies.spawnByType(Game.enemies, 'skeleton', player.x + Math.cos(ang) * dist, player.y + Math.sin(ang) * dist);
      }
    }
  }
};

GameMap._handleMagicRuneEvent = function(event, player) {
  switch (event.type) {
    case 'fire': {
      const dx = player.x - event.x, dy = player.y - event.y;
      if (dx * dx + dy * dy <= event.radius * event.radius) player.hp -= event.damage;
      if (window.Game && Game.enemies) {
        const items = Game.enemies.items;
        for (let i = 0; i < items.length; i++) {
          const e = items[i];
          if (!e.active) continue;
          const edx = e.x - event.x, edy = e.y - event.y;
          if (edx * edx + edy * edy <= event.radius * event.radius) {
            e.hp -= event.damage;
            if (e.hp <= 0) Game.killEnemy(e);
          }
        }
      }
      if (window.Particles) Particles.burst(event.x, event.y, 12, { color: '#ff4400', speedMin: 80, speedMax: 200, lifeMin: 0.3, lifeMax: 0.6, sizeMin: 3, sizeMax: 6 });
      break;
    }
    case 'ice': {
      const dx = player.x - event.x, dy = player.y - event.y;
      if (dx * dx + dy * dy <= 60 * 60) {
        player.hp -= event.damage;
        player._iceSlow = event.slowPct;
        player._iceSlowTimer = event.slowDuration;
      }
      if (window.Particles) Particles.burst(event.x, event.y, 8, { color: '#44aaff', speedMin: 60, speedMax: 140, lifeMin: 0.3, lifeMax: 0.5, sizeMin: 2, sizeMax: 5 });
      break;
    }
    case 'dark': {
      if (window.Enemies && window.Game && Game.enemies) {
        const biome = GameMap.currentBiome;
        const pool = biome && biome.enemyTypes ? biome.enemyTypes : ['skeleton'];
        for (let i = 0; i < event.spawnCount; i++) {
          const ang = Math.random() * Math.PI * 2;
          const dist = 40 + Math.random() * 30;
          const typeId = pool[Math.floor(Math.random() * Math.min(5, pool.length))];
          Enemies.spawnByType(Game.enemies, typeId, event.x + Math.cos(ang) * dist, event.y + Math.sin(ang) * dist);
        }
      }
      if (window.Particles) Particles.burst(event.x, event.y, 8, { color: '#9933ff', speedMin: 50, speedMax: 120, lifeMin: 0.3, lifeMax: 0.6, sizeMin: 3, sizeMax: 5 });
      break;
    }
    case 'teleport': {
      const safePos = GameMap._findRandomSafePosition();
      if (safePos) { player.x = safePos.x; player.y = safePos.y; }
      if (window.Particles) {
        Particles.burst(event.x, event.y, 10, { color: '#ffdd00', speedMin: 80, speedMax: 200, lifeMin: 0.3, lifeMax: 0.6, sizeMin: 2, sizeMax: 5 });
        Particles.burst(player.x, player.y, 10, { color: '#ffdd00', speedMin: 80, speedMax: 200, lifeMin: 0.3, lifeMax: 0.6, sizeMin: 2, sizeMax: 5 });
      }
      break;
    }
    case 'heal': {
      player.hp = Math.min(player.maxHp, player.hp + event.amount);
      if (window.Particles) {
        Particles.burst(event.x, event.y, 8, { color: '#33ff66', speedMin: 40, speedMax: 100, lifeMin: 0.4, lifeMax: 0.7, sizeMin: 2, sizeMax: 4 });
        Particles.text(player.x, player.y - 30, '+' + event.amount + ' HP', 1.0, '#33ff66', 12);
      }
      break;
    }
  }
};

GameMap._findSafePosition = function(x, y, platform) {
  const offsets = [
    { x: -platform.w - 20, y: 0 }, { x: platform.w + 20, y: 0 },
    { x: 0, y: -platform.h - 20 }, { x: 0, y: platform.h + 20 },
  ];
  for (const off of offsets) {
    const nx = x + off.x, ny = y + off.y;
    if (nx > 20 && nx < GameMap.mapW - 20 && ny > 20 && ny < GameMap.mapH - 20) {
      if (GameMap.dungeon && GameMap.dungeon.grid) {
        const cs = GameMap.dungeon.cellSize;
        const gx = Math.floor(nx / cs), gy = Math.floor(ny / cs);
        if (gx >= 0 && gx < GameMap.dungeon.gridW && gy >= 0 && gy < GameMap.dungeon.gridH) {
          if (GameMap.dungeon.grid[gy * GameMap.dungeon.gridW + gx] === 1) return { x: nx, y: ny };
        }
      } else return { x: nx, y: ny };
    }
  }
  return { x, y: y - 40 };
};

GameMap._findRandomSafePosition = function() {
  if (!GameMap.dungeon || !GameMap.dungeon.rooms) return null;
  const rooms = GameMap.dungeon.rooms.filter(r => !r.isSecret);
  if (rooms.length === 0) return null;
  // Bug fix #6.1: Проверяем проходимость точки телепортации (до 10 попыток)
  for (let attempt = 0; attempt < 10; attempt++) {
    const room = rooms[Math.floor(Math.random() * rooms.length)];
    const x = room.x + 40 + Math.random() * (room.w - 80);
    const y = room.y + 40 + Math.random() * (room.h - 80);
    // Проверяем, что точка проходима
    if (GameMap.dungeon.grid) {
      const cell = GameMap.dungeon.cellSize;
      const gx = Math.floor(x / cell);
      const gy = Math.floor(y / cell);
      if (gx >= 0 && gx < GameMap.dungeon.gridW && gy >= 0 && gy < GameMap.dungeon.gridH) {
        if (GameMap.dungeon.grid[gy * GameMap.dungeon.gridW + gx] === 1) {
          // Дополнительно проверяем что нет колонн/объектов рядом
          if (!GameMap.rectIsWalkable || GameMap.rectIsWalkable(x, y, 12)) {
            return { x, y };
          }
        }
      }
    } else {
      return { x, y };
    }
  }
  // Фоллбэк: центр случайной комнаты (гарантированно свободен)
  const fallbackRoom = rooms[Math.floor(Math.random() * rooms.length)];
  return { x: fallbackRoom.cx || fallbackRoom.x + fallbackRoom.w / 2, y: fallbackRoom.cy || fallbackRoom.y + fallbackRoom.h / 2 };
};

/** Отрисовать объекты Шага 17 (вызывается из GameMap.render). */
GameMap.renderStep17 = function(ctx, cam, viewW, viewH) {
  if (!this.dungeon) return;
  if (this.dungeon.magicFloorRunes) {
    for (const rune of this.dungeon.magicFloorRunes) MagicFloorRune.render(ctx, rune, cam, viewW, viewH);
  }
  if (this.dungeon.vanishingPlatforms) {
    for (const plat of this.dungeon.vanishingPlatforms) VanishingPlatform.render(ctx, plat, cam, viewW, viewH);
  }
  if (this.dungeon.runePuzzles) {
    for (const puzzle of this.dungeon.runePuzzles) RunePuzzle.render(ctx, puzzle, cam, viewW, viewH);
  }
  if (this.dungeon.floorPuzzles) {
    for (const puzzle of this.dungeon.floorPuzzles) FloorPuzzle.render(ctx, puzzle, cam, viewW, viewH);
  }
  if (this.dungeon.boulders) {
    for (const boulder of this.dungeon.boulders) Boulder.render(ctx, boulder, cam, viewW, viewH);
  }
};

/* ============================================================
   traps_extended.js — Шаг 17: Катящиеся валуны (Boulder),
   Исчезающие платформы (VanishingPlatform),
   Магические руны на полу (MagicFloorRune).
   ============================================================ */

/* ============================================================
   BOULDER — Катящийся валун
   В длинных коридорах периодически проезжает валун,
   наносящий урон и отбрасывающий всё на пути.
   ============================================================ */
const Boulder = {
  /**
   * Создать валун в коридоре.
   * @param {object} corridor — { x, y, w, h }
   * @returns {object} boulderState
   */
  create(corridor) {
    // Определяем направление: горизонтальное или вертикальное
    const isHorizontal = corridor.w > corridor.h;
    const cfg = STEP17_CONFIG.BOULDER;

    let startX, startY, endX, endY;
    if (isHorizontal) {
      startX = corridor.x + cfg.RADIUS;
      startY = corridor.y + corridor.h / 2;
      endX = corridor.x + corridor.w - cfg.RADIUS;
      endY = startY;
    } else {
      startX = corridor.x + corridor.w / 2;
      startY = corridor.y + cfg.RADIUS;
      endX = startX;
      endY = corridor.y + corridor.h - cfg.RADIUS;
    }

    return {
      type: 'boulder',
      x: startX,
      y: startY,
      startX, startY,
      endX, endY,
      radius: cfg.RADIUS,
      isHorizontal,
      // Фазы: 'idle' → 'warning' → 'rolling' → 'idle'
      phase: 'idle',
      timer: cfg.IDLE_TIME * Math.random(), // рандомный старт
      direction: 1, // 1 = вперёд, -1 = назад
      progress: 0,  // 0..1 — текущая позиция на пути
      // Параметры
      damage: cfg.DAMAGE,
      knockback: cfg.KNOCKBACK,
      idleTime: cfg.IDLE_TIME,
      warnTime: cfg.WARN_TIME,
      rollSpeed: cfg.ROLL_SPEED,
      // Визуал
      rotation: 0,
      dustTimer: 0,
      _hitCooldown: 0, // предотвращение двойного удара
    };
  },

  /**
   * Обновить валун.
   * @returns {object|null} — событие { type: 'hit_player', damage, knockX, knockY }
   */
  update(boulder, player, enemies, dt) {
    if (boulder._hitCooldown > 0) boulder._hitCooldown -= dt;
    let event = null;

    switch (boulder.phase) {
      case 'idle':
        boulder.timer -= dt;
        if (boulder.timer <= 0) {
          boulder.phase = 'warning';
          boulder.timer = boulder.warnTime;
        }
        break;

      case 'warning':
        boulder.timer -= dt;
        if (boulder.timer <= 0) {
          boulder.phase = 'rolling';
          boulder.progress = 0;
        }
        break;

      case 'rolling': {
        // Вычисляем расстояние пути
        const dx = boulder.endX - boulder.startX;
        const dy = boulder.endY - boulder.startY;
        const totalDist = Math.sqrt(dx * dx + dy * dy);
        if (totalDist < 1) {
          boulder.phase = 'idle';
          boulder.timer = boulder.idleTime;
          break;
        }

        // Двигаемся
        const step = (boulder.rollSpeed * dt) / totalDist;
        boulder.progress += step * boulder.direction;

        // Обновляем позицию
        if (boulder.direction > 0) {
          boulder.x = boulder.startX + dx * boulder.progress;
          boulder.y = boulder.startY + dy * boulder.progress;
        } else {
          boulder.x = boulder.endX - dx * (1 - boulder.progress);
          boulder.y = boulder.endY - dy * (1 - boulder.progress);
        }

        // Вращение
        boulder.rotation += dt * 8 * boulder.direction;

        // Проверяем конец пути
        if (boulder.progress >= 1 || boulder.progress <= 0) {
          boulder.phase = 'idle';
          boulder.timer = boulder.idleTime;
          boulder.direction *= -1; // следующий раз — обратно
          // Зажимаем progress
          boulder.progress = Utils.clamp(boulder.progress, 0, 1);
          // Обновляем позицию к конечной точке
          if (boulder.direction < 0) {
            boulder.x = boulder.endX;
            boulder.y = boulder.endY;
          } else {
            boulder.x = boulder.startX;
            boulder.y = boulder.startY;
          }
        }

        // Проверяем столкновение с игроком
        if (boulder._hitCooldown <= 0) {
          const pdx = player.x - boulder.x;
          const pdy = player.y - boulder.y;
          const hitR = boulder.radius + player.size * 0.4;
          if (pdx * pdx + pdy * pdy <= hitR * hitR) {
            // Направление отбрасывания — по движению валуна
            const moveAngle = Math.atan2(
              boulder.direction > 0 ? dy : -dy,
              boulder.direction > 0 ? dx : -dx
            );
            event = {
              type: 'hit_player',
              damage: boulder.damage,
              knockX: Math.cos(moveAngle) * boulder.knockback,
              knockY: Math.sin(moveAngle) * boulder.knockback,
            };
            boulder._hitCooldown = 1.0;
          }
        }

        // Урон врагам
        if (enemies) {
          const items = enemies.items;
          for (let i = 0; i < items.length; i++) {
            const e = items[i];
            if (!e.active) continue;
            const edx = e.x - boulder.x;
            const edy = e.y - boulder.y;
            const eR = boulder.radius + (e.cfg ? Math.max(e.cfg.w, e.cfg.h) * 0.4 : 14);
            if (edx * edx + edy * edy <= eR * eR) {
              if (!e._boulderHitCD || e._boulderHitCD <= 0) {
                e.hp -= boulder.damage;
                e._boulderHitCD = 1.0;
                if (e.hp <= 0 && window.Game) Game.killEnemy(e);
              }
            }
            if (e._boulderHitCD > 0) e._boulderHitCD -= dt;
          }
        }
        break;
      }
    }
    return event;
  },

  /** Отрисовка валуна. */
  render(ctx, boulder, cam, viewW, viewH) {
    if (boulder.x - boulder.radius > cam.x + viewW + 20 ||
        boulder.x + boulder.radius < cam.x - 20 ||
        boulder.y - boulder.radius > cam.y + viewH + 20 ||
        boulder.y + boulder.radius < cam.y - 20) return;

    const r = boulder.radius;

    // Предупреждение (тень и стрелка)
    if (boulder.phase === 'warning') {
      const alpha = 0.3 + Math.sin(boulder.timer * 12) * 0.3;
      // Тень на пути
      ctx.fillStyle = `rgba(255, 50, 50, ${alpha})`;
      if (boulder.isHorizontal) {
        const x1 = boulder.direction > 0 ? boulder.startX : boulder.endX;
        const x2 = boulder.direction > 0 ? boulder.endX : boulder.startX;
        ctx.fillRect(Math.min(x1, x2), boulder.startY - 12, Math.abs(x2 - x1), 24);
      } else {
        const y1 = boulder.direction > 0 ? boulder.startY : boulder.endY;
        const y2 = boulder.direction > 0 ? boulder.endY : boulder.startY;
        ctx.fillRect(boulder.startX - 12, Math.min(y1, y2), 24, Math.abs(y2 - y1));
      }
      // Стрелка направления
      ctx.fillStyle = `rgba(255, 100, 100, ${alpha + 0.2})`;
      ctx.font = 'bold 18px ui-monospace, monospace';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      const arrow = boulder.isHorizontal
        ? (boulder.direction > 0 ? '\u2192' : '\u2190')
        : (boulder.direction > 0 ? '\u2193' : '\u2191');
      ctx.fillText(arrow, boulder.x, boulder.y);
    }

    // Валун (всегда рисуется в текущей позиции)
    if (boulder.phase === 'rolling' || boulder.phase === 'warning') {
      ctx.save();
      ctx.translate(boulder.x, boulder.y);
      ctx.rotate(boulder.rotation);

      // Тень
      ctx.fillStyle = 'rgba(0, 0, 0, 0.3)';
      ctx.beginPath();
      ctx.ellipse(2, 4, r * 0.9, r * 0.5, 0, 0, Math.PI * 2);
      ctx.fill();

      // Камень
      ctx.fillStyle = '#6b6b6b';
      ctx.beginPath();
      ctx.arc(0, 0, r, 0, Math.PI * 2);
      ctx.fill();

      // Текстура камня
      ctx.strokeStyle = '#4a4a4a';
      ctx.lineWidth = 2;
      ctx.stroke();

      // Трещины
      ctx.strokeStyle = '#3a3a3a';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(-r * 0.3, -r * 0.4);
      ctx.lineTo(r * 0.2, r * 0.1);
      ctx.moveTo(r * 0.1, -r * 0.3);
      ctx.lineTo(-r * 0.1, r * 0.4);
      ctx.stroke();

      // Блик
      ctx.fillStyle = 'rgba(200, 200, 200, 0.3)';
      ctx.beginPath();
      ctx.arc(-r * 0.3, -r * 0.3, r * 0.25, 0, Math.PI * 2);
      ctx.fill();

      ctx.restore();
    } else {
      // В покое — рисуем неподвижно в стартовой/конечной позиции
      const drawX = boulder.direction > 0 ? boulder.startX : boulder.endX;
      const drawY = boulder.direction > 0 ? boulder.startY : boulder.endY;

      ctx.fillStyle = '#5a5a5a';
      ctx.beginPath();
      ctx.arc(drawX, drawY, r, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#4a4a4a';
      ctx.lineWidth = 2;
      ctx.stroke();
    }
  },
};

/* ============================================================
   VANISHING PLATFORM — Исчезающая платформа
   Зоны пола, которые периодически исчезают.
   ============================================================ */
const VanishingPlatform = {
  /**
   * Создать исчезающую платформу.
   * @param {number} x, y — позиция
   * @returns {object} platformState
   */
  create(x, y) {
    const cfg = STEP17_CONFIG.VANISHING_PLATFORM;
    return {
      type: 'vanishing_platform',
      x, y,
      w: cfg.SIZE,
      h: cfg.SIZE,
      // Фазы: 'solid' → 'flickering' → 'gone' → 'solid'
      phase: 'solid',
      timer: cfg.SOLID_TIME + Math.random() * 2, // рандомный старт
      solidTime: cfg.SOLID_TIME,
      flickerTime: cfg.FLICKER_TIME,
      goneTime: cfg.GONE_TIME,
      damage: cfg.DAMAGE,
      enemyDamage: cfg.ENEMY_DAMAGE,
      stunDuration: cfg.STUN_DURATION,
      // Визуал
      alpha: 1.0,
      crackPhase: Math.random() * Math.PI * 2,
      _playerWasOn: false,
    };
  },

  /**
   * Обновить платформу.
   * @returns {object|null} — событие { type: 'player_fell', damage, stunDuration }
   */
  update(platform, player, enemies, dt) {
    platform.crackPhase += dt * 2;
    let event = null;

    // Проверяем, стоит ли игрок на платформе
    const playerOn = Boulder._entityOnPlatform(player, platform);

    switch (platform.phase) {
      case 'solid':
        platform.alpha = 1.0;
        platform.timer -= dt;
        if (platform.timer <= 0) {
          platform.phase = 'flickering';
          platform.timer = platform.flickerTime;
        }
        platform._playerWasOn = playerOn;
        break;

      case 'flickering':
        // Мерцание — пульсация прозрачности
        platform.alpha = 0.4 + Math.sin(platform.timer * 15) * 0.4;
        platform.timer -= dt;
        if (platform.timer <= 0) {
          platform.phase = 'gone';
          platform.timer = platform.goneTime;
          platform.alpha = 0;

          // Если игрок стоит на платформе — урон + телепорт
          if (playerOn) {
            event = {
              type: 'player_fell',
              damage: platform.damage,
              stunDuration: platform.stunDuration,
            };
          }

          // Враги на платформе получают урон
          if (enemies) {
            const items = enemies.items;
            for (let i = 0; i < items.length; i++) {
              const e = items[i];
              if (!e.active) continue;
              if (Boulder._entityOnPlatform(e, platform)) {
                e.hp -= platform.enemyDamage;
                if (e.hp <= 0 && window.Game) Game.killEnemy(e);
              }
            }
          }
        }
        platform._playerWasOn = playerOn;
        break;

      case 'gone':
        platform.alpha = 0;
        platform.timer -= dt;
        if (platform.timer <= 0) {
          platform.phase = 'solid';
          platform.timer = platform.solidTime;
          platform.alpha = 1.0;
        }
        break;
    }
    return event;
  },

  /** Отрисовка платформы. */
  render(ctx, platform, cam, viewW, viewH) {
    if (platform.x + platform.w < cam.x || platform.x > cam.x + viewW ||
        platform.y + platform.h < cam.y || platform.y > cam.y + viewH) return;

    if (platform.phase === 'gone') {
      // Чёрный провал
      ctx.fillStyle = 'rgba(0, 0, 0, 0.8)';
      ctx.fillRect(platform.x, platform.y, platform.w, platform.h);
      // Мерцающие края
      ctx.strokeStyle = 'rgba(80, 40, 0, 0.6)';
      ctx.lineWidth = 2;
      ctx.strokeRect(platform.x + 2, platform.y + 2, platform.w - 4, platform.h - 4);
      return;
    }

    ctx.globalAlpha = platform.alpha;

    // Основная плитка (светлее обычного пола)
    ctx.fillStyle = 'rgba(100, 90, 70, 0.8)';
    ctx.fillRect(platform.x, platform.y, platform.w, platform.h);

    // Трещины
    ctx.strokeStyle = 'rgba(50, 40, 30, 0.6)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    const cx = platform.x + platform.w / 2;
    const cy = platform.y + platform.h / 2;
    // Рисуем несколько трещин
    ctx.moveTo(cx - 20, cy - 15);
    ctx.lineTo(cx + 10, cy + 5);
    ctx.lineTo(cx + 25, cy + 20);
    ctx.moveTo(cx + 15, cy - 20);
    ctx.lineTo(cx - 5, cy + 10);
    ctx.moveTo(cx - 25, cy + 5);
    ctx.lineTo(cx - 10, cy + 25);
    ctx.stroke();

    // Обводка
    ctx.strokeStyle = platform.phase === 'flickering'
      ? `rgba(255, 100, 50, ${platform.alpha})`
      : 'rgba(120, 100, 80, 0.5)';
    ctx.lineWidth = 2;
    ctx.strokeRect(platform.x, platform.y, platform.w, platform.h);

    ctx.globalAlpha = 1.0;
  },
};

// Вспомогательная функция — проверка, находится ли сущность на платформе
Boulder._entityOnPlatform = function(entity, platform) {
  const ex = entity.x, ey = entity.y;
  const size = entity.size || (entity.cfg ? Math.max(entity.cfg.w, entity.cfg.h) * 0.5 : 14);
  return ex + size * 0.3 > platform.x && ex - size * 0.3 < platform.x + platform.w &&
         ey + size * 0.3 > platform.y && ey - size * 0.3 < platform.y + platform.h;
};

/* ============================================================
   MAGIC FLOOR RUNE — Магическая руна на полу
   Одноразовая: при наступании — случайный эффект.
   ============================================================ */
const MagicFloorRune = {
  /** Типы рун */
  TYPES: ['fire', 'ice', 'dark', 'teleport', 'heal'],

  /**
   * Создать магическую руну.
   * @param {number} x, y — позиция центра
   * @param {string} [runeType] — тип (или случайный)
   * @returns {object} runeState
   */
  create(x, y, runeType) {
    const cfg = STEP17_CONFIG.MAGIC_FLOOR_RUNE;

    // Выбор типа: heal — 10% шанс, остальные равновероятны
    if (!runeType) {
      if (Math.random() < cfg.HEAL_CHANCE) {
        runeType = 'heal';
      } else {
        const types = ['fire', 'ice', 'dark', 'teleport'];
        runeType = types[Math.floor(Math.random() * types.length)];
      }
    }

    // Цвет по типу
    const colors = {
      fire: { main: '#ff4400', glow: 'rgba(255, 68, 0, 0.6)' },
      ice: { main: '#44aaff', glow: 'rgba(68, 170, 255, 0.6)' },
      dark: { main: '#9933ff', glow: 'rgba(153, 51, 255, 0.6)' },
      teleport: { main: '#ffdd00', glow: 'rgba(255, 221, 0, 0.6)' },
      heal: { main: '#33ff66', glow: 'rgba(51, 255, 102, 0.6)' },
    };

    return {
      type: 'magic_floor_rune',
      runeType: runeType,
      x, y,
      radius: cfg.RADIUS,
      triggerRadius: cfg.TRIGGER_RADIUS,
      active: true,       // ещё не сработала
      triggered: false,   // визуальный флаг (вспышка)
      triggerTimer: 0,
      pulse: Math.random() * Math.PI * 2,
      color: colors[runeType] || colors.fire,
      // Параметры по типу
      damage: cfg.FIRE_DAMAGE,
      explosionRadius: cfg.FIRE_EXPLOSION_RADIUS,
      slowPct: cfg.ICE_SLOW_PCT,
      slowDuration: cfg.ICE_SLOW_DURATION,
      iceDamage: cfg.ICE_DAMAGE,
      healAmount: cfg.HEAL_AMOUNT,
      darkSpawnCount: cfg.DARK_SPAWN_COUNT,
    };
  },

  /**
   * Обновить руну.
   * @returns {object|null} — событие { type: 'fire'|'ice'|'dark'|'teleport'|'heal', ... }
   */
  update(rune, player, dt) {
    if (!rune.active) return null;

    rune.pulse += dt * 4;

    // Анимация после триггера (вспышка 0.3 сек, затем удаляется)
    if (rune.triggered) {
      rune.triggerTimer -= dt;
      if (rune.triggerTimer <= 0) {
        rune.active = false;
      }
      return null;
    }

    // Проверяем приближение игрока
    const dx = player.x - rune.x;
    const dy = player.y - rune.y;
    const dist2 = dx * dx + dy * dy;

    if (dist2 <= rune.triggerRadius * rune.triggerRadius) {
      // Активируем руну!
      rune.triggered = true;
      rune.triggerTimer = 0.4;
      return MagicFloorRune._triggerEffect(rune, player);
    }

    return null;
  },

  /** Применить эффект руны. */
  _triggerEffect(rune, player) {
    switch (rune.runeType) {
      case 'fire':
        return {
          type: 'fire',
          x: rune.x, y: rune.y,
          damage: rune.damage,
          radius: rune.explosionRadius,
        };

      case 'ice':
        return {
          type: 'ice',
          x: rune.x, y: rune.y,
          damage: rune.iceDamage,
          slowPct: rune.slowPct,
          slowDuration: rune.slowDuration,
        };

      case 'dark':
        return {
          type: 'dark',
          x: rune.x, y: rune.y,
          spawnCount: rune.darkSpawnCount,
        };

      case 'teleport':
        return {
          type: 'teleport',
          x: rune.x, y: rune.y,
        };

      case 'heal':
        return {
          type: 'heal',
          x: rune.x, y: rune.y,
          amount: rune.healAmount,
        };

      default:
        return null;
    }
  },

  /** Отрисовка руны. */
  render(ctx, rune, cam, viewW, viewH) {
    if (!rune.active) return;
    if (rune.x - 30 > cam.x + viewW || rune.x + 30 < cam.x ||
        rune.y - 30 > cam.y + viewH || rune.y + 30 < cam.y) return;

    const r = rune.radius;
    const pulse = 1 + Math.sin(rune.pulse) * 0.2;

    // Вспышка при активации
    if (rune.triggered) {
      const alpha = rune.triggerTimer / 0.4;
      ctx.fillStyle = rune.color.main;
      ctx.globalAlpha = alpha;
      ctx.beginPath();
      ctx.arc(rune.x, rune.y, r * 3 * (1 - alpha), 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 1;
      return;
    }

    // Свечение
    ctx.shadowColor = rune.color.glow;
    ctx.shadowBlur = 8 * pulse;

    // Круг руны
    ctx.fillStyle = rune.color.main;
    ctx.globalAlpha = 0.5 + Math.sin(rune.pulse) * 0.2;
    ctx.beginPath();
    ctx.arc(rune.x, rune.y, r * pulse, 0, Math.PI * 2);
    ctx.fill();

    // Обводка
    ctx.strokeStyle = rune.color.main;
    ctx.globalAlpha = 0.8;
    ctx.lineWidth = 1.5;
    ctx.stroke();
    ctx.shadowBlur = 0;

    // Символ в центре (зависит от типа)
    ctx.globalAlpha = 0.9;
    ctx.fillStyle = '#ffffff';
    ctx.font = `bold ${Math.floor(12 * pulse)}px ui-monospace, monospace`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    const symbols = { fire: '\u2600', ice: '\u2744', dark: '\u2620', teleport: '\u2B50', heal: '\u2764' };
    ctx.fillText(symbols[rune.runeType] || '?', rune.x, rune.y);

    ctx.globalAlpha = 1;
  },
};

/* ============================================================
   Экспорт
   ============================================================ */
window.Boulder = Boulder;
window.VanishingPlatform = VanishingPlatform;
window.MagicFloorRune = MagicFloorRune;

// === js/map/pathfinding.js ===
/* ============================================================
   A* PATHFINDING для умного ИИ врагов.
   Использует существующую сетку dungeon.grid.
   Кэширует пути и пересчитывает не чаще чем раз в 0.3 сек.
   ============================================================ */

const Pathfinding = {
  // Кэш открытого списка (переиспользуемый binary heap)
  _openHeap: [],
  _closedSet: null,
  _gScores: null,
  _parents: null,

  /**
   * Найти путь от (sx,sy) до (tx,ty) на сетке dungeon.grid.
   * Возвращает массив точек [{x,y}, ...] в мировых координатах или null.
   * maxNodes — ограничение итераций для производительности.
   */
  findPath(sx, sy, tx, ty, maxNodes) {
    if (!GameMap.dungeon || !GameMap.dungeon.grid) return null;
    const grid = GameMap.dungeon.grid;
    const gw = GameMap.dungeon.gridW;
    const gh = GameMap.dungeon.gridH;
    const cs = GameMap.dungeon.cellSize;

    const startI = Math.floor(sx / cs), startJ = Math.floor(sy / cs);
    const endI = Math.floor(tx / cs), endJ = Math.floor(ty / cs);

    // Граничные проверки
    if (startI < 0 || startJ < 0 || startI >= gw || startJ >= gh) return null;
    if (endI < 0 || endJ < 0 || endI >= gw || endJ >= gh) return null;
    // Если цель в стене — ищем ближайшую проходимую ячейку рядом с целью
    let goalI = endI, goalJ = endJ;
    if (grid[goalJ * gw + goalI] !== 1) {
      let found = false;
      for (let r = 1; r <= 3 && !found; r++) {
        for (let dj = -r; dj <= r && !found; dj++) {
          for (let di = -r; di <= r && !found; di++) {
            const ni = endI + di, nj = endJ + dj;
            if (ni >= 0 && nj >= 0 && ni < gw && nj < gh && grid[nj * gw + ni] === 1) {
              goalI = ni; goalJ = nj; found = true;
            }
          }
        }
      }
      if (!found) return null;
    }
    // Если старт в стене — не ищем путь
    if (grid[startJ * gw + startI] !== 1) return null;
    // Старт == цель
    if (startI === goalI && startJ === goalJ) return [];

    // A* с binary heap
    const limit = maxNodes || 200;
    const SQRT2 = 1.414;

    // Используем плоские массивы для скорости
    const size = gw * gh;
    if (!this._closedSet || this._closedSet.length < size) {
      this._closedSet = new Uint8Array(size);
      this._gScores = new Float32Array(size);
      this._parents = new Int32Array(size);
    }
    const closed = this._closedSet;
    const gScore = this._gScores;
    const parent = this._parents;
    closed.fill(0);
    gScore.fill(1e9);
    parent.fill(-1);

    // Binary heap (min-heap по fScore)
    const heap = this._openHeap;
    heap.length = 0;
    const fScores = new Float32Array(size);
    fScores.fill(1e9);

    const startIdx = startJ * gw + startI;
    const goalIdx = goalJ * gw + goalI;
    gScore[startIdx] = 0;
    fScores[startIdx] = Math.abs(goalI - startI) + Math.abs(goalJ - startJ);
    heap.push(startIdx);

    // Направления: 8 сторон
    const dirs = [
      { di: 0, dj: -1, cost: 1 }, { di: 0, dj: 1, cost: 1 },
      { di: -1, dj: 0, cost: 1 }, { di: 1, dj: 0, cost: 1 },
      { di: -1, dj: -1, cost: SQRT2 }, { di: 1, dj: -1, cost: SQRT2 },
      { di: -1, dj: 1, cost: SQRT2 }, { di: 1, dj: 1, cost: SQRT2 },
    ];

    let iterations = 0;
    while (heap.length > 0 && iterations < limit) {
      iterations++;
      // Извлекаем минимум
      let minIdx = 0;
      for (let k = 1; k < heap.length; k++) {
        if (fScores[heap[k]] < fScores[heap[minIdx]]) minIdx = k;
      }
      const current = heap[minIdx];
      heap[minIdx] = heap[heap.length - 1];
      heap.pop();

      if (current === goalIdx) {
        // Восстанавливаем путь
        return this._reconstructPath(parent, current, gw, cs);
      }

      closed[current] = 1;
      const ci = current % gw, cj = Math.floor(current / gw);

      for (const dir of dirs) {
        const ni = ci + dir.di, nj = cj + dir.dj;
        if (ni < 0 || nj < 0 || ni >= gw || nj >= gh) continue;
        const nIdx = nj * gw + ni;
        if (closed[nIdx]) continue;
        if (grid[nIdx] !== 1) continue;
        // Для диагоналей проверяем что обе смежные клетки проходимы (нет среза углов)
        if (dir.di !== 0 && dir.dj !== 0) {
          if (grid[cj * gw + ni] !== 1 || grid[nj * gw + ci] !== 1) continue;
        }

        const tentG = gScore[current] + dir.cost;
        if (tentG < gScore[nIdx]) {
          parent[nIdx] = current;
          gScore[nIdx] = tentG;
          fScores[nIdx] = tentG + Math.abs(goalI - ni) + Math.abs(goalJ - nj);
          // Добавляем в heap если ещё не там
          if (heap.indexOf(nIdx) === -1) heap.push(nIdx);
        }
      }
    }
    return null; // Путь не найден
  },

  _reconstructPath(parent, goalIdx, gw, cs) {
    const path = [];
    let cur = goalIdx;
    let count = 0;
    while (cur !== -1 && count < 500) {
      const i = cur % gw, j = Math.floor(cur / gw);
      path.push({ x: i * cs + cs * 0.5, y: j * cs + cs * 0.5 });
      cur = parent[cur];
      count++;
    }
    path.reverse();
    // Убираем первую точку (текущая позиция) если путь длинный
    if (path.length > 1) path.shift();
    return path;
  },

  /**
   * Проверить прямую видимость между двумя точками (raycast по сетке).
   * Используется чтобы определить нужен ли pathfinding.
   */
  hasLineOfSight(x1, y1, x2, y2) {
    if (!GameMap.dungeon || !GameMap.dungeon.grid) return true;
    const grid = GameMap.dungeon.grid;
    const gw = GameMap.dungeon.gridW;
    const cs = GameMap.dungeon.cellSize;

    const dx = x2 - x1, dy = y2 - y1;
    const dist = Math.hypot(dx, dy);
    if (dist < cs) return true; // слишком близко — считаем видимым

    // Проверяем точки вдоль линии с шагом в половину ячейки
    const steps = Math.ceil(dist / (cs * 0.5));
    const stepX = dx / steps, stepY = dy / steps;
    for (let s = 1; s < steps; s++) {
      const px = x1 + stepX * s;
      const py = y1 + stepY * s;
      const gi = Math.floor(px / cs), gj = Math.floor(py / cs);
      if (gi < 0 || gj < 0 || gi >= gw || gj >= GameMap.dungeon.gridH) return false;
      if (grid[gj * gw + gi] !== 1) return false;
    }
    return true;
  },
};

window.Pathfinding = Pathfinding;

window.GameMap = GameMap;

'use strict';

// === js/systems/particles.js ===
'use strict';
/* ============================================================
   particles.js — пул частиц и помощники для визуальных эффектов.

   Шаг 3:
   - Унифицированный объект Particle: kind = 'spark' | 'ring' | 'text'
     поверх имеющихся полей (x, y, vx, vy, life, color, size).
   - Helpers: Particles.spark, Particles.ring, Particles.burst,
     Particles.text, Particles.chestGlow, Particles.fusionBurst.
   - Пул создаётся и обновляется в main.js (CONFIG.POOLS.PARTICLES = 100).
   - Этот модуль ТОЛЬКО предоставляет фабрику и хелперы спавна;
     апдейт/рендер живут в Game.updateParticles / Game.renderParticles
     (там же используем kind для разной отрисовки).
   ============================================================ */

/** Фабрика частицы. Расширенная под Шаг 3. */
function createParticle() {
  return {
    active: false,
    kind: 'spark',          // 'spark' | 'ring' | 'text' | 'dust'
    x: 0, y: 0,
    vx: 0, vy: 0,
    life: 0, maxLife: 0,
    color: '#888',
    size: 3,                // для 'spark' — сторона квадрата; для 'text' — px шрифта; для 'dust' — 2px
    // Для 'ring':
    radius: 0,
    maxRadius: 0,
    lineWidth: 2,
    // Для 'text':
    text: '',
    // Для 'dust':
    gravity: 0,             // px/s² вниз (лёгкое оседание)
  };
}
window.createParticle = createParticle;

const Particles = {
  /** Внутренний помощник: получить свободную частицу из пула Game.particles. */
  _spawn() {
    if (!window.Game || !Game.particles) return null;
    const p = Game.particles.spawn();
    if (!p) return null;
    // Сбросить опциональные поля к "нулю" (на случай переиспользования)
    p.kind = 'spark';
    p.radius = 0;
    p.maxRadius = 0;
    p.lineWidth = 2;
    p.text = '';
    p.gravity = 0;
    return p;
  },

  /** Простая искра: квадрат size px, разлетающийся со скоростью v. */
  spark(x, y, vx, vy, life, color, size) {
    const p = this._spawn();
    if (!p) return null;
    p.kind = 'spark';
    p.x = x; p.y = y;
    p.vx = vx; p.vy = vy;
    p.life = p.maxLife = life;
    p.color = color || '#fff';
    p.size = size || 3;
    return p;
  },

  /** Расширяющееся кольцо: от 0 до maxRadius за life секунд. */
  ring(x, y, maxRadius, life, color, lineWidth) {
    const p = this._spawn();
    if (!p) return null;
    p.kind = 'ring';
    p.x = x; p.y = y;
    p.vx = 0; p.vy = 0;
    p.life = p.maxLife = life;
    p.color = color || 'rgba(255, 215, 80, 0.9)';
    p.size = 0;
    p.radius = 0;
    p.maxRadius = maxRadius;
    p.lineWidth = lineWidth || 3;
    return p;
  },

  /** Всплывающий текст (например, "+20 XP"). vy отрицательная — взлёт вверх. */
  text(x, y, str, life, color, size) {
    const p = this._spawn();
    if (!p) return null;
    p.kind = 'text';
    p.x = x; p.y = y;
    p.vx = 0; p.vy = -40;
    p.life = p.maxLife = life || 1.0;
    p.color = color || '#ffe084';
    p.size = size || 16;
    p.text = String(str);
    return p;
  },

  /** "Взрыв" из count искр заданного цвета. */
  burst(x, y, count, opts) {
    opts = opts || {};
    const speedMin = opts.speedMin != null ? opts.speedMin : 60;
    const speedMax = opts.speedMax != null ? opts.speedMax : 160;
    const lifeMin  = opts.lifeMin  != null ? opts.lifeMin  : 0.4;
    const lifeMax  = opts.lifeMax  != null ? opts.lifeMax  : 0.8;
    const sizeMin  = opts.sizeMin  != null ? opts.sizeMin  : 2;
    const sizeMax  = opts.sizeMax  != null ? opts.sizeMax  : 4;
    const color    = opts.color    || '#fff';
    for (let i = 0; i < count; i++) {
      const a = Math.random() * Math.PI * 2;
      const sp = Utils.rand(speedMin, speedMax);
      this.spark(
        x, y,
        Math.cos(a) * sp, Math.sin(a) * sp,
        Utils.rand(lifeMin, lifeMax),
        color,
        Utils.rand(sizeMin, sizeMax),
      );
    }
  },

  /** Эффект слияния (эволюция): золотая вспышка-кольцо + 12 искр. */
  fusionBurst(x, y) {
    // Кольцо: расширяется до 100 px за 0.3 с
    this.ring(x, y, 100, 0.30, 'rgba(255, 220, 90, 0.95)', 4);
    // Внутреннее кольцо чуть меньше и ярче
    this.ring(x, y, 60,  0.25, 'rgba(255, 255, 200, 0.8)', 2);
    // Золотые искры
    this.burst(x, y, 12, {
      color: '#ffd84a',
      speedMin: 80, speedMax: 220,
      lifeMin: 0.45, lifeMax: 0.85,
      sizeMin: 2.5, sizeMax: 4.5,
    });
  },

  /** Лёгкое свечение при появлении сундука — мягкое расширяющееся кольцо. */
  chestGlow(x, y) {
    this.ring(x, y, 50, 0.50, 'rgba(255, 215, 80, 0.55)', 3);
  },

  /** Эффект открытия сундука: яркая вспышка + жёлтые искры. */
  chestOpen(x, y) {
    this.ring(x, y, 80, 0.35, 'rgba(255, 240, 160, 0.95)', 4);
    this.burst(x, y, 14, {
      color: '#ffd84a',
      speedMin: 90, speedMax: 240,
      lifeMin: 0.5, lifeMax: 0.9,
      sizeMin: 2, sizeMax: 4,
    });
  },

  /** Шаг 6: Эффект появления босса — двойная вспышка + портал. */
  bossSpawn(x, y, color) {
    this.ring(x, y, 80, 0.5, 'rgba(255, 200, 50, 0.9)', 4);
    this.ring(x, y, 50, 0.4, color || 'rgba(255, 80, 30, 0.8)', 3);
    this.burst(x, y, 15, {
      color: '#ffd700',
      speedMin: 80, speedMax: 200,
      lifeMin: 0.5, lifeMax: 0.9,
      sizeMin: 3, sizeMax: 5,
    });
  },

  /** Шаг 6: Эффект смерти босса — крупная вспышка + много частиц + тряска. */
  bossDeath(x, y, color) {
    this.ring(x, y, 120, 0.5, color || '#ff4444', 5);
    this.ring(x, y, 80, 0.35, 'rgba(255, 255, 200, 0.9)', 3);
    this.burst(x, y, 25, {
      color: color || '#ff4444',
      speedMin: 100, speedMax: 280,
      lifeMin: 0.5, lifeMax: 1.0,
      sizeMin: 3, sizeMax: 6,
    });
    this.text(x, y - 30, 'BOSS DEFEATED!', 2.0, '#ffd700', 20);
  },

  /* ============================================================
     Шаг 3 (анимации): Эффект «dusting» — рассыпание в пыль при смерти врага.
     ============================================================ */

  /** Одна пылевая частица 2×2, с гравитацией и альфа-затуханием. */
  dust(x, y, vx, vy, life, color, gravity) {
    const p = this._spawn();
    if (!p) return null;
    p.kind = 'dust';
    p.x = x; p.y = y;
    p.vx = vx; p.vy = vy;
    p.life = p.maxLife = life;
    p.color = color || '#aaa';
    p.size = 2;
    p.gravity = gravity || 30;
    return p;
  },

  /**
   * «Щелчок Таноса» — рассыпание обычного врага (8–12 частиц, 0.3 сек).
   * @param {number} x - позиция врага
   * @param {number} y - позиция врага
   * @param {string} color - основной цвет врага
   */
  enemyDust(x, y, color) {
    const count = Utils.randInt(8, 12);
    const baseColor = color || '#888';
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Utils.rand(20, 40);
      const vx = Math.cos(angle) * speed;
      const vy = Math.sin(angle) * speed - Utils.rand(5, 15); // лёгкий подлёт вверх
      const life = Utils.rand(0.2, 0.35);
      this.dust(
        x + Utils.rand(-6, 6),
        y + Utils.rand(-6, 6),
        vx, vy, life, baseColor, Utils.rand(20, 40)
      );
    }
  },

  /**
   * «Щелчок Таноса» для боссов — 20-30 частиц, 0.5 сек + вспышка.
   * @param {number} x - позиция босса
   * @param {number} y - позиция босса
   * @param {string} color - цвет босса
   */
  bossDust(x, y, color) {
    const count = Utils.randInt(20, 30);
    const baseColor = color || '#c00';
    // Вспышка
    this.ring(x, y, 60, 0.3, 'rgba(255, 255, 200, 0.9)', 4);
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Utils.rand(30, 60);
      const vx = Math.cos(angle) * speed;
      const vy = Math.sin(angle) * speed - Utils.rand(8, 20);
      const life = Utils.rand(0.3, 0.55);
      this.dust(
        x + Utils.rand(-10, 10),
        y + Utils.rand(-10, 10),
        vx, vy, life, baseColor, Utils.rand(15, 35)
      );
    }
  },

  /**
   * Вспышка при атаке оружия — лёгкие искры заданного цвета.
   * @param {number} x - позиция появления
   * @param {number} y - позиция появления
   * @param {number} count - количество искр (2-5)
   * @param {string} color - цвет
   */
  attackSparks(x, y, count, color) {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Utils.rand(40, 100);
      this.spark(
        x, y,
        Math.cos(angle) * speed, Math.sin(angle) * speed,
        Utils.rand(0.08, 0.15),
        color || '#fff',
        Utils.rand(1.5, 3)
      );
    }
  },

  /** Обновление одной частицы, специфичное для kind.
   *  Возвращает true, если частицу нужно деактивировать. */
  step(p, dt) {
    p.life -= dt;
    if (p.life <= 0) return true;
    switch (p.kind) {
      case 'spark':
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.vx *= 0.94;
        p.vy *= 0.94;
        break;
      case 'ring': {
        const t = 1 - Math.max(0, p.life / p.maxLife); // 0..1
        p.radius = p.maxRadius * t;
        break;
      }
      case 'text':
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.vy *= 0.98;
        break;
      case 'dust':
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.vy += p.gravity * dt; // гравитация — оседание вниз
        p.vx *= 0.92;
        p.vy *= 0.92;
        break;
    }
    return false;
  },

  /** Отрисовка одной частицы. ctx уже сдвинут на -cam. */
  draw(ctx, p) {
    const a = Math.max(0, p.life / p.maxLife);
    switch (p.kind) {
      case 'spark': {
        ctx.globalAlpha = a;
        ctx.fillStyle = p.color;
        ctx.fillRect(p.x - p.size * 0.5, p.y - p.size * 0.5, p.size, p.size);
        ctx.globalAlpha = 1;
        break;
      }
      case 'ring': {
        ctx.globalAlpha = a;
        ctx.strokeStyle = p.color;
        ctx.lineWidth = p.lineWidth;
        ctx.beginPath();
        ctx.arc(p.x, p.y, Math.max(0.5, p.radius), 0, Math.PI * 2);
        ctx.stroke();
        ctx.globalAlpha = 1;
        break;
      }
      case 'text': {
        ctx.globalAlpha = a;
        ctx.fillStyle = p.color;
        ctx.font = `bold ${p.size}px ui-monospace, monospace`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(p.text, p.x, p.y);
        ctx.globalAlpha = 1;
        break;
      }
      case 'dust': {
        // Квадратик 2×2 с быстрым альфа-затуханием
        ctx.globalAlpha = a * a; // квадратичное затухание — быстрее исчезает
        ctx.fillStyle = p.color;
        ctx.fillRect(p.x - 1, p.y - 1, p.size, p.size);
        ctx.globalAlpha = 1;
        break;
      }
    }
  },
};

window.Particles = Particles;

