  _gradRect(ctx, 3, 6, 10, 5, skin, skinDark);
  _rect(ctx, 4, 5, 8, 1, skinDark);
  _rect(ctx, 1, 6, 2, 5, skin); _rect(ctx, 13, 6, 2, 5, skin);
  _vline(ctx, 0, 3, 6, '#6b3510');
