  ice_storm: _evoSprite_ice_storm,
  thunder_chain: _evoSprite_thunder_chain,
  plague_cloud: _evoSprite_plague_cloud,
  mad_grimoire: _evoSprite_mad_grimoire,
  inferno: _evoSprite_inferno,
