// === js/meta/codex.js ===
'use strict';
/* ============================================================
   codex.js — Книга оружия, способностей и эволюций.
   Механика открытия + отображение в UI лагеря.
   Сохранение в localStorage (d20_codex).
   ============================================================ */

const Codex = {
  _data: null, // { weapons: Set, abilities: Set, evolutions: Set }

  /** Загрузить из localStorage. */
  load() {
    try {
      const raw = SafeStorage.getItem('d20_codex');
      if (raw) {
        const parsed = JSON.parse(raw);
        this._data = {
          weapons: new Set(parsed.weapons || []),
          abilities: new Set(parsed.abilities || []),
          evolutions: new Set(parsed.evolutions || []),
        };
      } else {
        this._data = { weapons: new Set(), abilities: new Set(), evolutions: new Set() };
      }
    } catch (e) {
      this._data = { weapons: new Set(), abilities: new Set(), evolutions: new Set() };
    }
  },

  /** Сохранить в localStorage. */
  save() {
    if (!this._data) return;
    const obj = {
      weapons: [...this._data.weapons],
      abilities: [...this._data.abilities],
      evolutions: [...this._data.evolutions],
    };
    SafeStorage.setItem('d20_codex', JSON.stringify(obj));
  },

  /** Разблокировать оружие. */
  unlockWeapon(weaponId) {
    if (!this._data) this.load();
    if (!this._data.weapons.has(weaponId)) {
      this._data.weapons.add(weaponId);
      this.save();
    }
  },

  /** Разблокировать способность. */
  unlockAbility(abilityId) {
    if (!this._data) this.load();
    if (!this._data.abilities.has(abilityId)) {
      this._data.abilities.add(abilityId);
      this.save();
    }
  },

  /** Разблокировать эволюцию. */
  unlockEvolution(evolutionResultId) {
    if (!this._data) this.load();
    if (!this._data.evolutions.has(evolutionResultId)) {
      this._data.evolutions.add(evolutionResultId);
      this.save();
    }
  },

  /** Проверки. */
  isWeaponUnlocked(id) { if (!this._data) this.load(); return this._data.weapons.has(id); },
  isAbilityUnlocked(id) { if (!this._data) this.load(); return this._data.abilities.has(id); },
  isEvolutionUnlocked(id) { if (!this._data) this.load(); return this._data.evolutions.has(id); },

  /** Статистика. */
  getStats() {
    if (!this._data) this.load();
    const totalWeapons = (window.WEAPON_INFO ? WEAPON_INFO.length : 0) +
                         (window.EXCLUSIVE_WEAPON_INFO ? EXCLUSIVE_WEAPON_INFO.length : 0);
    const totalAbilities = window.ABILITY_INFO ? ABILITY_INFO.length : 0;
    const totalEvolutions = (window.EVOLUTIONS ? EVOLUTIONS.length : 0) +
                            (window.SUPER_EVOLUTIONS ? SUPER_EVOLUTIONS.length : 0);
    return {
      weapons: { unlocked: this._data.weapons.size, total: totalWeapons },
      abilities: { unlocked: this._data.abilities.size, total: totalAbilities },
      evolutions: { unlocked: this._data.evolutions.size, total: totalEvolutions },
    };
  },
};

window.Codex = Codex;

// === js/input/input.js ===
'use strict';
/* ============================================================
   input.js — клавиатура + динамический джойстик.

   Динамический джойстик:
   - При pointerdown в любой точке экрана (вне HUD-кнопок)
     появляется база джойстика в этой точке.
   - При движении — стик смещается до MAX_OFFSET, направление
     движения = нормализованный вектор смещения.
   - При отпускании — джойстик скрывается, движение от него = 0.
   - На десктопе работают WASD/стрелки как альтернатива.
   ============================================================ */

const Input = {
  keys: Object.create(null),

  // Состояние джойстика
  joy: {
    active: false,
    pointerId: null,
    baseX: 0, baseY: 0,
    dx: 0, dy: 0,        // нормализованные -1..1
  },

  // DOM
  joyEl: null,
  stickEl: null,

  init() {
    // Клавиатура
    window.addEventListener('keydown', (e) => {
      this.keys[e.code] = true;
      if (e.code === 'KeyP' || e.code === 'Escape') {
        if (window.Game) {
          if (Game.state === 'playing') {
            Game.togglePause();
          } else if (Game.state === 'paused' && e.code === 'Escape') {
            // Escape в паузе — выход в лагерь
            Game.exitToMenu();
          }
        }
      }
    });
    window.addEventListener('keyup', (e) => { this.keys[e.code] = false; });

    // Джойстик
    this.joyEl   = document.getElementById('joystick');
    this.stickEl = this.joyEl.querySelector('.stick');

    // Слушаем события на всём документе (canvas сам не получает touch — у него
    // нет pointer-events когда поверх HUD; но у html/body — получают).
    // Используем capture, чтобы перехватить раньше canvas.
    document.addEventListener('pointerdown', this._onDown.bind(this), { passive: false });
    document.addEventListener('pointermove', this._onMove.bind(this), { passive: false });
    document.addEventListener('pointerup',     this._onUp.bind(this));
    document.addEventListener('pointercancel', this._onUp.bind(this));
  },

  /** Не создавать джойстик, если касание на интерактивном HUD-элементе. */
  _hitsHud(target) {
    if (!target) return false;
    // Любой button или элемент с pointer-events: auto в HUD-области
    let el = target;
    while (el && el !== document.body) {
      if (el.tagName === 'BUTTON') return true;
      if (el.classList && el.classList.contains('overlay')) return true;
      if (el.classList && el.classList.contains('card')) return true;
      el = el.parentElement;
    }
    return false;
  },

  _onDown(e) {
    if (this.joy.active) return;
    if (this._hitsHud(e.target)) return;
    // Игнорируем правую кнопку мыши
    if (e.pointerType === 'mouse' && e.button !== 0) return;

    this.joy.active = true;
    this.joy.pointerId = e.pointerId;
    this.joy.baseX = e.clientX;
    this.joy.baseY = e.clientY;
    this.joy.dx = 0;
    this.joy.dy = 0;

    // Позиционируем DOM-элемент базы
    this.joyEl.style.left = e.clientX + 'px';
    this.joyEl.style.top  = e.clientY + 'px';
    this.joyEl.classList.add('active');
    this.stickEl.style.transform = 'translate(0px, 0px)';

    e.preventDefault();
  },

  _onMove(e) {
    if (!this.joy.active || e.pointerId !== this.joy.pointerId) return;

    const dx = e.clientX - this.joy.baseX;
    const dy = e.clientY - this.joy.baseY;
    const max = CONFIG.JOYSTICK.MAX_OFFSET;
    const len = Math.hypot(dx, dy);

    let ix = dx, iy = dy;
    if (len > max) {
      ix = dx / len * max;
      iy = dy / len * max;
    }
    this.stickEl.style.transform = `translate(${ix}px, ${iy}px)`;

    // Нормализация: длина смещения / max -> 0..1; направление
    const nlen = Math.min(len, max) / max;
    if (nlen < CONFIG.JOYSTICK.DEAD_ZONE) {
      this.joy.dx = 0;
      this.joy.dy = 0;
    } else {
      const nx = len > 0 ? dx / len : 0;
      const ny = len > 0 ? dy / len : 0;
      this.joy.dx = nx * nlen;
      this.joy.dy = ny * nlen;
    }
    e.preventDefault();
  },

  _onUp(e) {
    if (!this.joy.active || (e.pointerId !== undefined && e.pointerId !== this.joy.pointerId)) return;
    this.joy.active = false;
    this.joy.pointerId = null;
    this.joy.dx = 0;
    this.joy.dy = 0;
    this.joyEl.classList.remove('active');
    this.stickEl.style.transform = 'translate(0px, 0px)';
  },

  /** Желаемый вектор движения (нормализованный, |v| 0..1). */
  getMove() {
    let dx = 0, dy = 0;
    // Джойстик имеет приоритет
    if (this.joy.active && (this.joy.dx !== 0 || this.joy.dy !== 0)) {
      dx = this.joy.dx;
      dy = this.joy.dy;
    } else {
      if (this.keys['KeyW'] || this.keys['ArrowUp'])    dy -= 1;
      if (this.keys['KeyS'] || this.keys['ArrowDown'])  dy += 1;
      if (this.keys['KeyA'] || this.keys['ArrowLeft'])  dx -= 1;
      if (this.keys['KeyD'] || this.keys['ArrowRight']) dx += 1;
      const l = Math.hypot(dx, dy);
      if (l > 1) { dx /= l; dy /= l; }
    }
    return { x: dx, y: dy };
  },

  /** Принудительно отпустить джойстик (например, при переходе в pause/levelup). */
  releaseJoystick() {
    this._onUp({ pointerId: this.joy.pointerId });
  },
};

window.Input = Input;

// === js/entities/player.js ===
'use strict';
/* ============================================================
   player.js — герой: создание, движение, слоты, урон и т.п.
   Всегда стартует с мечом в первом слоте оружия.
   ============================================================ */

const Player = {
  /** Создать нового героя. */
  create(startX, startY) {
    // Шаг 15: динамические слоты из мета-прогресса
    const weaponSlotCount = (window.MetaProgress && MetaProgress.data)
      ? MetaProgress.getWeaponSlots()
      : CONFIG.PLAYER.SLOTS_WEAPONS;
    const abilitySlotCount = (window.MetaProgress && MetaProgress.data)
      ? MetaProgress.getAbilitySlots()
      : CONFIG.PLAYER.SLOTS_ABILITIES;

    const p = {
      x: (startX != null) ? startX : CONFIG.MAP.W / 2,
      y: (startY != null) ? startY : CONFIG.MAP.H / 2,
      size: CONFIG.PLAYER.SIZE,
      hp: CONFIG.PLAYER.MAX_HP,
      maxHp: CONFIG.PLAYER.MAX_HP,

      // Множители
      speedMul: 1,
      damageMul: 1,
      swordCdMul: 1,        // оставлено для совместимости (базовые улучшения)
      missileCdMul: 1,
      pickupMul: 1,
      weaponCdMul: 1,       // глобальный для всех Weapon (базовое улучшение)

      // Bug fix #1: отдельно хранить бонус HP от талантов для корректного пересчёта
      talentBonusHp: 0,

      // Регенерация (HP/сек). Регенеративная пассивка пишет сюда.
      hpRegen: 0,
      _regenAcc: 0,

      // Шаг 8: новые статы от пассивок
      damageReduction: 0,    // 0..1 — снижение входящего урона
      manaShield: null,      // ссылка на ManaShieldAbility (или null)
      maxHpMul: 1,           // множитель макс. HP (от Укрепления)
      bonusMaxHp: 0,         // бонус макс. HP от базовых улучшений
      debuffReduction: 0,    // 0..1 — снижение длительности дебаффов
      lifesteal: 0,          // 0..1 — % лечения от нанесённого урона
      critChance: 0,         // 0..1 — шанс крита
      bleedChance: 0,        // 0..1 — шанс кровотечения при атаке
      explosiveDeathChance: 0, // 0..1 — шанс взрыва при убийстве
      frostAura: null,       // { slow, radius } или null
      magicDamageMul: 1,     // множитель магического урона
      magicEchoChance: 0,    // 0..1 — шанс ответного снаряда
      d20MinBonus: 0,        // +N к минимальному d20
      doubleXpChance: 0,     // 0..1 — шанс удвоения XP
      dotDamageMul: 1,       // множитель DoT-урона

      // Шаг 15: бонус XP от харизмы (умножает подбираемый XP)
      xpBonusMul: 1,

      // Встроенный Magic Missile (не занимает слот)
      missileCd: 0,
      missileCount: CONFIG.MISSILE.COUNT,

      // Направление
      moveDir: { x: 0, y: 0 },        // нормализованное направление в этом кадре
      facing: { x: 1, y: 0 },         // последнее ненулевое направление

      // XP / уровень
      level: 1,
      xp: 0,
      xpNext: CONFIG.XP.BASE,

      // Слоты (Шаг 15: динамический размер)
      weaponSlots:  new Array(weaponSlotCount).fill(null),
      abilitySlots: new Array(abilitySlotCount).fill(null),

      // Визуал
      trailTimer: 0,

      // Шаг 6: дебаффы от боссов
      poison: null,        // { dps, remaining }
      webSlow: 0,          // оставшееся время замедления паутиной
    };

    // Шаг 15: применить бонусы талантов из мета-прогресса
    if (window.MetaProgress && MetaProgress.data) {
      MetaProgress.applyTalents(p);
    }

    // Шаг 15: бонус гильдии — легендарный титул (+10% ко всем статам)
    if (window.MetaProgress && MetaProgress.hasGuildBonus('legendBonus')) {
      p.damageMul *= 1.10;
      p.speedMul *= 1.10;
      p.maxHp = Math.floor(p.maxHp * 1.10);
      p.hp = p.maxHp;
      p.magicDamageMul *= 1.10;
    }

    // Шаг 15: бонус гильдии — +20% XP на 2 мин при старте
    if (window.MetaProgress && MetaProgress.hasGuildBonus('startXpBoost')) {
      p._startXpBoostTimer = 120; // 2 минуты
      p.xpBonusMul = (p.xpBonusMul || 1) * 1.20;
    }

    // Выбор класса: стартовое оружие зависит от класса
    const selectedClass = (window.Classes) ? Classes.getSelected() : 'warrior';
    const startWeaponId = (window.Classes) ? Classes.getStartWeapon(selectedClass) : 'sword';

    // Магический снаряд (встроенный) — только у Волшебника
    if (selectedClass !== 'mage') {
      p._noBuiltInMissile = true; // Флаг: отключить встроенный Magic Missile
    }

    // Добавить стартовое оружие в первый слот
    if (startWeaponId === 'magic_missile_weapon') {
      // Волшебник получает Magic Missile как обычное оружие (в слоте)
      if (window.WEAPON_FACTORIES && WEAPON_FACTORIES.magic_missile_weapon) {
        Player.addWeapon(p, WEAPON_FACTORIES.magic_missile_weapon());
      } else if (window.WEAPON_FACTORIES && WEAPON_FACTORIES.spellbook) {
        Player.addWeapon(p, WEAPON_FACTORIES.spellbook());
      }
    } else if (window.WEAPON_FACTORIES && WEAPON_FACTORIES[startWeaponId]) {
      Player.addWeapon(p, WEAPON_FACTORIES[startWeaponId]());
    } else {
      Player.addWeapon(p, WEAPON_FACTORIES.sword());
    }

    // Разблокировать стартовое оружие в кодексе
    if (window.Codex) Codex.unlockWeapon(startWeaponId);

    // Применить пассивный бонус класса
    if (window.Classes) {
      Classes.applyClassPassive(p, selectedClass);
    }

    // Шаг 15: бонус гильдии — стартовое оружие начинает с +1 ур.
    if (window.MetaProgress && MetaProgress.hasGuildBonus('startBonus')) {
      const startW = p.weaponSlots[0];
      if (startW && startW.upgrade) startW.upgrade();
    }

    return p;
  },

  /** Найти первый свободный слот оружия и положить туда. Возвращает true/false. */
  addWeapon(player, weapon) {
    for (let i = 0; i < player.weaponSlots.length; i++) {
      if (!player.weaponSlots[i]) {
        weapon.slotIndex = i;
        player.weaponSlots[i] = weapon;
        return true;
      }
    }
    return false;
  },

  addAbility(player, ability) {
    for (let i = 0; i < player.abilitySlots.length; i++) {
      if (!player.abilitySlots[i]) {
        ability.slotIndex = i;
        player.abilitySlots[i] = ability;
        ability.apply(player);
        return true;
      }
    }
    return false;
  },

  /** Найти оружие по id (или null). */
  findWeapon(player, id) {
    for (const w of player.weaponSlots) if (w && w.id === id) return w;
    return null;
  },
  findAbility(player, id) {
    for (const a of player.abilitySlots) if (a && a.id === id) return a;
    return null;
  },

  hasFreeWeaponSlot(player)  { return player.weaponSlots.some(s => !s); },
  hasFreeAbilitySlot(player) { return player.abilitySlots.some(s => !s); },

  /** Удалить пассивку из её слота (со снятием эффектов). Возвращает true/false. */
  removeAbility(player, slotIndex) {
    if (slotIndex < 0 || slotIndex >= player.abilitySlots.length) return false;
    const a = player.abilitySlots[slotIndex];
    if (!a) return false;
    if (typeof a.remove === 'function') a.remove(player);
    a.slotIndex = -1;
    player.abilitySlots[slotIndex] = null;
    return true;
  },

  /**
   * Шаг 8: нанести урон герою с учётом пассивных эффектов.
   * Вызывать вместо прямого player.hp -= dmg.
   * Шаг 19: добавлены i-frames (0.3 сек неуязвимости после удара).
   * @param {object} player
   * @param {number} rawDmg — базовый урон до защиты
   * @param {object} [source] — источник урона (враг) для магического отклика
   * @returns {number} финальный нанесённый урон
   */
  takeDamage(player, rawDmg, source) {
    // I-frames: если герой в состоянии неуязвимости — игнорируем урон
    if (player._iFrameTimer && player._iFrameTimer > 0) return 0;

    // Уворот (талант): шанс полностью избежать удара
    if (player._dodgeChance && player._dodgeChance > 0 && Math.random() < player._dodgeChance) {
      if (window.Particles && Particles.text) {
        Particles.text(player.x, player.y - 30, 'DODGE!', 0.8, '#2ecc71', 14);
      }
      return 0;
    }

    // Щит маны — полная блокировка
    if (player.manaShield && player.manaShield.tryBlock()) {
      // Визуал блока
      if (window.Particles && Particles.burst) {
        Particles.burst(player.x, player.y, 5, {
          color: '#66ccff', speedMin: 40, speedMax: 100,
          lifeMin: 0.15, lifeMax: 0.3, sizeMin: 3, sizeMax: 5,
        });
      }
      return 0;
    }

    // Броня (снижение урона)
    let finalDmg = rawDmg;
    // Талант «Ловкач»: снижение урона от ловушек (source === null для ловушек)
    if (!source && player._trapDamageReduce && player._trapDamageReduce > 0) {
      finalDmg *= (1 - player._trapDamageReduce);
    }
    if (player.damageReduction > 0) {
      finalDmg *= (1 - Math.min(player.damageReduction, 0.75));
    }

    player.hp -= finalDmg;

    // Активируем i-frames (0.3 сек + бонус от таланта «Неуязвимость»)
    const iframeBase = 0.3;
    const iframeBonus = player._iFrameBonus || 0;
    player._iFrameTimer = iframeBase + iframeBonus;

    // Магический отклик — ответный снаряд
    if (player.magicEchoChance > 0 && Math.random() < player.magicEchoChance && source) {
      Player._fireEchoProjectile(player, source);
    }

    return finalDmg;
  },

  /** Шаг 8: выпустить ответный снаряд (магический отклик). */
  _fireEchoProjectile(player, target) {
    if (!window.Game || !Game.projectiles) return;
    const pr = Game.projectiles.spawn();
    if (!pr) return;
    const dx = target.x - player.x, dy = target.y - player.y;
    const dist = Math.hypot(dx, dy) || 1;
    pr.kind = 'echo';
    pr.owner = 'player';
    pr.x = player.x;
    pr.y = player.y;
    pr.vx = (dx / dist) * 350;
    pr.vy = (dy / dist) * 350;
    pr.life = 2.0;
    pr.damage = 15 * (player.magicDamageMul || 1) * player.damageMul;
    pr.radius = 5;
    pr.angle = Math.atan2(dy, dx);
    pr.source = 'echo';
    pr.homing = true;
    pr.homingStrength = 3.0;
  },

  /** Заменить оружие в указанном слоте. Если слот пустой — просто положить.
   *  Используется для эволюций: новое оружие занимает слот старого. */
  replaceWeapon(player, slotIndex, newWeapon) {
    if (slotIndex < 0 || slotIndex >= player.weaponSlots.length) return false;
    const old = player.weaponSlots[slotIndex];
    if (old) old.slotIndex = -1;
    newWeapon.slotIndex = slotIndex;
    player.weaponSlots[slotIndex] = newWeapon;
    return true;
  },

  /** Обновление героя: движение, регенерация, встроенные кулдауны. */
  update(player, dt) {
    const move = Input.getMove();
    const ml = Math.hypot(move.x, move.y);
    player.moveDir.x = move.x;
    player.moveDir.y = move.y;

    if (ml > 0.001) {
      const speed = CONFIG.PLAYER.SPEED * player.speedMul;
      const dx = move.x * speed * dt;
      const dy = move.y * speed * dt;
      // Движение с коллизиями (стены/колонны/закрытые двери)
      // Новая система: половинный хитбокс (shrinkFactor 0.25 = 50% ядро стены)
      const rad = player.size * 0.35;
      if (window.GameMap && GameMap.dungeon) {
        const r = GameMap.moveWithCollision(player.x, player.y, dx, dy, rad, 0.25);
        player.x = r.x;
        player.y = r.y;
      } else {
        player.x += dx;
        player.y += dy;
      }
      player.facing.x = move.x / ml;
      player.facing.y = move.y / ml;

      // Анимация ходьбы
      if (!player._walkAnimTimer) player._walkAnimTimer = 0;
      if (!player._walkFrame) player._walkFrame = 0;
      player._walkAnimTimer += dt;
      if (player._walkAnimTimer >= 0.25) {
        player._walkAnimTimer = 0;
        player._walkFrame = player._walkFrame === 0 ? 1 : 0;
      }

      // Трейл-частицы героя отключены (визуальный мусор).
      player.trailTimer = 0;
    } else {
      // Стоит — сброс анимации
      player._walkFrame = 0;
      player._walkAnimTimer = 0;
    }

    // Взаимодействие с рычагами по касанию
    if (window.GameMap && GameMap.tryToggleLever) {
      GameMap.tryToggleLever(player);
    }

    // Границы карты (динамические, учитывают размер сгенерированной карты)
    const half = player.size / 2;
    const mapW = (window.GameMap && GameMap.mapW) ? GameMap.mapW : CONFIG.MAP.W;
    const mapH = (window.GameMap && GameMap.mapH) ? GameMap.mapH : CONFIG.MAP.H;
    player.x = Utils.clamp(player.x, half, mapW - half);
    player.y = Utils.clamp(player.y, half, mapH - half);

    // Регенерация
    if (player.hpRegen > 0 && player.hp > 0) {
      player.hp = Math.min(player.maxHp, player.hp + player.hpRegen * dt);
    }

    // Шаг 19: тик i-frames (неуязвимость после получения урона)
    if (player._iFrameTimer && player._iFrameTimer > 0) {
      player._iFrameTimer -= dt;
    }

    // Шаг 15: снятие стартового XP-буста после 2 минут
    if (player._startXpBoostTimer && player._startXpBoostTimer > 0) {
      player._startXpBoostTimer -= dt;
      if (player._startXpBoostTimer <= 0) {
        player.xpBonusMul = (player.xpBonusMul || 1) / 1.20;
        player._startXpBoostTimer = 0;
      }
    }

    // Шаг 8: тик щита маны (кулдаун)
    if (player.manaShield && typeof player.manaShield.tick === 'function') {
      player.manaShield.tick(dt);
    }

    // Шаг 8: аура холода — замедление ближайших врагов
    if (player.frostAura && window.Game && Game.enemies) {
      const fa = player.frostAura;
      const r2 = fa.radius * fa.radius;
      const items = Game.enemies.items;
      for (let i = 0; i < items.length; i++) {
        const e = items[i];
        if (!e.active) continue;
        const dx = e.x - player.x, dy = e.y - player.y;
        if (dx * dx + dy * dy <= r2) {
          e.frostSlow = fa.slow; // будет использоваться в enemies.js при движении
          e.frostSlowTimer = 0.15; // перезаписывается каждый кадр, пока в ауре
        }
      }
    }

    // Встроенный Magic Missile
    player.missileCd = Math.max(0, player.missileCd - dt);
  },

  /** Отрисовка героя. ctx сдвинут на -cam. */
  render(ctx, player) {
    const ps = player.size;
    const t = Date.now() * 0.001; // время для анимаций

    // --- Аура холода: пульсирующее голубое кольцо с частицами ---
    if (player.frostAura) {
      const fa = player.frostAura;
      const pulse = 1 + Math.sin(t * 3) * 0.05;
      const r = fa.radius * pulse;
      // Градиентное заполнение
      ctx.save();
      const grad = ctx.createRadialGradient(player.x, player.y, r * 0.6, player.x, player.y, r);
      grad.addColorStop(0, 'rgba(100, 200, 255, 0)');
      grad.addColorStop(0.7, 'rgba(100, 200, 255, 0.06)');
      grad.addColorStop(1, 'rgba(80, 180, 255, 0.15)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(player.x, player.y, r, 0, Math.PI * 2);
      ctx.fill();
      // Внешнее кольцо (пульсирующее)
      ctx.globalAlpha = 0.35 + Math.sin(t * 4) * 0.1;
      ctx.strokeStyle = '#80d4ff';
      ctx.lineWidth = 1.5;
      ctx.stroke();
      // Ледяные искры на краю ауры
      ctx.globalAlpha = 0.5;
      ctx.fillStyle = '#aaeeff';
      for (let s = 0; s < 4; s++) {
        const a = t * 1.5 + s * Math.PI / 2;
        const sx = player.x + Math.cos(a) * r * 0.9;
        const sy = player.y + Math.sin(a) * r * 0.9;
        ctx.fillRect(sx - 1, sy - 1, 2, 2);
      }
      ctx.restore();
    }

    // --- Щит маны: энергетический пузырь с бликами ---
    if (player.manaShield && player.manaShield.shieldReady) {
      ctx.save();
      const shieldR = ps * 0.75;
      const pulse = 1 + Math.sin(t * 5) * 0.05;
      // Градиентный пузырь
      const sGrad = ctx.createRadialGradient(player.x, player.y, shieldR * 0.5, player.x, player.y, shieldR * pulse);
      sGrad.addColorStop(0, 'rgba(100, 200, 255, 0)');
      sGrad.addColorStop(0.8, 'rgba(100, 200, 255, 0.08)');
      sGrad.addColorStop(1, 'rgba(100, 200, 255, 0.2)');
      ctx.fillStyle = sGrad;
      ctx.beginPath();
      ctx.arc(player.x, player.y, shieldR * pulse, 0, Math.PI * 2);
      ctx.fill();
      // Кольцо
      ctx.globalAlpha = 0.4;
      ctx.strokeStyle = '#66ccff';
      ctx.lineWidth = 2;
      ctx.stroke();
      // Блик (перемещающийся огонёк)
      ctx.globalAlpha = 0.6;
      ctx.fillStyle = '#ffffff';
      const bx = player.x + Math.cos(t * 3) * shieldR * 0.6;
      const by = player.y + Math.sin(t * 3) * shieldR * 0.6;
      ctx.beginPath();
      ctx.arc(bx, by, 2, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    // Тень под игроком
    ctx.fillStyle = 'rgba(0,0,0,0.2)';
    ctx.beginPath();
    if (ctx.ellipse) {
      ctx.ellipse(player.x, player.y + ps * 0.4, ps * 0.35, ps * 0.1, 0, 0, Math.PI * 2);
    } else {
      ctx.arc(player.x, player.y + ps * 0.4, ps * 0.2, 0, Math.PI * 2);
    }
    ctx.fill();

    // Анимация ходьбы (2 кадра, управляется из update)
    const classId = player._classId || 'warrior';
    const walkSprites = window.PLAYER_WALK_SPRITES ? PLAYER_WALK_SPRITES[classId] : null;

    // Направление поворота: facing.x < 0 → смотрит влево (flipX)
    const flipX = player.facing.x < 0;

    if (walkSprites && walkSprites.length === 2) {
      const sprite = walkSprites[player._walkFrame];
      const drawSize = ps; // совпадает с размером игрока

      ctx.save();
      // Шаг 19: мерцание при i-frames (неуязвимость после удара)
      if (player._iFrameTimer && player._iFrameTimer > 0) {
        ctx.globalAlpha = 0.4 + Math.sin(player._iFrameTimer * 30) * 0.3;
      }
      ctx.imageSmoothingEnabled = false;

      if (flipX) {
        ctx.translate(player.x, player.y);
        ctx.scale(-1, 1);
        ctx.drawImage(sprite, -drawSize / 2, -drawSize / 2, drawSize, drawSize);
      } else {
        ctx.drawImage(sprite, player.x - drawSize / 2, player.y - drawSize / 2, drawSize, drawSize);
      }
      ctx.restore();
    } else {
      // Fallback: старый рендер (цветной квадрат с буквой)
      const classColor = player._classColor || '#2980d9';
      const classLetter = player._classLetter || 'K';
      ctx.fillStyle = classColor;
      if (player._iFrameTimer && player._iFrameTimer > 0) {
        ctx.globalAlpha = 0.4 + Math.sin(player._iFrameTimer * 30) * 0.3;
      }
      ctx.fillRect(player.x - ps / 2, player.y - ps / 2, ps, ps);
      ctx.globalAlpha = 1;
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 2;
      ctx.strokeRect(player.x - ps / 2 + 1, player.y - ps / 2 + 1, ps - 2, ps - 2);
      ctx.fillStyle = '#ffffff';
      ctx.font = 'bold 18px ui-monospace, monospace';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(classLetter, player.x, player.y + 1);
    }

    // Радиус подбора (мягкое пульсирующее свечение)
    const pickupR = CONFIG.PLAYER.PICKUP_RADIUS * player.pickupMul;
    const pickupAlpha = 0.04 + Math.sin(t * 2) * 0.02;
    ctx.strokeStyle = `rgba(255,255,200,${pickupAlpha})`;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(player.x, player.y, pickupR, 0, Math.PI * 2);
    ctx.stroke();
  },
};

window.Player = Player;

// === js/ui/hud.js ===
'use strict';
/* ============================================================
   ui.js — HUD, слоты, оверлеи (меню/пауза/левелап/смерть).
   ============================================================ */

const UI = {
  // Бары / счётчики
  hpFill: null, hpLabel: null,
  xpFill: null, xpLabel: null,
  cdMissileFill: null,
  killCount: null, runTimer: null, waveInfo: null,

  // Оверлеи
  menuOverlay: null, pauseOverlay: null, levelOverlay: null, gameOverOverlay: null,
  cardsEl: null, lvlNum: null,
  goTime: null, goKills: null, goLevel: null,

  // Шаг 3: оверлей сундука (создаётся динамически)
  chestOverlay: null,
  d20DieEl: null,
  chestPanelEl: null,         // контейнер для текущего "экрана" внутри overlay

  // Слоты
  weaponSlotEls: [],
  abilitySlotEls: [],

  init() {
    this.hpFill = document.querySelector('#hpBar .fill');
    this.hpLabel = document.querySelector('#hpBar .label');
    this.xpFill = document.querySelector('#xpBar .fill');
    this.xpLabel = document.querySelector('#xpBar .label');
    this.cdMissileFill = document.querySelector('#cdMissile .cd-fill');
    this.killCount = document.getElementById('killCount');
    this.runTimer  = document.getElementById('runTimer');
    this.waveInfo  = document.getElementById('waveInfo');

    this.menuOverlay     = document.getElementById('menuOverlay');
    this.pauseOverlay    = document.getElementById('pauseOverlay');
    this.levelOverlay    = document.getElementById('levelOverlay');
    this.gameOverOverlay = document.getElementById('gameOverOverlay');
    this.cardsEl = document.getElementById('cards');
    this.lvlNum  = document.getElementById('lvlNum');
    this.goTime  = document.getElementById('goTime');
    this.goKills = document.getElementById('goKills');
    this.goLevel = document.getElementById('goLevel');

    // Создать ячейки слотов
    this._buildSlotColumns();

    // Создать оверлей сундука (динамически, чтобы не трогать index.html)
    this._buildChestOverlay();
  },

  /** Сбор оверлея сундука: контейнер + общая 'панель', обновляемая под этап. */
  _buildChestOverlay() {
    const ov = document.createElement('div');
    ov.id = 'chestOverlay';
    ov.className = 'overlay';
    ov.innerHTML =
      '<div id="chestPanel" class="chest-panel"></div>';
    document.body.appendChild(ov);
    this.chestOverlay = ov;
    this.chestPanelEl = ov.querySelector('#chestPanel');
  },

  _buildSlotColumns() {
    const left  = document.getElementById('weaponSlots');
    const right = document.getElementById('abilitySlots');
    left.innerHTML = '';
    right.innerHTML = '';
    this.weaponSlotEls.length = 0;
    this.abilitySlotEls.length = 0;
    for (let i = 0; i < CONFIG.PLAYER.SLOTS_WEAPONS; i++) {
      const el = document.createElement('div');
      el.className = 'slot';
      el.innerHTML =
        '<div class="slot-cd"></div>' +
        '<div class="slot-icon"></div>' +
        '<div class="slot-level"></div>';
      left.appendChild(el);
      this.weaponSlotEls.push(el);
    }
    for (let i = 0; i < CONFIG.PLAYER.SLOTS_ABILITIES; i++) {
      const el = document.createElement('div');
      el.className = 'slot';
      el.innerHTML =
        '<div class="slot-cd"></div>' +
        '<div class="slot-icon"></div>' +
        '<div class="slot-level"></div>';
      right.appendChild(el);
      this.abilitySlotEls.push(el);
    }
  },

  hideAll() {
    this.menuOverlay.classList.remove('active');
    this.pauseOverlay.classList.remove('active');
    this.levelOverlay.classList.remove('active');
    this.gameOverOverlay.classList.remove('active');
    if (this.chestOverlay) this.chestOverlay.classList.remove('active');
    if (this._campOverlay) this._campOverlay.classList.remove('active');
    if (this._talentOverlay) this._talentOverlay.classList.remove('active');
    if (this._guildOverlay) this._guildOverlay.classList.remove('active');
    if (this._resultsOverlay) this._resultsOverlay.classList.remove('active');
    if (this._dialogueOverlay) this._dialogueOverlay.classList.remove('active');
    if (this._victoryOverlay) this._victoryOverlay.classList.remove('active');
    if (this._settingsOverlay) this._settingsOverlay.classList.remove('active');
    if (this._mapSelectOverlay) this._mapSelectOverlay.classList.remove('active');
    // Расширенные оверлеи
    const extIds = ['classOverlay', 'bestiaryOverlay', 'codexOverlay', 'runStatsOverlay'];
    for (const id of extIds) {
      const el = document.getElementById(id);
      if (el) el.classList.remove('active');
    }
  },

  showPause() { this.hideAll(); this.pauseOverlay.classList.add('active'); },
  showMenu()  { this.hideAll(); this.menuOverlay.classList.add('active'); },
  showGameOver(stats) {
    this.hideAll();
    this.goTime.textContent  = stats.time;
    this.goKills.textContent = stats.kills;
    this.goLevel.textContent = stats.level;
    this.gameOverOverlay.classList.add('active');
  },

  /**
   * Показать карты левелапа.
   * @param {number} level — текущий уровень (для заголовка).
   * @param {Array} choices — массив "карт" из main.js (см. buildLevelUpChoices).
   * @param {function} onPick — колбэк выбора (передаётся выбранная карта).
   */
  showLevelUp(level, choices, onPick) {
    this.hideAll();
    this.lvlNum.textContent = level;
    this.cardsEl.innerHTML = '';
    if (choices.length === 0) {
      // На случай форс-мажора — кнопка "Продолжить"
      const el = document.createElement('div');
      el.className = 'card basic';
      el.innerHTML = '<div class="card-icon">★</div><div class="card-title">' + t('levelup_continue') + '</div><div class="card-desc">' + t('levelup_all_max') + '</div>';
      el.addEventListener('click', () => onPick(null));
      this.cardsEl.appendChild(el);
    } else {
      choices.forEach((c) => {
        const el = document.createElement('div');
        el.className = 'card ' + (c.kind || 'basic');
        // Build card content
        let levelHtml = '';
        if (c.kind === 'weapon' || c.kind === 'ability') {
          // Show level dots if it's an upgrade card
          const isUpgrade = c.title && c.title.includes('→');
          if (isUpgrade) {
            levelHtml = '<div class="card-level-indicator">▲</div>';
          } else {
            levelHtml = '<div class="card-level-indicator card-new">' + t('levelup_new') + '</div>';
          }
        }
        el.innerHTML =
          `<div class="card-icon">${c.icon || '★'}</div>` +
          levelHtml +
          `<div class="card-title">${c.title}</div>` +
          `<div class="card-desc">${c.desc}</div>`;
        // Шаг 2: пиксельный спрайт в карте левелапа
        const cardIconEl = el.querySelector('.card-icon');
        const spriteId = c.weaponId || c.abilityId || c.resultId || c.id;
        const WS = window.WEAPON_SPRITES;
        const AS = window.ABILITY_SPRITES;
        const ES = window.EVOLUTION_SPRITES;
        const spr = (ES && ES[spriteId]) || (WS && WS[spriteId]) || (AS && AS[spriteId]);
        if (spr && cardIconEl) {
          cardIconEl.textContent = '';
          cardIconEl.style.backgroundImage = 'url(' + spr.toDataURL() + ')';
          cardIconEl.style.backgroundSize = 'contain';
          cardIconEl.style.backgroundRepeat = 'no-repeat';
          cardIconEl.style.backgroundPosition = 'center';
          cardIconEl.style.imageRendering = 'pixelated';
        }
        el.addEventListener('click', () => onPick(c));
        this.cardsEl.appendChild(el);
      });
    }
    this.levelOverlay.classList.add('active');
  },

  /** Покадровое обновление HUD. */
  tick(game) {
    if (!game.player) return;
    const p = game.player;

    // HP
    const hpPct = Utils.clamp(p.hp / p.maxHp, 0, 1);
    this.hpFill.style.width = (hpPct * 100) + '%';
    this.hpLabel.textContent = t('hud_hp', Math.ceil(p.hp), Math.ceil(p.maxHp));

    // XP
    const xpPct = Utils.clamp(p.xp / p.xpNext, 0, 1);
    this.xpFill.style.width = (xpPct * 100) + '%';
    this.xpLabel.textContent = t('hud_level', p.level || 1);

    // Magic Missile cd (встроенная способность) — только если не отключена
    if (p._noBuiltInMissile) {
      this.cdMissileFill.style.height = '0%';
      this.cdMissileFill.parentElement.style.display = 'none';
    } else {
      this.cdMissileFill.parentElement.style.display = '';
      const missTotal = CONFIG.MISSILE.COOLDOWN * p.missileCdMul;
      const missReady = 1 - (p.missileCd / Math.max(0.0001, missTotal));
      this.cdMissileFill.style.height = (Utils.clamp(missReady, 0, 1) * 100) + '%';
    }

    // Слоты
    for (let i = 0; i < this.weaponSlotEls.length; i++) {
      this._renderWeaponSlot(this.weaponSlotEls[i], p.weaponSlots[i], p);
    }
    for (let i = 0; i < this.abilitySlotEls.length; i++) {
      this._renderAbilitySlot(this.abilitySlotEls[i], p.abilitySlots[i]);
    }

    // Счётчики
    this.killCount.textContent = t('hud_kills', game.kills);
    this.runTimer.textContent  = Utils.formatTime(game.runTime);

    // Шаг 15: золото в HUD
    this._updateGoldHUD(game);
    // Шаг 16: цель кампании в HUD
    this._updateCampaignObjectiveHUD(game);
    if (game.state === 'playing' || game.state === 'paused' || game.state === 'levelup') {
      const next = Math.max(0, Math.ceil(game.waveTimer));
      this.waveInfo.textContent = t('hud_wave', game.waveIndex + 1, next);
      // Шаг 6: информация о боссе (Шаг 14: поддержка обоих боссов)
      if (window.Bosses && Bosses.isAlive()) {
        this.waveInfo.textContent = t('hud_boss');
      } else if (window.Bosses && !Bosses.current && Bosses.bossIndex < BOSS_CONFIG.SPAWN_TIMES.length) {
        const bossIn = Math.max(0, Math.ceil(Bosses.nextSpawnTime - game.runTime));
        if (bossIn <= 30) {
          this.waveInfo.textContent += ` | ${t('hud_boss_in', bossIn)}`;
        }
      }
      // Шаг 13: информация о портале
      if (game.portalSpawned && window.GameMap && GameMap.portal && GameMap.portal.active) {
        this.waveInfo.textContent = t('hud_portal_open');
      } else if (window.PORTAL_CONFIG && game.mapTime != null) {
        const portalIn = Math.max(0, Math.ceil(PORTAL_CONFIG.APPEAR_TIME - game.mapTime));
        if (portalIn <= 60 && portalIn > 0) {
          this.waveInfo.textContent += ` | ${t('hud_portal_in', portalIn)}`;
        }
      }
    }
  },

  _renderWeaponSlot(el, weapon, player) {
    const iconEl = el.children[1];
    const levelEl = el.children[2];
    const cdEl   = el.children[0];
    if (!weapon) {
      el.classList.remove('filled', 'exclusive-slot', 'super-evolved-slot');
      iconEl.textContent = '';
      iconEl.style.backgroundImage = '';
      levelEl.textContent = '';
      cdEl.style.height = '0%';
      return;
    }
    el.classList.add('filled');
    // Exclusive/Super-evolved visual
    if (weapon.isSuperEvolved) { el.classList.add('super-evolved-slot'); el.classList.remove('exclusive-slot'); }
    else if (weapon.isExclusive) { el.classList.add('exclusive-slot'); el.classList.remove('super-evolved-slot'); }
    else { el.classList.remove('exclusive-slot', 'super-evolved-slot'); }

    // Шаг 2: пиксельный спрайт оружия вместо эмодзи
    const WS = window.WEAPON_SPRITES;
    const ES = window.EVOLUTION_SPRITES;
    const sprite = (ES && ES[weapon.id]) || (WS && WS[weapon.id]);
    if (sprite && !iconEl._spriteSet) {
      iconEl.textContent = '';
      iconEl.style.backgroundImage = 'url(' + sprite.toDataURL() + ')';
      iconEl.style.backgroundSize = 'contain';
      iconEl.style.backgroundRepeat = 'no-repeat';
      iconEl.style.backgroundPosition = 'center';
      iconEl.style.imageRendering = 'pixelated';
      iconEl._spriteSet = weapon.id;
    } else if (!sprite) {
      iconEl.style.backgroundImage = '';
      iconEl.textContent = weapon.icon || '?';
      iconEl._spriteSet = null;
    } else if (iconEl._spriteSet !== weapon.id) {
      // Weapon changed (evolution) — update sprite
      iconEl.textContent = '';
      const newSprite = (ES && ES[weapon.id]) || (WS && WS[weapon.id]);
      if (newSprite) {
        iconEl.style.backgroundImage = 'url(' + newSprite.toDataURL() + ')';
        iconEl.style.imageRendering = 'pixelated';
        iconEl._spriteSet = weapon.id;
      } else {
        iconEl.style.backgroundImage = '';
        iconEl.textContent = weapon.icon || '?';
        iconEl._spriteSet = null;
      }
    }

    levelEl.textContent = Utils.roman(weapon.level);
    // CD-заполнение: растёт от 0% до 100% по мере готовности
    const ready = weapon.readyProgress ? weapon.readyProgress(player) : 1;
    cdEl.style.height = (Utils.clamp(ready, 0, 1) * 100) + '%';
  },

  _renderAbilitySlot(el, ability) {
    const iconEl = el.children[1];
    const levelEl = el.children[2];
    const cdEl   = el.children[0];
    if (!ability) {
      el.classList.remove('filled');
      el.classList.remove('slot-flash');
      iconEl.textContent = '';
      iconEl.style.backgroundImage = '';
      iconEl._spriteSet = null;
      levelEl.textContent = '';
      cdEl.style.height = '0%';
      return;
    }
    el.classList.add('filled');

    // Шаг 2: пиксельный спрайт пассивки вместо эмодзи
    const AS = window.ABILITY_SPRITES;
    const sprite = AS ? AS[ability.id] : null;
    if (sprite && !iconEl._spriteSet) {
      iconEl.textContent = '';
      iconEl.style.backgroundImage = 'url(' + sprite.toDataURL() + ')';
      iconEl.style.backgroundSize = 'contain';
      iconEl.style.backgroundRepeat = 'no-repeat';
      iconEl.style.backgroundPosition = 'center';
      iconEl.style.imageRendering = 'pixelated';
      iconEl._spriteSet = ability.id;
    } else if (!sprite) {
      iconEl.style.backgroundImage = '';
      iconEl.textContent = ability.icon || '?';
      iconEl._spriteSet = null;
    } else if (iconEl._spriteSet !== ability.id) {
      iconEl.textContent = '';
      iconEl.style.backgroundImage = 'url(' + sprite.toDataURL() + ')';
      iconEl.style.imageRendering = 'pixelated';
      iconEl._spriteSet = ability.id;
    }

    levelEl.textContent = Utils.roman(ability.level);
    cdEl.style.height = '100%'; // пассивки всегда "активны"

    // Шаг 8: вспышка при повышении уровня (200 мс белая обводка)
    if (ability._flashUntil && ability._flashUntil > performance.now()) {
      el.classList.add('slot-flash');
    } else {
      el.classList.remove('slot-flash');
    }
  },

  /* ============================================================
     Шаг 3: окна сундука — d20-бросок, награда, эволюция.
     ============================================================ */

  /**
   * Анимированный бросок d20.
   * Показывает быстро меняющиеся цифры 1..20, затем фиксирует финальную
   * (анимация ~1.0–1.3 с). По завершении — onDone(finalRoll).
   */
  showD20Roll(finalRoll, onDone) {
    this.hideAll();
    this.chestPanelEl.innerHTML =
      '<div class="d20-title">' + t('chest_title') + '</div>' +
      '<div class="d20-sub">' + t('chest_rolling') + '</div>' +
      '<div id="d20Die" class="d20-die">?</div>';
    this.chestOverlay.classList.add('active');
    const dieEl = this.chestPanelEl.querySelector('#d20Die');

    // Стадия 1: быстрая прокрутка (≈0.7 с, ~14 смен)
    let elapsed = 0;
    const rollDuration = 0.7;
    const tickStart = performance.now();
    const tick = () => {
      const now = performance.now();
      elapsed = (now - tickStart) / 1000;
      if (elapsed < rollDuration) {
        dieEl.textContent = String(1 + Math.floor(Math.random() * 20));
        // ускоряющееся затухание интервала
        const interval = 30 + (elapsed / rollDuration) * 90;
        setTimeout(tick, interval);
      } else {
        // Стадия 2: финал
        dieEl.textContent = String(finalRoll);
        dieEl.classList.add('final');
        // Цвет в зависимости от диапазона
        if (finalRoll >= 19)      dieEl.classList.add('crit');
        else if (finalRoll >= 11) dieEl.classList.add('good');
        else                       dieEl.classList.add('low');
        // Пауза, затем callback
        setTimeout(() => onDone && onDone(finalRoll), 700);
      }
    };
    tick();
  },

  /**
   * Окно с описанием результата (для бросков 1..10, либо когда вместо
   * эволюции выпала "разовая" награда). reward = { title, desc, kind }.
   * Кнопка "Забрать" закрывает окно.
   */
  showChestReward(roll, reward, onAccept) {
    this.hideAll();
    this.chestPanelEl.innerHTML =
      `<div class="d20-title">${reward.title || t('chest_reward_title')}</div>` +
      `<div class="d20-sub">${t('chest_roll_label')} <span class="d20-mini ${this._rollClass(roll)}">${roll}</span></div>` +
      `<div class="reward-desc">${reward.desc || ''}</div>` +
      '<button id="chestOk" class="btn">' + t('chest_accept') + '</button>';
    this.chestOverlay.classList.add('active');
    this.chestPanelEl.querySelector('#chestOk').addEventListener('click', () => {
      this.hideAll();
      onAccept && onAccept();
    });
  },

  /**
   * Окно "карточка-выбор" (как левелап, но без увеличения уровня).
   * Используется для бросков 11..18.
   */
  showChestPick(roll, choices, onPick) {
    this.hideAll();
    let html =
      '<div class="d20-title">' + t('chest_upgrade_title') + '</div>' +
      `<div class="d20-sub">${t('chest_roll_label')} <span class="d20-mini ${this._rollClass(roll)}">${roll}</span> ${t('chest_pick_sub')}</div>` +
      '<div id="chestCards" class="cards-row"></div>';
    this.chestPanelEl.innerHTML = html;
    const row = this.chestPanelEl.querySelector('#chestCards');
    if (!choices || choices.length === 0) {
      const el = document.createElement('div');
      el.className = 'card basic';
      el.innerHTML = '<div class="card-icon">★</div><div class="card-title">' + t('levelup_continue') + '</div><div class="card-desc">' + t('chest_no_upgrades') + '</div>';
      el.addEventListener('click', () => { this.hideAll(); onPick && onPick(null); });
      row.appendChild(el);
    } else {
      choices.forEach((c) => {
        const el = document.createElement('div');
        el.className = 'card ' + (c.kind || 'basic');
        el.innerHTML =
          `<div class="card-icon">${c.icon || '★'}</div>` +
          `<div class="card-title">${c.title}</div>` +
          `<div class="card-desc">${c.desc}</div>`;
        // Применяем пиксельный спрайт (как в showLevelUp)
        const cardIconEl = el.querySelector('.card-icon');
        const spriteId = c.weaponId || c.abilityId || c.resultId || c.id;
        const WS = window.WEAPON_SPRITES;
        const AS = window.ABILITY_SPRITES;
        const ES = window.EVOLUTION_SPRITES;
        const spr = (ES && ES[spriteId]) || (WS && WS[spriteId]) || (AS && AS[spriteId]);
        if (spr && cardIconEl) {
          cardIconEl.textContent = '';
          cardIconEl.style.backgroundImage = 'url(' + spr.toDataURL() + ')';
          cardIconEl.style.backgroundSize = 'contain';
          cardIconEl.style.backgroundRepeat = 'no-repeat';
          cardIconEl.style.backgroundPosition = 'center';
          cardIconEl.style.imageRendering = 'pixelated';
        }
        el.addEventListener('click', () => { this.hideAll(); onPick && onPick(c); });
        row.appendChild(el);
      });
    }
    this.chestOverlay.classList.add('active');
  },

  /**
   * Окно эволюции: оружие + пассивка → результат.
   * onChoice(true) — принять, onChoice(false) — отказаться.
   */
  showEvolutionDialog(roll, pair, onChoice) {
    this.hideAll();
    const w = pair.weapon, a = pair.ability, r = pair.recipe;
    this.chestPanelEl.innerHTML =
      '<div class="d20-title">' + t('chest_evo_title') + '</div>' +
      `<div class="d20-sub">${t('chest_roll_label')} <span class="d20-mini crit">${roll}</span></div>` +
      '<div class="evo-row">' +
        `<div class="evo-card"><div class="evo-icon" data-sprite-id="${w.id}">${w.icon}</div><div class="evo-name">${w.name}</div><div class="evo-lvl">ур. ${Utils.roman(w.level)}</div></div>` +
        '<div class="evo-plus">+</div>' +
        `<div class="evo-card"><div class="evo-icon" data-sprite-id="${a.id}">${a.icon}</div><div class="evo-name">${a.name}</div><div class="evo-lvl">ур. ${Utils.roman(a.level)}</div></div>` +
        '<div class="evo-arrow">→</div>' +
        `<div class="evo-card evo-result"><div class="evo-icon" data-sprite-id="${r.resultId || ''}">${r.resultIcon}</div><div class="evo-name">${r.resultName}</div><div class="evo-desc">${r.desc}</div></div>` +
      '</div>' +
      '<div class="evo-buttons">' +
        '<button id="evoAccept" class="btn">' + t('chest_evo_accept') + '</button>' +
        '<button id="evoDecline" class="btn btn-secondary">' + t('chest_evo_decline') + '</button>' +
      '</div>';
    // Применяем спрайты к иконкам эволюции
    const evoIcons = this.chestPanelEl.querySelectorAll('.evo-icon[data-sprite-id]');
    for (const iconEl of evoIcons) {
      const spriteId = iconEl.getAttribute('data-sprite-id');
      if (!spriteId) continue;
      const WS = window.WEAPON_SPRITES;
      const AS = window.ABILITY_SPRITES;
      const ES = window.EVOLUTION_SPRITES;
      const spr = (ES && ES[spriteId]) || (WS && WS[spriteId]) || (AS && AS[spriteId]);
      if (spr) {
        iconEl.textContent = '';
        iconEl.style.backgroundImage = 'url(' + spr.toDataURL() + ')';
        iconEl.style.backgroundSize = 'contain';
        iconEl.style.backgroundRepeat = 'no-repeat';
        iconEl.style.backgroundPosition = 'center';
        iconEl.style.imageRendering = 'pixelated';
        iconEl.style.width = '32px';
        iconEl.style.height = '32px';
      }
    }
    this.chestOverlay.classList.add('active');
    this.chestPanelEl.querySelector('#evoAccept').addEventListener('click', () => {
      this.hideAll();
      onChoice && onChoice(true);
    });
    this.chestPanelEl.querySelector('#evoDecline').addEventListener('click', () => {
      this.hideAll();
      onChoice && onChoice(false);
    });
  },

  /**
   * Окно выбора из нескольких доступных эволюций.
   * Прокручиваемый список. Игрок выбирает одну.
   */
  showEvolutionChoice(roll, readyList, onChoice) {
    this.hideAll();
    let html =
      '<div class="d20-title">' + t('chest_evo_title') + '</div>' +
      `<div class="d20-sub">${t('chest_roll_label')} <span class="d20-mini crit">${roll}</span> ${t('chest_evo_choose')}</div>` +
      '<div id="evoChoiceList" class="evo-choice-list">';
    for (let i = 0; i < readyList.length; i++) {
      const p = readyList[i];
      const w = p.weapon, a = p.ability, r = p.recipe;
      html += `<div class="evo-choice-item" data-idx="${i}">` +
        `<span class="evo-choice-icon" data-sprite-id="${w.id}">${w.icon}</span>` +
        `<span class="evo-choice-plus">+</span>` +
        `<span class="evo-choice-icon" data-sprite-id="${a.id}">${a.icon}</span>` +
        `<span class="evo-choice-arrow">→</span>` +
        `<span class="evo-choice-result-icon" data-sprite-id="${r.resultId}">${r.resultIcon}</span>` +
        `<span class="evo-choice-name">${r.resultName}</span>` +
        `<span class="evo-choice-desc">${r.desc}</span>` +
      '</div>';
    }
    html += '</div>' +
      '<div class="evo-buttons">' +
        '<button id="evoDeclineAll" class="btn btn-secondary">' + t('chest_evo_decline') + '</button>' +
      '</div>';
    this.chestPanelEl.innerHTML = html;
    this.chestOverlay.classList.add('active');

    // Apply sprites to evolution choice icons
    this._applySpriteIcons(this.chestPanelEl);

    // Event listeners
    const list = this.chestPanelEl.querySelector('#evoChoiceList');
    list.addEventListener('click', (e) => {
      const item = e.target.closest('.evo-choice-item');
      if (!item) return;
      const idx = parseInt(item.dataset.idx);
      if (idx >= 0 && idx < readyList.length) {
        this.hideAll();
        onChoice && onChoice(readyList[idx]);
      }
    });
    this.chestPanelEl.querySelector('#evoDeclineAll').addEventListener('click', () => {
      this.hideAll();
      onChoice && onChoice(null);
    });
  },

  /**
   * Окно супер-эволюции: золотая рамка, особое оформление.
   */
  showSuperEvolutionDialog(roll, superReadyList, onChoice) {
    this.hideAll();
    let html =
      '<div class="d20-title super-evo-title">' + t('chest_super_evo_title') + '</div>' +
      `<div class="d20-sub">${t('chest_roll_label')} <span class="d20-mini crit">${roll}</span></div>` +
      '<div id="superEvoList" class="evo-choice-list super-evo-list">';
    for (let i = 0; i < superReadyList.length; i++) {
      const s = superReadyList[i];
      const excl = s.exclusive, evolved = s.evolved, r = s.recipe;
      html += `<div class="evo-choice-item super-evo-item" data-idx="${i}">` +
        `<span class="evo-choice-icon" data-sprite-id="${excl.id}">${excl.icon}</span>` +
        `<span class="evo-choice-plus">+</span>` +
        `<span class="evo-choice-icon" data-sprite-id="${evolved.id}">${evolved.icon}</span>` +
        `<span class="evo-choice-arrow">→</span>` +
        `<span class="evo-choice-result-icon" data-sprite-id="${r.resultId}">${r.resultIcon}</span>` +
        `<span class="evo-choice-name">${r.resultName}</span>` +
        `<span class="evo-choice-desc">${r.desc}</span>` +
      '</div>';
    }
    html += '</div>' +
      '<div class="evo-buttons">' +
        '<button id="superEvoDecline" class="btn btn-secondary">' + t('chest_evo_decline') + '</button>' +
      '</div>';
    this.chestPanelEl.innerHTML = html;
    this.chestOverlay.classList.add('active');

    // Apply sprites to super-evolution choice icons
    this._applySpriteIcons(this.chestPanelEl);

    const list = this.chestPanelEl.querySelector('#superEvoList');
    list.addEventListener('click', (e) => {
      const item = e.target.closest('.super-evo-item');
      if (!item) return;
      const idx = parseInt(item.dataset.idx);
      if (idx >= 0 && idx < superReadyList.length) {
        this.hideAll();
        onChoice && onChoice(superReadyList[idx]);
      }
    });
    this.chestPanelEl.querySelector('#superEvoDecline').addEventListener('click', () => {
      this.hideAll();
      onChoice && onChoice(null);
    });
  },

  _rollClass(roll) {
    if (roll >= 19) return 'crit';
    if (roll >= 11) return 'good';
    return 'low';
  },

  /** Apply pixel sprites to all elements with data-sprite-id within a container. */
  _applySpriteIcons(container) {
    const icons = container.querySelectorAll('[data-sprite-id]');
    for (const iconEl of icons) {
      const spriteId = iconEl.getAttribute('data-sprite-id');
      if (!spriteId) continue;
      const WS = window.WEAPON_SPRITES;
      const AS = window.ABILITY_SPRITES;
      const ES = window.EVOLUTION_SPRITES;
      const spr = (ES && ES[spriteId]) || (WS && WS[spriteId]) || (AS && AS[spriteId]);
      if (spr) {
        iconEl.textContent = '';
        iconEl.style.backgroundImage = 'url(' + spr.toDataURL() + ')';
        iconEl.style.backgroundSize = 'contain';
        iconEl.style.backgroundRepeat = 'no-repeat';
        iconEl.style.backgroundPosition = 'center';
        iconEl.style.imageRendering = 'pixelated';
        iconEl.style.display = 'inline-block';
        iconEl.style.minWidth = '24px';
        iconEl.style.minHeight = '24px';
      }
    }
  },

  /* ============================================================
     Шаг 15: Золото в HUD (отображение во время забега)
     ============================================================ */

  /** Обновить золото в HUD (вызывается из tick). */
  _updateGoldHUD(game) {
    if (!this._goldHudEl) {
      // Создать элемент при первом вызове
      const el = document.createElement('div');
      el.id = 'goldHud';
      el.className = 'gold-hud';
      el.innerHTML = '<span class="gold-icon">🪙</span><span class="gold-value">0</span>';
      const topLeft = document.querySelector('.hud-top-left');
      if (topLeft) topLeft.appendChild(el);
      this._goldHudEl = el;
      this._goldValueEl = el.querySelector('.gold-value');
    }
    const gold = game.runGold || 0;
    this._goldValueEl.textContent = gold;
  },

  /* ============================================================
     Шаг 15: Лагерь / Таверна (Camp screen)
     ============================================================ */

  showCamp() {
    this.hideAll();
    if (!this._campOverlay) this._buildCampOverlay();
    this._updateCampData();
    this._campOverlay.classList.add('active');
  },

  _buildCampOverlay() {
    const ov = document.createElement('div');
    ov.id = 'campOverlay';
    ov.className = 'overlay camp-overlay';
    ov.innerHTML = `
      <div class="camp-bg">
        <h1 class="camp-title">${t('camp_title')}</h1>
        <div class="camp-tavern-name">${t('camp_tavern')}</div>
        <div class="camp-resources">
          <div class="camp-gold"><span class="gold-icon">🪙</span> <span id="campGoldVal">0</span></div>
          <div class="camp-rep"><span class="rep-icon">⚜</span> <span id="campRepVal">0</span> <span id="campGuildLvl">(${t('level_short')} 0)</span></div>
        </div>
        <div class="camp-buttons">
          <button id="campStartBtn" class="btn camp-btn camp-btn-main">${t('camp_start')}</button>
          <button id="campCampaignBtn" class="btn camp-btn camp-btn-campaign">${t('camp_campaign')}</button>
          <button id="campHeroBtn" class="btn camp-btn">${t('camp_hero')}</button>
          <button id="campTalentsBtn" class="btn camp-btn">${t('camp_talents')}</button>
          <button id="campGuildBtn" class="btn camp-btn">${t('camp_guild')}</button>
          <button id="campBestiaryBtn" class="btn camp-btn">${t('camp_bestiary')}</button>
          <button id="campCodexBtn" class="btn camp-btn">${t('camp_codex')}</button>
          <button id="campSettingsBtn" class="btn camp-btn">${t('camp_settings')}</button>
        </div>
        <div class="camp-stats">
          <div>${t('camp_runs', '<span id="campTotalRuns">0</span>')}</div>
          <div>${t('camp_total_kills', '<span id="campTotalKills">0</span>')}</div>
          <div>${t('camp_best_time', '<span id="campBestTime">00:00</span>')}</div>
        </div>
      </div>
    `;
    document.body.appendChild(ov);
    this._campOverlay = ov;

    // Bindings
    ov.querySelector('#campStartBtn').addEventListener('click', () => {
      this.hideCamp();
      this.showMapSelect();
    });
    ov.querySelector('#campCampaignBtn').addEventListener('click', () => {
      this.hideCamp();
      if (window.Campaign) Campaign.start();
    });
    ov.querySelector('#campTalentsBtn').addEventListener('click', () => {
      this.hideCamp();
      this.showTalents();
    });
    ov.querySelector('#campGuildBtn').addEventListener('click', () => {
      this.hideCamp();
      this.showGuild();
    });
    ov.querySelector('#campSettingsBtn').addEventListener('click', () => {
      this.hideCamp();
      this.showSettings();
    });
    // Новые кнопки: Выбор героя, Бестиарий, Книга
    ov.querySelector('#campHeroBtn').addEventListener('click', () => {
      this.hideCamp();
      if (window.UIExtended) UIExtended.showClassSelect(() => this.showCamp());
    });
    ov.querySelector('#campBestiaryBtn').addEventListener('click', () => {
      this.hideCamp();
      if (window.UIExtended) UIExtended.showBestiary(() => this.showCamp());
    });
    ov.querySelector('#campCodexBtn').addEventListener('click', () => {
      this.hideCamp();
      if (window.UIExtended) UIExtended.showCodex(() => this.showCamp());
    });
  },

  _updateCampData() {
    if (!window.MetaProgress || !MetaProgress.data) return;
    const d = MetaProgress.data;
    const ov = this._campOverlay;
    ov.querySelector('#campGoldVal').textContent = d.gold;
    ov.querySelector('#campRepVal').textContent = d.reputation;
    ov.querySelector('#campGuildLvl').textContent = `(${t('level_short')} ${MetaProgress.getGuildLevel()})`;
    ov.querySelector('#campTotalRuns').textContent = d.totalRuns;
    ov.querySelector('#campTotalKills').textContent = d.totalKills;
    ov.querySelector('#campBestTime').textContent = Utils.formatTime(d.bestTime);

    // Шаг 16: обновить кнопку кампании
    const campBtn = ov.querySelector('#campCampaignBtn');
    if (campBtn && window.Campaign) {
      const progress = Campaign.loadProgress();
      if (progress.completed) {
        campBtn.textContent = t('camp_campaign_plus');
      } else if (progress.currentMap > 1) {
        campBtn.textContent = t('camp_campaign_map', progress.currentMap);
      } else {
        campBtn.textContent = t('camp_campaign');
      }
    }
  },

  hideCamp() {
    if (this._campOverlay) this._campOverlay.classList.remove('active');
  },

  /* ============================================================
     Шаг 5 (новый): Экран выбора карты (биома)
     ============================================================ */

  _mapSelectOverlay: null,

  showMapSelect() {
    this.hideAll();
    if (!this._mapSelectOverlay) this._buildMapSelectOverlay();
    this._updateMapSelectHighlight();
    this._mapSelectOverlay.classList.add('active');
  },

  hideMapSelect() {
    if (this._mapSelectOverlay) this._mapSelectOverlay.classList.remove('active');
  },

  _buildMapSelectOverlay() {
    // Инициализируем превью если ещё не созданы
    if (window.initBiomePreviews && (!window.BIOME_PREVIEWS || Object.keys(BIOME_PREVIEWS).length === 0)) {
      initBiomePreviews();
    }

    const ov = document.createElement('div');
    ov.id = 'mapSelectOverlay';
    ov.className = 'overlay camp-overlay';

    // Описания биомов
    const BIOME_DESCRIPTIONS = {
      crypt: t('biome_desc_crypt'),
      ice_caves: t('biome_desc_ice_caves'),
      fire_mines: t('biome_desc_fire_mines'),
      forest_ruins: t('biome_desc_forest_ruins'),
      castle: t('biome_desc_castle'),
      sky_citadel: t('biome_desc_sky_citadel'),
      elven_forest: t('biome_desc_elven_forest'),
      mountain_keep: t('biome_desc_mountain_keep'),
    };

    // Сложность биомов (1–3 черепа)
    const BIOME_DIFFICULTY = {
      crypt: 1,
      ice_caves: 1,
      forest_ruins: 1,
      fire_mines: 2,
      castle: 2,
      elven_forest: 2,
      mountain_keep: 3,
      sky_citadel: 3,
    };

    let cardsHTML = '';
    const biomeList = window.BIOMES || [];
    for (const biome of biomeList) {
      const desc = BIOME_DESCRIPTIONS[biome.id] || '';
      const diff = BIOME_DIFFICULTY[biome.id] || 1;
      const skulls = '💀'.repeat(diff);
      cardsHTML += `
        <div class="map-card" data-biome="${biome.id}">
          <div class="map-card-preview" data-biome-preview="${biome.id}"></div>
          <div class="map-card-name">${biome.name}</div>
          <div class="map-card-desc">${desc}</div>
          <div class="map-card-diff">${skulls}</div>
        </div>
      `;
    }

    ov.innerHTML = `
      <div class="camp-bg map-select-bg">
        <h1 class="camp-title map-select-title">${t('map_select_title')}</h1>
        <div class="map-grid">${cardsHTML}</div>
        <div class="map-select-buttons">
          <button id="mapRandomBtn" class="btn camp-btn">${t('map_random')}</button>
          <button id="mapBackBtn" class="btn camp-btn">${t('map_back')}</button>
        </div>
      </div>
    `;

    document.body.appendChild(ov);
    this._mapSelectOverlay = ov;

    // Вставляем превью-канвасы
    const previewEls = ov.querySelectorAll('.map-card-preview');
    for (const el of previewEls) {
      const biomeId = el.getAttribute('data-biome-preview');
      if (window.BIOME_PREVIEWS && BIOME_PREVIEWS[biomeId]) {
        const img = BIOME_PREVIEWS[biomeId];
        el.style.backgroundImage = 'url(' + img.toDataURL() + ')';
        el.style.backgroundSize = 'cover';
        el.style.imageRendering = 'pixelated';
      }
    }

    // Клик по карточке
    const cards = ov.querySelectorAll('.map-card');
    for (const card of cards) {
      card.addEventListener('click', () => {
        const biomeId = card.getAttribute('data-biome');
        this.hideMapSelect();
        if (window.Game) Game.startNewGame(biomeId);
      });
    }

    // Случайная карта
    ov.querySelector('#mapRandomBtn').addEventListener('click', () => {
      const biomes = window.BIOMES || [];
      const randomBiome = biomes[Math.floor(Math.random() * biomes.length)];
      this.hideMapSelect();
      if (window.Game) Game.startNewGame(randomBiome ? randomBiome.id : 'crypt');
    });

    // Назад
    ov.querySelector('#mapBackBtn').addEventListener('click', () => {
      this.hideMapSelect();
      this.showCamp();
    });
  },

  /** Подсветить последний биом золотой рамкой */
  _updateMapSelectHighlight() {
    if (!this._mapSelectOverlay) return;
    const cards = this._mapSelectOverlay.querySelectorAll('.map-card');
    // Получаем последний биом из метапрогресса или из Game
    const lastBiome = (window.GameMap && GameMap.currentBiome)
      ? GameMap.currentBiome.id
      : (window.Game && Game.lastBiomeId) || 'crypt';
    for (const card of cards) {
      if (card.getAttribute('data-biome') === lastBiome) {
        card.classList.add('map-card-highlight');
      } else {
        card.classList.remove('map-card-highlight');
      }
    }
  },

  /* ============================================================
     Шаг 15: Дерево талантов (Talent Tree screen)
     ============================================================ */

  showTalents() {
    if (!this._talentOverlay) this._buildTalentOverlay();
    this._updateTalentData();
    this._talentOverlay.classList.add('active');
  },

  _buildTalentOverlay() {
    const ov = document.createElement('div');
    ov.id = 'talentOverlay';
    ov.className = 'overlay talent-overlay';
    ov.innerHTML = `
      <div class="talent-panel">
        <h1 class="talent-title">${t('talents_title')}</h1>
        <div class="talent-gold"><span class="gold-icon">🪙</span> <span id="talentGoldVal">0</span></div>
        <div id="talentGrid" class="talent-grid"></div>
        <div class="talent-footer">
          <button id="talentResetBtn" class="btn btn-secondary">${t('talents_reset')}</button>
          <button id="talentBackBtn" class="btn">${t('talents_back')}</button>
        </div>
      </div>
    `;
    document.body.appendChild(ov);
    this._talentOverlay = ov;

    ov.querySelector('#talentBackBtn').addEventListener('click', () => {
      this._talentOverlay.classList.remove('active');
      this.showCamp();
    });
    ov.querySelector('#talentResetBtn').addEventListener('click', () => {
      if (!window.MetaProgress) return;
      if (confirm(t('talents_reset_confirm'))) {
        MetaProgress.resetTalents();
        this._updateTalentData();
      }
    });
  },

  _updateTalentData() {
    if (!window.MetaProgress || !MetaProgress.data) return;
    if (!window.TALENT_DEFS) return;
    const ov = this._talentOverlay;
    ov.querySelector('#talentGoldVal').textContent = MetaProgress.data.gold;

    const container = ov.querySelector('#talentGrid');
    container.innerHTML = '';

    for (const def of TALENT_DEFS) {
      const lvl = MetaProgress.data.talents[def.id] || 0;
      const cost = MetaProgress.getTalentCost(def.id);
      const canBuy = MetaProgress.data.gold >= cost && lvl < def.maxLevel;
      const maxed = lvl >= def.maxLevel;

      // Звёзды уровней
      let starsHtml = '';
      for (let i = 0; i < def.maxLevel; i++) {
        starsHtml += `<span class="talent-star ${i < lvl ? 'filled' : ''}">${i < lvl ? '★' : '☆'}</span>`;
      }

      // Текущий эффект
      const effectText = lvl > 0 ? def.effects[lvl - 1] : def.effects[0];

      const card = document.createElement('div');
      card.className = 'talent-card' + (maxed ? ' maxed' : '');
      card.innerHTML = `
        <div class="talent-card-icon">${def.icon}</div>
        <div class="talent-card-name">${def.name}</div>
        <div class="talent-card-stars">${starsHtml}</div>
        <div class="talent-card-effect">${lvl > 0 ? def.effects[lvl - 1] : def.description}</div>
        <button class="btn talent-buy-btn ${canBuy ? '' : 'btn-disabled'}">
          ${maxed ? t('talents_max') : '🪙 ' + cost}
        </button>
      `;
      container.appendChild(card);

      if (!maxed) {
        card.querySelector('.talent-buy-btn').addEventListener('click', () => {
          if (MetaProgress.upgradeTalent(def.id)) {
            this._updateTalentData();
          }
        });
      }
    }
  },

  /* ============================================================
     Шаг 4: Гильдия (полная переработка) — ранги, статистика, задания
     ============================================================ */

  showGuild() {
    if (!this._guildOverlay) this._buildGuildOverlay();
    this._updateGuildData();
    this._guildOverlay.classList.add('active');
  },

  _buildGuildOverlay() {
    const ov = document.createElement('div');
    ov.id = 'guildOverlay';
    ov.className = 'overlay guild-overlay';
    ov.innerHTML = `
      <div class="guild-panel-v2">
        <div class="guild-header-v2">
          <div class="guild-emblem">⚜</div>
          <h1 class="guild-title-v2">${t('guild_title')}</h1>
        </div>

        <div class="guild-rank-section">
          <div class="guild-rank-current">
            <span class="guild-rank-icon">🛡</span>
            <span id="guildRankName" class="guild-rank-name">Новобранец</span>
          </div>
          <div class="guild-rep-bar-v2">
            <div class="guild-rep-fill-v2" id="guildRepFillV2"></div>
            <div class="guild-rep-text-v2" id="guildRepTextV2">0 / 100</div>
          </div>
        </div>

        <div class="guild-tabs">
          <button class="guild-tab active" data-tab="ranks">${t('guild_tab_ranks')}</button>
          <button class="guild-tab" data-tab="stats">${t('guild_tab_stats')}</button>
          <button class="guild-tab" data-tab="quests">${t('guild_tab_quests')}</button>
        </div>

        <div class="guild-content" id="guildContent"></div>

        <div class="guild-footer-v2">
          <button id="guildBackBtnV2" class="btn">${t('guild_back')}</button>
        </div>
      </div>
    `;
    document.body.appendChild(ov);
    this._guildOverlay = ov;

    ov.querySelector('#guildBackBtnV2').addEventListener('click', () => {
      this._guildOverlay.classList.remove('active');
      this.showCamp();
    });

    // Табы
    ov.querySelectorAll('.guild-tab').forEach(tab => {
      tab.addEventListener('click', () => {
        ov.querySelectorAll('.guild-tab').forEach(t => t.classList.remove('active'));
        tab.classList.add('active');
        this._renderGuildTab(tab.dataset.tab);
      });
    });
  },

  _updateGuildData() {
    if (!window.MetaProgress || !MetaProgress.data) return;
    const ov = this._guildOverlay;
    const rep = MetaProgress.data.reputation;
    const lvl = MetaProgress.getGuildLevel();
    const nextRep = MetaProgress.getNextLevelRep();
    const rankName = MetaProgress.getGuildRankName();

    ov.querySelector('#guildRankName').textContent = rankName + ' (' + t('level_short') + ' ' + lvl + ')';

    // Прогресс-бар
    let pct = 0;
    let repText = '';
    if (nextRep) {
      const prevRep = lvl > 0 ? GUILD_CONFIG.levels[lvl - 1].rep : 0;
      pct = Math.min(100, ((rep - prevRep) / (nextRep - prevRep)) * 100);
      repText = `${rep} / ${nextRep}`;
    } else {
      pct = 100;
      repText = `${rep} — МАКС`;
    }
    ov.querySelector('#guildRepFillV2').style.width = pct + '%';
    ov.querySelector('#guildRepTextV2').textContent = repText;

    // Рендер активной вкладки
    const activeTab = ov.querySelector('.guild-tab.active');
    this._renderGuildTab(activeTab ? activeTab.dataset.tab : 'ranks');
  },

  _renderGuildTab(tab) {
    const content = this._guildOverlay.querySelector('#guildContent');
    if (tab === 'ranks') this._renderGuildRanks(content);
    else if (tab === 'stats') this._renderGuildStats(content);
    else if (tab === 'quests') this._renderGuildQuests(content);
  },

  /** Вкладка «Ранги» — прокручиваемый список рангов с наградами. */
  _renderGuildRanks(container) {
    if (!window.MetaProgress) return;
    const lvl = MetaProgress.getGuildLevel();
    let html = '<div class="guild-ranks-list">';
    for (let i = 0; i < GUILD_CONFIG.levels.length; i++) {
      const r = GUILD_CONFIG.levels[i];
      const reached = i < lvl;
      const current = i === lvl - 1;
      let cls = 'guild-rank-row';
      if (reached) cls += ' reached';
      if (current) cls += ' current';
      html += `<div class="${cls}">
        <div class="guild-rank-row-left">
          <span class="guild-rank-num">${i + 1}</span>
          <span class="guild-rank-row-name">${r.name}</span>
          <span class="guild-rank-row-rep">(${r.rep} реп.)</span>
        </div>
        <div class="guild-rank-row-right">
          <span class="guild-rank-row-reward">${r.reward}</span>
          <span class="guild-rank-row-check">${reached ? '✓' : '🔒'}</span>
        </div>
      </div>`;
    }
    html += '</div>';
    container.innerHTML = html;
  },

  /** Вкладка «Статистика» — общая статистика гильдии. */
  _renderGuildStats(container) {
    if (!window.MetaProgress || !MetaProgress.data) return;
    const d = MetaProgress.data;
    const gs = d.guildStats || {};
    const bestiaryStats = window.Bestiary ? Bestiary.getStats() : { unlocked: 0, total: 0 };
    const totalEnemyTypes = Object.keys(window.ENEMY_TYPES || {}).length;

    const stats = [
      { label: t('guild_stat_total_kills'), value: d.totalKills || 0 },
      { label: t('guild_stat_total_bosses'), value: d.totalBossKills || 0 },
      { label: t('guild_stat_bestiary'), value: `${bestiaryStats.unlocked} / ${totalEnemyTypes}` },
      { label: t('guild_stat_runs'), value: d.totalRuns || 0 },
      { label: t('guild_stat_best_time'), value: Utils.formatTime(d.bestTime || 0) },
      { label: t('guild_stat_best_kills'), value: d.bestKills || 0 },
      { label: t('guild_stat_reputation'), value: d.reputation || 0 },
    ];

    let html = '<div class="guild-stats-list">';
    for (const s of stats) {
      html += `<div class="guild-stats-row">
        <span class="guild-stats-label">${s.label}</span>
        <span class="guild-stats-value">${s.value}</span>
      </div>`;
    }
    html += '</div>';
    container.innerHTML = html;
  },

  /** Вкладка «Задания» — ежедневные и еженедельные задания. */
  _renderGuildQuests(container) {
    if (!window.MetaProgress || !MetaProgress.data) {
      container.innerHTML = '<div class="guild-quests-empty">' + t('loading') + '</div>';
      return;
    }

    // Инициализировать задания если нужно
    MetaProgress.initGuildQuests();
    const quests = MetaProgress.getActiveQuests();

    let html = '<div class="guild-quests-section">';

    // Дневные
    html += '<div class="guild-quests-group-title">' + t('guild_daily_title') + '</div>';
    if (quests.daily.length === 0) {
      html += '<div class="guild-quest-empty">' + t('guild_no_quests') + '</div>';
    } else {
      for (const q of quests.daily) {
        html += this._renderQuestRow(q);
      }
    }

    // Недельные
    html += '<div class="guild-quests-group-title" style="margin-top:12px;">' + t('guild_weekly_title') + '</div>';
    if (quests.weekly.length === 0) {
      html += '<div class="guild-quest-empty">' + t('guild_no_quests') + '</div>';
    } else {
      for (const q of quests.weekly) {
        html += this._renderQuestRow(q);
      }
    }

    html += '</div>';
    container.innerHTML = html;

    // Привязка кнопок «Забрать»
    container.querySelectorAll('.guild-quest-claim-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const qId = btn.dataset.questId;
        if (MetaProgress.claimQuestReward(qId)) {
          this._updateGuildData();
        }
      });
    });
  },

  /** Рендер строки задания. */
  _renderQuestRow(q) {
    const pct = Math.min(100, Math.round((q.progress / q.target) * 100));
    let statusHtml = '';
    if (q.claimed) {
      statusHtml = '<span class="guild-quest-done">' + t('guild_quest_done') + '</span>';
    } else if (q.completed) {
      statusHtml = `<button class="btn guild-quest-claim-btn" data-quest-id="${q.id}">Забрать (+${q.repReward} реп.)</button>`;
    } else {
      statusHtml = `<span class="guild-quest-progress-text">${q.progress}/${q.target}</span>`;
    }

    return `<div class="guild-quest-row ${q.completed ? 'completed' : ''} ${q.claimed ? 'claimed' : ''}">
      <div class="guild-quest-desc">${q.desc}</div>
      <div class="guild-quest-bar"><div class="guild-quest-bar-fill" style="width:${pct}%"></div></div>
      <div class="guild-quest-status">${statusHtml}</div>
    </div>`;
  },

  /* ============================================================
     Шаг 15: Экран результатов забега (Run Results)
     ============================================================ */

  showRunResults(stats, onContinue) {
    this.hideAll();
    if (!this._resultsOverlay) this._buildResultsOverlay();
    const ov = this._resultsOverlay;

    ov.querySelector('#resTime').textContent = stats.time;
    ov.querySelector('#resKills').textContent = stats.kills;
    ov.querySelector('#resLevel').textContent = stats.level;
    ov.querySelector('#resGoldCollected').textContent = stats.goldCollected;
    ov.querySelector('#resGoldBonus').textContent = stats.goldBonus;
    ov.querySelector('#resGoldTotal').textContent = stats.goldTotal;
    ov.querySelector('#resRepGained').textContent = '+' + stats.repGained;

    // Замена обработчика
    const btn = ov.querySelector('#resToCampBtn');
    const newBtn = btn.cloneNode(true);
    btn.parentNode.replaceChild(newBtn, btn);
    newBtn.addEventListener('click', () => {
      this._resultsOverlay.classList.remove('active');
      onContinue && onContinue();
    });

    ov.classList.add('active');
  },

  _buildResultsOverlay() {
    const ov = document.createElement('div');
    ov.id = 'resultsOverlay';
    ov.className = 'overlay results-overlay';
    ov.innerHTML = `
      <div class="results-panel">
        <h1 class="results-title">ЗАБЕГ ОКОНЧЕН</h1>
        <div class="results-stats">
          <div class="res-row"><span>Время:</span><span id="resTime">00:00</span></div>
          <div class="res-row"><span>Убийств:</span><span id="resKills">0</span></div>
          <div class="res-row"><span>Уровень:</span><span id="resLevel">1</span></div>
          <div class="res-divider"></div>
          <div class="res-row gold-row"><span>🪙 Собрано:</span><span id="resGoldCollected">0</span></div>
          <div class="res-row gold-row"><span>🪙 Бонус за ур.:</span><span id="resGoldBonus">0</span></div>
          <div class="res-row gold-row total"><span>🪙 ИТОГО:</span><span id="resGoldTotal">0</span></div>
          <div class="res-row rep-row"><span>⚜ Репутация:</span><span id="resRepGained">+0</span></div>
        </div>
        <button id="resToCampBtn" class="btn camp-btn-main">Вернуться в лагерь</button>
      </div>
    `;
    document.body.appendChild(ov);
    this._resultsOverlay = ov;
  },

  /* ============================================================
     Шаг 15: перестроить слоты (вызывается при старте забега
     с учётом динамического количества слотов)
     ============================================================ */

  rebuildSlots(weaponCount, abilityCount) {
    const left  = document.getElementById('weaponSlots');
    const right = document.getElementById('abilitySlots');
    left.innerHTML = '';
    right.innerHTML = '';
    this.weaponSlotEls.length = 0;
    this.abilitySlotEls.length = 0;
    for (let i = 0; i < weaponCount; i++) {
      const el = document.createElement('div');
      el.className = 'slot';
      el.innerHTML =
        '<div class="slot-cd"></div>' +
        '<div class="slot-icon"></div>' +
        '<div class="slot-level"></div>';
      left.appendChild(el);
      this.weaponSlotEls.push(el);
    }
    for (let i = 0; i < abilityCount; i++) {
      const el = document.createElement('div');
      el.className = 'slot';
      el.innerHTML =
        '<div class="slot-cd"></div>' +
        '<div class="slot-icon"></div>' +
        '<div class="slot-level"></div>';
      right.appendChild(el);
      this.abilitySlotEls.push(el);
    }
  },

  /* ============================================================
     Шаг 16: Кампания — диалоги, цель в HUD, экран победы
     ============================================================ */

  /** Показать диалоговое окно кампании. */
  showCampaignDialogue(text, onClose) {
    this.hideAll();
    if (!this._dialogueOverlay) this._buildDialogueOverlay();
    const ov = this._dialogueOverlay;
    ov.querySelector('#dialogueText').textContent = text;
    ov.classList.add('active');

    // Защита от двойного вызова onClose
    let closed = false;
    const doClose = () => {
      if (closed) return;
      closed = true;
      clearTimeout(this._dialogueAutoClose);
      ov.classList.remove('active');
      onClose && onClose();
    };

    const btn = ov.querySelector('#dialogueNextBtn');
    const newBtn = btn.cloneNode(true);
    btn.parentNode.replaceChild(newBtn, btn);
    newBtn.addEventListener('click', doClose);
    // Также закрывать при тапе/клике по панели (для мобильных)
    const panel = ov.querySelector('.dialogue-panel');
    if (panel) {
      const newPanel = panel.cloneNode(true);
      panel.parentNode.replaceChild(newPanel, panel);
      // Перепривязать кнопку после замены панели
      const innerBtn = newPanel.querySelector('#dialogueNextBtn');
      if (innerBtn) innerBtn.addEventListener('click', doClose);
      newPanel.addEventListener('click', (e) => {
        // Закрыть при клике на панель (не только на кнопку)
        doClose();
      });
    }

    // Авто-закрытие через 10 секунд (увеличено для чтения длинного текста)
    clearTimeout(this._dialogueAutoClose);
    this._dialogueAutoClose = setTimeout(() => {
      doClose();
    }, 10000);
  },

  _buildDialogueOverlay() {
    const ov = document.createElement('div');
    ov.id = 'dialogueOverlay';
    ov.className = 'overlay dialogue-overlay';
    ov.innerHTML = `
      <div class="dialogue-panel">
        <div class="dialogue-border"></div>
        <p id="dialogueText" class="dialogue-text"></p>
        <button id="dialogueNextBtn" class="btn dialogue-btn">Далее ➤</button>
      </div>
    `;
    document.body.appendChild(ov);
    this._dialogueOverlay = ov;
  },

  /** Показать экран победы кампании. */
  showCampaignVictory(text, onClose) {
    this.hideAll();
    if (!this._victoryOverlay) this._buildVictoryOverlay();
    const ov = this._victoryOverlay;
    ov.querySelector('#victoryText').textContent = text;
    ov.classList.add('active');

    let closed = false;
    const doClose = () => {
      if (closed) return;
      closed = true;
      ov.classList.remove('active');
      onClose && onClose();
    };

    const btn = ov.querySelector('#victoryBtn');
    const newBtn = btn.cloneNode(true);
    btn.parentNode.replaceChild(newBtn, btn);
    newBtn.addEventListener('click', doClose);
  },

  _buildVictoryOverlay() {
    const ov = document.createElement('div');
    ov.id = 'victoryOverlay';
    ov.className = 'overlay victory-overlay';
    ov.innerHTML = `
      <div class="victory-panel">
        <h1 class="victory-title">🐉 ПОБЕДА! 🐉</h1>
        <h2 class="victory-sub">Древний дракон повержен!</h2>
        <p id="victoryText" class="victory-text"></p>
        <div class="victory-rewards">
          <div>🪙 +1000 золота</div>
          <div>⚜ +200 репутации</div>
          <div>🏆 Достижение: Победитель дракона</div>
        </div>
        <button id="victoryBtn" class="btn camp-btn-main">В лагерь</button>
      </div>
    `;
    document.body.appendChild(ov);
    this._victoryOverlay = ov;
  },

  /** Отрисовка цели кампании в HUD (вызывается из tick). */
  _updateCampaignObjectiveHUD(game) {
    if (!window.Campaign || !Campaign.active || !Campaign.objective) {
      if (this._objectiveEl) this._objectiveEl.style.display = 'none';
      return;
    }

    if (!this._objectiveEl) {
      const el = document.createElement('div');
      el.id = 'campaignObjective';
      el.className = 'campaign-objective';
      const topRight = document.querySelector('.hud-top-right');
      if (topRight) topRight.appendChild(el);
      this._objectiveEl = el;
    }

    this._objectiveEl.style.display = 'block';
    const obj = Campaign.objective;
    let text = '';

    if (obj.completed) {
      text = t('campaign_objective_done');
      this._objectiveEl.className = 'campaign-objective completed';
    } else {
      this._objectiveEl.className = 'campaign-objective';
      text = Campaign.getObjectiveText();
    }

    this._objectiveEl.textContent = text;
  },

  /** Показать название карты кампании (при загрузке). */
  showCampaignMapName(name) {
    if (!this._mapNameEl) {
      const el = document.createElement('div');
      el.id = 'campaignMapName';
      el.className = 'campaign-map-name';
      document.body.appendChild(el);
      this._mapNameEl = el;
    }
    this._mapNameEl.textContent = name;
    this._mapNameEl.classList.add('visible');
    setTimeout(() => {
      this._mapNameEl.classList.remove('visible');
    }, 3000);
  },

  /* ============================================================
     Шаг 17: HUD-индикаторы для загадок и ловушек
     ============================================================ */

  /** Показать подсказку загадки в нижней части экрана (при приближении). */
  renderPuzzleHints(ctx, player, viewW, viewH) {
    if (!window.GameMap || !GameMap.dungeon || !player) return;

    // Руновые загадки — показываем прогресс если рядом
    if (GameMap.dungeon.runePuzzles) {
      for (const puzzle of GameMap.dungeon.runePuzzles) {
        if (puzzle.solved) continue;
        // Проверяем, в комнате ли игрок
        const room = puzzle.room;
        if (player.x >= room.x && player.x <= room.x + room.w &&
            player.y >= room.y && player.y <= room.y + room.h) {
          this._renderPuzzleProgress(ctx, viewW, viewH, puzzle, 'Rune Activation');
          break;
        }
      }
    }

    // Плиты-шифры
    if (GameMap.dungeon.floorPuzzles) {
      for (const puzzle of GameMap.dungeon.floorPuzzles) {
        if (puzzle.solved) continue;
        const room = puzzle.room;
        if (player.x >= room.x && player.x <= room.x + room.w &&
            player.y >= room.y && player.y <= room.y + room.h) {
          this._renderPuzzleProgress(ctx, viewW, viewH, puzzle, 'Cipher');
          break;
        }
      }
    }
  },

  /** Отрисовать полоску прогресса загадки внизу экрана. */
  _renderPuzzleProgress(ctx, viewW, viewH, puzzle, label) {
    const seq = puzzle.sequence;
    const current = puzzle.currentStep;
    const total = seq.length;

    const barW = Math.min(300, total * 50);
    const barH = 36;
    const bx = (viewW - barW) / 2;
    const by = viewH - 60;

    // Фон
    ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
    ctx.fillRect(bx - 10, by - 8, barW + 20, barH + 16);
    ctx.strokeStyle = 'rgba(200, 180, 255, 0.5)';
    ctx.lineWidth = 1;
    ctx.strokeRect(bx - 10, by - 8, barW + 20, barH + 16);

    // Заголовок
    ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
    ctx.font = '10px ui-monospace, monospace';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    ctx.fillText(label + ' (' + current + '/' + total + ')', viewW / 2, by - 4);

    // Символы последовательности
    const slotW = barW / total;
    for (let i = 0; i < total; i++) {
      const sx = bx + i * slotW + slotW / 2;
      const sy = by + barH / 2 + 4;

      if (i < current) {
        // Выполнено — зелёный
        ctx.fillStyle = '#00ff88';
      } else if (i === current) {
        // Текущий — белый пульсирующий
        ctx.fillStyle = '#ffffff';
      } else {
        // Будущий — серый
        ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
      }

      ctx.font = 'bold 16px ui-monospace, monospace';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(seq[i].label, sx, sy);

      // Стрелка (если не последний)
      if (i < total - 1) {
        ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
        ctx.font = '12px ui-monospace, monospace';
        ctx.fillText('\u203A', sx + slotW / 2, sy);
      }
    }

    // Подсказка о failed
    if (puzzle.failed) {
      ctx.fillStyle = 'rgba(255, 50, 50, 0.9)';
      ctx.font = 'bold 12px ui-monospace, monospace';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'top';
      ctx.fillText('Wrong! Resetting...', viewW / 2, by + barH + 12);
    }
  },

  /** Показать предупреждение о ловушке (валун и т.д.) — кратковременное сообщение. */
  showTrapWarning(message, color) {
    if (!this._trapWarnEl) {
      const el = document.createElement('div');
      el.id = 'trapWarning';
      el.className = 'trap-warning';
      document.body.appendChild(el);
      this._trapWarnEl = el;
    }
    this._trapWarnEl.textContent = message;
    this._trapWarnEl.style.color = color || '#ff6633';
    this._trapWarnEl.classList.add('visible');
    clearTimeout(this._trapWarnTimer);
    this._trapWarnTimer = setTimeout(() => {
      this._trapWarnEl.classList.remove('visible');
    }, 2000);
  },

  /* ============================================================
     Шаг 18: Настройки звука (Settings screen)
     ============================================================ */

  showSettings() {
    if (!this._settingsOverlay) this._buildSettingsOverlay();
    this._updateSettingsData();
    this._settingsOverlay.classList.add('active');
  },

  _buildSettingsOverlay() {
    const ov = document.createElement('div');
    ov.id = 'settingsOverlay';
    ov.className = 'overlay settings-overlay';
    ov.innerHTML = `
      <div class="settings-panel">
        <h1 class="settings-title">${t('settings_title')}</h1>
        <div class="settings-section">
          <div class="settings-row">
            <span class="settings-label">${t('settings_sfx')}</span>
            <input type="range" id="sfxVolumeSlider" class="settings-slider" min="0" max="100" value="70">
            <span id="sfxVolumeVal" class="settings-value">70%</span>
          </div>
          <div class="settings-row">
            <span class="settings-label">${t('settings_music')}</span>
            <input type="range" id="musicVolumeSlider" class="settings-slider" min="0" max="100" value="25">
            <span id="musicVolumeVal" class="settings-value">25%</span>
          </div>
          <div class="settings-row settings-row-btn">
            <button id="muteToggleBtn" class="btn settings-mute-btn">🔊</button>
          </div>
          <div class="settings-row settings-row-lang">
            <span class="settings-label">${t('settings_lang')}</span>
            <div class="lang-switcher">
              <button id="langRuBtn" class="btn lang-btn ${getLang() === 'ru' ? 'lang-btn-active' : ''}">RU</button>
              <button id="langEnBtn" class="btn lang-btn ${getLang() === 'en' ? 'lang-btn-active' : ''}">EN</button>
            </div>
          </div>
          <div class="settings-row settings-row-btn">
            <button id="resetProgressBtn" class="btn settings-reset-btn">🗑 ${t('settings_reset')}</button>
          </div>
        </div>
        <div class="settings-footer">
          <button id="settingsBackBtn" class="btn">${t('settings_back')}</button>
        </div>
      </div>
    `;
    document.body.appendChild(ov);
    this._settingsOverlay = ov;

    // SFX slider
    const sfxSlider = ov.querySelector('#sfxVolumeSlider');
    const sfxVal = ov.querySelector('#sfxVolumeVal');
    sfxSlider.addEventListener('input', () => {
      const v = parseInt(sfxSlider.value);
      sfxVal.textContent = v + '%';
      if (window.GameAudio) GameAudio.setSfxVolume(v / 100);
    });

    // Music slider
    const musicSlider = ov.querySelector('#musicVolumeSlider');
    const musicVal = ov.querySelector('#musicVolumeVal');
    musicSlider.addEventListener('input', () => {
      const v = parseInt(musicSlider.value);
      musicVal.textContent = v + '%';
      if (window.GameAudio) GameAudio.setMusicVolume(v / 100);
    });

    // Mute toggle
    ov.querySelector('#muteToggleBtn').addEventListener('click', () => {
      if (window.GameAudio) {
        GameAudio.toggleMute();
        this._updateMuteBtn();
      }
    });

    // Переключатель языка
    ov.querySelector('#langRuBtn').addEventListener('click', () => {
      setLang('ru');
      // Перестроить настройки для обновления текстов
      this._settingsOverlay.remove();
      this._settingsOverlay = null;
      this.showSettings();
    });
    ov.querySelector('#langEnBtn').addEventListener('click', () => {
      setLang('en');
      // Перестроить настройки для обновления текстов
      this._settingsOverlay.remove();
      this._settingsOverlay = null;
      this.showSettings();
    });

    // Reset progress
    ov.querySelector('#resetProgressBtn').addEventListener('click', () => {
      if (confirm(t('settings_reset_confirm'))) {
        try { localStorage.clear(); } catch(e) { /* Private Browsing */ }
        if (window.MetaProgress) MetaProgress.load();
        location.reload();
      }
    });

    // Back button
    ov.querySelector('#settingsBackBtn').addEventListener('click', () => {
      this._settingsOverlay.classList.remove('active');
      this.showCamp();
    });
  },

  _updateSettingsData() {
    if (!this._settingsOverlay || !window.GameAudio) return;
    const ov = this._settingsOverlay;
    const sfxSlider = ov.querySelector('#sfxVolumeSlider');
    const sfxVal = ov.querySelector('#sfxVolumeVal');
    const musicSlider = ov.querySelector('#musicVolumeSlider');
    const musicVal = ov.querySelector('#musicVolumeVal');

    const sfxPct = Math.round(GameAudio.sfxVolume * 100);
    const musicPct = Math.round(GameAudio.musicVolume * 100);

    sfxSlider.value = sfxPct;
    sfxVal.textContent = sfxPct + '%';
    musicSlider.value = musicPct;
    musicVal.textContent = musicPct + '%';

    this._updateMuteBtn();
  },

  _updateMuteBtn() {
    if (!this._settingsOverlay || !window.GameAudio) return;
    const btn = this._settingsOverlay.querySelector('#muteToggleBtn');
    if (GameAudio.muted) {
      btn.textContent = '🔇';
      btn.classList.add('muted');
    } else {
      btn.textContent = '🔊';
      btn.classList.remove('muted');
    }
  },
};

window.UI = UI;

'use strict';

// === js/ui/overlays.js ===
/* ============================================================
   ui_extended.js — Расширенный UI: выбор класса, бестиарий,
   книга (кодекс), окно статистики, выход из забега, кнопка «Назад».
   ============================================================ */

const UIExtended = {
  _classOverlay: null,
  _bestiaryOverlay: null,
  _codexOverlay: null,
  _runStatsOverlay: null,

  /* ============================================================
     ВЫБОР КЛАССА
     ============================================================ */
  showClassSelect(onBack) {
    if (!this._classOverlay) this._buildClassOverlay();
    this._updateClassOverlay();
    this._classOverlay._onBack = onBack;
    this._classOverlay.classList.add('active');
  },

  _buildClassOverlay() {
    const ov = document.createElement('div');
    ov.id = 'classOverlay';
    ov.className = 'overlay camp-overlay';
    ov.innerHTML = `
      <div class="camp-bg">
        <h1 class="camp-title" style="font-size:1.4em;">${t('class_select_title')}</h1>
        <div id="classGrid" class="class-grid"></div>
        <button id="classBackBtn" class="btn" style="margin-top:16px;">↩ Назад</button>
      </div>
    `;
    document.body.appendChild(ov);
    this._classOverlay = ov;
    ov.querySelector('#classBackBtn').addEventListener('click', () => {
      ov.classList.remove('active');
      if (ov._onBack) ov._onBack();
    });
  },

  _updateClassOverlay() {
    const grid = this._classOverlay.querySelector('#classGrid');
    grid.innerHTML = '';
    const selected = Classes.getSelected();
    for (const id of Object.keys(CLASS_DEFS)) {
      const def = CLASS_DEFS[id];
      const isActive = (id === selected);
      const card = document.createElement('div');
      card.className = 'class-card' + (isActive ? ' class-card-active' : '');

      // Используем CLASS_SPRITES если доступны (32×32 пиксельная иконка)
      const sprite = window.CLASS_SPRITES ? CLASS_SPRITES[id] : null;
      let iconHtml;
      if (sprite) {
        iconHtml = `<div class="class-card-icon" style="background:${def.color};background-image:url(${sprite.toDataURL()});background-size:contain;background-repeat:no-repeat;background-position:center;image-rendering:pixelated;"></div>`;
      } else {
        iconHtml = `<div class="class-card-icon" style="background:${def.color};">${def.icon}</div>`;
      }

      card.innerHTML = `
        ${iconHtml}
        <div class="class-card-name">${def.name}</div>
        <div class="class-card-desc">${def.desc}</div>
        <div class="class-card-passive">${def.passiveDesc}</div>
      `;
      card.addEventListener('click', () => {
        Classes.setSelected(id);
        this._updateClassOverlay();
      });
      grid.appendChild(card);
    }
  },

  /* ============================================================
     БЕСТИАРИЙ — двухпанельный UI (Шаг 3 переработка)
     Левая панель: сетка карточек 48×48.
     Правая панель: подробная информация о выбранном враге.
     ============================================================ */
  showBestiary(onBack) {
    if (!this._bestiaryOverlay) this._buildBestiaryOverlay();
    Bestiary.selectedEnemyId = null;
    this._updateBestiaryGrid();
    this._updateBestiaryDetail();
    this._bestiaryOverlay._onBack = onBack;
    this._bestiaryOverlay.classList.add('active');
  },

  _buildBestiaryOverlay() {
    const ov = document.createElement('div');
    ov.id = 'bestiaryOverlay';
    ov.className = 'overlay camp-overlay';
    ov.innerHTML = `
      <div class="bestiary-layout">
        <div class="bestiary-header">
          <h1 class="bestiary-title">${t('bestiary_title')}</h1>
          <div id="bestiaryStats" class="bestiary-stats-header"></div>
          <button id="bestiaryBackBtn" class="btn bestiary-back-btn">${t('bestiary_back')}</button>
        </div>
        <div class="bestiary-body">
          <div class="bestiary-left" id="bestiaryLeft">
            <div id="bestiaryGrid" class="bestiary-grid-v2"></div>
          </div>
          <div class="bestiary-right" id="bestiaryRight">
            <div id="bestiaryDetail" class="bestiary-detail">
              <div class="bestiary-detail-empty">
                <div class="bestiary-detail-empty-icon">🔍</div>
                <div class="bestiary-detail-empty-text">${t('bestiary_select_enemy')}</div>
              </div>
            </div>
          </div>
        </div>
      </div>
    `;
    document.body.appendChild(ov);
    this._bestiaryOverlay = ov;
    ov.querySelector('#bestiaryBackBtn').addEventListener('click', () => {
      ov.classList.remove('active');
      if (ov._onBack) ov._onBack();
    });
  },

  /** Отрисовка левой сетки бестиария. */
  _updateBestiaryGrid() {
    const stats = Bestiary.getStats();
    this._bestiaryOverlay.querySelector('#bestiaryStats').textContent =
      t('bestiary_unlocked', stats.unlocked, stats.total);
    const grid = this._bestiaryOverlay.querySelector('#bestiaryGrid');
    grid.innerHTML = '';
    const enemies = Bestiary.getAllEnemies();
    for (const cfg of enemies) {
      const unlocked = Bestiary.isUnlocked(cfg.id);
      const cell = document.createElement('div');
      cell.className = 'bestiary-cell-v2' + (unlocked ? ' unlocked' : ' locked');
      if (Bestiary.selectedEnemyId === cfg.id) cell.classList.add('selected');

      // Иконка спрайта (маленькая 32×32 отображаемая как 48×48)
      const iconDiv = document.createElement('div');
      iconDiv.className = 'bestiary-cell-v2-icon';
      const sprite = window.getEnemySprite ? getEnemySprite(cfg.id) : null;

      if (sprite) {
        const display = document.createElement('canvas');
        display.width = 16; display.height = 16;
        display.style.imageRendering = 'pixelated';
        display.style.width = '32px'; display.style.height = '32px';
        const dCtx = display.getContext('2d');
        dCtx.imageSmoothingEnabled = false;
        dCtx.drawImage(sprite, 0, 0, 16, 16);
        if (!unlocked) {
          // Чёрный силуэт
          dCtx.globalCompositeOperation = 'source-in';
          dCtx.fillStyle = '#1a1a1a';
          dCtx.fillRect(0, 0, 16, 16);
          dCtx.globalCompositeOperation = 'source-over';
        }
        iconDiv.appendChild(display);
      } else {
        if (unlocked) {
          iconDiv.style.background = cfg.color;
          iconDiv.textContent = cfg.letter;
        } else {
          iconDiv.textContent = '?';
          iconDiv.classList.add('silhouette');
        }
      }
      cell.appendChild(iconDiv);

      // Мини-название
      const nameDiv = document.createElement('div');
      nameDiv.className = 'bestiary-cell-v2-name';
      nameDiv.textContent = unlocked ? cfg.name : '???';
      cell.appendChild(nameDiv);

      // Клик — выбрать
      cell.addEventListener('click', () => {
        if (!unlocked) return; // Неоткрытых не выбираем
        Bestiary.selectedEnemyId = cfg.id;
        // Обновить подсветку
        grid.querySelectorAll('.bestiary-cell-v2').forEach(c => c.classList.remove('selected'));
        cell.classList.add('selected');
        this._updateBestiaryDetail();
      });

      grid.appendChild(cell);
    }
  },

  /** Отрисовка правой панели деталей. */
  _updateBestiaryDetail() {
    const detail = this._bestiaryOverlay.querySelector('#bestiaryDetail');
    const id = Bestiary.selectedEnemyId;
    if (!id || !window.ENEMY_TYPES || !ENEMY_TYPES[id]) {
      detail.innerHTML = `
        <div class="bestiary-detail-empty">
          <div class="bestiary-detail-empty-icon">🔍</div>
          <div class="bestiary-detail-empty-text">${t('bestiary_select_enemy')}</div>
        </div>`;
      return;
    }

    const cfg = ENEMY_TYPES[id];
    const desc = Bestiary.getDescription(id);
    const abilities = Bestiary.getAbilities(id);
    const speedLabel = Bestiary.getSpeedLabel(id);
    const xpMin = cfg.xp ? cfg.xp[0] : 0;
    const xpMax = cfg.xp ? cfg.xp[1] : 0;

    // Крупный спрайт
    let spriteHtml = '';
    const sprite = window.getEnemySprite ? getEnemySprite(id) : null;
    if (sprite) {
      // Рисуем в canvas 48×48 и масштабируем отображение
      const cvs = document.createElement('canvas');
      cvs.width = 32; cvs.height = 32;
      cvs.style.imageRendering = 'pixelated';
      cvs.style.width = '96px'; cvs.style.height = '96px';
      cvs.className = 'bestiary-detail-sprite';
      const ctx2 = cvs.getContext('2d');
      ctx2.imageSmoothingEnabled = false;
      ctx2.drawImage(sprite, 0, 0, 32, 32);
      spriteHtml = cvs.outerHTML;
    } else {
      spriteHtml = `<div class="bestiary-detail-sprite-fallback" style="background:${cfg.color};border-color:${cfg.stroke || '#666'};">${cfg.letter}</div>`;
    }

    // Тир
    const tierNames = { 0: 'Special', 1: 'Tier I', 2: 'Tier II', 3: 'Tier III', 4: 'Tier IV', 5: 'Tier V' };
    const tierLabel = tierNames[cfg.tier] || 'Tier ' + cfg.tier;

    let html = `
      <div class="bestiary-detail-card">
        <div class="bestiary-detail-sprite-wrap">${spriteHtml}</div>
        <div class="bestiary-detail-name">${cfg.name}</div>
        <div class="bestiary-detail-tier">${tierLabel}</div>
        <div class="bestiary-detail-divider"></div>
        <div class="bestiary-detail-desc">"${desc}"</div>
        <div class="bestiary-detail-divider"></div>
        <div class="bestiary-detail-stats">
          <div class="bestiary-stat-row"><span class="bestiary-stat-label">❤ HP:</span><span class="bestiary-stat-value">${cfg.hp}</span></div>
          <div class="bestiary-stat-row"><span class="bestiary-stat-label">⚔ Урон:</span><span class="bestiary-stat-value">${cfg.damage}</span></div>
          <div class="bestiary-stat-row"><span class="bestiary-stat-label">🏃 Скорость:</span><span class="bestiary-stat-value">${speedLabel}</span></div>
          <div class="bestiary-stat-row"><span class="bestiary-stat-label">✨ Опыт:</span><span class="bestiary-stat-value">${xpMin}–${xpMax}</span></div>
        </div>`;

    if (abilities) {
      html += `
        <div class="bestiary-detail-divider"></div>
        <div class="bestiary-detail-abilities">
          <div class="bestiary-abilities-title">⚡ Особые способности</div>
          <div class="bestiary-abilities-text">${abilities}</div>
        </div>`;
    }

    html += `</div>`;
    detail.innerHTML = html;

    // Заменяем canvas placeholder на реальный спрайт (innerHTML теряет canvas)
    if (sprite) {
      const wrap = detail.querySelector('.bestiary-detail-sprite-wrap');
      wrap.innerHTML = '';
      const cvs = document.createElement('canvas');
      cvs.width = 32; cvs.height = 32;
      cvs.style.imageRendering = 'pixelated';
      cvs.style.width = '96px';
      cvs.style.height = '96px';
      cvs.className = 'bestiary-detail-sprite';
      const ctx2 = cvs.getContext('2d');
      ctx2.imageSmoothingEnabled = false;
      ctx2.drawImage(sprite, 0, 0, 32, 32);
      wrap.appendChild(cvs);
    }
  },

  /* ============================================================
     КОДЕКС (КНИГА)
     ============================================================ */
  showCodex(onBack) {
    if (!this._codexOverlay) this._buildCodexOverlay();
    this._updateCodexOverlay('weapons');
    this._codexOverlay._onBack = onBack;
    this._codexOverlay.classList.add('active');
  },

  _buildCodexOverlay() {
    const ov = document.createElement('div');
    ov.id = 'codexOverlay';
    ov.className = 'overlay camp-overlay';
    ov.innerHTML = `
      <div class="camp-bg" style="max-height:95vh;overflow-y:auto;">
        <h1 class="camp-title" style="font-size:1.3em;">${t('codex_title')}</h1>
        <div class="codex-tabs">
          <button class="codex-tab active" data-tab="weapons">${t('codex_tab_weapons')}</button>
          <button class="codex-tab" data-tab="abilities">${t('codex_tab_abilities')}</button>
          <button class="codex-tab" data-tab="evolutions">${t('codex_tab_evolutions')}</button>
        </div>
        <div id="codexContent" class="codex-content"></div>
        <button id="codexBackBtn" class="btn" style="margin-top:12px;">${t('codex_back')}</button>
      </div>
    `;
    document.body.appendChild(ov);
    this._codexOverlay = ov;
    ov.querySelector('#codexBackBtn').addEventListener('click', () => {
      ov.classList.remove('active');
      if (ov._onBack) ov._onBack();
    });
    ov.querySelectorAll('.codex-tab').forEach(tab => {
      tab.addEventListener('click', () => {
        ov.querySelectorAll('.codex-tab').forEach(t => t.classList.remove('active'));
        tab.classList.add('active');
        this._updateCodexOverlay(tab.dataset.tab);
      });
    });
  },

  _updateCodexOverlay(tab) {
    const content = this._codexOverlay.querySelector('#codexContent');
    content.innerHTML = '';
    if (tab === 'weapons') {
      this._renderCodexWeapons(content);
    } else if (tab === 'abilities') {
      this._renderCodexAbilities(content);
    } else if (tab === 'evolutions') {
      this._renderCodexEvolutions(content);
    }
  },

  _renderCodexWeapons(container) {
    const allWeapons = [...(window.WEAPON_INFO || []), ...(window.EXCLUSIVE_WEAPON_INFO || [])];
    for (const info of allWeapons) {
      const unlocked = Codex.isWeaponUnlocked(info.id);
      const card = document.createElement('div');
      card.className = 'codex-card' + (unlocked ? ' unlocked' : ' locked');
      if (unlocked) {
        card.innerHTML = `
          <div class="codex-card-icon">${info.icon || '?'}</div>
          <div class="codex-card-name">${info.name}</div>
          <div class="codex-card-desc">${info.desc || ''}</div>
        `;
        // Шаг 2: пиксельный спрайт
        const iconEl = card.querySelector('.codex-card-icon');
        const WS = window.WEAPON_SPRITES;
        const spr = WS ? WS[info.id] : null;
        if (spr && iconEl) {
          iconEl.textContent = '';
          iconEl.style.backgroundImage = 'url(' + spr.toDataURL() + ')';
          iconEl.style.backgroundSize = 'contain';
          iconEl.style.backgroundRepeat = 'no-repeat';
          iconEl.style.backgroundPosition = 'center';
          iconEl.style.imageRendering = 'pixelated';
        }
      } else {
        card.innerHTML = `
          <div class="codex-card-icon locked-icon">?</div>
          <div class="codex-card-name">???</div>
        `;
      }
      container.appendChild(card);
    }
  },

  _renderCodexAbilities(container) {
    const allAbilities = window.ABILITY_INFO || [];
    for (const info of allAbilities) {
      const unlocked = Codex.isAbilityUnlocked(info.id);
      const card = document.createElement('div');
      card.className = 'codex-card' + (unlocked ? ' unlocked' : ' locked');
      if (unlocked) {
        card.innerHTML = `
          <div class="codex-card-icon">${info.icon || '?'}</div>
          <div class="codex-card-name">${info.name}</div>
          <div class="codex-card-desc">${info.desc || ''}</div>
        `;
        // Шаг 2: пиксельный спрайт
        const iconEl = card.querySelector('.codex-card-icon');
        const AS = window.ABILITY_SPRITES;
        const spr = AS ? AS[info.id] : null;
        if (spr && iconEl) {
          iconEl.textContent = '';
          iconEl.style.backgroundImage = 'url(' + spr.toDataURL() + ')';
          iconEl.style.backgroundSize = 'contain';
          iconEl.style.backgroundRepeat = 'no-repeat';
          iconEl.style.backgroundPosition = 'center';
          iconEl.style.imageRendering = 'pixelated';
        }
      } else {
        card.innerHTML = `
          <div class="codex-card-icon locked-icon">?</div>
          <div class="codex-card-name">???</div>
        `;
      }
      container.appendChild(card);
    }
  },

  _renderCodexEvolutions(container) {
    const allEvo = [...(window.EVOLUTIONS || []), ...(window.SUPER_EVOLUTIONS || [])];
    for (const evo of allEvo) {
      const resultId = evo.resultId;
      const unlocked = Codex.isEvolutionUnlocked(resultId);
      const card = document.createElement('div');
      card.className = 'codex-card' + (unlocked ? ' unlocked' : ' locked');
      if (unlocked) {
        card.innerHTML = `
          <div class="codex-card-icon">${evo.resultIcon || '?'}</div>
          <div class="codex-card-name">${evo.resultName}</div>
          <div class="codex-card-desc">${evo.desc || ''}</div>
        `;
        // Шаг 2: пиксельный спрайт эволюции
        const iconEl = card.querySelector('.codex-card-icon');
        const ES = window.EVOLUTION_SPRITES;
        const spr = ES ? ES[resultId] : null;
        if (spr && iconEl) {
          iconEl.textContent = '';
          iconEl.style.backgroundImage = 'url(' + spr.toDataURL() + ')';
          iconEl.style.backgroundSize = 'contain';
          iconEl.style.backgroundRepeat = 'no-repeat';
          iconEl.style.backgroundPosition = 'center';
          iconEl.style.imageRendering = 'pixelated';
        }
      } else {
        card.innerHTML = `
          <div class="codex-card-icon locked-icon">?</div>
          <div class="codex-card-name">???</div>
        `;
      }
      container.appendChild(card);
    }
  },

  /* ============================================================
     ОКНО СТАТИСТИКИ ПОСЛЕ ЗАБЕГА
     ============================================================ */
  showRunStats(stats, onContinue) {
    if (!this._runStatsOverlay) this._buildRunStatsOverlay();
    this._updateRunStats(stats);
    this._runStatsOverlay._onContinue = onContinue;
    this._runStatsOverlay.classList.add('active');
  },

  _buildRunStatsOverlay() {
    const ov = document.createElement('div');
    ov.id = 'runStatsOverlay';
    ov.className = 'overlay camp-overlay';
    ov.innerHTML = `
      <div class="camp-bg">
        <h1 class="camp-title" style="font-size:1.4em;">${t('stats_title')}</h1>
        <div id="runStatsContent" class="run-stats-content"></div>
        <button id="runStatsContinueBtn" class="btn" style="margin-top:16px;">${t('stats_continue')}</button>
      </div>
    `;
    document.body.appendChild(ov);
    this._runStatsOverlay = ov;
    ov.querySelector('#runStatsContinueBtn').addEventListener('click', () => {
      ov.classList.remove('active');
      if (ov._onContinue) ov._onContinue();
    });
  },

  _updateRunStats(stats) {
    const content = this._runStatsOverlay.querySelector('#runStatsContent');
    // Строим список статистик
    const items = [
      { label: t('stats_time'), value: stats.time || '00:00' },
      { label: t('stats_kills'), value: stats.kills || 0 },
      { label: t('stats_level'), value: stats.level || 1 },
      { label: t('stats_wave'), value: stats.wave || 0 },
      { label: t('stats_maps'), value: stats.mapsCleared || 0 },
      { label: t('stats_gold_collected'), value: stats.goldCollected || 0 },
      { label: t('stats_gold_bonus'), value: stats.goldBonus || 0 },
      { label: t('stats_gold_total'), value: stats.goldTotal || 0 },
      { label: t('stats_damage_dealt'), value: stats.damageDealt || '—' },
      { label: t('stats_damage_taken'), value: stats.damageTaken || '—' },
      { label: t('stats_bosses'), value: stats.bossKills || 0 },
      { label: t('stats_chests'), value: stats.chestsOpened || 0 },
      { label: t('stats_best_roll'), value: stats.bestRoll || '—' },
    ];
    let html = '<div class="run-stats-grid">';
    for (const item of items) {
      html += `<div class="run-stats-row"><span class="run-stats-label">${item.label}</span><span class="run-stats-value">${item.value}</span></div>`;
    }
    html += '</div>';
    content.innerHTML = html;
  },

  /* ============================================================
     ПАУЗА: кнопка «Выйти в лагерь»
     ============================================================ */
  addPauseExitButton() {
    const pauseOv = document.getElementById('pauseOverlay');
    if (!pauseOv) return;
    if (pauseOv.querySelector('#pauseExitBtn')) return; // уже добавлена
    const btn = document.createElement('button');
    btn.id = 'pauseExitBtn';
    btn.className = 'btn btn-secondary';
    btn.textContent = t('pause_exit');
    btn.style.marginTop = '12px';
    btn.addEventListener('click', () => {
      if (window.Game) {
        Game.exitToMenu();
      }
    });
    pauseOv.appendChild(btn);
  },

  /* ============================================================
     КНОПКА «НАЗАД» НА СМАРТФОНЕ
     ============================================================ */
  initBackButton() {
    // Обработка hardware back button (Android) через history API
    // Пушим состояние, чтобы при нажатии «назад» вызвать popstate
    window.history.pushState({ game: true }, '');
    window.addEventListener('popstate', (e) => {
      // Предотвращаем реальный уход назад
      window.history.pushState({ game: true }, '');
      this._handleBackButton();
    });
  },

  _handleBackButton() {
    if (!window.Game) return;
    if (Game.state === 'playing') {
      // Открыть паузу
      Game.togglePause();
    } else if (Game.state === 'paused') {
      // Выйти в лагерь (показать статистику)
      Game.exitToMenu();
    }
    // В остальных состояниях (camp, levelup, chest) — игнорируем
  },
};

window.UIExtended = UIExtended;

// === js/meta/campaign.js ===
'use strict';
/* ============================================================
   campaign.js — Шаг 16: Сюжетный режим (кампания).
   5 карт со сквозным сюжетом, целями, диалогами, финальным боссом.
   ============================================================ */

const CAMPAIGN_KEY = 'd20_campaignProgress';

/* ---------- Диалоги ---------- */
const CAMPAIGN_DIALOGUES = {
  beforeMap1: t('campaign_dialogue_before1'),
  afterMap1: t('campaign_dialogue_after1'),
  afterMap2: t('campaign_dialogue_after2'),
  afterMap3: t('campaign_dialogue_after3'),
  mageSaved: t('campaign_dialogue_mage'),
  afterMap4: t('campaign_dialogue_after4'),
  beforeBoss: t('campaign_dialogue_boss'),
  victory: t('campaign_dialogue_victory'),
};

/* ---------- Карты кампании ---------- */
const CAMPAIGN_MAPS = [
  {
    id: 1,
    name: t('campaign_map1'),
    biome: 'crypt',
    objective: {
      type: 'activate',
      description: t('campaign_obj_activate'),
      target: 2,
    },
    timeLimit: 0, // без лимита
    specialObjects: ['altars'],
    dialogueBefore: 'beforeMap1',
    dialogueAfter: 'afterMap1',
    bossId: null, // опциональный страж
    rewards: { gold: 200, rep: 30 },
  },
  {
    id: 2,
    name: t('campaign_map2'),
    biome: 'ice_caves',
    objective: {
      type: 'survive',
      description: t('campaign_obj_survive'),
      target: 480, // 8 минут в секундах
    },
    timeLimit: 480,
    specialObjects: [],
    dialogueBefore: null,
    dialogueAfter: 'afterMap2',
    bossId: 'boss_ice_serpent', // мини-босс на 4-й минуте
    bossSpawnTime: 240,
    rewards: { gold: 300, rep: 40 },
  },
  {
    id: 3,
    name: t('campaign_map3'),
    biome: 'fire_mines',
    objective: {
      type: 'kill_boss',
      description: t('campaign_obj_kill_boss'),
      target: 1,
    },
    timeLimit: 0,
    specialObjects: ['fire_heart'],
    dialogueBefore: null,
    dialogueAfter: 'afterMap3',
    bossId: 'boss_magma_giant',
    bossSpawnTime: 30,
    rewards: { gold: 400, rep: 50 },
  },
  {
    id: 4,
    name: t('campaign_map4'),
    biome: 'forest_ruins',
    objective: {
      type: 'rescue',
      description: t('campaign_obj_rescue'),
      target: 1,
    },
    timeLimit: 0,
    specialObjects: ['cage', 'key_enemy'],
    dialogueBefore: null,
    dialogueAfter: 'afterMap4',
    bossId: null,
    rewards: { gold: 300, rep: 50 },
  },
  {
    id: 5,
    name: t('campaign_map5'),
    biome: 'castle',
    objective: {
      type: 'kill_boss',
      description: t('campaign_obj_kill_dragon'),
      target: 1,
    },
    timeLimit: 0,
    specialObjects: [],
    dialogueBefore: 'beforeBoss',
    dialogueAfter: null, // victory screen instead
    bossId: 'boss_ancient_dragon',
    bossSpawnTime: 30,
    rewards: { gold: 1000, rep: 200 },
  },
];

/* ---------- Campaign State Manager ---------- */
const Campaign = {
  active: false,          // кампания запущена?
  currentMapIndex: 0,     // индекс текущей карты (0-based)
  objective: null,        // { type, description, current, target, completed }
  mapTime: 0,             // время на текущей карте
  bossSpawned: false,     // босс карты уже появился?
  bossDefeated: false,    // босс убит?
  specialObjects: [],     // массив специальных объектов на карте
  hasKey: false,          // ключ подобран (для карты 4)?
  mageBlessing: false,    // благословение мага получено?
  newGamePlus: false,     // режим Новая Игра+
  dialogueQueue: [],      // очередь диалогов для показа

  /* ---------- Сохранение/загрузка ---------- */

  loadProgress() {
    try {
      const raw = SafeStorage.getItem(CAMPAIGN_KEY);
      if (raw) return JSON.parse(raw);
    } catch (e) { /* ignore */ }
    return { currentMap: 1, completed: false, newGamePlus: false, mageBlessing: false };
  },

  saveProgress() {
    const data = {
      currentMap: this.currentMapIndex + 1,
      completed: false,
      newGamePlus: this.newGamePlus,
      mageBlessing: this.mageBlessing,
    };
    try {
      SafeStorage.setItem(CAMPAIGN_KEY, JSON.stringify(data));
    } catch (e) { /* ignore */ }
  },

  saveCompleted() {
    const data = {
      currentMap: 5,
      completed: true,
      newGamePlus: true,
      mageBlessing: this.mageBlessing,
    };
    try {
      SafeStorage.setItem(CAMPAIGN_KEY, JSON.stringify(data));
    } catch (e) { /* ignore */ }
  },

  /* ---------- Запуск кампании ---------- */

  start() {
    const progress = this.loadProgress();
    this.active = true;
    this.currentMapIndex = progress.completed ? 0 : Math.max(0, (progress.currentMap || 1) - 1);
    this.newGamePlus = progress.newGamePlus || false;
    this.mageBlessing = progress.mageBlessing || false;
    this.hasKey = false;
    this.bossSpawned = false;
    this.bossDefeated = false;
    this.mapTime = 0;
    this.specialObjects = [];
    this.objective = null;

    // Установить состояние игры в 'dialogue' чтобы не обновлять мир
    if (window.Game) Game.state = 'dialogue';

    // Показать начальный диалог
    const mapCfg = CAMPAIGN_MAPS[this.currentMapIndex];
    if (this.currentMapIndex === 0) {
      this.dialogueQueue = ['beforeMap1'];
    } else if (mapCfg.dialogueBefore) {
      this.dialogueQueue = [mapCfg.dialogueBefore];
    } else {
      this.dialogueQueue = [];
    }

    // Показать диалог перед загрузкой карты
    this._showNextDialogue(() => {
      this._loadCurrentMap();
    });
  },

  /** Начать заново (после завершения). */
  startNewGamePlus() {
    this.newGamePlus = true;
    this.currentMapIndex = 0;
    this.mageBlessing = false;
    this.start();
  },

  /* ---------- Загрузка карты ---------- */

  _loadCurrentMap() {
    const mapCfg = CAMPAIGN_MAPS[this.currentMapIndex];
    if (!mapCfg) return;

    // Инициализация состояния карты
    this.mapTime = 0;
    this.bossSpawned = false;
    this.bossDefeated = false;
    this.hasKey = false;
    this.specialObjects = [];

    // Инициализация цели
    this.objective = {
      type: mapCfg.objective.type,
      description: mapCfg.objective.description,
      current: 0,
      target: mapCfg.objective.target,
      completed: false,
    };

    // Запуск игры с параметрами кампании
    if (window.Game) {
      Game._startCampaignMap(mapCfg);
    }

    this.saveProgress();
  },

  /* ---------- Обновление каждый кадр ---------- */

  update(dt) {
    if (!this.active) return;
    this.mapTime += dt;

    const mapCfg = CAMPAIGN_MAPS[this.currentMapIndex];
    if (!mapCfg) return;

    // Спавн босса по таймеру
    if (mapCfg.bossId && mapCfg.bossSpawnTime && !this.bossSpawned && this.mapTime >= mapCfg.bossSpawnTime) {
      this.bossSpawned = true;
      this._spawnCampaignBoss(mapCfg.bossId);
    }

    // Проверка целей
    this._checkObjective(mapCfg, dt);
  },

  /* ---------- Проверка целей ---------- */

  _checkObjective(mapCfg, dt) {
    if (!this.objective || this.objective.completed) return;

    switch (this.objective.type) {
      case 'survive':
        this.objective.current = Math.floor(this.mapTime);
        if (this.mapTime >= this.objective.target) {
          this._completeObjective();
        }
        break;

      case 'kill_boss':
        if (this.bossDefeated) {
          this.objective.current = 1;
          this._completeObjective();
        }
        break;

      case 'activate':
        // Проверяется извне (при взаимодействии с алтарями)
        break;

      case 'rescue':
        // Проверяется извне (при открытии клетки)
        break;

      case 'fetch':
        // Проверяется извне (при подборе предмета)
        break;
    }
  },

  /* ---------- Внешние события ---------- */

  /** Вызывается когда алтарь активирован. */
  onAltarActivated() {
    if (!this.objective || this.objective.type !== 'activate') return;
    this.objective.current++;
    if (this.objective.current >= this.objective.target) {
      this._completeObjective();
    }
  },

  /** Вызывается когда босс кампании убит. */
  onCampaignBossKilled() {
    this.bossDefeated = true;
    // Для карты 3: спавнить Огненное сердце
    if (this.currentMapIndex === 2) {
      this._spawnFireHeart();
    }
  },

  /** Вызывается когда ключ подобран (карта 4). */
  onKeyPickedUp() {
    this.hasKey = true;
    if (window.Particles && window.Game && Game.player) {
      Particles.text(Game.player.x, Game.player.y - 30, t('campaign_key_obtained'), 1.5, '#ffd700', 14);
    }
  },

  /** Вызывается когда клетка открыта (карта 4). */
  onCageOpened() {
    if (!this.objective || this.objective.type !== 'rescue') return;
    this.mageBlessing = true;
    this.objective.current = 1;

    // Диалог мага
    if (window.UI && UI.showCampaignDialogue) {
      UI.showCampaignDialogue(CAMPAIGN_DIALOGUES.mageSaved, () => {
        this._completeObjective();
      });
    } else {
      this._completeObjective();
    }

    // Применить благословение
    if (window.Game && Game.player) {
      Game.player.magicDamageMul *= 1.20;
    }

    // Сохранить благословение
    this.saveProgress();
  },

  /** Вызывается когда Огненное сердце подобрано. */
  onFireHeartPickedUp() {
    if (this.currentMapIndex === 2 && this.objective && this.objective.type === 'kill_boss') {
      this._completeObjective();
    }
    if (window.Particles && window.Game && Game.player) {
      Particles.text(Game.player.x, Game.player.y - 30, t('campaign_fire_heart'), 2.0, '#ff6600', 16);
    }
  },

  /* ---------- Завершение цели ---------- */

  _completeObjective() {
    if (!this.objective || this.objective.completed) return;
    this.objective.completed = true;

    if (window.Particles && window.Game && Game.player) {
      Particles.text(Game.player.x, Game.player.y - 40, t('campaign_objective_done'), 2.0, '#2ecc71', 18);
      Particles.burst(Game.player.x, Game.player.y, 15, {
        color: '#2ecc71', speedMin: 80, speedMax: 200,
        lifeMin: 0.5, lifeMax: 1.0, sizeMin: 3, sizeMax: 6,
      });
    }

    // Небольшая задержка перед переходом
    setTimeout(() => {
      this._onMapComplete();
    }, 2000);
  },

  /* ---------- Завершение карты ---------- */

  _onMapComplete() {
    const mapCfg = CAMPAIGN_MAPS[this.currentMapIndex];
    if (!mapCfg) return;

    // Награды
    if (window.MetaProgress && MetaProgress.data) {
      const goldMul = this.newGamePlus ? 1.20 : 1.0;
      MetaProgress.addGold(Math.floor(mapCfg.rewards.gold * goldMul));
      MetaProgress.addReputation(mapCfg.rewards.rep);
    }

    // Финал?
    if (this.currentMapIndex >= CAMPAIGN_MAPS.length - 1) {
      this._onCampaignComplete();
      return;
    }

    // Показать диалог после карты, затем перейти к следующей
    const dialogueKey = mapCfg.dialogueAfter;
    if (dialogueKey && CAMPAIGN_DIALOGUES[dialogueKey]) {
      if (window.UI && UI.showCampaignDialogue) {
        UI.showCampaignDialogue(CAMPAIGN_DIALOGUES[dialogueKey], () => {
          this._advanceToNextMap();
        });
      } else {
        this._advanceToNextMap();
      }
    } else {
      this._advanceToNextMap();
    }
  },

  _advanceToNextMap() {
    this.currentMapIndex++;
    const mapCfg = CAMPAIGN_MAPS[this.currentMapIndex];

    // Показать диалог перед картой если есть
    if (mapCfg && mapCfg.dialogueBefore && CAMPAIGN_DIALOGUES[mapCfg.dialogueBefore]) {
      if (window.UI && UI.showCampaignDialogue) {
        UI.showCampaignDialogue(CAMPAIGN_DIALOGUES[mapCfg.dialogueBefore], () => {
          this._loadCurrentMap();
        });
      } else {
        this._loadCurrentMap();
      }
    } else {
      this._loadCurrentMap();
    }
  },

  /* ---------- Победа ---------- */

  _onCampaignComplete() {
    this.active = false;
    this.saveCompleted();

    // Достижение
    if (window.MetaProgress && MetaProgress.data) {
      if (!MetaProgress.data.achievements) MetaProgress.data.achievements = [];
      if (!MetaProgress.data.achievements.includes('dragon_slayer')) {
        MetaProgress.data.achievements.push('dragon_slayer');
      }
      MetaProgress.save();
    }

    // Показать экран победы
    if (window.UI && UI.showCampaignVictory) {
      UI.showCampaignVictory(CAMPAIGN_DIALOGUES.victory, () => {
        // Вернуться в лагерь
        if (window.Game) {
          Game.state = 'camp';
          UI.hideAll();
          UI.showCamp();
        }
      });
    }
  },

  /* ---------- Смерть в кампании ---------- */

  onPlayerDeath() {
    // Сохраняем текущую карту (не сбрасываем)
    this.saveProgress();
    this.active = false;
  },

  /* ---------- Спавн босса ---------- */

  _spawnCampaignBoss(bossId) {
    if (!window.Bosses || !window.Game || !Game.player) return;

    // Для Древнего дракона — особая обработка
    if (bossId === 'boss_ancient_dragon') {
      const boss = Bosses._createBoss(bossId, Game.player, 'campaign', 0);
      if (boss) {
        boss.isCampaignBoss = true;
        Bosses.current = boss;
        Bosses._announcesBoss(boss.cfg.name);
        // Шаг 18: музыка финального босса
        if (window.GameAudio) GameAudio.playMusic('boss');
      }
      return;
    }

    // Обычный босс кампании (усиленный на 30%)
    const boss = Bosses._createBoss(bossId, Game.player, 'campaign', 0);
    if (boss) {
      boss.hp = Math.floor(boss.hp * 1.30);
      boss.maxHp = boss.hp;
      boss.isCampaignBoss = true;
      Bosses.current = boss;
      Bosses._announcesBoss(boss.cfg.name);
    }
  },

  /* ---------- Спавн огненного сердца ---------- */

  _spawnFireHeart() {
    if (!window.Game || !window.Bosses) return;
    const boss = Bosses.current;
    const x = boss ? boss.x : (Game.player ? Game.player.x + 50 : 500);
    const y = boss ? boss.y : (Game.player ? Game.player.y : 500);

    this.specialObjects.push({
      type: 'fire_heart',
      x: x,
      y: y,
      size: 24,
      pulse: 0,
      pickedUp: false,
    });

    if (window.Particles) {
      Particles.burst(x, y, 12, {
        color: '#ff6600', speedMin: 60, speedMax: 150,
        lifeMin: 0.5, lifeMax: 1.0, sizeMin: 3, sizeMax: 5,
      });
    }
  },

  /* ---------- Диалоги ---------- */

  _showNextDialogue(onDone) {
    if (this.dialogueQueue.length === 0) {
      onDone && onDone();
      return;
    }
    const key = this.dialogueQueue.shift();
    const text = CAMPAIGN_DIALOGUES[key];
    if (!text) { onDone && onDone(); return; }

    if (window.UI && UI.showCampaignDialogue) {
      UI.showCampaignDialogue(text, () => {
        this._showNextDialogue(onDone);
      });
    } else {
      onDone && onDone();
    }
  },

  /* ---------- Получить текущую информацию ---------- */

  getCurrentMapConfig() {
    if (!this.active) return null;
    return CAMPAIGN_MAPS[this.currentMapIndex] || null;
  },

  getObjectiveText() {
    if (!this.objective) return '';
    const o = this.objective;
    if (o.type === 'survive') {
      const remaining = Math.max(0, o.target - o.current);
      return `${o.description}: ${Utils.formatTime(remaining)}`;
    }
    if (o.type === 'activate' || o.type === 'rescue' || o.type === 'kill_boss') {
      return `${o.description}: ${o.current}/${o.target}`;
    }
    return o.description;
  },

  isActive() {
    return this.active;
  },
};

// Экспорт
window.Campaign = Campaign;
window.CAMPAIGN_MAPS = CAMPAIGN_MAPS;
window.CAMPAIGN_DIALOGUES = CAMPAIGN_DIALOGUES;

// === js/systems/urns.js ===
'use strict';
/* ============================================================
   urns.js — Урны и зелёные яблоки (Шаг 1).

   Урны:
   - Спавнятся раз в 60 сек в случайном проходимом месте.
   - Максимум 3 одновременно на карте.
   - 10 HP, не двигаются, не атакуют.
   - При разрушении: 50% — зелёное яблоко, 50% — немного золота (5-10).

   Зелёные яблоки:
   - +75 HP при подборе (не превышая максимум).
   - Притягиваются магнитом подбора.
   - Звук «хруст» при подборе.
   ============================================================ */

/* ---------- Конфигурация ---------- */
const URN_CONFIG = {
  SPAWN_INTERVAL: 60,       // секунд между спавнами
  MAX_ON_MAP: 3,            // максимум одновременно
  HP: 10,                   // HP урны
  SIZE: 16,                 // визуальный размер (16x16)
  APPLE_CHANCE: 0.50,       // 50% шанс яблока
  GOLD_MIN: 5,              // золото если не яблоко
  GOLD_MAX: 10,
  APPLE_HEAL: 75,           // HP от яблока
  APPLE_SIZE: 12,           // визуальный размер яблока
  MAGNET_SPEED: 300,        // скорость притяжения яблока
};

/* ---------- Спрайты (генерируются один раз) ---------- */
let URN_SPRITE = null;
let APPLE_SPRITE = null;

function _generateUrnSprite() {
  const size = 16;
  const c = document.createElement('canvas');
  c.width = size; c.height = size;
  const ctx = c.getContext('2d');
  // Коричневая/серая ваза пиксельная
  const body = '#8b6914';
  const dark = '#5a4010';
  const rim = '#a07820';
  const highlight = '#c9a040';
  // Корпус урны (пузатая форма)
  ctx.fillStyle = body;
  ctx.fillRect(5, 4, 6, 9);   // основное тело
  ctx.fillRect(4, 6, 8, 5);   // пузо
  ctx.fillRect(3, 7, 10, 3);  // самое широкое место
  // Горлышко
  ctx.fillStyle = rim;
  ctx.fillRect(6, 2, 4, 2);   // шея
  ctx.fillRect(5, 1, 6, 1);   // ободок
  // Дно
  ctx.fillStyle = dark;
  ctx.fillRect(5, 13, 6, 1);
  ctx.fillRect(4, 12, 8, 1);
  // Тень/объём
  ctx.fillStyle = dark;
  ctx.fillRect(4, 8, 1, 3);
  ctx.fillRect(10, 8, 1, 3);
  // Блик
  ctx.fillStyle = highlight;
  ctx.fillRect(6, 6, 1, 3);
  ctx.fillRect(7, 5, 1, 2);
  return c;
}

function _generateAppleSprite() {
  const size = 12;
  const c = document.createElement('canvas');
  c.width = size; c.height = size;
  const ctx = c.getContext('2d');
  // Зелёное яблоко с красным бочком
  const green = '#4caf50';
  const darkGreen = '#2e7d32';
  const red = '#c62828';
  const highlight = '#a5d6a7';
  const stem = '#5d4037';
  // Тело яблока
  ctx.fillStyle = green;
  ctx.fillRect(3, 3, 6, 6);
  ctx.fillRect(2, 4, 8, 4);
  ctx.fillRect(4, 2, 4, 1);
  ctx.fillRect(3, 9, 6, 1);
  // Красный бочок (правая часть)
  ctx.fillStyle = red;
  ctx.fillRect(7, 4, 2, 3);
  ctx.fillRect(8, 3, 1, 4);
  // Тень
  ctx.fillStyle = darkGreen;
  ctx.fillRect(2, 7, 2, 1);
  ctx.fillRect(3, 8, 1, 1);
  // Блик
  ctx.fillStyle = highlight;
  ctx.fillRect(4, 3, 1, 2);
  ctx.fillRect(3, 4, 1, 1);
  // Стебель
  ctx.fillStyle = stem;
  ctx.fillRect(5, 0, 1, 3);
  ctx.fillRect(6, 1, 1, 1);
  return c;
}

/* ---------- Объекты ---------- */

const Urns = {
  /** Список активных урн на карте. */
  list: [],
  /** Список активных яблок на земле. */
  apples: [],
  /** Таймер спавна. */
  spawnTimer: 30, // первая урна через 30 сек (не 60)

  /** Инициализация при старте забега. */
  init() {
    this.list = [];
    this.apples = [];
    this.spawnTimer = 30;
    // Генерация спрайтов при первом вызове
    if (!URN_SPRITE) URN_SPRITE = _generateUrnSprite();
    if (!APPLE_SPRITE) APPLE_SPRITE = _generateAppleSprite();
  },

  /** Обновление: спавн, проверка урона, подбор яблок. */
  update(dt, player) {
    if (!player) return;

    // Спавн урн по таймеру
    this.spawnTimer -= dt;
    if (this.spawnTimer <= 0 && this.list.length < URN_CONFIG.MAX_ON_MAP) {
      this._spawnUrn(player);
      this.spawnTimer = URN_CONFIG.SPAWN_INTERVAL;
    }

    // Обновление яблок: магнит + подбор
    const pickupR = CONFIG.PLAYER.PICKUP_RADIUS * player.pickupMul;
    const pickupR2 = pickupR * pickupR;
    const collectR = (player.size * 0.5 + 8);
    const collectR2 = collectR * collectR;

    for (let i = this.apples.length - 1; i >= 0; i--) {
      const apple = this.apples[i];
      apple.pulse += dt;
      const dx = player.x - apple.x;
      const dy = player.y - apple.y;
      const d2 = dx * dx + dy * dy;

      // Притяжение магнитом
      if (d2 <= pickupR2) {
        const d = Math.sqrt(d2) || 1;
        apple.x += (dx / d) * URN_CONFIG.MAGNET_SPEED * dt;
        apple.y += (dy / d) * URN_CONFIG.MAGNET_SPEED * dt;
      }

      // Подбор
      if (d2 <= collectR2) {
        // Восстановление HP (не выше максимума)
        const heal = Math.min(URN_CONFIG.APPLE_HEAL, player.maxHp - player.hp);
        player.hp += heal;
        // Звук хруста
        if (window.GameAudio) GameAudio.playSfx('apple_crunch');
        // Частицы исцеления
        if (window.Particles) {
          Particles.burst(player.x, player.y, 6, {
            color: '#4caf50', speedMin: 40, speedMax: 100,
            lifeMin: 0.3, lifeMax: 0.5, sizeMin: 2, sizeMax: 4,
          });
          if (heal > 0) {
            Particles.text(player.x, player.y - 20, `+${Math.round(heal)}`, 0.8, '#4caf50', 12);
          }
        }
        this.apples.splice(i, 1);
      }
    }
  },

  /** Нанести урон урне (вызывается из Game при попадании снаряда/мели). */
  damageUrn(urn, dmg) {
    if (!urn || urn.hp <= 0) return;
    urn.hp -= dmg;
    urn.flash = 0.1;
    if (urn.hp <= 0) {
      this._destroyUrn(urn);
    }
  },

  /** Проверить попадание снарядов игрока в урны. */
  checkProjectileHits(projectiles) {
    if (!projectiles || this.list.length === 0) return;
    const items = projectiles.items;
    for (let i = 0; i < items.length; i++) {
      const p = items[i];
      if (!p.active || p.owner !== 'player') continue;
      for (let j = this.list.length - 1; j >= 0; j--) {
        const urn = this.list[j];
        if (urn.hp <= 0) continue;
        const dx = p.x - urn.x;
        const dy = p.y - urn.y;
        const hitR = URN_CONFIG.SIZE * 0.5 + (p.radius || 5);
        if (dx * dx + dy * dy <= hitR * hitR) {
          this.damageUrn(urn, p.damage || 10);
          // Не удаляем снаряд — проходит сквозь урну
          break;
        }
      }
    }
  },

  /** Проверить мели-атаки оружий (проходим по урнам в радиусе). */
  checkMeleeHits(player) {
    if (this.list.length === 0) return;
    // Мели-оружия наносят урон через Game.damageEnemy, но урны не враги.
    // Вместо этого проверяем расстояние от игрока — если в пределах 50px,
    // наносим базовый урон при каждой атаке мечом.
    // Это интегрируется через отдельный вызов из main.js.
    for (let j = this.list.length - 1; j >= 0; j--) {
      const urn = this.list[j];
      if (urn.hp <= 0) continue;
      const dx = player.x - urn.x;
      const dy = player.y - urn.y;
      if (dx * dx + dy * dy <= 50 * 50) {
        this.damageUrn(urn, 5);
      }
    }
  },

  /** Спавн урны в случайной проходимой точке. */
  _spawnUrn(player) {
    if (!window.GameMap || !GameMap.dungeon) return;
    // Ищем проходимую точку не слишком близко к игроку
    let ux, uy;
    let found = false;
    for (let attempt = 0; attempt < 30; attempt++) {
      const rooms = GameMap.dungeon.rooms.filter(r => !r.isSecret);
      if (rooms.length === 0) return;
      const room = rooms[Math.floor(Math.random() * rooms.length)];
      const tx = room.x + 30 + Math.random() * (room.w - 60);
      const ty = room.y + 30 + Math.random() * (room.h - 60);
      // Проверка проходимости
      if (!GameMap.rectIsWalkable(tx, ty, 10)) continue;
      // Не слишком близко к игроку (мин 150px)
      const dx = tx - player.x, dy = ty - player.y;
      if (dx * dx + dy * dy < 150 * 150) continue;
      ux = tx; uy = ty;
      found = true;
      break;
    }
    if (!found) return;

    this.list.push({
      x: ux, y: uy,
      hp: URN_CONFIG.HP,
      maxHp: URN_CONFIG.HP,
      flash: 0,
      pulse: Math.random() * Math.PI * 2,
    });
  },

  /** Уничтожение урны — дроп яблока или золота. */
  _destroyUrn(urn) {
    // Удаляем из списка
    const idx = this.list.indexOf(urn);
    if (idx !== -1) this.list.splice(idx, 1);

    // Эффект разрушения
    if (window.Particles) {
      Particles.burst(urn.x, urn.y, 8, {
        color: '#8b6914', speedMin: 40, speedMax: 120,
        lifeMin: 0.2, lifeMax: 0.4, sizeMin: 2, sizeMax: 4,
      });
    }

    // Дроп
    if (Math.random() < URN_CONFIG.APPLE_CHANCE) {
      // Зелёное яблоко
      this.apples.push({
        x: urn.x + (Math.random() - 0.5) * 10,
        y: urn.y + (Math.random() - 0.5) * 10,
        pulse: 0,
      });
    } else {
      // Немного золота
      if (window.Game && Game.goldDrops && window.Loot) {
        const goldValue = URN_CONFIG.GOLD_MIN +
          Math.floor(Math.random() * (URN_CONFIG.GOLD_MAX - URN_CONFIG.GOLD_MIN + 1));
        Loot.dropGold(Game.goldDrops, urn.x, urn.y, goldValue);
      }
    }

    // Звук разрушения
    if (window.GameAudio) GameAudio.playSfx('urn_break');
  },

  /** Отрисовка урн и яблок. ctx уже сдвинут на -cam. */
  render(ctx, cam, viewW, viewH) {
    const minX = cam.x - 20, minY = cam.y - 20;
    const maxX = cam.x + viewW + 20, maxY = cam.y + viewH + 20;

    // Урны
    for (const urn of this.list) {
      if (urn.x < minX || urn.x > maxX || urn.y < minY || urn.y > maxY) continue;
      ctx.save();
      ctx.imageSmoothingEnabled = false;
      // Мерцание при попадании
      if (urn.flash > 0) {
        ctx.globalAlpha = 0.5 + Math.sin(urn.flash * 40) * 0.3;
        urn.flash -= 0.016; // примерно 1/60
      }
      const s = URN_CONFIG.SIZE;
      if (URN_SPRITE) {
        ctx.drawImage(URN_SPRITE, urn.x - s / 2, urn.y - s / 2, s, s);
      } else {
        ctx.fillStyle = '#8b6914';
        ctx.fillRect(urn.x - s / 2, urn.y - s / 2, s, s);
      }
      ctx.restore();
    }

    // Яблоки
    for (const apple of this.apples) {
      if (apple.x < minX || apple.x > maxX || apple.y < minY || apple.y > maxY) continue;
      const pulse = 1 + Math.sin(apple.pulse * 5) * 0.12;
      const s = URN_CONFIG.APPLE_SIZE * pulse;
      ctx.save();
      ctx.imageSmoothingEnabled = false;
      // Зелёное свечение
      ctx.shadowColor = 'rgba(76, 175, 80, 0.7)';
      ctx.shadowBlur = 8;
      if (APPLE_SPRITE) {
        ctx.drawImage(APPLE_SPRITE, apple.x - s / 2, apple.y - s / 2, s, s);
      } else {
        ctx.fillStyle = '#4caf50';
        ctx.beginPath();
        ctx.arc(apple.x, apple.y, s / 2, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.shadowBlur = 0;
      ctx.restore();
    }
  },

  /** Отрисовать индикатор HP над урнами (только для повреждённых). */
  renderHP(ctx) {
    for (const urn of this.list) {
      if (urn.hp >= urn.maxHp) continue;
      const w = 20, h = 3;
      const pct = Math.max(0, urn.hp / urn.maxHp);
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(urn.x - w / 2, urn.y - URN_CONFIG.SIZE / 2 - 6, w, h);
      ctx.fillStyle = '#4caf50';
      ctx.fillRect(urn.x - w / 2, urn.y - URN_CONFIG.SIZE / 2 - 6, w * pct, h);
    }
  },
};

window.Urns = Urns;
window.URN_CONFIG = URN_CONFIG;

// === js/core/registry.js ===
'use strict';
/* ============================================================
   registry.js — Единый реестр модулей.
   Гарантирует порядок инициализации и предоставляет
   безопасный доступ к модулям через Registry.get().
   Загружается ПОСЛЕДНИМ (перед state-machine.js).
   ============================================================ */

const Registry = {
  _modules: {},

  /**
   * Зарегистрировать модуль. Вызывается автоматически
   * (модули определяются через <script> в правильном порядке).
   */
  register(name, ref) {
    this._modules[name] = ref;
  },

  /** Получить модуль (или null если не загружен) */
  get(name) {
    return this._modules[name] || window[name] || null;
  },

  /** Проверить наличие модуля */
  has(name) {
    return !!(this._modules[name] || window[name]);
  },

  /**
   * Инициализировать все зарегистрированные модули.
   * Вызывается из Game.init() один раз.
   */
  initAll() {
    // 1. Утилиты (уже инициализированы определением)
    // 2. Карта
    if (window.GameMap) GameMap.precompute();

    // 3. Ввод
    if (window.Input) Input.init();

    // 4. Аудио
    if (window.GameAudio) GameAudio.init();

    // 5. Спрайты
    if (window.initSprites) initSprites();
    if (window.initBiomePreviews) initBiomePreviews();

    // 6. Мета-прогресс
    if (window.MetaProgress) MetaProgress.load();

    // 7. Бестиарий и кодекс
    if (window.Bestiary) Bestiary.load();
    if (window.Codex) Codex.load();

    // 8. Extended UI
    if (window.UIExtended) {
      UIExtended.addPauseExitButton();
      UIExtended.initBackButton();
    }
  }
};

window.Registry = Registry;

// === js/core/game-loop.js ===
'use strict';
/* ============================================================
   main.js — точка входа: инициализация, состояния, игровой цикл.
   ============================================================ */

// createParticle и фабрики частиц — в js/particles.js (Шаг 3).

/* ============================================================
   Базовые улучшения (как в Шаге 1, по ТЗ — пусть стакаются).
   Каждое имеет id, title, desc, apply(player) и available(player)
   (можно ли предложить — например, +1 missile всегда доступен,
   а HP — тоже всегда).
   ============================================================ */
const BASIC_UPGRADES = [
  { id: 'b_maxhp',     icon: '❤', title: t('upgrade_maxhp'),     desc: t('upgrade_maxhp_desc'),
    apply(p) { p.bonusMaxHp = (p.bonusMaxHp || 0) + 20; p.maxHp += 20; p.hp = Math.min(p.maxHp, p.hp + 20); }, available() { return true; } },
  { id: 'b_damage',    icon: '⚔', title: t('upgrade_damage'),         desc: t('upgrade_damage_desc'),
    apply(p) { p.damageMul *= 1.15; }, available() { return true; } },
  { id: 'b_speed',     icon: '➤', title: t('upgrade_speed'),     desc: t('upgrade_speed_desc'),
    apply(p) { p.speedMul *= 1.10; }, available() { return true; } },
  { id: 'b_weapon_cd', icon: '⏱', title: t('upgrade_weapon_cd'),  desc: t('upgrade_weapon_cd_desc'),
    apply(p) { p.weaponCdMul *= 0.90; }, available() { return true; } },
  { id: 'b_missile_cd',icon: '✦', title: t('upgrade_missile_cd'),        desc: t('upgrade_missile_cd_desc'),
    apply(p) { p.missileCdMul *= 0.75; }, available() { return true; } },
  { id: 'b_pickup',    icon: '◎', title: t('upgrade_pickup'), desc: t('upgrade_pickup_desc'),
    apply(p) { p.pickupMul *= 1.30; }, available() { return true; } },
  { id: 'b_multishot', icon: '✶', title: t('upgrade_multishot'),          desc: t('upgrade_multishot_desc'),
    apply(p) { p.missileCount += 1; }, available() { return true; } },
  { id: 'b_heal',      icon: '✚', title: t('upgrade_heal'), desc: t('upgrade_heal_desc'),
    apply(p) { p.hp = Math.min(p.maxHp, p.hp + p.maxHp * 0.30); }, available() { return true; } },
];

/* ============================================================
   Game — основной объект. Делает всё, что не вошло в подмодули:
   состояние, цикл, спавн волн, левелап-пул.
   ============================================================ */
const Game = {
  // canvas
  canvas: null, ctx: null,
  viewW: 0, viewH: 0, dpr: 1,

  // state: 'menu' | 'playing' | 'paused' | 'levelup' | 'gameover' | 'chest'
  state: 'menu',

  // мир
  player: null,
  enemies: null,
  projectiles: null,
  xpDrops: null,
  particles: null,

  // тайминги
  lastTs: 0,
  runTime: 0,
  waveIndex: 0,
  waveTimer: 0,
  kills: 0,
  killsByType: Object.create(null),

  // Шаг 3: сундук
  chest: null,           // текущий активный сундук на карте (или null)
  chestTimer: 0,         // секунд до следующего спавна (0 — спавним немедленно)

  // Шаг 4: спец-режим спавна мимика
  mimicState: null,

  init() {
    this.canvas = document.getElementById('game');
    this.ctx = this.canvas.getContext('2d');
    this.resize();
    window.addEventListener('resize', () => this.resize());

    // Пулы
    this.enemies     = new ObjectPool(createEnemy,      CONFIG.POOLS.ENEMIES);
    this.projectiles = new ObjectPool(createProjectile, CONFIG.POOLS.PROJECTILES);
    this.xpDrops     = new ObjectPool(createXP,         CONFIG.POOLS.XP);
    this.particles   = new ObjectPool(createParticle,   CONFIG.POOLS.PARTICLES);
    // Шаг 15: пул золота
    this.goldDrops   = new ObjectPool(createGold,       GOLD_CONFIG.POOL_SIZE);

    // Spatial grid для оптимизации поиска врагов
    this._enemyGrid = new SpatialGrid(128);

    // Инициализация всех модулей через реестр
    Registry.initAll();

    // UI bindings
    document.getElementById('startBtn').addEventListener('click',   () => this.startNewGame());
    document.getElementById('restartBtn').addEventListener('click', () => this._handleRestartBtn());
    document.getElementById('resumeBtn').addEventListener('click',  () => this.togglePause());
    document.getElementById('pauseBtn').addEventListener('click',   () => this.togglePause());

    // Шаг 20: показать лагерь
    this.state = 'camp';
    UI.hideAll();
    UI.showCamp();
    // Шаг 18: музыка лагеря
    GameAudio.playMusic('camp');

    this.lastTs = performance.now();
    requestAnimationFrame((t) => this.loop(t));
  },

  /** Шаг 20: вызывается после закрытия тайтлового экрана (первый запуск). */
  _afterTitleDismissed() {
    Game.init();
  },

  resize() {
    this.dpr = Math.min(window.devicePixelRatio || 1, 2);
    const w = window.innerWidth;
    const h = window.innerHeight;
    this.viewW = w;
    this.viewH = h;

    // Шаг 3 (анимации): BASE_SCALE — кратный масштаб спрайтов для чёткости
    if (w < 600) this.baseScale = 2;
    else if (w <= 1200) this.baseScale = 3;
    else this.baseScale = 4;
    // Экспорт глобально для использования в sprites.js и других модулях
    window.BASE_SCALE = this.baseScale;

    // Камера: приближенный зум (30% ближе к игроку для лучшей видимости персонажа)
    this.cameraScale = 0.65; // 1 / 1.54 — показываем ~154% области (вместо 200%)
    this.cameraViewW = w / this.cameraScale;
    this.cameraViewH = h / this.cameraScale;
    this.canvas.width = Math.floor(w * this.dpr);
    this.canvas.height = Math.floor(h * this.dpr);
    this.canvas.style.width = w + 'px';
    this.canvas.style.height = h + 'px';
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    // Шаг 3: отключаем сглаживание глобально
    this.ctx.imageSmoothingEnabled = false;
  },

  /* ----- состояния ----- */
  startNewGame(biomeId) {
    this.enemies.clearAll();
    this.projectiles.clearAll();
    this.xpDrops.clearAll();
    this.particles.clearAll();
    this.goldDrops.clearAll();
    if (window.GameMap && GameMap.clearGroundEffects) GameMap.clearGroundEffects();

    // Bug fix: полный сброс всех счётчиков забега
    this.runGold = 0;
    this.bossKills = 0;
    this._chestsOpened = 0;
    this._bestD20Roll = 0;
    this._totalDamageDealt = 0;
    this._totalDamageTaken = 0;
    this._attractTimer = 0;

    // Шаг 13: бесконечный режим — инициализация
    this.mapNumber = 1;
    this.mapTime = 0;            // время на текущей карте
    this.portalSpawned = false;  // портал уже появился?
    this.guardianSpawned = false; // страж уже появился?
    this.lastBiomeId = biomeId || 'crypt';  // запоминаем выбранный биом
    this.transitioning = false;  // идёт переход?
    this.transitionTimer = 0;

    // Шаг 5 (новый): генерируем подземелье в выбранном биоме
    if (window.GameMap && GameMap.generateDungeon) {
      GameMap.generateDungeon(this.lastBiomeId, 1);
    }

    this.kills = 0;
    this.killsByType = Object.create(null);
    this.runTime = 0;
    this.waveIndex = 0;
    this.waveTimer = CONFIG.WAVE.INITIAL_DELAY;

    // Шаг 3: сундук
    this.chest = null;
    this.chestTimer = CONFIG.CHEST.FIRST_DELAY;
    // Шаг 5: секретный сундук (даётся при открытии секретной комнаты)
    this.secretChest = null;

    // Шаг 6: мини-боссы
    this.bossChest = null;  // золотой сундук после убийства босса
    Bosses.init();

    // Шаг 1: инициализация урн
    Urns.init();

    // Шаг 4: мимик
    this.mimicState = (window.Enemies && Enemies.initMimicState)
      ? Enemies.initMimicState()
      : { count: 0, nextCheckTime: 180 };

    // Стартовая позиция героя — центр стартовой комнаты подземелья
    let startX = (window.GameMap ? GameMap.mapW : CONFIG.MAP.W) / 2;
    let startY = (window.GameMap ? GameMap.mapH : CONFIG.MAP.H) / 2;
    if (window.GameMap && GameMap.dungeon && GameMap.dungeon.startRoom) {
      const sp = GameMap.randomPointInRoom(GameMap.dungeon.startRoom, 18);
      if (sp) { startX = sp.x; startY = sp.y; }
    }
    this.player = Player.create(startX, startY);

    // Шаг 15: перестроить UI-слоты под динамическое количество
    UI.rebuildSlots(this.player.weaponSlots.length, this.player.abilitySlots.length);

    UI.hideAll();
    this.state = 'playing';
    // Шаг 18: запуск музыки выбранного биома
    GameAudio.playMusic(this.lastBiomeId || 'crypt');
  },

  togglePause() {
    if (this.state === 'playing') {
      this.state = 'paused';
      Input.releaseJoystick();
      // Шаг 18: пауза музыки
      GameAudio.pauseMusic();
      UI.showPause();
    } else if (this.state === 'paused') {
      this.state = 'playing';
      UI.hideAll();
      // Шаг 18: возобновление музыки
      GameAudio.resumeMusic();
    }
  },

  triggerLevelUp() {
    const choices = this.buildLevelUpChoices(3);
    if (choices.length === 0) {
      // Всё прокачано — просто +10% HP без паузы
      const p = this.player;
      const add = p.maxHp * 0.10;
      p.maxHp += add;
      p.hp = Math.min(p.maxHp, p.hp + add);
      return;
    }
    this.state = 'levelup';
    Input.releaseJoystick();
    UI.showLevelUp(this.player.level, choices, (chosen) => {
      if (chosen) chosen.apply(this.player);
      UI.hideAll();
      this.state = 'playing';
    });
  },

  /**
   * Собираем все доступные варианты для левелапа и отдаём n случайных.
   * Виды карт:
   *  - 'basic'   — базовые улучшения (всегда доступны)
   *  - 'weapon'  — новое оружие (если есть свободный слот) или
   *                апгрейд существующего (level < max)
   *  - 'ability' — новая пассивка или апгрейд
   */
  buildLevelUpChoices(n) {
    const p = this.player;
    const all = [];

    // 1) Новое оружие (если слот свободен)
    if (Player.hasFreeWeaponSlot(p)) {
      for (const info of WEAPON_INFO) {
        if (Player.findWeapon(p, info.id)) continue; // уже есть — не предлагать "новое"
        all.push({
          kind: 'weapon',
          icon: info.icon,
          id: info.id,
          title: t('levelup_new_weapon', info.name),
          desc: info.desc,
          apply(player) {
            const w = WEAPON_FACTORIES[info.id]();
            Player.addWeapon(player, w);
            // Разблокировка в кодексе
            if (window.Codex) Codex.unlockWeapon(info.id);
          },
        });
      }
    }

    // 2) Апгрейд существующего оружия
    for (const w of p.weaponSlots) {
      if (!w) continue;
      if (w.level >= w.maxLevel) continue;
      const next = w.level + 1;
      all.push({
        kind: 'weapon',
        icon: w.icon,
        id: w.id,
        weaponId: w.id,
        title: `${w.name} ${Utils.roman(w.level)} → ${Utils.roman(next)}`,
        desc: t('levelup_upgrade_desc', next, w.maxLevel),
        apply(player) {
          const tgt = Player.findWeapon(player, w.id);
          if (tgt) tgt.upgrade();
        },
      });
    }

    // 3) Новая пассивка
    if (Player.hasFreeAbilitySlot(p)) {
      for (const info of ABILITY_INFO) {
        if (Player.findAbility(p, info.id)) continue;
        all.push({
          kind: 'ability',
          icon: info.icon,
          id: info.id,
          title: t('levelup_new_ability', info.name),
          desc: info.desc,
          apply(player) {
            const a = ABILITY_FACTORIES[info.id]();
            Player.addAbility(player, a);
            // Разблокировка в кодексе
            if (window.Codex) Codex.unlockAbility(info.id);
          },
        });
      }
    }

    // 4) Апгрейд пассивки
    for (const a of p.abilitySlots) {
      if (!a) continue;
      if (a.level >= a.maxLevel) continue;
      const next = a.level + 1;
      all.push({
        kind: 'ability',
        icon: a.icon,
        id: a.id,
        abilityId: a.id,
        title: `${a.name} ${Utils.roman(a.level)} → ${Utils.roman(next)}`,
        desc: a.effectText ? a.effectText.call ? `След.: ${(function(){ const tmp = Object.create(a); tmp.level = next; return tmp.effectText ? tmp.effectText() : a.desc; })()}` : a.desc : a.desc,
        apply(player) {
          const tgt = Player.findAbility(player, a.id);
          if (tgt) tgt.upgrade(player);
        },
      });
    }

    // 5) Базовые улучшения (всегда доступны и стакаются)
    for (const u of BASIC_UPGRADES) {
      if (!u.available(p)) continue;
      all.push({
        kind: 'basic',
        icon: u.icon,
        title: u.title,
        desc: u.desc,
        apply(player) { u.apply(player); },
      });
    }

    // Шаг 7: Взвешенная выборка — оружие/пассивки чаще, базовые улучшения реже.
    // Вес: weapon/ability = 3, basic = 1
    const weighted = [];
    for (const item of all) {
      const weight = (item.kind === 'basic') ? 1 : 3;
      for (let w = 0; w < weight; w++) weighted.push(item);
    }
    const out = [];
    const picked = new Set();
    for (let i = 0; i < n && picked.size < all.length; i++) {
      let attempts = 0;
      while (attempts < 50) {
        const idx = Math.floor(Math.random() * weighted.length);
        const item = weighted[idx];
        if (!picked.has(item)) { picked.add(item); out.push(item); break; }
        attempts++;
      }
    }
    return out;
  },

  triggerGameOver() {
    this.state = 'gameover';
    Input.releaseJoystick();

    // Шаг 19: остановить музыку и очистить все таймеры
    GameAudio.playSfx('death');
    GameAudio.stopMusic();

    // Шаг 19: очистить все объекты для предотвращения утечек
    this.enemies.clearAll();
    this.projectiles.clearAll();
    this.xpDrops.clearAll();
    this.particles.clearAll();
    if (this.goldDrops) this.goldDrops.clearAll();

    // Шаг 15: сохранить мета-прогресс
    if (window.MetaProgress && MetaProgress.data) {
      const goldCollected = this.runGold || 0;
      const goldBonus = (this.player ? this.player.level : 1) * 10;
      const goldTotal = MetaProgress.calcEndOfRunGold(goldCollected, this.player ? this.player.level : 1);

      MetaProgress.addGold(goldTotal);
      MetaProgress.updateStats(this.kills, this.runTime);
      const repGained = 10 + (this.bossKills || 0) * 5 + Math.floor(this.kills / 100);
      MetaProgress.addRunReputation(this.bossKills || 0, this.kills);

      // Собираем полную статистику забега
      const runStats = {
        time: Utils.formatTime(this.runTime),
        kills: this.kills,
        level: this.player ? this.player.level : 1,
        wave: this.waveIndex,
        mapsCleared: (this.mapNumber || 1) - 1,
        goldCollected: goldCollected,
        goldBonus: goldBonus,
        goldTotal: goldTotal,
        repGained: repGained,
        bossKills: this.bossKills || 0,
        chestsOpened: this._chestsOpened || 0,
        bestRoll: this._bestD20Roll || 0,
        damageDealt: this._totalDamageDealt || '—',
        damageTaken: this._totalDamageTaken || '—',
      };

      // Показать окно статистики через UIExtended
      if (window.UIExtended) {
        UIExtended.showRunStats(runStats, () => {
          this.state = 'camp';
          UI.showCamp();
          GameAudio.playMusic('camp');
        });
      } else {
        // Фоллбэк: старое поведение
        UI.showRunResults({
          time: Utils.formatTime(this.runTime),
          kills: this.kills,
          level: this.player ? this.player.level : 1,
          goldCollected: goldCollected,
          goldBonus: goldBonus,
          goldTotal: goldTotal,
          repGained: repGained,
        }, () => {
          this.state = 'camp';
          UI.showCamp();
          GameAudio.playMusic('camp');
        });
      }
    } else {
      // Фоллбэк: старое поведение
      UI.showGameOver({
        time: Utils.formatTime(this.runTime),
        kills: this.kills,
        level: this.player.level,
      });
    }
  },

  /** Шаг 15: обработчик кнопки рестарта (из старого Game Over). */
  _handleRestartBtn() {
    // Переход в лагерь вместо прямого рестарта
    if (window.MetaProgress) {
      this.state = 'camp';
      UI.hideAll();
      UI.showCamp();
      // Шаг 18: музыка лагеря
      GameAudio.playMusic('camp');
    } else {
      this.startNewGame();
    }
  },

  /** Выход из забега в лагерь (из меню паузы или кнопки «назад»). */
  exitToMenu() {
    if (this.state !== 'paused' && this.state !== 'playing') return;
    Input.releaseJoystick();

    // Останавливаем музыку
    GameAudio.stopMusic();

    // Очищаем ВСЕ объекты (bug fix: ранее xpDrops и particles не очищались)
    this.enemies.clearAll();
    this.projectiles.clearAll();
    this.xpDrops.clearAll();
    this.particles.clearAll();
    if (this.goldDrops) this.goldDrops.clearAll();

    // Сохраняем мета-прогресс
    const goldCollected = this.runGold || 0;
    const goldTotal = (window.MetaProgress && MetaProgress.calcEndOfRunGold)
      ? MetaProgress.calcEndOfRunGold(goldCollected, this.player ? this.player.level : 1)
      : goldCollected;

    if (window.MetaProgress && MetaProgress.data) {
      MetaProgress.addGold(goldTotal);
      MetaProgress.updateStats(this.kills, this.runTime);
      MetaProgress.addRunReputation(this.bossKills || 0, this.kills);
    }

    // Собираем статистику забега
    const runStats = {
      time: Utils.formatTime(this.runTime),
      kills: this.kills,
      level: this.player ? this.player.level : 1,
      wave: this.waveIndex,
      mapsCleared: (this.mapNumber || 1) - 1,
      goldCollected: goldCollected,
      goldBonus: (this.player ? this.player.level : 1) * 10,
      goldTotal: goldTotal,
      bossKills: this.bossKills || 0,
      chestsOpened: this._chestsOpened || 0,
      bestRoll: this._bestD20Roll || 0,
      damageDealt: this._totalDamageDealt || '—',
      damageTaken: this._totalDamageTaken || '—',
    };

    this.state = 'gameover';
    UI.hideAll();

    // Показать окно статистики
    if (window.UIExtended) {
      UIExtended.showRunStats(runStats, () => {
        this.state = 'camp';
        UI.showCamp();
        GameAudio.playMusic('camp');
      });
    } else {
      this.state = 'camp';
      UI.showCamp();
      GameAudio.playMusic('camp');
    }
  },

  /* ----- игровой цикл ----- */
  loop(ts) {
    const dt = Math.min(0.05, (ts - this.lastTs) / 1000);
    this.lastTs = ts;
    if (this.state === 'playing') this.update(dt);
    this.render();
    UI.tick(this);
    requestAnimationFrame((t) => this.loop(t));
  },

  update(dt) {
    this.runTime += dt;

    // Оптимизации: кэш расстояний и throttle
    if (this.player && window.DistanceCache) {
      DistanceCache.beginFrame(this.player.x, this.player.y);
    }
    if (window.EnemyThrottle) EnemyThrottle.tick();

    Player.update(this.player, dt);
    // Шаг 4: применяем эффекты от наземных луж (slime/rot замедляют, fire — DoT)
    if (window.GameMap && GameMap.queryGroundAt) {
      const eff = GameMap.queryGroundAt(this.player.x, this.player.y);
      if (eff.dps > 0) this.player.hp -= eff.dps * dt;
      // Замедление применим в Player.update в этот же кадр в следующий раз —
      // здесь подкорректируем позицию: поскольку Player уже сдвинулся,
      // компенсируем "лишнее" движение, если есть slow > 0.
      let totalSlow = eff.slow || 0;
      // Шаг 6: замедление от паутины босса
      if (this.player.webSlow && this.player.webSlow > 0) {
        totalSlow = Math.max(totalSlow, 0.50);
      }
      // Шаг 17: замедление от ледяной руны
      if (this.player._iceSlow && this.player._iceSlowTimer > 0) {
        totalSlow = Math.max(totalSlow, this.player._iceSlow);
        this.player._iceSlowTimer -= dt;
        if (this.player._iceSlowTimer <= 0) this.player._iceSlow = 0;
      }
      // Шаг 17: оглушение (полная остановка)
      if (this.player._stunTimer && this.player._stunTimer > 0) {
        totalSlow = 1.0;
        this.player._stunTimer -= dt;
      }
      if (totalSlow > 0) {
        const move = Input.getMove();
        const ml = Math.hypot(move.x, move.y);
        if (ml > 0.001) {
          const speed = CONFIG.PLAYER.SPEED * this.player.speedMul;
          this.player.x -= move.x * speed * dt * totalSlow;
          this.player.y -= move.y * speed * dt * totalSlow;
        }
      }
    }
    if (window.GameMap && GameMap.updateGroundEffects) GameMap.updateGroundEffects(dt);
    // Шаг 5: обновление подземелья (ловушки, дверь, кулдауны рычагов)
    if (window.GameMap && GameMap.update) GameMap.update(dt);

    this.updateWaves(dt);
    this.updateBoss(dt);
    // Шаг 13: бесконечный режим — таймер карты, портал, страж
    if (!window.Campaign || !Campaign.active) {
      this.updateInfiniteMode(dt);
    }
    // Шаг 16: обновление кампании
    if (window.Campaign && Campaign.active) {
      Campaign.update(dt);
      if (window.GameMap && GameMap.updateCampaignObjects) {
        GameMap.updateCampaignObjects(dt, this.player);
      }
    }
    Enemies.update(this.enemies, this.player, dt);

    // Оружия в слотах
    const weaponHelpers = {
      damageEnemy: (e, dmg) => this.damageEnemy(e, dmg),
    };
    for (const w of this.player.weaponSlots) {
      if (!w) continue;
      // Меч имеет визуальный таймер — отдельный tick
      if (typeof w.tick === 'function') w.tick(dt);
      w.update(this.player, this.enemies, this.projectiles, dt, weaponHelpers);
    }
    // Шаг 6: проверка мили-оружий на попадание в босса
    this.checkMeleeVsBoss();
    // Шаг 1: проверка мили-оружий на попадание в урны
    if (window.Urns && Urns.list.length > 0) {
      for (const w of this.player.weaponSlots) {
        if (!w) continue;
        const isSwing = w.swing && w.swing.active && w.swing.t <= 0.05;
        const isThrust = w.thrust && w.thrust.active && w.thrust.t <= 0.05;
        const isSlam = w.slam && w.slam.active && w.slam.t <= 0.05;
        const isWhip = w.whipAnim && w.whipAnim.active && w.whipAnim.t <= 0.05;
        if (isSwing || isThrust || isSlam || isWhip) {
          Urns.checkMeleeHits(this.player);
          break; // one check per frame is enough
        }
      }
    }

    // Встроенный Magic Missile (не в слотах)
    this.updateBuiltInMissile(dt);

    // Снаряды
    const camViewWUpdate = this.cameraViewW || this.viewW;
    const camViewHUpdate = this.cameraViewH || this.viewH;
    const cam = GameMap.getCamera(this.player, camViewWUpdate, camViewHUpdate);
    Projectiles.update(
      this.projectiles, this.enemies, cam, camViewWUpdate, camViewHUpdate,
      (e, dmg) => this.damageEnemy(e, dmg),
      dt
    );

    // Шаг 6: проверка попадания снарядов игрока в босса
    this.checkProjectilesVsBoss();
    // Шаг 9-10: отражение снарядов
    this.updateProjectileReflection();
    // Шаг 6: хоминг для снарядов босса (лич)
    this.updateHomingProjectiles(dt);

    // Шаг 6: яд от паука-королевы
    if (this.player.poison && this.player.poison.remaining > 0) {
      // Шаг 8: сопротивление снижает длительность яда (тик урона остаётся)
      this.player.hp -= this.player.poison.dps * dt;
      this.player.poison.remaining -= dt;
    }
    // Шаг 6: замедление от паутины
    if (this.player.webSlow && this.player.webSlow > 0) {
      this.player.webSlow -= dt;
    }

    // Лут и частицы
    Loot.update(this.xpDrops, this.player, dt);
    // Шаг 15: обновление золота
    if (this.goldDrops) Loot.updateGold(this.goldDrops, this.player, dt);

    // Притяжение застрявших объектов к проходимой зоне (раз в 0.5 сек)
    if (!this._attractTimer) this._attractTimer = 0;
    this._attractTimer += dt;
    if (this._attractTimer >= 0.5) {
      if (window.GameMap && GameMap.attractAllStuck) {
        GameMap.attractAllStuck(this, this._attractTimer);
      }
      this._attractTimer = 0;
    }

    this.updateChest(dt);
    this.updateBossChest(dt);
    this.updateParticles(dt);

    // Шаг 1: обновление урн и яблок
    if (window.Urns) {
      Urns.update(dt, this.player);
      // Проверка попадания снарядов игрока в урны
      Urns.checkProjectileHits(this.projectiles);
    }

    // Левелап (only trigger if still in playing state)
    // Формула прогресса: каждый следующий уровень = предыдущий + 20%
    // Уровень 1→2: 100, уровень 2→3: 120, уровень 3→4: 144 и т.д.
    if (this.state === 'playing' && this.player.xp >= this.player.xpNext) {
      this.player.xp -= this.player.xpNext;
      // Следующий уровень = текущий порог × 1.20 (прирост 20%)
      const nextXpNext = Math.floor(this.player.xpNext * 1.20);
      // Ограничиваем остаток XP — не более 80% от следующего уровня
      // Это предотвращает цепочку мгновенных повышений уровня
      this.player.xp = Math.min(this.player.xp, Math.floor(nextXpNext * 0.8));
      this.player.level += 1;
      this.player.xpNext = nextXpNext;
      // Шаг 18: звук повышения уровня
      GameAudio.playSfx('levelup');
      this.triggerLevelUp();
    }

    // Смерть
    if (this.player.hp <= 0) {
      // Feature #6: Возрождение (талант Телосложения ур.8-9)
      if (this.player._resurrectCount && this.player._resurrectCount > 0) {
        this.player._resurrectCount--;
        const healPct = this.player._resurrectHpPct || 0.30;
        this.player.hp = Math.floor(this.player.maxHp * healPct);
        // Визуальный эффект возрождения
        Particles.burst(this.player.x, this.player.y, 15, {
          color: '#ffd700', speedMin: 80, speedMax: 200,
          lifeMin: 0.5, lifeMax: 1.0, sizeMin: 4, sizeMax: 8,
        });
        Particles.text(this.player.x, this.player.y - 40, t('campaign_resurrect'), 2.0, '#ffd700', 18);
        // Шаг 19: I-frames после воскрешения (2 сек)
        this.player._iFrameTimer = 2.0;
        return; // не умираем
      }
      this.player.hp = 0;
      // Шаг 16: обработка смерти в кампании
      if (window.Campaign && Campaign.active) {
        Campaign.onPlayerDeath();
      }
      this.triggerGameOver();
    }

    // Пост-оптимизации
    if (window.MemoryOptimizer) {
      MemoryOptimizer.enforceParticleLimit(this.particles);
      if (window.EnemyThrottle && EnemyThrottle._frameCounter % 30 === 0) {
        const mapW = (window.GameMap ? GameMap.mapW : CONFIG.MAP.W) || 2000;
        const mapH = (window.GameMap ? GameMap.mapH : CONFIG.MAP.H) || 2000;
        MemoryOptimizer.cleanupDistantProjectiles(this.projectiles, mapW, mapH);
      }
    }
    if (this.enemies && this._enemyGrid) {
      this._enemyGrid.rebuild(this.enemies);
    }
  },

  updateBuiltInMissile(/* dt */) {
    const p = this.player;
    // Классовая система: только Волшебник имеет встроенный Magic Missile
    if (p._noBuiltInMissile) return;
    if (p.missileCd > 0) return;

    // Направление: по движению / по ближайшему врагу / по facing
    let dir;
    const move = Input.getMove();
    if (Math.hypot(move.x, move.y) > 0.05) {
      dir = Utils.norm(move.x, move.y);
    } else {
      const t = Projectiles.findNearestEnemy(this.enemies, p.x, p.y, Infinity);
      dir = t ? Utils.norm(t.x - p.x, t.y - p.y) : { x: p.facing.x, y: p.facing.y };
    }

    const count = p.missileCount + (p._talentBonusProjectiles || 0);
    const spread = CONFIG.MISSILE.SPREAD;
    const baseAngle = Math.atan2(dir.y, dir.x);
    for (let i = 0; i < count; i++) {
      const off = (i - (count - 1) / 2) * spread;
      const a = baseAngle + off;
      const pr = this.projectiles.spawn();
      if (!pr) break;
      pr.kind = 'missile';
      pr.owner = 'player';
      pr.x = p.x; pr.y = p.y;
      pr.vx = Math.cos(a) * CONFIG.MISSILE.SPEED;
      pr.vy = Math.sin(a) * CONFIG.MISSILE.SPEED;
      pr.life = CONFIG.MISSILE.LIFETIME;
      pr.damage = CONFIG.MISSILE.DAMAGE * p.damageMul * (p.magicDamageMul || 1);
      pr.radius = CONFIG.MISSILE.RADIUS;
      pr.angle = a;
      pr.source = 'missile';
    }
    p.missileCd = CONFIG.MISSILE.COOLDOWN * p.missileCdMul;
  },

  updateWaves(dt) {
    this.waveTimer -= dt;
    if (this.waveTimer <= 0) {
      this.waveIndex += 1;
      const count = CONFIG.WAVE.BASE + this.waveIndex * CONFIG.WAVE.PER_WAVE;
      Enemies.spawnWave(this.enemies, this.player, count, this.waveIndex);
      this.waveTimer = CONFIG.WAVE.INTERVAL;
    }
    // Шаг 4: попытка заспавнить мимика (после 3-й минуты, не более 1-2 за забег)
    if (window.Enemies && Enemies.tryMimicSpawn && this.mimicState) {
      Enemies.tryMimicSpawn(this.player, this.runTime, this.mimicState);
    }
  },

  /* ============================================================
     Шаг 13: Бесконечный режим — портал, страж, переход.
     ============================================================ */

  updateInfiniteMode(dt) {
    if (!window.PORTAL_CONFIG || !window.INFINITE_MODE) return;

    this.mapTime += dt;

    // Анимация перехода
    if (this.transitioning) {
      this.transitionTimer -= dt;
      if (this.transitionTimer <= 0) {
        this.transitioning = false;
        this._executeMapTransition();
      }
      return;
    }

    // Страж карты (появляется через GUARDIAN_SPAWN_DELAY на картах >= 2)
    if (!this.guardianSpawned &&
        this.mapNumber >= INFINITE_MODE.GUARDIAN_MIN_MAP &&
        this.mapTime >= INFINITE_MODE.GUARDIAN_SPAWN_DELAY) {
      this.guardianSpawned = true;
      if (window.Bosses && Bosses.spawnGuardian) {
        Bosses.spawnGuardian(this.player);
      }
    }

    // Портал (появляется через PORTAL_CONFIG.APPEAR_TIME секунд на карте)
    if (!this.portalSpawned && this.mapTime >= PORTAL_CONFIG.APPEAR_TIME) {
      this.portalSpawned = true;
      if (window.GameMap && GameMap.spawnPortal) {
        GameMap.spawnPortal();
      }
      // Уведомление
      if (window.Particles && this.player) {
        Particles.text(this.player.x, this.player.y - 40, t('campaign_portal_open'), 2.0, '#9b59b6', 16);
      }
    }

    // Проверка входа в портал
    if (this.portalSpawned && window.GameMap && GameMap.isPlayerInPortal &&
        GameMap.isPlayerInPortal(this.player)) {
      this._startMapTransition();
    }
  },

  /** Начать анимацию перехода на следующую карту. */
  _startMapTransition() {
    this.transitioning = true;
    this.transitionTimer = 0.8; // длительность анимации перехода (секунды)
    Input.releaseJoystick();
    // Шаг 20: показать экран загрузки
    if (window.LoadingScreen) LoadingScreen.show();
  },

  /** Выполнить переход на следующую карту (после анимации). */
  _executeMapTransition() {
    const player = this.player;
    if (!player) return;

    // Сохраняем состояние игрока (HP, оружие, пассивки, уровень, опыт)
    // — всё в объекте player, ничего не сбрасываем.

    // Увеличиваем номер карты
    this.mapNumber += 1;

    // Выбираем биом (не повторять предыдущий)
    let newBiome = INFINITE_MODE.getBiome(this.mapNumber);
    let attempts = 0;
    while (newBiome.id === this.lastBiomeId && attempts < 10) {
      newBiome = BIOMES[Math.floor(Math.random() * BIOMES.length)];
      attempts++;
    }
    this.lastBiomeId = newBiome.id;

    // Шаг 18: смена музыки на новый биом
    GameAudio.playMusic(newBiome.id);

    // Очистка объектов
    this.enemies.clearAll();
    this.projectiles.clearAll();
    this.xpDrops.clearAll();
    this.particles.clearAll();
    if (this.goldDrops) this.goldDrops.clearAll();
    if (window.GameMap && GameMap.clearGroundEffects) GameMap.clearGroundEffects();

    // Убираем активного босса
    if (window.Bosses) {
      Bosses.current = null;
      Bosses.guardian = null;
    }

    // Убираем сундуки
    this.chest = null;
    this.secretChest = null;
    this.bossChest = null;

    // Сброс урн при переходе на новую карту
    Urns.init();

    // Генерируем новую карту
    if (window.GameMap && GameMap.generateDungeon) {
      GameMap.generateDungeon(newBiome.id, this.mapNumber);
    }

    // Размещаем героя в стартовой комнате новой карты
    let startX = (window.GameMap ? GameMap.mapW : CONFIG.MAP.W) / 2;
    let startY = (window.GameMap ? GameMap.mapH : CONFIG.MAP.H) / 2;
    if (window.GameMap && GameMap.dungeon && GameMap.dungeon.startRoom) {
      const sp = GameMap.randomPointInRoom(GameMap.dungeon.startRoom, 18);
      if (sp) { startX = sp.x; startY = sp.y; }
    }
    player.x = startX;
    player.y = startY;

    // Сброс таймеров карты
    this.mapTime = 0;
    this.portalSpawned = false;
    this.guardianSpawned = false;

    // Волны продолжаются с текущего waveIndex (не сбрасываем)
    this.waveTimer = CONFIG.WAVE.INITIAL_DELAY;

    // Сундук: сброс таймера
    this.chestTimer = CONFIG.CHEST.FIRST_DELAY;

    // Визуальный эффект при выходе из перехода
    Particles.burst(player.x, player.y, 12, {
      color: '#f1c40f', speedMin: 60, speedMax: 180,
      lifeMin: 0.4, lifeMax: 0.8, sizeMin: 3, sizeMax: 5,
    });
    Particles.ring(player.x, player.y, 60, 0.5, 'rgba(155, 89, 182, 0.8)', 3);
    // Шаг 20: скрыть экран загрузки
    if (window.LoadingScreen) LoadingScreen.hide();
  },

  /* ============================================================
     Шаг 16: Кампания — загрузка карты кампании.
     ============================================================ */

  /** Запуск карты кампании (вызывается из Campaign._loadCurrentMap). */
  _startCampaignMap(mapCfg) {
    // Очистка
    this.enemies.clearAll();
    this.projectiles.clearAll();
    this.xpDrops.clearAll();
    this.particles.clearAll();
    if (this.goldDrops) this.goldDrops.clearAll();
    if (window.GameMap && GameMap.clearGroundEffects) GameMap.clearGroundEffects();

    // Шаг 15: счётчики
    this.runGold = this.runGold || 0;
    this.bossKills = this.bossKills || 0;

    // Сброс боссов
    if (window.Bosses) {
      Bosses.current = null;
      Bosses.guardian = null;
    }

    // Сундуки
    this.chest = null;
    this.secretChest = null;
    this.bossChest = null;

    // Бесконечный режим отключён для кампании
    this.portalSpawned = false;
    this.guardianSpawned = false;
    this.transitioning = false;
    this.mapNumber = mapCfg.id;

    // Генерация карты
    if (window.GameMap && GameMap.generateDungeon) {
      GameMap.generateDungeon(mapCfg.biome, mapCfg.id);
    }

    // Размещение специальных объектов кампании
    if (window.GameMap && GameMap.placeCampaignObjects) {
      GameMap.placeCampaignObjects(mapCfg);
    }

    // Создаём игрока (если первая карта) или перемещаем
    if (!this.player) {
      let startX = (window.GameMap ? GameMap.mapW : CONFIG.MAP.W) / 2;
      let startY = (window.GameMap ? GameMap.mapH : CONFIG.MAP.H) / 2;
      if (window.GameMap && GameMap.dungeon && GameMap.dungeon.startRoom) {
        const sp = GameMap.randomPointInRoom(GameMap.dungeon.startRoom, 18);
        if (sp) { startX = sp.x; startY = sp.y; }
      }
      this.player = Player.create(startX, startY);
      UI.rebuildSlots(this.player.weaponSlots.length, this.player.abilitySlots.length);
    } else {
      // Bug fix #7: если HP <= 0 (после смерти), пересоздаём героя полностью
      if (this.player.hp <= 0) {
        let startX = (window.GameMap ? GameMap.mapW : CONFIG.MAP.W) / 2;
        let startY = (window.GameMap ? GameMap.mapH : CONFIG.MAP.H) / 2;
        if (window.GameMap && GameMap.dungeon && GameMap.dungeon.startRoom) {
          const sp = GameMap.randomPointInRoom(GameMap.dungeon.startRoom, 18);
          if (sp) { startX = sp.x; startY = sp.y; }
        }
        this.player = Player.create(startX, startY);
        UI.rebuildSlots(this.player.weaponSlots.length, this.player.abilitySlots.length);
        // Сбрасываем счётчики забега
        this.kills = 0;
        this.runTime = 0;
        this.waveIndex = 0;
        this.runGold = 0;
        this.bossKills = 0;
      } else {
        // Перемещаем игрока в стартовую комнату новой карты
        let startX = (window.GameMap ? GameMap.mapW : CONFIG.MAP.W) / 2;
        let startY = (window.GameMap ? GameMap.mapH : CONFIG.MAP.H) / 2;
        if (window.GameMap && GameMap.dungeon && GameMap.dungeon.startRoom) {
          const sp = GameMap.randomPointInRoom(GameMap.dungeon.startRoom, 18);
          if (sp) { startX = sp.x; startY = sp.y; }
        }
        this.player.x = startX;
        this.player.y = startY;
      }
    }

    // Применить благословение мага (если есть, карта 5)
    if (window.Campaign && Campaign.mageBlessing && this.player) {
      // Уже применено через Campaign, но убедимся
    }

    // Волны
    if (!this.waveIndex) this.waveIndex = 0;
    this.waveTimer = CONFIG.WAVE.INITIAL_DELAY;
    this.chestTimer = CONFIG.CHEST.FIRST_DELAY;

    // Инициализация боссов для кампании (без глобальной ротации)
    if (window.Bosses) {
      if (!Bosses.globalRotation || Bosses.globalRotation.length === 0) {
        Bosses.init();
      }
    }

    // Мимик
    this.mimicState = (window.Enemies && Enemies.initMimicState)
      ? Enemies.initMimicState()
      : { count: 0, nextCheckTime: 180 };

    // Переключить состояние
    UI.hideAll();
    this.state = 'playing';
    this.kills = this.kills || 0;
    this.runTime = this.runTime || 0;

    // Показать название карты
    if (window.UI && UI.showCampaignMapName) {
      UI.showCampaignMapName(mapCfg.name);
    }
    // Шаг 18: музыка биома кампании
    const biomeMusic = mapCfg.biome || 'crypt';
    GameAudio.playMusic(biomeMusic);
  },

  /* ============================================================
     Шаг 3: Сундук — спавн, подбор, бросок d20.
     ============================================================ */

  /** Тик: уменьшаем таймер пока сундука нет (ровно "не копится при наличии"
   *  по ТЗ — но мы трактуем ровно как сказано: пока есть сундук, новый
   *  не появляется и таймер не идёт). При подборе таймер сбрасывается. */
  updateChest(dt) {
    if (this.chest) {
      Chest.update(this.chest, dt);
      // Подобрать
      if (Chest.pickedUpBy(this.chest, this.player)) {
        this.openChest();
      }
    } else {
      // Сундука нет — копится таймер (только после 5-й волны)
      const waveIndex = this.waveIndex || 0;
      if (waveIndex >= CONFIG.CHEST.MIN_WAVE) {
        this.chestTimer -= dt;
        if (this.chestTimer <= 0) {
          this.chest = Chest.spawnNear(this.player);
          this.chestTimer = CONFIG.CHEST.INTERVAL;
        }
      }
    }
    // Шаг 5: секретный сундук (за решёткой) — отдельная логика подбора
    if (this.secretChest) {
      Chest.update(this.secretChest, dt);
      if (Chest.pickedUpBy(this.secretChest, this.player)) {
        this.openSecretChest();
      }
    }
  },

  /** Шаг 5: создать сундук в секретной комнате (вызывается из GameMap при
   *  правильной комбинации рычагов). */
  spawnSecretChest() {
    if (this.secretChest) return;
    if (!window.GameMap || !GameMap.dungeon) return;
    const pos = GameMap.dungeon.secretChestPos;
    if (!pos) return;
    const c = Chest.create();
    c.x = pos.x; c.y = pos.y;
    c.guaranteedRare = true;
    Particles.chestGlow(c.x, c.y);
    this.secretChest = c;
  },

  /** Открытие секретного сундука: гарантированно бросок 19..20. */
  openSecretChest() {
    if (!this.secretChest) return;
    Particles.chestOpen(this.secretChest.x, this.secretChest.y);
    // Шаг 18: звук открытия сундука
    GameAudio.playSfx('chest');
    // Шаг 17: помечаем как секретный (практически не мимик)
    this._lastChestX = this.secretChest.x;
    this._lastChestY = this.secretChest.y;
    this._lastChestIsSecret = true;
    this.secretChest = null;

    this.state = 'chest';
    Input.releaseJoystick();

    // Гарантированный редкий бросок: 19 или 20
    const finalRoll = 19 + Math.floor(Math.random() * 2);
    // Шаг 18: звук броска d20
    GameAudio.playSfx('d20');
    UI.showD20Roll(finalRoll, () => this.resolveChest(finalRoll));
  },

  /** Подбор сундука: переход в state=chest, эффект открытия, бросок d20. */
  openChest() {
    if (!this.chest) return;
    // Шаг 17: сохраняем позицию сундука для возможного мимика
    this._lastChestX = this.chest.x;
    this._lastChestY = this.chest.y;
    this._lastChestIsSecret = false;

    // Визуальный эффект открытия в точке сундука
    Particles.chestOpen(this.chest.x, this.chest.y);
    // Шаг 18: звук открытия сундука
    GameAudio.playSfx('chest');
    // Сундук исчезает (логически — открыт)
    this.chest = null;

    // Переходим в "сундучный" state (игра паузится по факту:
    // update() выполняется только в state==='playing')
    this.state = 'chest';
    Input.releaseJoystick();

    // Бросок d20 с финальным значением, заданным заранее
    // Шаг 8: пассивка «Счастливчик» повышает минимальный результат
    let finalRoll = 1 + Math.floor(Math.random() * 20);
    const minRoll = 1 + (this.player.d20MinBonus || 0);
    if (finalRoll < minRoll) finalRoll = Math.min(minRoll, 20);
    // Трекинг статистики
    this._chestsOpened = (this._chestsOpened || 0) + 1;
    if (!this._bestD20Roll || finalRoll > this._bestD20Roll) this._bestD20Roll = finalRoll;
    // Шаг 18: звук броска d20
    GameAudio.playSfx('d20');
    UI.showD20Roll(finalRoll, () => this.resolveChest(finalRoll));
  },

  /** Применить результат броска (НОВАЯ ТАБЛИЦА d20). */
  resolveChest(roll) {
    const player = this.player;
    if (!player) { this.state = 'playing'; UI.hideAll(); return; }

    // === 1–5: МИМИК ===
    if (roll <= 5) {
      const reward = {
        title: t('chest_mimic'),
        desc: 'The chest turns into a mimic! Kill it for XP!',
      };
      UI.showChestReward(roll, reward, () => {
        // Спавним усиленного мимика (+30% HP и урона)
        if (window.Enemies && window.Game && Game.enemies) {
          const mx = this._lastChestX || player.x;
          const my = this._lastChestY || player.y;
          const mimic = Enemies.spawnByType ? Enemies.spawnByType(Game.enemies, 'mimic', mx, my) : null;
          if (mimic) {
            mimic.hp = Math.round(mimic.hp * 1.30);
            mimic.maxHp = mimic.hp;
            mimic._mimicDmgMul = 1.30;
            // При убийстве мимика дропнет 500-1000 XP
            mimic._mimicXpReward = Utils.randInt(500, 1000);
          }
        }
        this._afterChestClose();
      });
      return;
    }

    // === 6–10: ОПЫТ (сразу 1000–4000 XP) ===
    if (roll <= 10) {
      const xpAmount = Utils.randInt(1000, 4000);
      const reward = {
        title: 'XP Surge!',
        desc: `+${xpAmount} XP`,
      };
      player.xp += xpAmount;
      UI.showChestReward(roll, reward, () => this._afterChestClose());
      return;
    }

    // === 11–15: КАРТОЧКА (выбор 1 из 3) ===
    if (roll <= 15) {
      const choices = this.buildLevelUpChoices(3);
      UI.showChestPick(roll, choices, (chosen) => {
        if (chosen) chosen.apply(player);
        this._afterChestClose();
      });
      return;
    }

    // === 16–19: РЕДКАЯ КАРТОЧКА + ШАНС ЭВОЛЮЦИИ ===
    if (roll <= 19) {
      // Проверяем готовые эволюции
      const ready = (window.Evolutions && Evolutions.findReady) ? Evolutions.findReady(player) : [];
      if (ready.length > 0) {
        // Предлагаем выбор: эволюция ИЛИ карточка
        const choices = this.buildLevelUpChoices(3);
        // Показываем эволюцию
        if (ready.length === 1) {
          UI.showEvolutionDialog(roll, ready[0], (accepted) => {
            if (accepted) {
              Evolutions.apply(player, ready[0].recipe);
              if (window.Codex) Codex.unlockEvolution(ready[0].recipe.resultId);
              this._afterChestClose();
            } else {
              // Отказался от эволюции — даём карточку
              UI.showChestPick(roll, choices, (chosen) => {
                if (chosen) chosen.apply(player);
                this._afterChestClose();
              });
            }
          });
        } else {
          UI.showEvolutionChoice(roll, ready, (chosenPair) => {
            if (chosenPair) {
              Evolutions.apply(player, chosenPair.recipe);
              if (window.Codex) Codex.unlockEvolution(chosenPair.recipe.resultId);
              this._afterChestClose();
            } else {
              UI.showChestPick(roll, choices, (chosen) => {
                if (chosen) chosen.apply(player);
                this._afterChestClose();
              });
            }
          });
        }
      } else {
        // Нет готовых эволюций — редкая карточка
        const choices = this.buildLevelUpChoices(3);
        UI.showChestPick(roll, choices, (chosen) => {
          if (chosen) chosen.apply(player);
          this._afterChestClose();
        });
      }
      return;
    }

    // === 20: ЭКСКЛЮЗИВ / СУПЕР-ЭВОЛЮЦИЯ / ФОЛЛБЭК ===
    // Приоритет 1: эксклюзивное оружие (если есть свободный слот)
    if (Player.hasFreeWeaponSlot(player)) {
      const excl = this._tryGetExclusiveWeapon(player);
      if (excl) {
        excl.apply(player);
        UI.showChestReward(roll, excl, () => this._afterChestClose());
        return;
      }
    }
    // Приоритет 2: супер-эволюция
    const superReady = (window.Evolutions && Evolutions.findSuperReady) ? Evolutions.findSuperReady(player) : [];
    if (superReady.length > 0) {
      UI.showSuperEvolutionDialog(roll, superReady, (chosen) => {
        if (chosen) {
          Evolutions.applySuper(player, chosen.recipe);
          if (window.Codex) Codex.unlockEvolution(chosen.recipe.resultId);
        }
        this._afterChestClose();
      });
      return;
    }
    // Фоллбэк: редкая карточка + 3000 опыта
    player.xp += 3000;
    const choices = this.buildLevelUpChoices(3);
    UI.showChestPick(roll, choices, (chosen) => {
      if (chosen) chosen.apply(player);
      this._afterChestClose();
    });
  },

  /** Проверить обычные эволюции или дать фоллбэк (эксклюзив/большая награда). */
  _resolveChestEvolutionsOrFallback(roll, player) {
    const ready = (window.Evolutions && Evolutions.findReady) ? Evolutions.findReady(player) : [];
    if (ready.length > 0) {
      // Если несколько — показываем окно выбора эволюции
      if (ready.length === 1) {
        const pair = ready[0];
        UI.showEvolutionDialog(roll, pair, (accepted) => {
          if (accepted) {
            Evolutions.apply(player, pair.recipe);
            this._afterChestClose();
          } else {
            this._resolveChestExclusiveOrFallback(roll, player);
          }
        });
      } else {
        // Множественный выбор
        UI.showEvolutionChoice(roll, ready, (chosenPair) => {
          if (chosenPair) {
            Evolutions.apply(player, chosenPair.recipe);
            this._afterChestClose();
          } else {
            this._resolveChestExclusiveOrFallback(roll, player);
          }
        });
      }
      return;
    }

    this._resolveChestExclusiveOrFallback(roll, player);
  },

  /** Эксклюзивное оружие или большая награда как фоллбэк при d20=20. */
  _resolveChestExclusiveOrFallback(roll, player) {
    // d20=20 и нет эволюций — шанс эксклюзивного оружия
    if (roll >= 20 && Player.hasFreeWeaponSlot(player)) {
      const excl = this._tryGetExclusiveWeapon(player);
      if (excl) {
        UI.showChestReward(roll, excl, () => this._afterChestClose());
        excl.apply(player);
        return;
      }
    }
    // Большая награда
    const reward = this._buildBigReward(player);
    reward.apply(player);
    UI.showChestReward(roll, reward, () => this._afterChestClose());
  },

  /** Попробовать выдать случайное эксклюзивное оружие. */
  _tryGetExclusiveWeapon(player) {
    if (!window.EXCLUSIVE_WEAPON_INFO || !window.EXCLUSIVE_WEAPON_FACTORIES) return null;
    // Не давать то, что уже есть
    const available = EXCLUSIVE_WEAPON_INFO.filter(info => !Player.findWeapon(player, info.id));
    if (available.length === 0) return null;
    const info = available[Math.floor(Math.random() * available.length)];
    return {
      title: `⭐ Легендарное: ${info.name}`,
      desc: info.desc,
      id: info.id,
      apply(p) {
        const w = EXCLUSIVE_WEAPON_FACTORIES[info.id]();
        Player.addWeapon(p, w);
      },
    };
  },

  /** Подбор разовой "редкой" награды на 19..20 без эволюции. */
  _buildBigReward(player) {
    // Сначала пытаемся выдать новую вещь, если есть свободные слоты
    if (Player.hasFreeWeaponSlot(player)) {
      const missingWeapons = WEAPON_INFO.filter(info => !Player.findWeapon(player, info.id));
      if (missingWeapons.length > 0) {
        const info = missingWeapons[Math.floor(Math.random() * missingWeapons.length)];
        return {
          title: `Редкая находка: ${info.name}`,
          desc: info.desc,
          apply(p) {
            const w = WEAPON_FACTORIES[info.id]();
            Player.addWeapon(p, w);
          },
        };
      }
    }
    if (Player.hasFreeAbilitySlot(player)) {
      const missingAbilities = ABILITY_INFO.filter(info => !Player.findAbility(player, info.id));
      if (missingAbilities.length > 0) {
        const info = missingAbilities[Math.floor(Math.random() * missingAbilities.length)];
        return {
          title: `Редкая находка: ${info.name}`,
          desc: info.desc,
          apply(p) {
            const a = ABILITY_FACTORIES[info.id]();
            Player.addAbility(p, a);
          },
        };
      }
    }
    // Иначе — мощное разовое улучшение (rand один из вариантов)
    const variants = [
      {
        title: 'Powerful Upgrade: HP',
        desc: 'Max HP +30%, fully healed.',
        apply(p) {
          p.maxHp = Math.round(p.maxHp * 1.30);
          p.hp = p.maxHp;
        },
      },
      {
        title: 'Powerful Upgrade: Damage',
        desc: '+20% all damage (stacks).',
        apply(p) { p.damageMul *= 1.20; },
      },
      {
        title: 'Powerful Upgrade: Speed',
        desc: '+15% movement speed.',
        apply(p) { p.speedMul *= 1.15; },
      },
    ];
    return variants[Math.floor(Math.random() * variants.length)];
  },

  /** Закрытие сундучного флоу: возврат к игре, отложенный левелап если набрали XP. */
  _afterChestClose() {
    UI.hideAll();
    this.state = 'playing';
    // Если очки опыта переполнили шкалу (например, после +20 XP или после
    // эволюции это не происходит — но на всякий случай) — обработаем.
    if (this.player && this.player.xp >= this.player.xpNext) {
      // отдадим в обычный update()-цикл — он сам переведёт в levelup
    }
  },

  /** Притянуть весь опыт мгновенно к игроку (эффект Soul Flame). */
  magnetizeAllXP() {
    if (!this.xpDrops || !this.player) return;
    Loot.magnetizeAll(this.xpDrops, this.player);
  },

  damageEnemy(e, dmg) {
    if (e.invulnerable) return;

    // Талант «Мгновенная казнь»: шанс мгновенно убить обычного врага (не босса)
    if (this.player && this.player._instantKillChance > 0 &&
        !e.isBoss && !e.isElite && Math.random() < this.player._instantKillChance) {
      e.hp = 0;
      if (window.Particles && Particles.text) {
        Particles.text(e.x, e.y - 20, 'EXECUTE!', 0.8, '#ff0000', 13);
      }
      this.killEnemy(e);
      return;
    }

    // Шаг 8: критический удар
    let finalDmg = dmg;
    if (this.player && this.player.critChance > 0 && Math.random() < this.player.critChance) {
      finalDmg *= 2;
      // Визуал крита
      if (window.Particles && Particles.text) {
        Particles.text(e.x, e.y - 20, 'CRIT!', 0.6, '#ffff00', 12);
      }
    }

    e.hp -= finalDmg;

    // Шаг 8: вампиризм (лечение от нанесённого урона)
    if (this.player && this.player.lifesteal > 0) {
      const heal = finalDmg * this.player.lifesteal;
      this.player.hp = Math.min(this.player.maxHp, this.player.hp + heal);
    }

    // Шаг 8: кровотечение
    if (this.player && this.player.bleedChance > 0 && Math.random() < this.player.bleedChance) {
      if (!e.bleed) e.bleed = { dps: 0, remaining: 0 };
      e.bleed.dps = 4 * (this.player.dotDamageMul || 1);
      e.bleed.remaining = 3;
    }

    if (e.hp <= 0) {
      this.killEnemy(e);
    } else if (window.Enemies && Enemies.handleHit) {
      Enemies.handleHit(e, this);
    }
  },

  killEnemy(e) {
    if (!e.active) return;
    // Хук: лужи / расщепление / взрыв
    if (window.Enemies && Enemies.handleDeath) {
      Enemies.handleDeath(e, this);
    }
    e.active = false;
    this.kills += 1;

    // Клинок короля-лича: призыв скелета при убийстве (если гильдия >= 2)
    if (this.player && this.player.weaponSlots) {
      for (const w of this.player.weaponSlots) {
        if (w && w.id === 'lich_blade' && w.onKill) {
          w.onKill(e, this.player);
          break;
        }
      }
    }
    // Учёт по типам (заготовка для UI)
    const tid = (e.cfg && e.cfg.id) || e.type || 'unknown';
    this.killsByType[tid] = (this.killsByType[tid] || 0) + 1;

    // Бестиарий: разблокировать убитого врага
    if (window.Bestiary && tid !== 'unknown') {
      Bestiary.unlock(tid);
    }

    // Мимик из сундука: награда XP при убийстве
    if (e._mimicXpReward && e._mimicXpReward > 0) {
      const xpReward = e._mimicXpReward;
      if (this.xpDrops) {
        Loot.dropXPRaw(this.xpDrops, e.x, e.y, xpReward);
      }
      Particles.text(e.x, e.y - 30, `+${xpReward} XP`, 1.5, '#ffd700', 14);
    }

    // Шаг 8: взрывная смерть
    if (this.player && this.player.explosiveDeathChance > 0 &&
        Math.random() < this.player.explosiveDeathChance) {
      // Взрыв: урон 18, радиус 50px по всем врагам рядом
      const explosionDmg = 18 * this.player.damageMul;
      const explosionR2 = 50 * 50;
      const items = this.enemies.items;
      for (let i = 0; i < items.length; i++) {
        const other = items[i];
        if (!other.active || other === e) continue;
        const dx = other.x - e.x, dy = other.y - e.y;
        if (dx * dx + dy * dy <= explosionR2) {
          this.damageEnemy(other, explosionDmg);
        }
      }
      // Визуальный эффект взрыва
      if (window.Particles && Particles.burst) {
        Particles.burst(e.x, e.y, 8, {
          color: '#ff6600', speedMin: 60, speedMax: 140,
          lifeMin: 0.2, lifeMax: 0.4, sizeMin: 4, sizeMax: 7,
        });
      }
    }

    // Выпадение опыта по конфигу типа
    const cfg = e.cfg;
    const dropChance = (cfg && cfg.dropChance != null) ? cfg.dropChance : 0.6;
    // Шаг 6: увеличение выпадения кристаллов на 100% (удвоение шанса, макс 1.0)
    const finalDropChance = Math.min(1.0, dropChance * 2);
    if (Math.random() < finalDropChance) {
      Loot.dropXP(this.xpDrops, e.x, e.y, 0, this.player);
    }

    // Шаг 15: выпадение золота
    if (this.goldDrops) {
      Loot.tryDropGold(this.goldDrops, e);
    }

    // Шанс выпадения сундука с обычных мобов (3%, только после 5-й волны, не элитные/боссы)
    const waveIdx = this.waveIndex || 0;
    const isElite = e.cfg && (e.cfg.tier >= 4);
    if (waveIdx >= CONFIG.CHEST.MIN_WAVE && !isElite && Math.random() < CONFIG.CHEST.DROP_CHANCE && !this.chest) {
      const mobChest = Chest.spawnAt(e.x, e.y);
      if (mobChest) {
        this.chest = mobChest;
      }
    }

    // Шаг 16: кампания — проверка выпадения ключа
    if (window.Campaign && Campaign.active && e._hasKey) {
      Campaign.onKeyPickedUp();
    }
  },

  spawnTrailParticle(player, move) {
    const tp = this.particles.spawn();
    if (!tp) return;
    tp.kind = 'spark';
    tp.x = player.x; tp.y = player.y;
    tp.vx = -move.x * 20 + Utils.rand(-10, 10);
    tp.vy = -move.y * 20 + Utils.rand(-10, 10);
    tp.life = tp.maxLife = 0.35;
    tp.color = 'rgba(120,170,255,0.5)';
    tp.size = 4;
  },

  updateParticles(dt) {
    const items = this.particles.items;
    for (let i = 0; i < items.length; i++) {
      const p = items[i];
      if (!p.active) continue;
      const done = (window.Particles && Particles.step) ? Particles.step(p, dt) : (p.life -= dt) <= 0;
      if (done) p.active = false;
    }
  },

  /* ----- рендер ----- */
  render() {
    const ctx = this.ctx;
    // Шаг 3: гарантируем crisp-pixels каждый кадр (setTransform может сбросить)
    ctx.imageSmoothingEnabled = false;
    ctx.fillStyle = '#1f1f1f';
    ctx.fillRect(0, 0, this.viewW, this.viewH);

    if (!this.player) return;

    // Feature #4: используем расширенную область камеры для рендера
    const camViewW = this.cameraViewW || this.viewW;
    const camViewH = this.cameraViewH || this.viewH;
    const camScale = this.cameraScale || 1;
    const cam = GameMap.getCamera(this.player, camViewW, camViewH);
    ctx.save();
    // Feature #4: масштабирование для увеличения радиуса видимости
    ctx.scale(camScale, camScale);
    ctx.translate(-cam.x, -cam.y);

    // Анимация парения для Небесного города (Sky Citadel)
    let _skyFloatOffset = 0;
    if (window.GameMap && GameMap.currentBiome && GameMap.currentBiome.floatingAnimation) {
      const amp = GameMap.currentBiome.floatAmplitude || 2;
      const spd = GameMap.currentBiome.floatSpeed || 1.5;
      _skyFloatOffset = Math.sin(this.runTime * spd) * amp;
      ctx.translate(0, _skyFloatOffset);
    }

    GameMap.render(ctx, cam, camViewW, camViewH);
    Loot.render(ctx, this.xpDrops, cam, camViewW, camViewH);
    // Шаг 15: рендер золота
    if (this.goldDrops) Loot.renderGold(ctx, this.goldDrops, cam, camViewW, camViewH);
    // Шаг 4: лужи и следы под врагами/героем
    if (GameMap.renderGroundEffects) GameMap.renderGroundEffects(ctx, cam, camViewW, camViewH);
    // Шаг 1: рендер урн и яблок
    if (window.Urns) {
      Urns.render(ctx, cam, camViewW, camViewH);
      Urns.renderHP(ctx);
    }
    // Шаг 3: сундук рисуется в мире
    if (this.chest) Chest.render(ctx, this.chest, cam, camViewW, camViewH);
    if (this.secretChest) Chest.render(ctx, this.secretChest, cam, camViewW, camViewH);
    this.renderParticles(ctx, cam);
    Enemies.render(ctx, this.enemies, cam, camViewW, camViewH);
    // Шаг 6: рендер босса
    Bosses.render(ctx, cam, camViewW, camViewH);
    // Шаг 6: рендер золотого сундука босса
    if (this.bossChest && window.Bosses) Bosses.renderBossChest(ctx, this.bossChest, cam, camViewW, camViewH);
    // Шаг 16: рендер объектов кампании
    if (window.Campaign && Campaign.active && window.GameMap && GameMap.renderCampaignObjects) {
      GameMap.renderCampaignObjects(ctx, cam, camViewW, camViewH);
    }
    Player.render(ctx, this.player);

    // Оверлей оружий поверх героя (например, взмах меча)
    for (const w of this.player.weaponSlots) {
      if (w && typeof w.renderOverlay === 'function') w.renderOverlay(ctx, this.player);
    }

    Projectiles.render(ctx, this.projectiles, cam, camViewW, camViewH);

    ctx.restore();

    // Шаг 6: полоса HP босса (экранные координаты)
    if (window.Bosses) {
      // Тряска экрана
      if (Bosses.screenShake > 0) {
        ctx.save();
        ctx.translate(Bosses.screenShakeX, Bosses.screenShakeY);
      }
      Bosses.renderHPBar(ctx, this.viewW, this.viewH);
      Bosses.renderDefeatedMsg(ctx, this.viewW, this.viewH);
      // Шаг 14: анонс имени босса
      Bosses.renderBossAnnounce(ctx, this.viewW, this.viewH);
      if (Bosses.screenShake > 0) {
        ctx.restore();
      }
    }

    // Индикатор сундука — экранные координаты, без сдвига камеры
    if (this.chest) Chest.renderIndicator(ctx, this.chest, cam, camViewW, camViewH);
    if (this.secretChest) Chest.renderIndicator(ctx, this.secretChest, cam, camViewW, camViewH);

    // Миникарта удалена

    // Шаг 17: подсказки загадок (экранные координаты)
    if (window.UI && UI.renderPuzzleHints) {
      UI.renderPuzzleHints(ctx, this.player, this.viewW, this.viewH);
    }

    // Шаг 13: анимация перехода (затемнение экрана)
    if (this.transitioning) {
      const progress = 1 - (this.transitionTimer / 0.8);
      ctx.fillStyle = `rgba(0, 0, 0, ${Math.min(1, progress)})`;
      ctx.fillRect(0, 0, this.viewW, this.viewH);
      // Текст
      ctx.fillStyle = `rgba(255, 255, 255, ${Math.min(1, progress)})`;
      ctx.font = 'bold 20px ui-monospace, monospace';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(t('transition_text'), this.viewW / 2, this.viewH / 2);
    }

    // Шаг 13: индикатор биома и номера карты
    if (window.GameMap && GameMap.currentBiome && this.state === 'playing') {
      ctx.fillStyle = 'rgba(255, 255, 255, 0.6)';
      ctx.font = '12px ui-monospace, monospace';
      ctx.textAlign = 'left';
      ctx.textBaseline = 'top';
      ctx.fillText(`${GameMap.currentBiome.name} #${this.mapNumber || 1}`, 10, this.viewH - 24);
    }

    // Шаг 13: индикатор портала (стрелка к порталу)
    if (this.portalSpawned && window.GameMap && GameMap.portal && GameMap.portal.active) {
      this._renderPortalIndicator(ctx, cam);
    }
  },

  /** Шаг 13: Стрелка-индикатор направления к порталу. */
  _renderPortalIndicator(ctx, cam) {
    const portal = GameMap.portal;
    if (!portal || !this.player) return;
    const px = portal.x - cam.x, py = portal.y - cam.y;
    // Если портал на экране — не показываем стрелку
    if (px >= 0 && px <= this.viewW && py >= 0 && py <= this.viewH) return;
    // Стрелка у края экрана
    const cx = this.viewW / 2, cy = this.viewH / 2;
    const angle = Math.atan2(py - cy, px - cx);
    const margin = 30;
    const edgeX = Utils.clamp(cx + Math.cos(angle) * (this.viewW / 2 - margin), margin, this.viewW - margin);
    const edgeY = Utils.clamp(cy + Math.sin(angle) * (this.viewH / 2 - margin), margin, this.viewH - margin);
    // Рисуем стрелку
    ctx.save();
    ctx.translate(edgeX, edgeY);
    ctx.rotate(angle);
    ctx.fillStyle = PORTAL_CONFIG.COLOR_OUTER;
    ctx.beginPath();
    ctx.moveTo(10, 0);
    ctx.lineTo(-6, -6);
    ctx.lineTo(-6, 6);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
    // Текст
    ctx.fillStyle = 'rgba(155, 89, 182, 0.8)';
    ctx.font = 'bold 11px ui-monospace, monospace';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('⟐', edgeX, edgeY - 12);
  },

  /* ============================================================
     Шаг 6: Босс — таймер, апдейт, проверка снарядов, хоминг, сундук.
     ============================================================ */

  /** Таймер и спавн босса (Шаг 14: ротация). */
  updateBoss(dt) {
    if (!window.Bosses) return;
    Bosses.update(this.player, dt);

    // Шаг 16: в кампании не спавним глобальных боссов по таймеру
    if (window.Campaign && Campaign.active) return;

    // Проверка таймера спавна глобального босса (из ротации)
    if (!Bosses.isGlobalAlive() && !Bosses.current && Bosses.bossIndex < BOSS_CONFIG.SPAWN_TIMES.length) {
      if (this.runTime >= Bosses.nextSpawnTime) {
        Bosses.spawnGlobalBoss(Bosses.bossIndex, this.player);
      }
    }

    // Шаг 14: дебафф от теневого дракона (снижение урона на время)
    if (this.player && this.player._darkDebuffTimer > 0) {
      this.player._darkDebuffTimer -= dt;
      if (this.player._darkDebuffTimer <= 0) {
        this.player._darkDebuff = 0;
      }
    }
  },

  /** Проверка попадания снарядов игрока в босса (Шаг 14: оба босса). */
  checkProjectilesVsBoss() {
    if (!window.Bosses || !Bosses.isAlive()) return;
    const items = this.projectiles.items;
    for (let i = 0; i < items.length; i++) {
      const p = items[i];
      if (!p.active || p.owner !== 'player') continue;
      // Проверяем обоих боссов
      const target = Bosses.getClosestBoss(p.x, p.y);
      if (!target) continue;
      const bossR = Math.max(target.cfg.w, target.cfg.h) * 0.45;
      const dx = target.x - p.x, dy = target.y - p.y;
      const hitR = bossR + p.radius;
      if (dx * dx + dy * dy <= hitR * hitR) {
        Bosses.damage(p.damage, target);
        p.active = false;
        Particles.burst(p.x, p.y, 3, {
          color: '#ffffff', speedMin: 30, speedMax: 80,
          lifeMin: 0.1, lifeMax: 0.25, sizeMin: 2, sizeMax: 3,
        });
      }
    }
  },

  /** Проверка мили-оружий на попадание в босса (Шаг 14: оба босса). */
  checkMeleeVsBoss() {
    if (!window.Bosses || !Bosses.isAlive()) return;
    const p = this.player;
    // Проверяем попадание в каждого живого босса
    const targets = [];
    if (Bosses.current && Bosses.current.hp > 0) targets.push(Bosses.current);
    if (Bosses.guardian && Bosses.guardian.hp > 0) targets.push(Bosses.guardian);

    for (const boss of targets) {
      for (const w of p.weaponSlots) {
        if (!w) continue;
        const r = w.radius || 60;
        const dx = boss.x - p.x, dy = boss.y - p.y;
        const d2 = dx * dx + dy * dy;

        // Swing-based (Sword, Axe, VampireBlade)
        if (w.swing && w.swing.active && w.swing.t <= 0.05) {
          if (d2 > r * r) continue;
          const a = Math.atan2(dy, dx);
          let diff = a - w.swing.angle;
          while (diff > Math.PI) diff -= Math.PI * 2;
          while (diff < -Math.PI) diff += Math.PI * 2;
          const halfArc = (w.arc || Math.PI) * 0.5;
          if (Math.abs(diff) <= halfArc) {
            Bosses.damage((w.damageAt ? w.damageAt() : 20) * p.damageMul, boss);
          }
          continue;
        }
        // Thrust-based (Spear)
        if (w.thrust && w.thrust.active && w.thrust.t <= 0.05) {
          const cos = Math.cos(w.thrust.angle), sin = Math.sin(w.thrust.angle);
          const along = dx * cos + dy * sin;
          const across = -dx * sin + dy * cos;
          if (along >= 0 && along <= (w.range || 100) && Math.abs(across) <= 30) {
            Bosses.damage((w.damageAt ? w.damageAt() : 18) * p.damageMul, boss);
          }
          continue;
        }
        // Slam-based (Hammer)
        if (w.slam && w.slam.active && w.slam.t <= 0.05) {
          if (d2 <= r * r) {
            Bosses.damage((w.damageAt ? w.damageAt() : 20) * p.damageMul, boss);
          }
          continue;
        }
        // Whip
        if (w.whipAnim && w.whipAnim.active && w.whipAnim.t <= 0.05) {
          const bossR = Math.max(boss.cfg.w, boss.cfg.h) * 0.45;
          if (d2 <= (w.range + bossR) * (w.range + bossR)) {
            Bosses.damage((w.damageAt ? w.damageAt() : 14) * p.damageMul, boss);
          }
          continue;
        }
      }
    }
  },

  /** Хоминг для снарядов босса (лич: boss_bolt). */
  updateHomingProjectiles(dt) {
    if (!this.player) return;
    const items = this.projectiles.items;
    for (let i = 0; i < items.length; i++) {
      const p = items[i];
      if (!p.active || !p.homing) continue;
      const dx = this.player.x - p.x, dy = this.player.y - p.y;
      const dist = Math.hypot(dx, dy) || 1;
      const strength = p.homingStrength || 2.0;
      const speed = Math.hypot(p.vx, p.vy) || 250;
      // Плавно поворачиваем вектор скорости к игроку
      const targetVx = (dx / dist) * speed;
      const targetVy = (dy / dist) * speed;
      p.vx += (targetVx - p.vx) * strength * dt;
      p.vy += (targetVy - p.vy) * strength * dt;
      // Нормализуем, чтобы скорость не менялась
      const curSpeed = Math.hypot(p.vx, p.vy) || 1;
      p.vx = (p.vx / curSpeed) * speed;
      p.vy = (p.vy / curSpeed) * speed;
      p.angle = Math.atan2(p.vy, p.vx);
    }
  },

  /** Обновление золотого сундука босса (подбор без d20). */
  updateBossChest(dt) {
    if (!this.bossChest) return;
    // Проверка подбора
    const r = 30 + this.player.size * 0.5;
    const dx = this.bossChest.x - this.player.x;
    const dy = this.bossChest.y - this.player.y;
    if (dx * dx + dy * dy <= r * r) {
      this.openBossChest();
    }
  },

  /** Открытие золотого сундука босса: сразу карты без d20, с гарантированной редкой. */
  openBossChest() {
    if (!this.bossChest) return;
    Particles.chestOpen(this.bossChest.x, this.bossChest.y);
    this.bossChest = null;

    this.state = 'chest';
    Input.releaseJoystick();

    // 20% шанс эксклюзивного оружия
    if (Math.random() < 0.20 && Player.hasFreeWeaponSlot(this.player)) {
      const excl = this._tryGetExclusiveWeapon(this.player);
      if (excl) {
        excl.apply(this.player);
        UI.showChestReward(20, { title: excl.title, desc: excl.desc }, () => this._afterChestClose());
        return;
      }
    }

    // Карты: 3 штуки, одна гарантированно "сильная"
    const choices = this._buildBossChestChoices();
    UI.showChestPick(20, choices, (chosen) => {
      if (chosen) chosen.apply(this.player);
      this._afterChestClose();
    });
  },

  /** Формирует набор карт для сундука босса (одна гарантированно редкая). */
  _buildBossChestChoices() {
    const p = this.player;
    const choices = [];

    // 1) Попытка предложить эволюцию
    const ready = (window.Evolutions && Evolutions.findReady) ? Evolutions.findReady(p) : [];
    if (ready.length > 0) {
      const pair = ready[0];
      const r = pair.recipe;
      choices.push({
        kind: 'weapon',
        icon: r.resultIcon,
        id: r.resultId,
        title: `Эволюция: ${r.resultName}`,
        desc: r.desc,
        apply(player) { Evolutions.apply(player, r); },
      });
    }

    // 2) Заполняем оставшиеся слоты из buildLevelUpChoices
    const fillers = this.buildLevelUpChoices(3 - choices.length + 2); // больше, чтобы было из чего выбрать
    // Убираем дубликаты
    for (const f of fillers) {
      if (choices.length >= 3) break;
      if (!choices.find(c => c.title === f.title)) choices.push(f);
    }

    // Если мало вариантов — добавляем мощные разовые
    while (choices.length < 3) {
      const big = this._buildBigReward(p);
      choices.push({
        kind: 'basic',
        icon: '★',
        title: big.title,
        desc: big.desc,
        apply(player) { big.apply(player); },
      });
    }

    return choices.slice(0, 3);
  },

  renderParticles(ctx, cam) {
    const minX = cam.x, minY = cam.y;
    const maxX = cam.x + this.viewW, maxY = cam.y + this.viewH;
    const items = this.particles.items;
    for (let i = 0; i < items.length; i++) {
      const pa = items[i];
      if (!pa.active) continue;
      // 'ring' может быть большой — пропускаем bbox-cull для них
      const pad = pa.kind === 'ring' ? (pa.maxRadius || 0) : 12;
      if (pa.x + pad < minX || pa.x - pad > maxX || pa.y + pad < minY || pa.y - pad > maxY) continue;
      if (window.Particles && Particles.draw) {
        Particles.draw(ctx, pa);
      } else {
        // Фолбэк: квадрат старого формата
        const a = Math.max(0, pa.life / pa.maxLife);
        ctx.globalAlpha = a;
        ctx.fillStyle = pa.color;
        ctx.fillRect(pa.x - pa.size * 0.5, pa.y - pa.size * 0.5, pa.size, pa.size);
        ctx.globalAlpha = 1;
      }
    }
  },

  /* ============================================================
     Шаг 9-10: Отражение снарядов врагов своими снарядами.
     Снаряды игрока могут столкнуться с вражескими и уничтожить их.
     Более сильные вражеские снаряды требуют 2+ попаданий.
     ============================================================ */
  updateProjectileReflection() {
    const items = this.projectiles.items;
    for (let i = 0; i < items.length; i++) {
      const ep = items[i];
      if (!ep.active || ep.owner !== 'enemy') continue;
      // Определяем "уровень сложности" вражеского снаряда
      let hitsNeeded = 1;
      if (ep.kind === 'boss_bolt' || ep.kind === 'boss_fireball') hitsNeeded = 3;
      else if (ep.kind === 'boss_web') hitsNeeded = 2;
      else if (ep.kind === 'magebolt' || ep.kind === 'breath') hitsNeeded = 2;

      // Проверяем столкновение со снарядами игрока
      for (let j = 0; j < items.length; j++) {
        const pp = items[j];
        if (!pp.active || pp.owner !== 'player') continue;
        const dx = ep.x - pp.x, dy = ep.y - pp.y;
        const hitR = ep.radius + pp.radius + 4;
        if (dx * dx + dy * dy <= hitR * hitR) {
          // Попадание: уменьшаем hitsNeeded
          if (!ep._reflectHits) ep._reflectHits = 0;
          ep._reflectHits++;
          pp.active = false; // Наш снаряд расходуется

          if (ep._reflectHits >= hitsNeeded) {
            ep.active = false; // Вражеский снаряд уничтожен
            // Визуальный эффект
            if (window.Particles && Particles.burst) {
              Particles.burst(ep.x, ep.y, 5, {
                color: '#ffffff', speedMin: 40, speedMax: 120,
                lifeMin: 0.15, lifeMax: 0.3, sizeMin: 2, sizeMax: 4,
              });
            }
          } else {
            // Частичное попадание - искры
            if (window.Particles && Particles.burst) {
              Particles.burst(ep.x, ep.y, 3, {
                color: '#ffff00', speedMin: 30, speedMax: 80,
                lifeMin: 0.1, lifeMax: 0.2, sizeMin: 1, sizeMax: 3,
              });
            }
          }
          break; // Один снаряд игрока за кадр на один вражеский
        }
      }
    }
  },
};

// === js/core/state-machine.js ===
'use strict';

/* ============================================================
   FAVICON & ICON GENERATOR — programmatic d20 icon
   ============================================================ */
const IconGenerator = {
  generate(size) {
    const c = document.createElement('canvas');
    c.width = size; c.height = size;
    const ctx = c.getContext('2d');

    // Background
    ctx.fillStyle = '#1a1210';
    ctx.fillRect(0, 0, size, size);

    // Draw d20 shape (hexagon approximation)
    const cx = size / 2, cy = size / 2;
    const r = size * 0.38;
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
      const angle = (Math.PI / 3) * i - Math.PI / 6;
      const x = cx + r * Math.cos(angle);
      const y = cy + r * Math.sin(angle);
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.fillStyle = '#2a1f14';
    ctx.fill();
    ctx.strokeStyle = '#c9a84c';
    ctx.lineWidth = size * 0.04;
    ctx.stroke();

    // Inner triangle lines
    ctx.strokeStyle = 'rgba(201,168,76,0.3)';
    ctx.lineWidth = size * 0.02;
    ctx.beginPath();
    ctx.moveTo(cx, cy - r * 0.7);
    ctx.lineTo(cx - r * 0.6, cy + r * 0.5);
    ctx.lineTo(cx + r * 0.6, cy + r * 0.5);
    ctx.closePath();
    ctx.stroke();

    // Number "20"
    ctx.fillStyle = '#c9a84c';
    ctx.font = `bold ${size * 0.3}px 'Courier New', monospace`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('20', cx, cy + size * 0.02);

    return c.toDataURL('image/png');
  },

  install() {
    const favicon32 = this.generate(32);
    const favicon64 = this.generate(64);
    const icon192 = this.generate(192);

    const faviconEl = document.getElementById('favicon');
    if (faviconEl) faviconEl.href = favicon64;

    const touchEl = document.getElementById('touchIcon');
    if (touchEl) touchEl.href = icon192;
  }
};

window.IconGenerator = IconGenerator;

/* ============================================================
   TITLE SCREEN
   ============================================================ */
const TitleScreen = {
  el: null,
  shown: false,
  autoTimer: null,

  init() {
    this.el = document.getElementById('titleScreen');
    if (!this.el) return;

    // Check if first launch
    const launched = SafeStorage.getItem('d20_firstLaunch');
    if (launched) {
      // Not first launch — skip title screen
      this.el.classList.add('hidden');
      this.shown = true;
      return;
    }

    // First launch — show title, draw runes
    this._drawRunes();
    this.shown = false;

    // Event listeners for dismissal
    const dismiss = () => {
      if (this.shown) return;
      this.shown = true;
      SafeStorage.setItem('d20_firstLaunch', '1');
      this.el.style.transition = 'opacity 0.5s ease';
      this.el.style.opacity = '0';
      setTimeout(() => {
        this.el.classList.add('hidden');
        this.el.style.opacity = '';
        // Start the game (show camp)
        Game._afterTitleDismissed();
      }, 500);
      if (this.autoTimer) clearTimeout(this.autoTimer);
    };

    this.el.addEventListener('click', dismiss);
    this.el.addEventListener('touchstart', dismiss, { passive: true });

    // Auto-dismiss after 4 seconds
    this.autoTimer = setTimeout(dismiss, 4000);
  },

  _drawRunes() {
    const runesEl = document.getElementById('titleRunes');
    if (!runesEl) return;
    // Draw decorative rune SVG lines on canvas
    const c = document.createElement('canvas');
    c.width = window.innerWidth;
    c.height = window.innerHeight;
    c.style.cssText = 'position:absolute;inset:0;width:100%;height:100%;';
    const ctx = c.getContext('2d');
    ctx.strokeStyle = 'rgba(201,168,76,0.5)';
    ctx.lineWidth = 1;

    // Draw cracks / rune lines
    const numLines = 12;
    for (let i = 0; i < numLines; i++) {
      ctx.beginPath();
      let x = Math.random() * c.width;
      let y = Math.random() * c.height;
      ctx.moveTo(x, y);
      const segs = 3 + Math.floor(Math.random() * 4);
      for (let j = 0; j < segs; j++) {
        x += (Math.random() - 0.5) * 120;
        y += (Math.random() - 0.5) * 120;
        ctx.lineTo(x, y);
      }
      ctx.stroke();
    }

    // Draw rune symbols at intersections
    const runes = ['ᚠ', 'ᚢ', 'ᚦ', 'ᚨ', 'ᚱ', 'ᚲ', 'ᚷ', 'ᛁ', 'ᛃ', 'ᛈ'];
    ctx.font = '16px serif';
    ctx.fillStyle = 'rgba(201,168,76,0.4)';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    for (let i = 0; i < 8; i++) {
      const rx = Math.random() * c.width;
      const ry = Math.random() * c.height;
      ctx.fillText(runes[Math.floor(Math.random() * runes.length)], rx, ry);
    }

    runesEl.appendChild(c);
  },

  isActive() {
    return !this.shown;
  }
};

window.TitleScreen = TitleScreen;

/* ============================================================
   LOADING SCREEN
   ============================================================ */
const LoadingScreen = {
  el: null,
  dieEl: null,
  _interval: null,

  init() {
    this.el = document.getElementById('loadingScreen');
    this.dieEl = document.getElementById('loadingDie');
  },

  show() {
    if (!this.el) return;
    this.el.classList.add('active');
    // Animate number
    this._interval = setInterval(() => {
      if (this.dieEl) this.dieEl.textContent = String(1 + Math.floor(Math.random() * 20));
    }, 100);
  },

  hide() {
    if (!this.el) return;
    this.el.classList.remove('active');
    if (this._interval) { clearInterval(this._interval); this._interval = null; }
  }
};

window.LoadingScreen = LoadingScreen;

/* ============================================================
   BOOT
   ============================================================ */
window.addEventListener('load', () => {
  // Generate and install favicon/icons
  IconGenerator.install();

  // Initialize loading screen
  LoadingScreen.init();

  // Initialize UI
  UI.init();

  // Bestiary back-button fix
  const _bfix = document.createElement('style');
  _bfix.textContent = '.bestiary-back-btn{position:absolute!important;top:12px;right:12px;z-index:10;min-width:80px;text-align:center}';
  document.head.appendChild(_bfix);

  // Initialize title screen
  TitleScreen.init();

  // If title was skipped (not first launch), boot game immediately
  if (TitleScreen.shown) {
    Game.init();
  }
  // Otherwise, Game.init() will be called after title dismissal via _afterTitleDismissed

  // Prevent context menu on long press (for mobile WebView)
  document.addEventListener('contextmenu', (e) => e.preventDefault());
});

